  str_skill_desc_290120102 = "Jika Claymore bisa berpindah ke target dengan menghubungkan tile, Claymore beraksi seperti Aurorian dan menimbulkan damage pada target setelah menghubungkan tile dan berpindah ke target.",
  str_skill_name_290120103 = "Umbral Stalker",
  str_skill_desc_290120103 = "Claymore berpindah ke tengah peta dan melepaskan kekuatan mengerikan untuk menghancurkan tile dalam bentuk silang di tengah peta. Ia melakukannya sambil menggunakan energi gelap untuk menutupi tiga area peta yang menelan semua Lumina di area ini untuk sementara.",
  str_skill_name_290130101 = "Retreat",
  str_skill_desc_290130101 = "Fearmonger menyerang semua target musuh dalam jangkauan skill, menimbulkan damage dan mendorong mereka.",
  str_skill_name_290130102 = "Nightmare",
  str_skill_desc_290130102 = "Fearmonger menimbulkan damage pada semua target di semua area.",
  str_skill_name_290130103 = "Corruption",
  str_skill_desc_290130103 = "Fearmonger memberikan damage ke target dalam 2 cluster di sekitarnya dan mengubah warna pada ubin dalam jangkauan skill. Itu juga mengunci beberapa ubin dalam rentang yang sama. Setelah itu, Fearmonger memanggil 3 minion.",
  str_skill_desc_290130113 = "Fearmonger memberikan damage ke target dalam 2 cluster di sekitarnya dan mengubah warna pada ubin dalam jangkauan skill. Itu juga mengunci beberapa ubin dalam rentang yang sama. Setelah itu, Fearmonger memanggil 2 minion.",
  str_skill_desc_290130123 = "Fearmonger memberikan kerusakan pada target dalam 2 kelompok di sekitarnya dan mengubah warna pada ubin sambil juga mengunci ubin dalam jangkauan. Setelah itu, Fearmonger memanggil 4 minion.",
  str_skill_name_290134101 = "Retreat",
  str_skill_desc_290134101 = "Fearmonger menyerang semua target musuh dalam jangkauan skill, menimbulkan damage dan mendorong mundur mereka, lalu memanggil Fearmonger Minion di medan tempur.",
  str_skill_name_290134102 = "Mimpi Buruk",
  str_skill_desc_290134102 = "Fearmonger menimbulkan damage ke semua target di semua area dan memunculkan Weakened Tile di medan tempur.",
  str_skill_name_290134103 = "Corruption",
  str_skill_desc_290134103 = "Fearmonger mengubah warna semua Tile dalam 2 klaster di sekitar dan mengunci beberapa Tile dalam jangkauan.",
  str_skill_desc_290130104 = "??? menyerang semua target musuh dalam jangkauan skill, menimbulkan damage, dan mendorong mereka.",
  str_skill_desc_290130105 = "??? menimbulkan damage pada semua target di semua area.",
  str_skill_desc_290130106 = "??? menimbulkan damage pada target dalam 2 klaster di sekitarnya dan mengubah warna pada tile sambil mengunci tile yang sejajar.",
  str_skill_name_200130101 = "Sneak Attack",
  str_skill_desc_200130101 = "Menimbulkan damage tinggi ke satu target musuh satu kali.",
  str_skill_name_200134101 = "Sneak Attack",
  str_skill_desc_200134101 = "Memberikan damage tinggi satu kali ke target musuh dalam area serangan.",
  str_skill_name_200134105 = "Sneak Attack",
  str_skill_desc_200134105 = "Menimbulkan damage tinggi ke satu target musuh satu kali.",
  str_skill_desc_200130102 = "Menimbulkan damage besar pada satu target musuh di medan tempur satu kali dan memberikan Fearmonger Mark pada target. Setiap tumpuk Mark ini mengurangi DEF target (makin banyak tumpukan yang ditimbulkan, makin rendah DEF target). Memasuki Aurora Time akan menghapus semua Fearmonger Mark.",
  str_skill_name_290180101 = "Order - Banish",
  str_skill_desc_290180101 = "Meluncurkan serangan jarak jauh pada target dalam jangkauan.",
  str_skill_name_290180201 = "Order - Guard",
  str_skill_desc_290180201 = "Meluncurkan serangan jarak jauh pada target dalam jangkauan, lalu memanggil Jammer ke medan tempur (jumlah Jammer terbatas).",
  str_skill_name_290180301 = "Order - Annihilate",
  str_skill_desc_290180301 = "Meluncurkan serangan jarak jauh pada target dalam jangkauan, lalu memanggil Prism Tower ke medan tempur.",
  str_skill_name_290180401 = "Order - Purge",
  str_skill_desc_290180401 = "Meluncurkan serangan jarak jauh pada target dalam jangkauan, lalu memanggil Prism Tower dan Jammer ke medan tempur (jumlah Jammer terbatas).",
  str_skill_name_51104811 = "Deception",
  str_skill_desc_51104811 = "Memanggil ilusi pada tile di depan.",
  str_skill_desc_39104512 = "Phorosion bergerak ke target, menimbulkan damage pada target dan memanggil ilusi di dekat mereka. Semakin sedikit dinding yang tersisa, semakin kuat ilusinya.",
  str_skill_desc_39204512 = "Phorosion bergerak ke target dan menimbulkan damage sambil memanggil ilusi di dekat mereka dan mengunci 1 tile klaster di sekitarnya. Semakin sedikit dinding yang tersisa, semakin kuat ilusinya.",
  str_skill_desc_39104522 = "Phorosion bergerak ke arah target untuk menimbulkan damage dan memanggil 1–2 ilusi ke medan tempur berdasarkan pada jumlah dinding yang tersisa. Makin sedikit dinding yang tersisa, maka ilusi makin kuat.",
  str_skill_desc_39204522 = "Phorosion bergerak ke arah target untuk menimbulkan damage dan memanggil 1–2 ilusi ke medan tempur berdasarkan pada jumlah dinding yang tersisa saat mengunci tile 1 klaster di sekitar. Makin sedikit dinding yang tersisa, maka ilusi makin kuat.",
  str_skill_desc_39104511 = "Phorosion meluncurkan serangan jarak jauh pada target dalam jangkauan setelah bergerak.",
  str_skill_desc_290039101 = "Bowlinger menembakkan 5 Deathrider ke medan tempur.",
  str_skill_desc_290039102 = "Bowlinger melepaskan bom di tujuh tile 2×2 pada papan dan meledakkan semua Deathrider dalam jangkauan.",
  str_skill_desc_290139102 = "Bowlinger melepaskan bom di tujuh tile 2×2 pada papan, mereset tile, dan meledakkan semua Deathrider dalam jangkauan.",
  str_skill_desc_291139102 = "Bowlinger melepaskan bom di tujuh tile 2×2 pada papan, mereset tile, dan meledakkan semua Deathrider dalam jangkauan.",
  str_skill_name_13005802 = "Dawn Banner",
  str_skill_desc_13005802 = "Menempatkan banner milik Amy di 1 tile yang dipilih. Semakin dekat jarak Aurorian dengan banner, semakin tinggi peningkatan DEF-nya (hingga <color=#00F6FF>30%</color>). Banner akan menghilang ketika ada musuh yang menyentuhnya.",
  str_skill_name_13008001 = "Universal Support Box",
  str_skill_desc_13008001 = "<color=#00F6FF>Hanya bisa diaktifkan 1 kali di setiap putaran</color>. Melempar kaleng ke Tile mana pun yang dipilih lalu memunculkan item defense di Tile tersebut.",
  str_skill_name_14006701 = "The Knight & The Queen",
  str_skill_desc_14006701 = "Segera memulihkan 10% HP Maks kepada timmu dan mengurangi damage yang diterima selanjutnya pada putaran ini sebesar <color=#00F6FF>30%</color>.",
