  str_skill_upgrade_desc_15007115 = "Peningkatan Skill Aktif: Setelah Skill Aktif menyebar, ubin terjauh diubah menjadi ubin Merah.",
  str_skill_upgrade_desc_16010513 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16010516 = "Peningkatan Keterampilan Aktif: Memberikan kerusakan 1 kali tambahan untuk setiap ubin Kuning di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> dari lokasi Anda saat ini.",
  str_skill_upgrade_desc_17010913 = "Equipment Skill Enhancement: Memperoleh <color=#FFFF00>1</color> Vis untuk serangan normal pertama yang dilancarkan setiap putaran dan meningkatkan damage yang ditimbulkan oleh serangan normal ini sebesar <color=#FFFF00>100%</color>.",
  str_skill_upgrade_desc_17010916 = "Chain Combo Enhancement: Peluang 30% untuk +<color=#FFFF00>50%</color> bonus damage chain combo. Peluang +1% untuk dipicu per Vis.",
  str_skill_upgrade_desc_17011013 = "Equipment Skill Enhancement: Ketika Active Skill berhasil membunuh <color=#FFFF00>1</color> musuh, memperoleh <color=#FFFF00>2</color> Vis.",
  str_skill_upgrade_desc_17011016 = "Active Skill Enhancement: Untuk setiap 1 Vis yang dihilangkan, damage ini mengabaikan <color=#FFFF00>1%</color> DEF target.",
  str_skill_upgrade_desc_17010713 = "Active Skill Enhancement: Saat diaugmentasi, membunuh <color=#FFFF00>1</color> musuh akan memberikan <color=#FFFF00>2</color> Vis.",
  str_skill_upgrade_desc_17010716 = "Equipment Skill Enhancement: Pada awal setiap putaran, untuk setiap <color=#FFFF00>1</color> musuh dalam <color=#FFFF00>4 tile dalam bentuk silang</color>, memperoleh <color=#FFFF00>1</color> Vis.",
  str_skill_upgrade_desc_17010813 = "Active Skill Enhancement: Meningkatkan damage Active Skill sebesar <color=#FFFF00>60%</color>.",
  str_skill_upgrade_desc_17010816 = "Active Skill Enhancement: Meningkatkan ATK dasar sebesar <color=#FFFF00>3%</color> dalam pertempuran saat ini untuk setiap skill yang digunakan.",
  str_skill_upgrade_desc_16011213 = "Peningkatan Keterampilan Aktif: Mengubah Keterampilan Aktif menjadi <color=#FFFF00>Serangan Preemptive</color>. Tersedia saat memasuki pertempuran. Memperluas rentang pilihan Keterampilan Aktif ke seluruh medan pertempuran.",
  str_skill_upgrade_desc_16011216 = "Active Skill Enhancement: Mengubah 1 Tile musuh atau lebih menjadi Tile Merah.",
  str_skill_upgrade_desc_15011312 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_15011315 = "Active Skill Enhancement: Mengurangi cooldown skill sebanyak <color=#FFFF00>1</color> putaran.",
