  str_skill_upgrade_desc_16011916 = "Active Skill Enhancement: Setelah setiap gelombang guntur mengenai target, damage gelombang guntur selanjutnya berkurang sebesar <color=#00F6FF>20%</color>. Bisa mengenai maksimal <color=#00F6FF>5</color> kali.",
