  str_skill_name_200553 = "Condemn",
  str_skill_desc_300050 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color> dan mendorong mundur musuh.",
  str_skill_desc_320050 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color> dan mendorong mundur musuh. Musuh yang terdorong akan mengalami 10% pengurangan DEF.",
  str_skill_desc_300022 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> dan mendorong mundur musuh.",
  str_skill_desc_303022 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> dan mendorong mundur musuh.",
  str_skill_desc_310022 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> dan mendorong mundur musuh.",
  str_skill_desc_313022 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> dan mendorong mundur musuh.",
  str_skill_desc_300047 = "Memulihkan HP tim sebesar <color=#00F6FF>150%</color> dari ATK Zoya. Setiap tile Biru di medan tempur meningkatkan efektivitas penyembuhan sebesar <color=#00F6FF>5%</color>.",
  str_skill_desc_303047 = "Memulihkan HP tim sebesar <color=#00F6FF>150%</color> dari ATK Zoya. Setiap tile Biru di medan tempur meningkatkan efektivitas penyembuhan sebesar <color=#00F6FF>5%</color>.",
  str_skill_desc_320047 = "Memulihkan HP tim sebesar <color=#00F6FF>150%</color> dari ATK Zoya. Setiap tile Biru di medan tempur meningkatkan efektivitas penyembuhan sebesar <color=#00F6FF>8%</color>.",
  str_skill_desc_323047 = "Memulihkan HP tim sebesar <color=#00F6FF>150%</color> dari ATK Zoya. Setiap tile Biru di medan tempur meningkatkan efektivitas penyembuhan sebesar <color=#00F6FF>8%</color>.",
  str_skill_desc_300049 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_303049 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_320049 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan mengonversi semua tile Merah di dalam jarak serang menjadi elemen lain.",
  str_skill_desc_323049 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan mengonversi semua tile Merah di dalam jarak serang menjadi elemen lain.",
  str_skill_desc_300051 = "Melancarkan serangan ke 1 arah mana saja yang dipilih. Menimbulkan <color=#00F6FF>240%</color> damage pada musuh pertama yang terkena dan pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_310051 = "Menyerang di 1 arah mana saja yang dipilih. Menimbulkan <color=#00F6FF>240%</color> damage pada musuh pertama yang terkena dan pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_320051 = "Melancarkan serangan ke 1 arah mana saja yang dipilih. Menimbulkan <color=#00F6FF>240%</color> damage pada musuh pertama yang terkena dan pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color> serta menimbulkan efek <link=\"10002\"><#FFAE07><u>Burn</u></color></link> (2 tumpukan pada musuh pertama, 1 tumpukan pada musuh lainnya) selama 2 putaran.",
  str_skill_desc_300052 = "Berteleportasi ke lokasi yang dipilih dalam jarak 3 tile. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>4 tile dalam bentuk silang</color> di lokasi tersebut.",
  str_skill_desc_310052 = "Berteleportasi ke lokasi yang dipilih dalam jarak 3 tile. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>4 tile dalam bentuk silang</color> di lokasi tersebut.",
  str_skill_desc_320052 = "Berpindah ke lokasi yang dipilih dalam jarak 3 tile. Menimbulkan <color=#00F6FF>{1}%</color> damage pada tile dalam <color=#00F6FF>1 klaster di sekitar</color> lokasi ini.",
  str_skill_desc_300007 = "Menimbulkan <color=#00F6FF>{1}%</color> damage <color=#00F6FF>dalam bentuk silang hingga jangkauan maksimum</color>.",
  str_skill_desc_320007 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>area berbentuk silang dalam jangkauan maksimum</color>. Tumpukan Poison menjadi dua kali lipat jika target telah terkena Poison. Setelah target menerima hingga maksimum 5 tumpukan Poison, Active Skill menimbulkan +<color=#00F6FF>50%</color> damage pada target.",
  str_skill_desc_300008 = "Mengonversi 1 tile yang dapat dilalui menjadi <link=\"30001\"><#FFAE07><u>tile Prism</u></color></link> Merah.",
  str_skill_desc_310008 = "Mengonversi 1 tile yang dapat dilalui menjadi <link=\"30001\"><#FFAE07><u>tile Prism</u></color></link> Merah.",
  str_skill_desc_300032 = "Penawaran <color=#00F6FF>100%</color> kerusakan <color=#00F6FF>6-10</color> kali secara acak ke musuh di lapangan. Ketika target menerima damage lebih dari sekali, damage dari kedua kalinya akan berkurang setengahnya.",
  str_skill_desc_310032 = "Penawaran <color=#00F6FF>100%</color> kerusakan <color=#00F6FF>6-10</color> kali secara acak ke musuh di lapangan. Ketika target menerima damage lebih dari sekali, damage dari kedua kalinya akan berkurang setengahnya.",
  str_skill_desc_300035 = "Berteleportasi ke tile mana saja di dalam <color=#00F6FF>2 klaster di sekitar</color> di sekeliling unit.",
  str_skill_desc_310035 = "Berteleportasi ke tile mana saja di dalam <color=#00F6FF>2 klaster di sekitar</color> di sekeliling unit.",
  str_skill_desc_320035 = "Berteleportasi ke tile mana saja di dalam <color=#00F6FF>2 klaster di sekitar</color> di sekeliling unit.",
  str_skill_desc_300058 = "Menempatkan banner di 1 tile yang dipilih. Semakin dekat jarak Amy dengan banner, semakin tinggi peningkatan DEF-nya (hingga <color=#00F6FF>100%</color>). Banner akan menghilang ketika ada musuh yang menyentuhnya.",
  str_skill_desc_303058 = "Menempatkan banner di 1 tile yang dipilih. Semakin dekat jarak Amy dengan banner, semakin tinggi peningkatan DEF-nya (hingga <color=#00F6FF>100%</color>). Banner akan menghilang ketika ada musuh yang menyentuhnya.",
  str_skill_desc_310058 = "Menempatkan banner di 1 tile yang dipilih. Semakin dekat jarak Amy dengan banner, semakin tinggi peningkatan DEF-nya (hingga <color=#00F6FF>100%</color>). Banner akan menghilang ketika ada musuh yang menyentuhnya.",
  str_skill_desc_313058 = "Menempatkan banner di 1 tile yang dipilih. Semakin dekat jarak Amy dengan banner, semakin tinggi peningkatan DEF-nya (hingga <color=#00F6FF>100%</color>). Banner akan menghilang ketika ada musuh yang menyentuhnya.",
  str_skill_desc_300053 = "Menimbulkan <color=#00F6FF>150%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>. Damage meningkat menjadi <color=#00F6FF>150%</color> jika hanya ada 1 musuh.",
  str_skill_desc_303053 = "Menimbulkan <color=#00F6FF>150%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>. Damage meningkat menjadi <color=#00F6FF>150%</color> jika hanya ada 1 musuh. Menghilangkan cooldown Active Skill jika target berhasil disingkirkan dengan skill.",
  str_skill_desc_310053 = "Menimbulkan <color=#00F6FF>150%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>. Damage meningkat menjadi <color=#00F6FF>150%</color> jika hanya ada 1 musuh.",
  str_skill_desc_313053 = "Menimbulkan <color=#00F6FF>150%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>. Damage meningkat menjadi <color=#00F6FF>150%</color> jika hanya ada 1 musuh. Menghilangkan cooldown Active Skill jika target berhasil dibunuh dengan skill.",
  str_skill_desc_320053 = "Menimbulkan <color=#00F6FF>150%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>. Damage meningkat menjadi <color=#00F6FF>200%</color> jika hanya ada 1 musuh.",
  str_skill_desc_323053 = "Menimbulkan <color=#00F6FF>150%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>. Damage meningkat menjadi <color=#00F6FF>200%</color> jika hanya ada 1 musuh. Menghilangkan cooldown Active Skill jika target berhasil disingkirkan dengan skill.",
  str_skill_desc_300074 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>bentuk silang ke kisaran maksimum</color> dan aggros mereka ke unit.",
  str_skill_desc_310074 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>bentuk silang ke kisaran maksimum</color> dan aggros mereka ke unit.",
  str_skill_desc_320074 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>bentuk silang ke kisaran maksimum</color> dan aggros mereka ke unit. Untuk setiap <color=#00F6FF>1</color> ubin dikumpulkan, musuh mengambil <color=#00F6FF>10%</color> kerusakan yang lebih akhir.",
  str_skill_desc_300017 = "Berteleportasi ke lokasi yang dipilih. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>4 tile dalam bentuk silang</color> dan mendorong mundur musuh.",
  str_skill_desc_320017 = "Berteleportasi ke lokasi yang dipilih. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan mendorong mundur musuh.",
  str_skill_desc_300040 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> dan mereset semua tile di dalam area serangan.",
  str_skill_desc_330040 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> dan mereset semua tile <color=#00F6FF>non-Merah</color> dalam area serangan. Ada <color=#00F6FF>peluang kecil</color> menghasilkan tile Merah.",
  str_skill_desc_300041 = "Mengonversi <color=#00F6FF>4 tile dalam bentuk silang</color> menjadi Biru.",
  str_skill_desc_304041 = "Mengonversi <color=#00F6FF>4 tile dalam bentuk silang</color> menjadi Biru dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_300021 = "Mereset semua tile di medan tempur seraya mempertahankan jumlah <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> yang akan didistribusikan ulang.",
  str_skill_desc_310021 = "Mereset semua tile di medan tempur seraya mempertahankan jumlah <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> yang akan didistribusikan ulang.",
  str_skill_desc_330021 = "Mereset semua tile di medan tempur seraya mempertahankan jumlah <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> yang akan didistribusikan ulang. Tile Hijau memiliki peluang lebih tinggi untuk menghasilkan <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_300004 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>9 tile dalam bentuk kotak</color> yang berpusat pada 1 tile yang dipilih.",
