  str_skill_desc_300019 = "Menimbulkan <color=#00F6FF>250%</color> damage pada 3 musuh maksimum dalam <color=#00F6FF>3 klaster di sekitar</color>. Menimbulkan <color=#00F6FF>250%</color> damage saat hanya ada 1 musuh dalam jangkauan (damage ini mengabaikan DEF). Memulihkan HP setara dengan 25% damage yang ditimbulkan.",
  str_skill_desc_303019 = "Menimbulkan <color=#00F6FF>250%</color> damage pada 3 musuh maksimum dalam <color=#00F6FF>3 klaster di sekitar</color>. Menimbulkan <color=#00F6FF>250%</color> damage saat hanya ada 1 musuh dalam jangkauan (damage ini mengabaikan DEF). Memulihkan HP setara dengan 35% damage yang ditimbulkan.",
  str_skill_desc_306019 = "Menimbulkan <color=#00F6FF>250%</color> damage pada 3 musuh terdekat. Menimbulkan <color=#00F6FF>250%</color> damage saat hanya ada 1 musuh dalam jangkauan (damage ini mengabaikan DEF). Memulihkan HP setara dengan 35% damage yang ditimbulkan.",
  str_skill_desc_320019 = "Menimbulkan <color=#00F6FF>250%</color> damage pada 3 musuh maksimum dalam <color=#00F6FF>3 klaster di sekitar</color>. Menimbulkan <color=#00F6FF>250%</color> damage saat hanya ada 1 musuh dalam jangkauan (damage ini mengabaikan DEF). Memulihkan HP setara dengan 25% damage yang ditimbulkan. Meningkatkan damage final yang ditimbulkan pada target sebesar 10% untuk setiap 1 tumpukan Bleeding yang dimilikinya.",
  str_skill_desc_323019 = "Menimbulkan <color=#00F6FF>250%</color> damage pada 3 musuh maksimum dalam <color=#00F6FF>3 klaster di sekitar</color>. Menimbulkan <color=#00F6FF>250%</color> damage saat hanya ada 1 musuh dalam jangkauan (damage ini mengabaikan DEF). Memulihkan HP setara dengan 35% damage yang ditimbulkan. Meningkatkan damage final yang ditimbulkan pada target sebesar 10% untuk setiap 1 tumpukan Bleeding yang dimilikinya.",
  str_skill_desc_326019 = "Menimbulkan <color=#00F6FF>250%</color> damage pada 3 musuh terdekat. Menimbulkan <color=#00F6FF>250%</color> damage saat hanya ada 1 musuh dalam jangkauan (damage ini mengabaikan DEF). Memulihkan HP setara dengan 35% damage yang ditimbulkan. Meningkatkan damage final yang ditimbulkan pada target sebesar 10% untuk setiap 1 tumpukan Bleeding yang dimilikinya.",
  str_skill_desc_300023 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar.",
  str_skill_desc_303023 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar.",
  str_skill_desc_306023 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar.",
  str_skill_desc_300002 = "Mengonversi <color=#00F6FF>2</color> tile yang dipilih menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile Hijau</u></color></link> dan menimbulkan <color=#00F6FF>200%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> yang berpusat di setiap tile yang dipilih.",
  str_skill_desc_303002 = "Mengonversi <color=#00F6FF>2</color> tile yang dipilih menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile Hijau</u></color></link> dan menimbulkan <color=#00F6FF>240%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> yang berpusat di setiap tile yang dipilih.",
  str_skill_desc_306002 = "Mengonversi <color=#00F6FF>2</color> tile yang dipilih menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile Hijau</u></color></link> dan menimbulkan <color=#00F6FF>240%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> yang berpusat di setiap tile yang dipilih.",
  str_skill_desc_320002 = "Mengonversi <color=#00F6FF>2</color> tile yang dipilih menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile Hijau</u></color></link> dan menimbulkan <color=#00F6FF>200%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> yang berpusat di setiap tile yang dipilih.",
  str_skill_desc_323002 = "Mengonversi <color=#00F6FF>2</color> tile yang dipilih menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile Hijau</u></color></link> dan menimbulkan <color=#00F6FF>240%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> yang berpusat di setiap tile yang dipilih.",
  str_skill_desc_326002 = "Mengonversi <color=#00F6FF>2</color> tile yang dipilih menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile Hijau</u></color></link> dan menimbulkan <color=#00F6FF>240%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> yang berpusat di setiap tile yang dipilih.",
  str_skill_desc_16000213 = "Mengubah 2 Tile mana pun yang dipilih menjadi Tile Hijau yang diperkuat serta menimbulkan damage dalam bentuk silang hingga jangkauan maksimum yang terpusat pada Tile yang dipilih.",
  str_skill_desc_300005 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar. Semakin rendah HP musuh, damage menjadi semakin besar (damage meningkat hingga 100%).",
  str_skill_desc_306005 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar. Semakin rendah HP musuh, damage menjadi semakin besar (damage meningkat hingga 100%).",
  str_skill_desc_310005 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar. Semakin rendah HP musuh, damage menjadi semakin besar (damage meningkat hingga 100%).",
  str_skill_desc_316005 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar. Semakin rendah HP musuh, damage menjadi semakin besar (damage meningkat hingga 100%).",
  str_skill_desc_330005 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar. Semakin rendah HP musuh, damage menjadi semakin besar (damage meningkat hingga 100%).",
  str_skill_desc_336005 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar. Semakin rendah HP musuh, damage menjadi semakin besar (damage meningkat hingga 100%).",
  str_skill_desc_300006 = "Berteleportasi ke lokasi yang dipilih. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 kolom</color> dan mendorong mundur musuh. Mengonversi tile di dalam area serangan menjadi Biru.",
  str_skill_desc_303006 = "Berteleportasi ke lokasi yang dipilih. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 kolom</color> dan mendorong mundur musuh. Mengonversi tile di dalam area serangan menjadi Biru.",
  str_skill_desc_300025 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom yang dipilih</color> atau <color=#00F6FF>3 baris yang dipilih</color> dan memukul mundur musuh. Mereset semua tile <color=#00F6FF>non-Merah</color> dalam area serangan.",
  str_skill_desc_306025 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom yang dipilih</color> atau <color=#00F6FF>3 baris yang dipilih</color> dan memukul mundur musuh. Mereset semua tile <color=#00F6FF>non-Merah</color> dalam area serangan dan memiliki <color=#00F6FF>peluang kecil</color> untuk menghasilkan tile Merah.",
  str_skill_desc_320025 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom yang dipilih</color> atau <color=#00F6FF>3 baris yang dipilih</color> dan memukul mundur musuh. Damage yang ditimbulkan pada baris atau kolom tengah akan menjadi 1,5x damage yang ditimbulkan ke kedua sisi. Mereset semua tile <color=#00F6FF>non-Merah</color> dalam area serangan.",
  str_skill_desc_326025 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom yang dipilih</color> atau <color=#00F6FF>3 baris yang dipilih</color> dan memukul mundur musuh. Damage yang ditimbulkan pada baris atau kolom tengah akan menjadi 1,5x damage yang ditimbulkan ke kedua sisi. Mereset semua tile <color=#00F6FF>non-Merah</color> dalam area serangan, dan ada <color=#00F6FF>peluang kecil</color> menghasilkan tile Merah.",
  str_skill_desc_300026 = "Mereset <color=#00F6FF>semua tile non-Merah</color> dan memiliki <color=#00F6FF>peluang kecil</color> untuk menghasilkan tile Merah. Mengonversi 1 atau beberapa tile musuh menjadi tile Merah.",
  str_skill_desc_306026 = "Mereset <color=#00F6FF>semua tile non-Merah</color>, dan <color=#00F6FF>berpeluang kecil</color> membuat tile Merah. Mengonversi 1 atau beberapa tile musuh menjadi tile Merah.",
  str_skill_desc_300028 = "Memulihkan HP tim sebesar <color=#00F6FF>200%</color> dari ATK Raphael. Mereset semua <color=#00F6FF>tile non-Biru dalam 3 klaster di sekitar</color>.",
  str_skill_desc_306028 = "Memulihkan HP tim sebesar <color=#00F6FF>200%</color> dari ATK Raphael. Mereset semua <color=#00F6FF>tile non-Biru dalam 3 klaster di sekitar</color> dan ada <color=#00F6FF>peluang kecil</color> untuk menghasilkan tile Biru.",
  str_skill_desc_330028 = "Memulihkan HP tim sebesar <color=#00F6FF>200%</color> dari ATK Raphael. Mereset <color=#00F6FF>semua tile non-Biru</color>.",
  str_skill_desc_336028 = "Memulihkan HP tim sebesar <color=#00F6FF>200%</color> dari ATK Raphael. Mereset semua <color=#00F6FF>tile non-Biru</color> dan ada <color=#00F6FF>peluang kecil</color> untuk menghasilkan tile Biru.",
  str_skill_desc_300029 = "Mengonversi tile dengan <color=#00F6FF>1</color> elemen yang dipilih dari Biru, Merah, dan Kuning ke elemen lain sembari tetap mempertahankan status Enhanced Tile.",
  str_skill_desc_306029 = "Mengonversi tile dengan <color=#00F6FF>1</color> elemen yang dipilih dari Biru, Merah, dan Kuning ke elemen lain sembari tetap mempertahankan status Enhanced Tile.",
  str_skill_desc_320029 = "Mengonversi tile dengan <color=#00F6FF>1</color> elemen yang dipilih dari Biru, Merah, dan Kuning ke elemen lain sembari tetap mempertahankan status Enhanced Tile. Akan ada 1 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> yang dibuat untuk setiap <color=#00F6FF>10</color> tile yang dikonversi.",
  str_skill_desc_326029 = "Mengonversi tile dengan <color=#00F6FF>1</color> elemen yang dipilih dari Biru, Merah, dan Kuning ke elemen lain sembari tetap mempertahankan status Enhanced Tile. 1 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> akan dibuat untuk setiap <color=#00F6FF>10</color> tile yang dikonversi.",
  str_skill_desc_300038 = "Mengonversi <color=#00F6FF>4</color> tile Biru dan Merah terdekat menjadi Kuning.",
  str_skill_desc_303038 = "Mengonversi <color=#00F6FF>4</color> tile Biru dan Merah terdekat menjadi Kuning. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>1</color> di putaran ini.",
  str_skill_desc_306038 = "Mengonversi <color=#00F6FF>5</color> tile Biru dan Merah terdekat menjadi Kuning. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>1</color> di putaran ini.",
  str_skill_desc_300077 = "Mengonversi <color=#00F6FF>4</color> tile yang dipilih menjadi Biru.",
  str_skill_desc_303077 = "Mengonversi <color=#00F6FF>5</color> tile yang dipilih menjadi Biru.",
  str_skill_desc_306077 = "Mengonversi <color=#00F6FF>5</color> tile yang dipilih menjadi Biru.",
  str_skill_desc_300092 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Hijau.",
  str_skill_desc_302092 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Hijau. Jika active skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_305092 = "Mengonversi <color=#00F6FF>5</color> tile Merah terdekat menjadi Hijau. Jika active skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_330092 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Hijau dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_332092 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Hijau dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_335092 = "Mengonversi <color=#00F6FF>5</color> tile Merah terdekat menjadi Hijau dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_300075 = "Menimbulkan {1}% damage pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> selama 2 putaran.",
  str_skill_desc_302075 = "Menimbulkan {1}% damage pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> selama 2 putaran.",
  str_skill_desc_305075 = "Menimbulkan {1}% damage pada <color=#00F6FF>semua</color> musuh dan menimbulkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> selama 2 putaran.",
  str_skill_desc_320075 = "Menimbulkan {1}% damage pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> selama 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_desc_322075 = "Menimbulkan {1}% damage pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> selama 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_desc_325075 = "Menimbulkan {1}% damage pada <color=#00F6FF>semua</color> musuh dan menimbulkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> selama 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_desc_300086 = "Memulihkan HP tim sebesar <color=#00F6FF>60%</color> dari HP Maks Uriah. Jika ada sisa penyembuhan, tile Hijau terdekat akan dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_304086 = "Memulihkan HP tim sebesar <color=#00F6FF>70%</color> dari HP Maks Uriah. Jika ada sisa penyembuhan, tile Hijau terdekat akan dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_330086 = "Memulihkan HP tim sebesar <color=#00F6FF>60%</color> dari HP Maks Uriah. Jika ada sisa penyembuhan, tile Hijau terdekat akan dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Jika <link=\"30010\"><#FFAE07><u>Aurora Time</u></color></link> dipicu, Active Skill akan dapat digunakan lagi.",
  str_skill_desc_334086 = "Memulihkan HP tim sebesar <color=#00F6FF>70%</color> dari HP Maks Uriah. Jika ada sisa penyembuhan, tile Hijau terdekat akan dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Jika <link=\"30010\"><#FFAE07><u>Aurora Time</u></color></link> dipicu, Active Skill akan dapat digunakan lagi.",
  str_skill_desc_300068 = "Berpindah ke lokasi mana saja dan membuat 1 Wendy's Feather di lokasi. Ketuk Wendy's Feather untuk kembali ke lokasi semula. Hanya boleh ada 1 Wendy's Feather di medan tempur.",
  str_skill_desc_320068 = "Membuat 1 Wendy's Feather di medan tempur saat pertempuran dimulai. Membuat 1 Wendy's Feather di lokasi setelah menggunakan Active Skill. Ketuk Wendy's Feather untuk kembali ke lokasinya. Hanya boleh ada 1 Wendy's Feather di medan tempur.",
  str_skill_desc_300082 = "Bertukar elemen di antara <color=#00F6FF>2</color> tile.",
  str_skill_desc_320082 = "Bertukar elemen di antara <color=#00F6FF>2</color> tile. Tile Forest yang dipilih akan dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_300057 = "Berteleportasi ke lokasi mana pun dan memulihkan HP tim dengan jumlah setara dengan <color=#00F6FF>250%</color> ATK Philyshy. Meningkatkan Faktor Heal sebesar <color=#00F6FF>10%</color> untuk setiap musuh dalam <color=#00F6FF>2 klaster di sekitar</color> lokasi target.",
  str_skill_desc_305057 = "Berteleportasi ke lokasi mana pun dan memulihkan HP tim dengan jumlah setara dengan <color=#00F6FF>250%</color> ATK Philyshy. Meningkatkan Faktor Heal sebesar <color=#00F6FF>15%</color> untuk setiap musuh dalam <color=#00F6FF>3 klaster di sekitar</color> lokasi target.",
  str_skill_desc_320057 = "Teleport ke lokasi mana pun dan meregenerasi HP tim dengan jumlah yang sama <color=#00F6FF>250%</color> dari ATK Philyshy. Hibah Philyshy perisai sama dengan <color=#00F6FF>30%</color> dari max HP-nya dan meningkatkan Healing Factor sebesar <color=#00F6FF>10%</color> untuk setiap musuh di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> dari lokasi sasaran.",
  str_skill_desc_325057 = "Teleport ke lokasi mana pun dan meregenerasi HP tim dengan jumlah yang sama <color=#00F6FF>250%</color> dari ATK Philyshy. Hibah Philyshy perisai sama dengan <color=#00F6FF>30%</color> dari max HP-nya dan meningkatkan Healing Factor sebesar <color=#00F6FF>15%</color> untuk setiap musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> dari lokasi sasaran.",
  str_skill_desc_300091 = "Saat dikeluarkan, setiap tile Biru di medan tempur akan memberikan bonus ATK setara dengan <color=#00F6FF> 0,5%</color> ATK Chloe kepada semua anggota yang dikerahkan selama 2 putaran.",
  str_skill_desc_320091 = "Memberikan <link=\"30006\"><#FFAE07><u>Concerto Mark</u></color></link>. Saat dikeluarkan, setiap tile Biru di medan tempur dan setiap tumpuk Mark akan memberikan bonus ATK setara dengan <color=#00F6FF> 0,5%</color> ATK Chloe kepada semua anggota yang dikerahkan selama 2 putaran.",
  str_skill_desc_300079 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh dalam <color=#00F6FF>2 klaster di sekitar</color> dan mereset semua tile di dalam area serangan.",
  str_skill_desc_330079 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh dalam <color=#00F6FF>2 klaster di sekitar</color> dan mereset semua tile <color=#00F6FF>non-Biru</color> di dalam area serangan. Ada <color=#00F6FF>peluang kecil</color> untuk menghasilkan tile Biru.",
  str_skill_desc_300085 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dengan <color=#00F6FF>persentase HP paling rendah</color>.",
  str_skill_desc_320085 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dengan <color=#00F6FF>persentase HP paling rendah</color>. Menghilangkan cooldown Active Skill jika target berhasil dibunuh dengan skill",
  str_skill_desc_330085 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dengan <color=#00F6FF>persentase HP paling rendah</color>. Memberikan <link=\"30005\"><#FFAE07><u>Witness Mark</u></color></link>. Setiap tumpukan Witness Mark akan meningkatkan ATK Water Aurorian sebesar <color=#00F6FF>1%</color>. Menghilangkan cooldown Active Skill jika target berhasil dibunuh dengan skill",
  str_skill_desc_300089 = "Mengonversi <color=#00F6FF>2</color> tile yang dipilih menjadi <link=\"30001\"><#FFAE07><u>tile Prism</u></color></link> Kuning.",
  str_skill_desc_16008901 = "Mengonversi 2 Tile yang dipilih menjadi Tile Prism Kuning.",
  str_skill_desc_303089 = "Mengonversi <color=#00F6FF>2</color> tile yang dipilih menjadi <link=\"20001\"><#FFAE07><u>enhanced</u></color></link> tile Prism Kuning.",
  str_skill_desc_300027 = "Berlari ke lokasi yang dipilih, menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalur dan di tile yang berdekatan.",
  str_skill_desc_303027 = "Berlari ke lokasi yang dipilih, menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalur dan di tile yang berdekatan, lalu seketika mengeluarkan Chain Combo sekali di lokasi yang dipilih sesuai jarak yang dilalui.",
  str_skill_desc_330027 = "Berlari ke lokasi yang dipilih, menimbulkan <color=#00F6FF>{1}%</color> damage dan damage ekstra setara dengan <color=#00F6FF>5%</color> HP-nya saat ini pada musuh di sepanjang jalur dan di tile yang berdekatan.",
  str_skill_desc_333027 = "Berlari ke lokasi yang dipilih, menimbulkan <color=#00F6FF>{1}%</color> damage dan damage ekstra setara dengan <color=#00F6FF>5%</color> HP musuh saat ini pada musuh di sepanjang jalur dan di tile yang berdekatan, lalu seketika mengeluarkan Chain Combo sekali di lokasi yang dipilih sesuai jarak yang dilalui.",
  str_skill_desc_300060 = "Memasuki status Noon, meningkatkan Attack Jona sebesar <color=#00F6FF>10%</color> dan damage Chain Combo sebesar <color=#00F6FF>30%</color> selama 2 putaran.",
  str_skill_desc_303060 = "Memasuki status Noon, meningkatkan Attack Jona sebesar <color=#00F6FF>10%</color> dan damage Chain Combo sebesar <color=#00F6FF>30%</color> selama 2 putaran.",
