  str_skill_desc_323064 = "Memasuki status Overload yang menyebabkan damage Wrath's Chain Combo meningkat sebesar <color=#00F6FF>50%</color> dan menimbulkan damage pada musuh terdekat 2 kali. Berlangsung selama 2 putaran.",
  str_skill_desc_326064 = "Memasuki status Overload yang menyebabkan damage Wrath's Chain Combo meningkat sebesar <color=#00F6FF>50%</color> dan menimbulkan damage pada musuh terdekat 2 kali. Berlangsung selama 2 putaran.",
  str_skill_desc_300070 = "Menimbulkan <color=#00F6FF>90%</color> damage <color=#00F6FF>5</color> kali pada musuh di medan tempur secara acak. Melancarkan 1 serangan tambahan untuk setiap tile Fire dalam <color=#00F6FF>1 klaster di sekitar</color> unit.",
  str_skill_desc_302070 = "Menimbulkan <color=#00F6FF>90%</color> damage <color=#00F6FF>5</color> kali pada musuh di medan tempur secara acak. Melancarkan 1 serangan tambahan untuk setiap tile Fire dalam <color=#00F6FF>1 klaster di sekitar</color> unit.",
  str_skill_desc_305070 = "Menimbulkan <color=#00F6FF>90%</color> damage <color=#00F6FF>6</color> kali pada musuh di medan tempur secara acak. Melancarkan 1 serangan tambahan untuk setiap tile Fire dalam <color=#00F6FF>12 tile yang berdekatan</color>.",
  str_skill_desc_300088 = "Menimbulkan <color=#00F6FF>{1}%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> dan mendorong mundur musuh. Mengubah Tile di area serangan menjadi Merah.",
  str_skill_desc_302088 = "Menimbulkan <color=#00F6FF>{1}%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> dan mendorong mundur musuh. Mengubah Tile di area serangan menjadi Merah.",
  str_skill_desc_305088 = "Menimbulkan <color=#00F6FF>{1}%</color> damage dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color> dan mendorong mundur musuh. Mengubah Tile di area serangan menjadi Merah.",
  str_skill_desc_300084 = "Pada saat digunakan, Chain Combo Fire Aurorian akan dipicu <color=#00F6FF>2</color> kali dalam putaran ini. Untuk Chain Combo <color=#00F6FF>kedua</color>, ATK semua Fire Aurorian akan setara dengan <color=#00F6FF>70%</color> ATK Istvan.",
  str_skill_desc_302084 = "Pada saat digunakan, Chain Combo Fire Aurorian akan dipicu <color=#00F6FF>2</color> kali dalam putaran ini. Untuk Chain Combo <color=#00F6FF>kedua</color>, ATK semua Fire Aurorian akan setara dengan <color=#00F6FF>70%</color> ATK Istvan.",
  str_skill_desc_305084 = "Pada saat digunakan, Chain Combo Fire Aurorian akan dipicu <color=#00F6FF>2</color> kali dalam putaran ini. Untuk Chain Combo <color=#00F6FF>kedua</color>, ATK semua Fire Aurorian akan setara dengan <color=#00F6FF>70%</color> ATK Istvan.",
  str_skill_desc_330084 = "Pada saat digunakan, Chain Combo Fire Aurorian akan dipicu <color=#00F6FF>2</color> kali dalam putaran ini. Untuk Chain Combo <color=#00F6FF>kedua</color>, ATK semua Fire Aurorian akan setara dengan <color=#00F6FF>85%</color> ATK Istvan.",
  str_skill_desc_332084 = "Pada saat digunakan, Chain Combo Fire Aurorian akan dipicu <color=#00F6FF>2</color> kali dalam putaran ini. Untuk Chain Combo <color=#00F6FF>kedua</color>, ATK semua Fire Aurorian akan setara dengan <color=#00F6FF>85%</color> ATK Istvan.",
  str_skill_desc_335084 = "Pada saat digunakan, Chain Combo Fire Aurorian akan dipicu <color=#00F6FF>2</color> kali dalam putaran ini. Untuk Chain Combo <color=#00F6FF>kedua</color>, ATK semua Fire Aurorian akan setara dengan <color=#00F6FF>85%</color> ATK Istvan.",
  str_skill_desc_300090 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh dan membuat stun semua musuh di tile Merah.",
  str_skill_desc_302090 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh dan membuat Stun semua musuh di tile Merah.",
  str_skill_desc_320090 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh dan membuat stun semua musuh di tile Merah. Musuh di tile lain memiliki peluang <color=#00F6FF>35%</color> untuk mengalami stun.",
  str_skill_desc_322090 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh dan membuat Stun semua musuh di tile Merah. Musuh di tile lain memiliki peluang <color=#00F6FF>35%</color> untuk mengalami Stun.",
  str_skill_desc_300045 = "Memilih 1 tile sebagai target, mengorbankan <color=#00F6FF>15%</color> HP saat ini untuk menimbulkan damage yang setara pada musuh dalam <color=#00F6FF>9 tile dalam bentuk kotak</color> (damage ini mengabaikan DEF), dan menimbulkan 1 tumpukan <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> yang bertahan selama 2 putaran.",
  str_skill_desc_320045 = "Memilih 1 tile sebagai target, mengorbankan <color=#00F6FF>15%</color> HP saat ini untuk menimbulkan damage yang setara pada musuh dalam <color=#00F6FF>9 tile dalam bentuk kotak</color> (damage ini mengabaikan DEF), dan menimbulkan <link=\"30004\"><#FFAE07><u>1 tumpukan</u></color></link> Bleeding yang bertahan selama 2 putaran.",
  str_skill_desc_330045 = "Memilih 1 sebagai target, mengorbankan <color=#00F6FF>15%</color> HP saat ini untuk menimbulkan damage yang setara pada musuh dalam <color=#00F6FF>9 tile dalam bentuk kotak</color> (damage ini mengabaikan DEF), dan menimbulkan <link=\"30004\"><#FFAE07><u>1 tumpukan</u></color></link> Bleeding yang bertahan selama 2 putaran. HP Maks Basic Nails meningkat sebesar <color=#00F6FF>50%</color>.",
  str_skill_desc_300081 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh dan meng-aggro semua musuh ke unit.",
  str_skill_desc_320081 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh dan menjadikan semua musuh aggro ke unit. Damage final meningkat sebesar <color=#00F6FF>10%</color> untuk setiap tile yang didatangi musuh.",
  str_skill_desc_300083 = "Memilih 1 tile, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>4 tile dalam bentuk silang</color> dan mendorong mundur musuh.",
  str_skill_desc_320083 = "Memilih 1 tile, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan mendorong mundur musuh.",
  str_skill_desc_330083 = "Memilih 1 tile, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan mendorong mundur musuh, serta mengurangi DEF sesuai dengan persentase damage yang ditimbulkan selama 2 putaran.",
  str_skill_desc_300059 = "Bergerak ke tile mana saja dalam <color=#00F6FF>1 klaster di sekitar</color> unit.",
  str_skill_desc_3000591 = "Bergerak ke tile mana saja dalam <color=#00F6FF>1 klaster di sekitar</color> unit.",
  str_skill_desc_3000592 = "Bergerak ke tile mana saja dalam <color=#00F6FF>2 klaster di sekitar</color> unit.",
  str_skill_desc_3000593 = "Bergerak ke tile mana saja dalam <color=#00F6FF>3 klaster di sekitar</color> unit.",
  str_skill_desc_3000594 = "Bergerak ke tile mana saja dalam <color=#00F6FF>4 klaster di sekitar</color> unit.",
  str_skill_desc_3000595 = "Bergerak ke tile mana saja dalam <color=#00F6FF>5 klaster di sekitar</color> unit.",
  str_skill_desc_300080 = "Melempar kaleng ke tile yang dipilih, mengubah tile menjadi tile Kuning. Lightning Crystal, Meteorite Crystal, Bandage, Attack, atau Defense dibuat secara acak di tile.",
  str_skill_desc_320080 = "Melempar kaleng ke tile yang dipilih, mengubah tile menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> Kuning. Lightning Crystal, Meteorite Crystal, Bandage, Attack, atau Defense dibuat secara acak di tile.",
  str_skill_desc_300093 = "Berteleportasi ke lokasi mana pun dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Damage menjadi dua kali lipat ketika hanya ada 1 musuh dalam area serangan.",
  str_skill_desc_306093 = "Berteleportasi ke lokasi mana pun dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Damage menjadi dua kali lipat ketika hanya ada 1 musuh dalam area serangan. Menghilangkan cooldown Active Skill jika target berhasil dibunuh dengan skill (sekali per putaran).",
  str_skill_desc_310093 = "Berteleportasi ke lokasi mana pun dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Damage menjadi dua kali lipat ketika hanya ada 1 musuh dalam area serangan.",
  str_skill_desc_316093 = "Berteleportasi ke lokasi mana pun dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Damage menjadi dua kali lipat ketika hanya ada 1 musuh dalam area serangan. Menghilangkan cooldown Active Skill jika target berhasil dibunuh dengan skill (sekali per putaran).",
  str_skill_desc_320093 = "Berteleportasi ke lokasi mana pun dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Damage menjadi dua kali lipat ketika hanya ada 1 musuh dalam area serangan. Damage final bertambah sebesar <color=#00F6FF>15%</color> untuk tiap musuh yang terbunuh. Menumpuk hingga 10 kali.",
  str_skill_desc_326093 = "Berteleportasi ke lokasi mana pun dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Damage menjadi dua kali lipat ketika hanya ada 1 musuh dalam area serangan. Damage final bertambah sebesar <color=#00F6FF>15%</color> untuk tiap musuh yang terbunuh. Menumpuk hingga 10 kali. Menghilangkan cooldown Active Skill jika target berhasil dibunuh dengan skill (sekali per putaran).",
  str_skill_desc_330093 = "Berteleportasi ke lokasi mana pun dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Damage menjadi dua kali lipat ketika hanya ada 1 musuh dalam area serangan. Damage final bertambah sebesar <color=#00F6FF>15%</color> untuk tiap musuh yang terbunuh. Menumpuk hingga 10 kali.",
  str_skill_desc_336093 = "Berteleportasi ke lokasi mana pun dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Damage menjadi dua kali lipat ketika hanya ada 1 musuh dalam area serangan. Damage final bertambah sebesar <color=#00F6FF>15%</color> untuk tiap musuh yang terbunuh. Menumpuk hingga 10 kali. Menghilangkan cooldown Active Skill jika target berhasil dibunuh dengan skill (sekali per putaran).",
  str_skill_desc_300097 = "Berteleportasi ke lokasi mana pun dan menimbulkan damage pada musuh dalam bentuk kotak di sela-sela titik awal dan tujuan. Semakin kecil kotaknya, damage yang ditimbulkan menjadi semakin besar, hingga <color=#00F6FF>480%</color> damage.",
  str_skill_desc_302097 = "Berteleportasi ke lokasi mana pun dan menimbulkan damage pada musuh dalam bentuk kotak di sela-sela titik awal dan tujuan. Semakin kecil kotaknya, damage yang ditimbulkan menjadi semakin besar, hingga <color=#00F6FF>600%</color> damage.",
  str_skill_desc_300095 = "Memilih 1 tile dan meletakkan 1 ranjau di tile tersebut serta di <color=#00F6FF>4 tile berbentuk X</color> yang berdekatan. Setiap ranjau dapat menimbulkan <color=#00F6FF>190%</color> damage ketika dipicu dan menyebabkan 1 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_desc_320095 = "Memilih 1 tile dan meletakkan 1 ranjau di tile tersebut serta di <color=#00F6FF>4 tile berbentuk X</color> yang berdekatan. Setiap ranjau dapat menimbulkan <color=#00F6FF>190%</color> damage (dua kali lipat untuk tile yang dipilih) ketika dipicu dan menyebabkan 1 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_desc_330095 = "Memilih 1 tile dan meletakkan 1 ranjau di tile tersebut serta di <color=#00F6FF>4 tile berbentuk X</color> yang berdekatan. Setiap ranjau dapat menimbulkan <color=#00F6FF>190%</color> damage (dua kali lipat untuk tile yang dipilih) ketika dipicu dan menyebabkan 1 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_desc_300062 = "Memilih salah satu tile yang paling jauh di sekitar unit di semua <color=#00F6FF>8</color> arah dan berlari ke lokasi yang dipilih, menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalur dan di tile yang berdekatan.",
  str_skill_desc_320062 = "Memilih salah satu tile di tepi medan tempur dan berlari ke lokasi yang dipilih, menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalur dan di tile yang berdekatan.",
  str_skill_desc_300024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>2</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, Chain Combo juga akan dikeluarkan sekali di lokasi yang ditandai.",
  str_skill_desc_305024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>2</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, Chain Combo juga akan dikeluarkan sekali di lokasi yang ditandai.",
  str_skill_desc_320024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>2</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, Chain Combo juga akan dikeluarkan sekali di lokasi yang ditandai (meningkatkan damage final kedua Chain Combo sebesar <color=#00F6FF>30%</color>).",
  str_skill_desc_325024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>2</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, Chain Combo juga akan dikeluarkan sekali di lokasi yang ditandai (meningkatkan damage final kedua Chain Combo sebesar <color=#00F6FF>30%</color>).",
  str_skill_desc_330024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>1,5</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, Chain Combo juga akan dikeluarkan sekali di lokasi yang ditandai (meningkatkan damage final kedua Chain Combo sebesar <color=#00F6FF>30%</color>).",
  str_skill_desc_335024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>1,5</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, Chain Combo juga akan dikeluarkan sekali di lokasi yang ditandai (meningkatkan damage final kedua Chain Combo sebesar <color=#00F6FF>30%</color>).",
  str_skill_desc_300087 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Kuning.",
  str_skill_desc_302087 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Kuning. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_305087 = "Mengonversi <color=#00F6FF>5</color> tile Merah terdekat menjadi Kuning. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_330087 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Kuning dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_332087 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Kuning dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_335087 = "Mengonversi <color=#00F6FF>5</color> tile Merah terdekat menjadi Kuning dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3020871 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Kuning. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3050871 = "Mengonversi <color=#00F6FF>5</color> tile Merah terdekat menjadi Kuning. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3320871 = "Mengonversi <color=#00F6FF>4</color> tile Merah terdekat menjadi Kuning dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3350871 = "Mengonversi <color=#00F6FF>5</color> tile Merah terdekat menjadi Kuning dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_300101 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> dan mereset semua tile di dalam area serangan.",
  str_skill_desc_330101 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> dan mereset semua tile <color=#00F6FF>non-Kuning</color> dalam area serangan. Ada <color=#00F6FF>peluang kecil</color> untuk menghasilkan tile Kuning.",
  str_skill_desc_300102 = "Memilih 1 dari <color=#00F6FF>4</color> arah di sekeliling unit dan menarik semua musuh di arah yang dipilih serta baris dan kolom yang berdekatan ke unit, menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh yang ditarik.",
  str_skill_desc_300099 = "Mengontrol pedang ajaib, meningkatkan ATK unit sebesar <color=#00F6FF>20%</color> di putaran ini. Setelahnya, mengurangi ATK dan DEF sebesar <color=#00F6FF>50%</color> selama 1 putaran.",
  str_skill_desc_305099 = "Mengontrol pedang ajaib, meningkatkan ATK unit sebesar <color=#00F6FF>25%</color> di putaran ini. Setelahnya, mengurangi ATK dan DEF sebesar <color=#00F6FF>50%</color> selama 1 putaran.",
  str_skill_desc_330099 = "Mengontrol pedang ajaib, meningkatkan ATK unit sebesar <color=#00F6FF>20%</color> di putaran ini. Setelahnya, mengurangi ATK dan DEF sebesar <color=#00F6FF>50%</color> selama 1 putaran. Unit kebal terhadap efek status yang mengurangi ATK dan DEF saat unit mengontrol pedang ajaib untuk membunuh musuh.",
  str_skill_desc_335099 = "Mengontrol pedang ajaib, meningkatkan ATK unit sebesar <color=#00F6FF>25%</color> di putaran ini. Setelahnya, mengurangi ATK dan DEF sebesar <color=#00F6FF>50%</color> selama 1 putaran. Unit kebal terhadap efek status yang mengurangi ATK dan DEF saat unit mengontrol pedang ajaib untuk membunuh musuh.",
  str_skill_desc_300100 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada bentuk salib ke jangkauan maksimum dan menjatuhkan musuh ke belakang. Mengonversi ubin di area serangan menjadi Hijau.",
  str_skill_desc_302100 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan dalam bentuk salib ke jangkauan maksimum dan memukul mundur musuh. Mengonversi ubin di area serangan menjadi Hijau.",
  str_skill_desc_300098 = "Memilih 1 musuh dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh tersebut. Jika musuh menduduki satu tile dan dapat dijatuhkan, pindahkan musuh tersebut ke posisi yang dipilih dalam jangkauan serangan.",
  str_skill_desc_305098 = "Memilih 1 musuh dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh tersebut. Jika musuh menduduki satu tile dan dapat didorong mundur, musuh tersebut dipindahkan ke posisi yang dipilih dalam jangkauan serangan.",
  str_skill_desc_330098 = "Memilih 1 musuh dalam <color=#00F6FF>3 klaster di sekitar</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh tersebut. Jika musuh menduduki satu tile dan dapat dijatuhkan, pindahkan musuh tersebut ke posisi yang dipilih dalam jangkauan serangan. Jika target yang memiliki Mark tersingkir, menimbulkan damage setara dengan <color=#00F6FF>40%</color> ATK Cuscuta pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color> (damage ini mengabaikan DEF).",
  str_skill_desc_335098 = "Memilih 1 musuh & menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh. Jika musuh menduduki satu tile & bisa dijatuhkan, pindahkan musuh tersebut ke posisi yang dipilih dalam jangkauan serangan. Jika target yang memiliki Mark dibunuh, menimbulkan damage setara dengan <color=#00F6FF>40%</color> ATK Cuscuta pada musuh dalam <color=#00F6FF>1 klaster di sekitar</color> (damage ini mengabaikan DEF).",
  str_skill_desc_300094 = "Merekam lokasi saat ini. Unit kembali ke lokasi yang direkam setelah mengeluarkan Chain Combo Aurorian atau bergerak.",
  str_skill_desc_300096 = "Mengonversi <color=#00F6FF>4</color> tile Merah atau Hijau terdekat menjadi Biru.",
  str_skill_desc_303096 = "Mengonversi <color=#00F6FF>4</color> tile Merah atau Hijau terdekat menjadi Biru. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_306096 = "Mengonversi <color=#00F6FF>5</color> tile Merah atau Hijau terdekat menjadi Biru. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_330096 = "Mengonversi <color=#00F6FF>4</color> tile Merah atau Hijau terdekat menjadi Biru dan ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_333096 = "Mengonversi <color=#00F6FF>4</color> tile Merah atau Hijau terdekat menjadi Biru (ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>). Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_336096 = "Mengonversi <color=#00F6FF>5</color> tile Merah atau Hijau terdekat menjadi Biru (ada peluang untuk menghasilkan hingga 2 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>). Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3030961 = "Mengonversi <color=#00F6FF>4</color> tile Merah atau Hijau terdekat menjadi Biru. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3060961 = "Mengonversi <color=#00F6FF>5</color> tile Merah atau Hijau terdekat menjadi Biru. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3330961 = "Mengonversi <color=#00F6FF>4</color> tile Merah atau Hijau terdekat menjadi Biru. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3360961 = "Mengonversi <color=#00F6FF>5</color> tile Merah atau Hijau terdekat menjadi Biru. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_300056 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_desc_320056 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh dari <color=#00F6FF>semua</color> musuh di layar.",
  str_skill_desc_300103 = "Mengonversi <color=#00F6FF>4</color> tile Biru atau Hijau terdekat menjadi Merah.",
  str_skill_desc_303103 = "Mengonversi <color=#00F6FF>4</color> tile Biru atau Hijau terdekat menjadi Merah. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_306103 = "Mengonversi <color=#00F6FF>5</color> tile Biru atau Hijau terdekat menjadi Merah. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3031031 = "Mengonversi <color=#00F6FF>4</color> tile Biru atau Hijau terdekat menjadi Merah. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3061031 = "Mengonversi <color=#00F6FF>5</color> tile Biru atau Hijau terdekat menjadi Merah. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_300067 = "Mengurangi damage berikutnya yang diterima di putaran ini sebesar <color=#00F6FF>30%</color>, hingga <color=#00F6FF>2</color> kali HP Maks Alice.",
  str_skill_desc_304067 = "Mengurangi damage berikutnya yang diterima di putaran ini sebesar <color=#00F6FF>40%</color>, hingga <color=#00F6FF>2</color> kali HP Maks Alice.",
  str_skill_desc_320067 = "Mengurangi damage berikutnya yang diterima di putaran ini sebesar <color=#00F6FF>30%</color> dan langsung memulihkan <color=#00F6FF>10%</color> HP tim yang hilang akibat damage. Pengurangan damage dan HP yang pulih tidak akan melebihi <color=#00F6FF>2</color> kali HP Maks Alice.",
  str_skill_desc_324067 = "Mengurangi damage berikutnya yang diterima di putaran ini sebesar <color=#00F6FF>40%</color> dan langsung memulihkan <color=#00F6FF>10%</color> HP tim yang hilang akibat damage. Pengurangan damage dan HP yang pulih tidak akan melebihi <color=#00F6FF>2</color> kali HP Maks Alice.",
  str_skill_desc_300104 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh.",
  str_skill_desc_310104 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh.",
  str_skill_desc_320104 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh. Jika jumlah musuh yang terkena adalah 2 atau kurang, skill akan digunakan 1 kali lagi pada putaran ini.",
  str_skill_desc_300030 = "Memilih 1 tile dari <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitar dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam area bentuk kipas di arah ini (makin dekat jarak musuh, makin tinggi damage. Dapat menimbulkan damage hingga 2,5x).",
  str_skill_desc_306030 = "Memilih 1 tile dari <color=#00F6FF>4 tile dalam bentuk silang</color> dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam area bentuk kipas di arah ini (makin dekat jarak musuh, makin tinggi damage. Dapat menimbulkan damage hingga 2,5x).",
  str_skill_desc_320030 = "Memilih 1 tile dari <color=#00F6FF>8 tile dalam bentuk silang</color> di area sekitar dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam area berbentuk kipas di arah ini (makin dekat musuh pada Sinsa, makin tinggi damage. Dapat menimbulkan damage hingga 2,5x). Jika tile bagian luar dipilih, Sinsa akan bergerak maju 1 tile untuk menggunakan skill ini.",
  str_skill_desc_326030 = "Memilih 1 tile dari <color=#00F6FF>8 tile dalam bentuk silang</color> di sekitar dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam area berbentuk kipas di arah ini (makin dekat musuh pada Sinsa, makin tinggi damage. Dapat menimbulkan damage hingga 3x). Jika tile bagian luar dipilih, Sinsa akan bergerak maju 1 tile untuk menggunakan skill ini.",
  str_skill_desc_330030 = "Memilih 1 tile dari <color=#00F6FF>8 tile dalam bentuk silang</color> di area sekitar dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam area berbentuk kipas di arah ini (makin dekat musuh pada Sinsa, makin tinggi damage. Dapat menimbulkan damage hingga 2,5x). Jika tile bagian luar dipilih, Sinsa akan bergerak maju 1 tile untuk menggunakan skill ini.",
  str_skill_desc_336030 = "Memilih 1 tile dari <color=#00F6FF>8 tile dalam bentuk silang</color> di sekitar dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam area berbentuk kipas di arah ini (makin dekat musuh pada Sinsa, makin tinggi damage. Dapat menimbulkan damage hingga 3x). Jika tile bagian luar dipilih, Sinsa akan bergerak maju 1 tile untuk menggunakan skill ini.",
  str_skill_desc_300071 = "Memilih ubin apa pun di a <color=#00F6FF>bentuk silang</color>, mengonversi ubin ini menjadi Red Enhanced Tile, dan melontarkan Dragonscorch untuk menangani <color=#00F6FF>{1}%</color> kerusakan ubin di sepanjang jalan. Setelah sampai di ubin yang dipilih, Dragonscorch menyebar ke <color=#00F6FF>sisi kiri dan kanan</color> ubin ini ke jarak maksimum, memberikan 80% kerusakan.",
  str_skill_desc_305071 = "Memilih ubin apa pun di a <color=#00F6FF>bentuk silang</color>, mengonversi ubin ini menjadi Red Enhanced Tile, dan melontarkan Dragonscorch untuk menangani <color=#00F6FF>{1}%</color> kerusakan ubin di sepanjang jalan. Setelah sampai di ubin yang dipilih, Dragonscorch menyebar ke <color=#00F6FF>sisi kiri dan kanan</color> ubin ini ke jarak maksimum, menimbulkan 80% kerusakan dan mengubah ubin terjauh di setiap sisi menjadi ubin Merah.",
  str_skill_desc_320071 = "Memilih ubin apa pun di a <color=#00F6FF>bentuk silang</color>, mengonversi ubin ini menjadi Red Enhanced Tile, dan melontarkan Dragonscorch untuk menangani <color=#00F6FF>{1}%</color> kerusakan ubin di sepanjang jalan. Setelah sampai di ubin yang dipilih, Dragonscorch menyebar ke <color=#00F6FF>sisi kiri dan kanan</color> ubin ini ke jarak maksimum, memberikan 80% kerusakan. Dragonscorch memberi target dengan Burn Mark sebelum memberikan damage.",
  str_skill_desc_325071 = "Memilih ubin apa pun di a <color=#00F6FF>bentuk silang</color>, mengonversi ubin ini menjadi Red Enhanced Tile, dan melontarkan Dragonscorch untuk menangani <color=#00F6FF>{1}%</color> kerusakan ubin di sepanjang jalan. Setelah sampai di ubin yang dipilih, Dragonscorch menyebar ke <color=#00F6FF>sisi kiri dan kanan</color> ubin ini ke jarak maksimum, menimbulkan 80% kerusakan dan mengubah ubin terjauh di setiap sisi menjadi ubin Merah. Dragonscorch memberi target dengan Burn Mark sebelum memberikan damage.",
  str_skill_desc_300105 = "Memilih 1 tile di mana musuh berdiri dan memberikan <color=#00F6FF>40%</color> damage sebanyak 20 kali pada musuh. Memilih kembali target setelah mengeliminasi musuh saat ini. Active Skill memberikan damage 1 kali tambahan untuk setiap tile Kuning di dalam <color=#00F6FF>1 klaster di sekitar</color> lokasi Anda saat ini.",
  str_skill_desc_306105 = "Pilih 1 ubin tempat musuh berdiri dan memberikan <color=#00F6FF>40%</color> damage sebanyak 20 kali pada musuh. Memilih target baru setelah mengeliminasi musuh saat ini. Active Skill memberikan damage 1 kali tambahan untuk setiap ubin Kuning dalam <color=#00F6FF>2 klaster di sekitar</color> lokasi Anda saat ini.",
  str_skill_desc_330105 = "Memilih 1 tile di mana musuh berdiri dan memberikan <color=#00F6FF>40%</color> kerusakan 20 kali pada musuh, dengan faktor kerusakan meningkat sebesar <color=#00F6FF>0,8%</color> setiap kali. Memilih kembali target setelah mengeliminasi musuh saat ini. Target akhir serangan Anda akan mengalami pengurangan DEF sebesar 10% selama 1 putaran. Active Skill memberikan kerusakan 1 kali tambahan untuk setiap tile Kuning dalam <color=#00F6FF>1 klaster di sekitar</color> lokasi Anda saat ini.",
  str_skill_desc_336105 = "Memilih 1 ubin tempat musuh berdiri dan memberikan <color=#00F6FF>40%</color> kerusakan 20 kali pada musuh, dengan faktor kerusakan meningkat sebesar <color=#00F6FF>0,8%</color> setiap kali. Memilih kembali target setelah mengeliminasi musuh saat ini. Target akhir serangan Anda akan mengalami penurunan DEF sebesar 10% selama 1 putaran. Active Skill memberikan kerusakan 1 kali tambahan untuk setiap ubin Kuning dalam <color=#00F6FF>2 klaster di sekitar</color> lokasi Anda saat ini.",
  str_skill_desc_330109 = "Memakai <color=#00F6FF>10</color> Vis dan menghilangkan Vis yang tersisa untuk menimbulkan <color=#00F6FF><color=#00F6FF>150%</color></color> damage pada semua musuh di arah yang dipilih dan tile yang berdekatan. Damage final meningkat sebesar <color=#00F6FF>8%</color> untuk setiap 1 Vis yang dihilangkan.",
  str_skill_desc_330110 = "Memakai <color=#00F6FF>10</color> Vis dan menghilangkan Vis yang tersisa untuk menimbulkan <color=#00F6FF>150%</color> damage pada semua musuh. Damage meningkat sebesar <color=#00F6FF>15%</color> untuk setiap 1 Vis yang dihilangkan.",
  str_skill_desc_336110 = "Memakai <color=#00F6FF>10</color> Vis dan menghilangkan Vis yang tersisa untuk menimbulkan <color=#00F6FF>150%</color> damage pada semua musuh. Untuk setiap 1 Vis yang dihilangkan, damage meningkat sebesar <color=#00F6FF>15%</color> dan mengabaikan <color=#00F6FF>1%</color> defense.",
  str_skill_desc_330107 = "Memakai <color=#00F6FF>10</color> Vis untuk memasuki status augmented di putaran ini: Normal Attack dapat dilancarkan secara diagonal, dan meningkatkan damage serangan normal dan chain combo sebesar <color=#00F6FF>20%</color> (dapat ditumpuk ketika digunakan lebih dari sekali).",
  str_skill_desc_333107 = "Memakai <color=#00F6FF>10</color> Vis untuk memasuki status augmented di putaran ini: Normal Attack bisa dilancarkan secara diagonal, meningkatkan damage Normal Attack & chain combo sebesar <color=#00F6FF>20%</color> (bisa ditumpuk saat digunakan lebih dari sekali). Mendapatkan 2 Vis untuk tiap 1 musuh yang terbunuh saat berada di status augmented.",
  str_skill_desc_336107 = "Memakai <color=#00F6FF>10</color> Vis untuk memasuki status augmented di putaran ini: Normal Attack bisa dilancarkan secara diagonal, meningkatkan damage Normal Attack & chain combo sebesar <color=#00F6FF>20%</color> (bisa ditumpuk saat digunakan lebih dari sekali). Mendapatkan 2 Vis untuk tiap 1 musuh yang terbunuh saat berada di status augmented.",
  str_skill_desc_330108 = "Memakai <color=#00F6FF>10</color> Vis untuk menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 tile yang dipilih dan menimbulkan 50% damage <link=\"30015\"><#FFAE07><u>Splash</u></color></link> pada <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitarnya. Dapat dikeluarkan beberapa kali dalam setiap putaran.",
  str_skill_desc_333108 = "Memakai <color=#00F6FF>10</color> Vis untuk menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 tile yang dipilih dan menimbulkan 50% damage <link=\"30015\"><#FFAE07><u>Splash</u></color></link> pada <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitarnya. Dapat dikeluarkan beberapa kali dalam setiap putaran.",
  str_skill_desc_336108 = "Memakai <color=#00F6FF>10</color> Vis untuk menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 Tile yang dipilih, dan menimbulkan 50% damage <link=\"30015\"><#FFAE07><u>Splash</u></color></link> pada <color=#00F6FF>4 Tile dalam bentuk silang</color> di sekitarnya. Setiap penggunaan akan meningkatkan ATK dasar sebesar <color=#00F6FF>3%</color>. Dapat digunakan beberapa kali dalam setiap putaran.",
  str_skill_desc_300112 = "Teleportasi ke tile mana pun dalam <color=#00F6FF>3 klaster di sekitar</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua tile </color>non-Merah<color=#00F6FF> dalam area serangan.",
  str_skill_desc_301112 = "Berteleportasi ke tile mana pun, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua tile </color>non-merah<color=#00F6FF> dalam area serangan.",
  str_skill_desc_303112 = "Berteleportasi ke Tile mana pun, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua Tile </color>non-Merah<color=#00F6FF> dalam area serangan. Mengubah 1 Tile musuh atau lebih menjadi Tile Merah.",
  str_skill_desc_320112 = "Teleportasi ke tile mana pun dalam <color=#00F6FF>3 klaster di sekitar</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua tile </color>non-Merah<color=#00F6FF> dalam area serangan.",
  str_skill_desc_321112 = "Berteleportasi ke tile mana pun, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua tile </color>non-merah<color=#00F6FF> dalam area serangan.",
  str_skill_desc_323112 = "Berteleportasi ke Tile mana pun, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua Tile </color>non-Merah<color=#00F6FF> dalam area serangan. Mengubah 1 Tile musuh atau lebih menjadi Tile Merah.",
  str_skill_desc_330112 = "Berteleportasi ke Tile mana pun dalam <color=#00F6FF>3 klaster di sekitar</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua Tile </color>non-Merah<color=#00F6FF> dalam area serangan. Setelah mengaktifkan <color=#00F6FF>Manticore's Kiss</color>, tumpukan Manticore's Mark target akan disingkirkan.",
  str_skill_desc_331112 = "Berteleportasi ke Tile mana pun, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua Tile </color>non-Merah<color=#00F6FF> dalam area serangan. Setelah mengaktifkan <color=#00F6FF>Manticore's Kiss</color>, tumpukan Manticore's Mark target akan disingkirkan.",
  str_skill_desc_333112 = "Berteleportasi ke Tile mana pun, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> lokasi target, dan mereset semua Tile </color>non-Merah<color=#00F6FF> dalam area serangan. Setelah mengaktifkan <color=#00F6FF>Manticore's Kiss</color>, tumpukan Manticore's Mark target akan disingkirkan. Mengubah 1 Tile musuh atau lebih menjadi Tile Merah.",
  str_skill_desc_300113 = "Memilih 1 dari <color=#00F6FF>4</color> arah di sekitar unit dan memindahkan semua musuh bukan Boss yang menduduki sebuah tile di arah yang dipilih, sambil menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh di atas papan.",
  str_skill_desc_305113 = "Memilih 1 dari <color=#00F6FF>4</color> arah di sekitar unit dan memindahkan semua musuh bukan boss yang menduduki sebuah tile di arah yang dipilih, sambil menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh di atas papan.",
  str_skill_desc_330113 = "Memilih 1 dari <color=#00F6FF>4</color> arah di sekitar unit dan memindahkan semua musuh bukan Boss yang menduduki sebuah tile di arah yang dipilih, sambil menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh di atas papan. Jika jumlah musuh yang terkena berjumlah 2 atau kurang, skill akan digunakan 1 kali lagi pada putaran ini.",
  str_skill_desc_335113 = "Memilih 1 dari <color=#00F6FF>4</color> arah di sekitar unit dan memindahkan semua musuh bukan boss yang menduduki sebuah tile di arah yang dipilih, sambil menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh di atas papan. Jika jumlah musuh yang terkena adalah 2 atau kurang, skill akan digunakan 1 kali lagi pada putaran ini.",
  str_skill_desc_300114 = "Berteleportasi ke lokasi mana pun dalam bentuk L dari posisi saat ini (1 tile secara horizontal dan 2 tile secara vertikal atau 1 tile secara vertikal dan 2 tile secara horizontal), menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> lokasi target.",
  str_skill_desc_302114 = "Berteleportasi ke lokasi mana pun dalam bentuk L dari posisi saat ini (1 tile secara horizontal dan 2 tile secara vertikal atau 1 tile secara vertikal dan 2 tile secara horizontal), menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> lokasi target. Setelah menggunakan Active Skill, Chain Combo akan efektif terhadap semua musuh dalam jangkauan di putaran ini.",
  str_skill_desc_305114 = "Berteleportasi ke lokasi mana pun dalam bentuk L dari posisi saat ini (1 tile secara horizontal dan 2 tile secara vertikal atau 1 tile secara vertikal dan 2 tile secara horizontal), menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> lokasi target. Setelah menggunakan Active Skill, Chain Combo akan efektif terhadap semua musuh dalam jangkauan di putaran ini. Saat hanya mengenai 1 musuh, skill ini masih bisa digunakan 1 kali lagi di putaran ini.",
  str_skill_desc_320114 = "Berteleportasi ke lokasi mana pun dalam bentuk L dari posisi saat ini (1 tile secara horizontal dan 2 tile secara vertikal atau 1 tile secara vertikal dan 2 tile secara horizontal), menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> lokasi target. Setelah menggunakan Active Skill, jangkauan Chain Combo meningkat sebesar 1 klaster di putaran ini.",
  str_skill_desc_322114 = "Berteleportasi ke lokasi mana pun dalam bentuk L dari posisi saat ini (1 tile secara horizontal dan 2 tile secara vertikal atau 1 tile secara vertikal dan 2 tile secara horizontal), menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> lokasi target. Setelah menggunakan Active Skill, jangkauan Chain Combo meningkat sebesar 1 klaster di putaran ini dan Chain Combo akan efektif terhadap semua musuh dalam jangkauan.",
  str_skill_desc_325114 = "Berteleportasi ke lokasi mana pun dalam bentuk L dari posisi saat ini (1 tile secara horizontal dan 2 tile secara vertikal atau 1 tile secara vertikal dan 2 tile secara horizontal), menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> lokasi target. Setelah menggunakan Active Skill, jangkauan Chain Combo meningkat sebear 1 klaster di putaran ini dan Chain Combo akan efektif terhadap semua musuh dalam jangkauan di putaran ini. Saat hanya mengenai 1 musuh, skill ini masih bisa digunakan 1 kali lagi di putaran ini.",
  str_skill_desc_300127 = "Pilih 1 tile (termasuk Abyssal Tile) dan letakkan 1 Paper Crane di atasnya selagi mengonversi tile ini menjadi Hijau. Paper Crane akan menghilang setelah rekan tim melewatinya.",
  str_skill_desc_304127 = "Memilih 1 tile (termasuk Abyssal Tile) dan meletakkan 1 Paper Crane di atasnya selagi mengonversi tile ini menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> Hijau. Paper Crane akan menghilang setelah rekan tim melewatinya.",
  str_skill_desc_320127 = "Memilih 1 tile (termasuk Abyssal Tile) dan meletakkan 1 Paper Crane di atasnya selagi mengonversi tile ini menjadi Hijau. Paper Crane akan menghilang setelah rekan tim melewatinya dan mengonversi non-Abyssal Tile di bawahnya menjadi Hijau.",
  str_skill_desc_324127 = "Memilih 1 tile (termasuk Abyssal Tile) dan meletakkan 1 Paper Crane di atasnya selagi mengonversi tile ini menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> Hijau. Paper Crane akan menghilang setelah rekan tim melewatinya dan mengonversi non-Abyssal Tile di bawahnya menjadi Hijau.",
  str_skill_desc_300117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target.",
  str_skill_desc_303117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target.",
  str_skill_desc_306117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Jika Active Skill sudah siap di putaran sebelumnya, jangkauan teleportasi di putaran ini menjadi <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_3061171 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Jika Active Skill sudah siap di putaran sebelumnya, jangkauan pemindahan di putaran ini menjadi <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_320117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Menimbulkan 1,5x damage ke klaster luar.",
  str_skill_desc_323117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Menimbulkan 1,5x damage ke klaster luar.",
  str_skill_desc_326117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Menimbulkan 1,5x damage ke klaster luar. Jika Active Skill sudah siap di putaran sebelumnya, jangkauan teleportasi di putaran ini menjadi <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_3261171 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Menimbulkan 1,5x damage ke klaster luar. Jika Active Skill sudah siap di putaran sebelumnya, jangkauan pemindahan di putaran ini menjadi <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_330117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Menimbulkan 1,5x damage ke klaster luar.",
  str_skill_desc_333117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Menimbulkan 1,5x damage ke klaster luar.",
  str_skill_desc_336117 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Menimbulkan 1,5x damage ke klaster luar. Jika Active Skill sudah siap di putaran sebelumnya, jangkauan pemindahan di putaran ini menjadi <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_3361171 = "Berteleportasi ke tile mana pun dalam <color=#00F6FF>12 tile di sekitar dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>20 tile di sekitar</color> lokasi target. Menimbulkan 1,5x damage ke klaster luar. Jika Active Skill sudah siap di putaran sebelumnya, jangkauan pemindahan di putaran ini menjadi <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_300119 = "Memilih 1 dari <color=#00F6FF>4</color> arah di sekitar unit dan melancarkan 3 gelombang guntur ke depan dalam jangkauan 3 kolom, menimbulkan <color=#00F6FF>250%</color> damage. Setelah setiap gelombang guntur mengenai target, damage gelombang guntur selanjutnya berkurang sebesar <color=#00F6FF>40%</color>. Bisa mengenai maksimal <color=#00F6FF>3</color> kali.",
  str_skill_desc_306119 = "Memilih 1 dari <color=#00F6FF>4</color> arah di sekitar unit dan melancarkan 3 gelombang guntur ke depan dalam jangkauan 3 kolom, menimbulkan <color=#00F6FF>250%</color> damage. Setelah setiap gelombang guntur mengenai target, damage gelombang guntur selanjutnya berkurang sebesar <color=#00F6FF>20%</color>. Bisa mengenai maksimal <color=#00F6FF>5</color> kali.",
  str_skill_desc_300122 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>17 tile dalam bentuk lingkaran</color> yang berpusat pada 1 tile yang dipilih.",
  str_skill_desc_305122 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>17 tile dalam bentuk lingkaran</color> yang berpusat pada 1 tile yang dipilih. Menghilangkan efek <color=#00F6FF>Tile Hancur</color> dari tile yang terdampak.",
  str_skill_desc_320122 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>17 tile dalam bentuk lingkaran</color> yang berpusat pada 1 tile yang dipilih. Damage yang ditimbulkan pada tile yang dipilih akan mengabaikan DEF.",
  str_skill_desc_325122 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>17 tile dalam bentuk lingkaran</color> yang berpusat pada 1 tile yang dipilih. Damage yang ditimbulkan pada tile yang dipilih akan mengabaikan DEF. Menghilangkan efek <color=#00F6FF>Tile Hancur</color> dari tile yang terdampak.",
  str_skill_desc_330122 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>17 tile dalam bentuk lingkaran</color> yang berpusat pada 1 tile yang dipilih. Damage yang ditimbulkan pada tile yang dipilih akan mengabaikan DEF. Saat Blessing mencapai 10 tumpuk, jangkauan Active Skill menjadi <color=#00F6FF>jangkauan berbentuk lingkaran maksimum</color>.",
  str_skill_desc_3301221 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>17 tile dalam bentuk lingkaran</color> yang berpusat pada 1 tile yang dipilih. Damage yang ditimbulkan pada tile yang dipilih akan mengabaikan DEF. Saat Blessing mencapai 10 tumpuk, jangkauan Active Skill menjadi <color=#00F6FF>jangkauan berbentuk lingkaran maksimum</color>.",
  str_skill_desc_335122 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>17 tile dalam bentuk lingkaran</color> yang berpusat pada 1 tile yang dipilih. Damage yang ditimbulkan pada tile yang dipilih akan mengabaikan DEF. Menyingkirkan efek <color=#00F6FF>Tile Hancur</color> dari tile dalam jangkauan ini. Saat Blessing mencapai 10 tumpuk, jangkauan Active Skill menjadi <color=#00F6FF>jangkauan berbentuk lingkaran maksimum</color>.",
  str_skill_desc_300121 = "Pilih 1 tile, lalu dengan tile ini sebagai pusat, pilih 1 arah untuk memperpanjang sulur yang menjalar ke tepi medan tempur dan menimbulkan <color=#00F6FF>360%</color> damage dalam jangkauan ini sambil mengonversi <color=#00F6FF>2</color> tile di depan menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Damage meningkat sebesar <color=#00F6FF>10%</color> untuk setiap 1 tile yang dilalui sulur.",
  str_skill_desc_306121 = "Pilih 1 tile, lalu dengan tile ini sebagai pusat, pilih 1 arah untuk memperpanjang sulur yang menjalar ke tepi medan tempur dan menimbulkan <color=#00F6FF>360%</color> damage dalam jangkauan ini sambil mengonversi <color=#00F6FF>3</color> tile di depan menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Damage meningkat sebesar <color=#00F6FF>15%</color> untuk setiap 1 tile yang dilalui sulur.",
  str_skill_desc_320121 = "Pilih 1 tile, lalu dengan tile ini sebagai pusat, pilih 1 arah untuk memperpanjang sulur yang menjalar ke tepi medan tempur dan menimbulkan <color=#00F6FF>360%</color> damage dalam jangkauan ini sambil mengonversi <color=#00F6FF>2</color> tile di depan menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Sulur memanjang <color=#00F6FF>3</color> tile dalam bentuk silang setelah menimbulkan damage. Efek perpanjangan ini hanya bisa dipicu 1 kali untuk setiap musuh yang terkena. Damage meningkat sebesar <color=#00F6FF>10%</color> untuk setiap 1 tile yang dilalui sulur.",
  str_skill_desc_326121 = "Pilih 1 tile, lalu dengan tile ini sebagai pusat, pilih 1 arah untuk memperpanjang sulur yang menjalar ke tepi medan tempur dan menimbulkan <color=#00F6FF>360%</color> damage dalam jangkauan ini sambil mengonversi <color=#00F6FF>3</color> tile di depan menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Sulur memanjang <color=#00F6FF>3</color> tile dalam bentuk silang setelah menimbulkan damage. Efek perpanjangan ini hanya bisa dipicu 1 kali untuk setiap musuh yang terkena. Damage meningkat sebesar <color=#00F6FF>15%</color> untuk setiap 1 tile yang dilalui sulur.",
  str_skill_desc_300065 = "Berpindah ke tile mana saja dalam <color=#00F6FF>2 klaster di sekitar</color> tile Biru di medan tempur.",
  str_skill_desc_330065 = "Berteleportasi ke tile mana saja dalam <color=#00F6FF>2 klaster di sekitar</color> atau ke tile Biru mana pun di medan tempur. Bisa digunakan 1 kali lagi setelah memasuki Aurora Time.",
  str_skill_desc_300115 = "Berteleportasi ke lokasi tertentu dan memberikan efek <link=\"30020\"><#FFAE07><u>Purify</u></color></link> pada tile dalam <color=#00F6FF>2 klaster di sekitar</color> dan tile lain secara acak sebagai tambahan. Sebanyak <color=#00F6FF>3</color> tile dalam jangkauan Purify dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_305115 = "Berteleportasi ke lokasi tertentu dan memberikan efek <link=\"30020\"><#FFAE07><u>Purify</u></color></link> pada tile dalam <color=#00F6FF>2 klaster di sekitar</color> dan tile lain secara acak sebagai tambahan. Sebanyak <color=#00F6FF>4</color> tile dalam jangkauan Purify dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_320115 = "Berteleportasi ke lokasi tertentu dan memberikan efek <link=\"30020\"><#FFAE07><u>Purify</u></color></link> pada tile dalam <color=#00F6FF>3 klaster di sekitar</color> dan tile lain secara acak sebagai tambahan. Sebanyak <color=#00F6FF>4</color> tile dalam jangkauan Purify dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_325115 = "Berteleportasi ke lokasi tertentu dan memberikan efek <link=\"30020\"><#FFAE07><u>Purify</u></color></link> pada tile dalam <color=#00F6FF>3 klaster di sekitar</color> dan tile lain secara acak sebagai tambahan. Sebanyak <color=#00F6FF>5</color> tile dalam jangkauan Purify dikonversi menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_300126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui.",
  str_skill_desc_303126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui.",
  str_skill_desc_306126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui. Bisa digunakan 1 kali lagi setelah memasuki Aurora Time (bisa dipicu 1 kali per gelombang).",
  str_skill_desc_310126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui.",
  str_skill_desc_313126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui.",
  str_skill_desc_316126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui. Bisa menggunakan 1 kali lagi setelah memasuki Aurora Time (bisa memicu 1 kali per gelombang).",
  str_skill_desc_320126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui.",
  str_skill_desc_323126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui.",
  str_skill_desc_326126 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color> yang berpusat pada 1 tile yang dapat dilalui. Bisa menggunakan 1 kali lagi setelah memasuki Aurora Time (bisa memicu 1 kali per gelombang).",
  str_skill_desc_300129 = "Menggunakan semua <link=\"30021\"><#FFAE07><u>Scion</u></color></link> untuk menimbulkan damage pada 1 musuh. Setiap <link=\"30021\"><#FFAE07><u>Scion</u></color></link> menimbulkan <color=#00F6FF>40%</color> damage.",
  str_skill_desc_303129 = "Menggunakan semua <link=\"30022\"><#FFAE07><u>Scion</u></color></link> untuk menimbulkan damage pada 1 musuh. Setiap <link=\"30022\"><#FFAE07><u>Scion</u></color></link> menimbulkan <color=#00F6FF>50%</color> damage.",
  str_skill_desc_306129 = "Menggunakan semua <link=\"30023\"><#FFAE07><u>Scion</u></color></link> untuk menimbulkan damage pada 1 musuh. Setiap <link=\"30023\"><#FFAE07><u>Scion</u></color></link> menimbulkan <color=#00F6FF>50%</color> damage.",
  str_skill_desc_300055 = "Menyerang dalam 1 arah mana pun yang dipilih dan menimbulkan <color=#00F6FF>160%</color> damage pada semua musuh dalam arah ini dan mendorong mereka mundur.",
  str_skill_desc_302055 = "Menyerang dalam 1 arah mana pun yang dipilih dan menimbulkan <color=#00F6FF>160%</color> damage pada semua musuh dalam arah ini dan mendorong mereka mundur. Jika Active Skill sudah siap di putaran sebelumnya, damage final ke putaran ini meningkat sebesar <color=#00F6FF>60%</color>.",
  str_skill_desc_3020551 = "Menyerang dalam 1 arah mana pun yang dipilih dan menimbulkan <color=#00F6FF>160%</color> damage pada semua musuh dalam arah ini dan mendorong mereka mundur. Jika Active Skill sudah siap di putaran sebelumnya, damage final ke putaran ini meningkat sebesar <color=#00F6FF>60%</color>.",
  str_skill_desc_305055 = "Menyerang dalam 1 arah mana pun yang dipilih dan menimbulkan <color=#00F6FF>160%</color> damage pada semua musuh dalam arah ini dan mendorong mereka mundur. Untuk setiap <color=#00F6FF>1</color> tile musuh dipukul mundur, damage final meningkat sebesar <color=#00F6FF>5%</color>. Jika Active Skill sudah siap di putaran sebelumnya, damage final ke putaran ini meningkat sebesar <color=#00F6FF>60%</color>.",
  str_skill_desc_3050551 = "Menyerang dalam 1 arah mana pun yang dipilih dan menimbulkan <color=#00F6FF>160%</color> damage pada semua musuh dalam arah ini dan mendorong mereka mundur. Untuk setiap <color=#00F6FF>1</color> tile musuh dipukul mundur, damage final meningkat sebesar <color=#00F6FF>5%</color>. Jika Active Skill sudah siap di putaran sebelumnya, damage final ke putaran ini meningkat sebesar <color=#00F6FF>60%</color>.",
  str_skill_desc_300120 = "Berteleportasi ke lokasi yang dipilih. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 kolom</color> dan mendorong mundur musuh. Mengonversi tile di dalam area serangan menjadi Hijau.",
  str_skill_desc_16012001 = "Menimbulkan damage kecil ke 1 kolom dan mendorong mundur musuh. Mengubah Tile dalam area serangan menjadi Hijau.",
  str_skill_desc_16012002 = "Memukul mundur 1 barisan musuh dalam area yang telah dipilih. Mengubah Tile di area serangan menjadi Hijau.",
  str_skill_desc_303120 = "Berteleportasi ke lokasi yang dipilih. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 kolom</color> dan menjatuhkan musuh. Mengonversi tile di dalam area serangan menjadi Hijau.",
  str_skill_desc_300123 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Saat menyerang target yang sama untuk pertama kalinya, mereka mengalami <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> selama 1 putaran. Saat menyerang untuk kedua kalinya, mereka mengalami <color=#00F6FF><color=#00F6FF>Stun</color></color> selama 1 putaran.",
  str_skill_desc_302123 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Saat menyerang target yang sama untuk pertama kalinya, mereka mengalami <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> selama 1 putaran. Saat menyerang untuk kedua kalinya, mereka mengalami <color=#00F6FF>Stun</color> selama 1 putaran.",
  str_skill_desc_305123 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Saat menyerang target yang sama untuk 2 kali pertama, mereka mengalami <color=#00F6FF>Stun</color> selama 1 putaran.",
  str_skill_desc_320123 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Saat menyerang target yang sama untuk pertama kalinya, mereka mengalami <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> selama 1 putaran. Saat menyerang untuk kedua kalinya, mereka mengalami <color=#00F6FF>Stun</color> selama 1 putaran. Damage Active Skill meningkat berdasarkan pada jumlah tile yang ditempati target.",
  str_skill_desc_322123 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Saat menyerang target yang sama untuk pertama kalinya, mereka akan mengalami <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> selama 1 putaran. Saat menyerang untuk kedua kalinya, mereka akan mengalami <color=#00F6FF>Stun</color> selama 1 putaran. Damage Active Skill ditingkatkan berdasarkan jumlah tile yang ditempati target.",
  str_skill_desc_325123 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh dalam <color=#00F6FF>1 klaster di sekitar</color>. Saat menyerang target yang sama untuk 2 kali pertama, mereka mengalami <color=#00F6FF>Stun</color> selama 1 putaran setiap waktu. Damage Active Skill meningkat berdasarkan pada jumlah tile yang ditempati target.",
  str_skill_desc_300015 = "Pilih tile yang bisa dilalui untuk memanggil Gin dan tentukan arahnya, lalu lemparkan 1 granat ke arah ini. Granat ini bisa memantul lagi ke jarak terjauh yang memungkinkan dari arah yang dipilih Gin. Granat menimbulkan <color=#00F6FF>200%</color> damage pada musuh yang dilewatinya di sepanjang jalan.",
  str_skill_desc_330015 = "Pilih tile yang bisa dilalui untuk memanggil Gin dan tentukan arahnya, lalu lemparkan 1 granat ke arah ini. Granat ini bisa memantul lagi ke jarak terjauh yang memungkinkan dari arah yang dipilih Gin. Granat menimbulkan <color=#00F6FF>200%</color> damage pada musuh yang dilewatinya di sepanjang jalan. Gin bisa menghadap ke arah diagonal.",
  str_skill_desc_300131 = "Memulihkan HP tim setara dengan <color=#00F6FF>220%</color> dari ATK Novio dan mendapatkan Shield setara dengan <color=#00F6FF>90%</color> dari HP Novio. Pemulihan yang berlebih akan menimbulkan damage pada musuh dalam <color=#00F6FF>12 tile berbentuk wajik</color> yang setara dengan kelebihan nilai yang dipulihkan terlepas dari pertahanannya.",
  str_skill_desc_306131 = "Memulihkan HP tim setara dengan <color=#00F6FF>220%</color> dari ATK Novio dan mendapatkan Shield setara dengan <color=#00F6FF>120%</color> dari HP Novio. Pemulihan yang berlebih akan menimbulkan damage pada musuh dalam <color=#00F6FF>12 tile berbentuk wajik</color> yang setara dengan kelebihan nilai yang dipulihkan terlepas dari pertahanannya.",
  str_skill_desc_320131 = "Memulihkan HP tim setara dengan <color=#00F6FF>220%</color> dari ATK Novio dan mendapatkan Shield setara dengan <color=#00F6FF>90%</color> dari HP Novio. Pemulihan yang berlebih akan menimbulkan damage pada musuh dalam <color=#00F6FF>2 klaster di sekitar</color> yang setara dengan kelebihan nilai yang dipulihkan terlepas dari pertahanannya. Setelah memasuki Aurora Time, Shield dengan nilai hingga setara HP Maks akan dikonversi menjadi HP.",
  str_skill_desc_326131 = "Memulihkan HP tim setara dengan <color=#00F6FF>220%</color> dari ATK Novio dan mendapatkan Shield setara dengan <color=#00F6FF>120%</color> dari HP Novio. Pemulihan yang berlebih akan menimbulkan damage pada musuh dalam <color=#00F6FF>2 klaster di sekitar</color> yang setara dengan kelebihan nilai yang dipulihkan terlepas dari pertahanannya. Setelah memasuki Aurora Time, Shield dengan nilai hingga setara HP Maks akan dikonversi menjadi HP.",
  str_skill_desc_300132 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan.",
  str_skill_desc_302132 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan. Setelah pulih, cooldown Active Skill juga berkurang <color=#00F6FF>1</color> putaran.",
  str_skill_desc_305132 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan. Setelah pulih, cooldown Active Skill juga berkurang <color=#00F6FF>1</color> putaran.",
  str_skill_desc_320132 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan. Saat memasuki Aurora Time, musuh tidak bisa memulihkan HP saat putaran berakhir.",
  str_skill_desc_3201321 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan. Saat memasuki Aurora Time, musuh tidak bisa memulihkan HP saat putaran berakhir.",
  str_skill_desc_322132 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan. Setelah pulih, cooldown Active Skill juga berkurang <color=#00F6FF>1</color> putaran. Saat memasuki Aurora Time, musuh tidak bisa memulihkan HP saat putaran berakhir.",
  str_skill_desc_3221321 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan. Setelah pulih, cooldown Active Skill juga berkurang <color=#00F6FF>1</color> putaran. Saat memasuki Aurora Time, musuh tidak bisa memulihkan HP saat putaran berakhir.",
  str_skill_desc_325132 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan. Setelah pulih, cooldown Active Skill juga berkurang <color=#00F6FF>1</color> putaran. Saat memasuki Aurora Time, musuh tidak bisa memulihkan HP saat putaran berakhir.",
  str_skill_desc_3251321 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 1 musuh yang dipilih. Jika musuh masih bertahan di akhir putaran, HP yang dipulihkan setara dengan damage yang ditimbulkan. Setelah pulih, cooldown Active Skill juga berkurang <color=#00F6FF>1</color> putaran. Saat memasuki Aurora Time, musuh tidak bisa memulihkan HP saat putaran berakhir.",
  str_skill_desc_300133 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>13 tile dalam bentuk wajik</color> yang berpusat pada 1 tile yang dipilih dan mendorong mundur musuh.",
  str_skill_desc_302133 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>13 tile dalam bentuk wajik</color> yang berpusat pada 1 tile yang dipilih dan menjatuhkan musuh.",
  str_skill_desc_300137 = "Pilih 1 musuh dan mengonversi hingga maksimal <color=#00F6FF>2</color> tile non-Biru yang diinjak musuh menjadi Biru.",
  str_skill_desc_310137 = "Pilih 1 musuh dan mengonversi hingga maksimal <color=#00F6FF>2</color> tile non-Biru di kaki musuh menjadi Biru.",
  str_skill_desc_304137 = "Pilih 1 musuh dan mengonversi hingga maksimal <color=#00F6FF>3</color> tile non-Biru yang diinjak musuh menjadi Biru.",
  str_skill_desc_314137 = "Pilih 1 musuh dan mengonversi hingga maksimal <color=#00F6FF>3</color> tile non-Biru di kaki musuh menjadi Biru.",
  str_skill_desc_300135 = "Memilih 1 dari <color=#00F6FF>4</color> arah, lalu memilih arah di kedua sisinya, menyerang musuh dalam <color=#00F6FF>45 derajat</color> dan menimbulkan <color=#00F6FF>340%</color> damage di area tersebut. Damage berkurang selama penyisiran ini, yaitu menjadi minimal 30% dari nilai aslinya.",
  str_skill_desc_302135 = "Memilih 1 dari <color=#00F6FF>4</color> arah, lalu memilih arah di kedua sisinya, menyerang musuh dalam <color=#00F6FF>45 derajat</color> dan menimbulkan <color=#00F6FF>340%</color> damage di area tersebut. Damage berkurang selama penyisiran ini, yaitu menjadi minimal 30% dari nilai aslinya.",
  str_skill_desc_305135 = "Memilih 1 dari <color=#00F6FF>4</color> arah, lalu memilih arah di kedua sisinya, menyerang musuh dalam <color=#00F6FF>45 derajat</color> dan menimbulkan <color=#00F6FF>340%</color> damage di area tersebut. Damage berkurang selama penyisiran ini, yaitu menjadi minimal 40% dari nilai aslinya.",
  str_skill_desc_320135 = "Memilih 1 dari <color=#00F6FF>4</color> arah, lalu memilih arah di kedua sisinya, menyerang musuh dalam <color=#00F6FF>90 derajat</color> dan menimbulkan <color=#00F6FF>340%</color> damage di area tersebut. Damage berkurang selama penyisiran ini, yaitu menjadi minimal 30% dari nilai aslinya.",
  str_skill_desc_322135 = "Memilih 1 dari <color=#00F6FF>4</color> arah, lalu memilih arah di kedua sisinya, menyerang musuh dalam <color=#00F6FF>90 derajat</color> dan menimbulkan <color=#00F6FF>340%</color> damage di area tersebut. Damage berkurang selama penyisiran ini, yaitu menjadi minimal 30% dari nilai aslinya.",
  str_skill_desc_325135 = "Memilih 1 dari <color=#00F6FF>4</color> arah, lalu memilih arah di kedua sisinya, menyerang musuh dalam <color=#00F6FF>90 derajat</color> dan menimbulkan <color=#00F6FF>340%</color> damage di area tersebut. Damage berkurang selama penyisiran ini, yaitu menjadi minimal 40% dari nilai aslinya.",
  str_skill_desc_300134 = "Pilih satu tile dan timbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalan dan pada tile yang berdekatan. Jatuhkan mereka sejauh mungkin.",
  str_skill_desc_303134 = "Pilih satu tile dan timbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalan dan pada tile yang berdekatan. Jatuhkan mereka sejauh mungkin.",
  str_skill_desc_320134 = "Pilih satu tile dan timbulkan <color=#00F6FF>{1}%</color> damage pada musuh <color=#00F6FF>di sepanjang jalan</color> dan pada tile yang <color=#00F6FF>berdekatan</color>. Jatuhkan mereka sejauh mungkin. Musuh <color=#00F6FF>di sepanjang jalan</color> akan menerima damage <color=#00F6FF>1,3×</color>.",
  str_skill_desc_323134 = "Pilih satu tile dan timbulkan <color=#00F6FF>{1}%</color> damage pada musuh <color=#00F6FF>di sepanjang jalan</color> dan pada tile yang <color=#00F6FF>berdekatan</color>. Jatuhkan mereka sejauh mungkin. Musuh <color=#00F6FF>di sepanjang jalan</color> akan menerima damage <color=#00F6FF>1,3×</color>.",
  str_skill_desc_300136 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh, dan menyebabkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> pada semua musuh di tile Hijau selama 2 putaran.",
  str_skill_desc_302136 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh, dan menyebabkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> pada semua musuh di tile Hijau selama 2 putaran.",
  str_skill_desc_320136 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh, dan menyebabkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> pada semua musuh di tile Hijau selama 2 putaran. Musuh akan terkena <color=#00F6FF>2 tumpuk</color> Mortality Mark sebelum Active Skill menimbulkan damage.",
  str_skill_desc_322136 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh, dan menyebabkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> pada semua musuh di tile Hijau selama 2 putaran. Musuh akan terkena <color=#00F6FF>2 tumpuk</color> Mortality Mark sebelum Active Skill menimbulkan damage.",
  str_skill_desc_325136 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh, dan menyebabkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> pada semua musuh di tile Hijau selama 2 putaran. Musuh akan terkena <color=#00F6FF>3 tumpuk</color> Mortality Mark sebelum Active Skill menimbulkan damage.",
  str_skill_passive_desc_410022 = "Meningkatkan damage Active Skill sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410051 = "Meningkatkan damage Active Skill sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410047 = "Meningkatkan Faktor Heal Chain Combo sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410049 = "Ada peluang <color=#00F6FF>{1}</color> untuk meningkatkan damage Chain Combo sebesar <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_410050 = "Meningkatkan damage Chain Combo sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410052 = "Active skill memiliki peluang <color=#00F6FF>{1}</color> untuk memberi musuh <link=\"10006\"><#FFAE07><u>Slow</u></color></link> selama 2 putaran.",
  str_skill_passive_desc_410074 = "Meningkatkan damage Active Skill sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410008 = "Damage Normal Attack Tiny One meningkat sebesar <color=#00F6FF>{1}</color> untuk putaran ini setelah menggunakan Active Skill.",
  str_skill_passive_desc_410007 = "Saat menggunakan Chain Combo, menimbulkan +<color=#00F6FF>{1}</color> damage pada musuh yang pertama terkena serangan dan memberikan 1 tumpukan Poison, bertahan selama 2 putaran.",
  str_skill_passive_desc_410032 = "Setiap sambaran petir memiliki a <color=#00F6FF>15%</color> kesempatan untuk menangani tambahan <color=#00F6FF>{1}</color> kerusakan.",
  str_skill_passive_desc_410053 = "Meningkatkan damage Chain Combo sebesar <color=#00F6FF>{1}</color> pada saat Active Skill siap.",
  str_skill_passive_desc_410058 = "Jika Banner masih ada hingga akhir putaran, memulihkan HP tim sebanyak <color=#00F6FF>{1}</color> kali DEF Amy.",
  str_skill_passive_desc_400035 = "Setelah menggunakan skill gerakan ini, Eho memperoleh <color=#00F6FF>{1}</color> damage Normal Attack yang lebih besar selama putaran berlangsung.",
  str_skill_passive_desc_410035 = "Setelah menggunakan skill gerakan ini, Eho memperoleh <color=#00F6FF>{1}</color> damage Normal Attack yang lebih besar selama putaran berlangsung.",
  str_skill_passive_desc_420035 = "Setelah menggunakan skill gerakan ini, Eho memperoleh <color=#00F6FF>{1}</color> damage Normal Attack yang lebih besar dan damage Chain Combo selama putaran berlangsung.",
  str_skill_passive_desc_410017 = "Setiap kali Aurorian sekutu memukul mundur musuh, Rabbie menimbulkan damage setara dengan <color=#00F6FF>{1}</color> ATK miliknya pada musuh tersebut (damage ini mengabaikan DEF).",
  str_skill_passive_desc_430017 = "Ketika ada Aurorian sekutu yang memukul mundur musuh, Rabbie menimbulkan damage setara dengan <color=#00F6FF>{1}</color> dari ATK miliknya pada musuh tersebut (damage ini mengabaikan DEF). Meningkatkan damage yang mengabaikan DEF sebesar <color=#00F6FF>10%</color> untuk setiap 1 tile yang dilewati musuh yang terpukul mundur.",
  str_skill_passive_desc_410040 = "Memberikan 1 tumpukan Tanda Kelekatan di awal setiap putaran. Setiap tumpukan meningkatkan kemungkinan menimbulkan keterampilan Kombo Rantai <link=\"10002\"> <#FFAE07><u>Membakar</u></color></link> yang berlangsung 2 putaran oleh <color=#00F6FF>{1}</color>. Semua tumpukan dibersihkan pada awal setiap gelombang.",
  str_skill_passive_desc_420040 = "Memberikan 1 tumpukan Tanda Kelekatan di awal setiap putaran. Setiap tumpukan meningkatkan kemungkinan menimbulkan keterampilan Kombo Rantai <link=\"10002\"> <#FFAE07><u>Membakar</u></color></link> yang berlangsung 2 putaran oleh <color=#00F6FF>{1}</color>. Semua tumpukan dibersihkan pada awal setiap gelombang.",
  str_skill_passive_desc_410041 = "Meningkatkan ATK Blanc sebesar <color=#00F6FF>{1}</color> ketika HP penuh.",
  str_skill_passive_desc_420041 = "Meningkatkan ATK Blanc sebesar <color=#00F6FF>{1}</color> ketika HP di atas 70%.",
  str_skill_passive_desc_430041 = "Meningkatkan ATK Blanc sebesar <color=#00F6FF>{1}</color> dan meningkatkan ATK Water Aurorian yang dikerahkan lainnya sebesar <color=#00F6FF>{2}</color> ATK Blanc saat HP di atas 70%.",
  str_skill_passive_desc_410021 = "Meningkatkan kerusakan Chain Combo dengan <color=#00F6FF>{1}</color> ketika Skill Aktif belum siap.",
  str_skill_passive_desc_420021 = "Meningkatkan kerusakan Chain Combo dengan <color=#00F6FF>{1}</color> dan kerusakan Serangan Normal oleh <color=#00F6FF>{2}</color> ketika Skill Aktif belum siap.",
  str_skill_passive_desc_410004 = "Meningkatkan HP Maks tim sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410073 = "Mengeluarkan 1 Chain Combo tambahan di awal garis, menimbulkan <color=#00F6FF>{1}</color> damage normal.",
  str_skill_passive_desc_430073 = "Mengeluarkan 1 Chain Combo tambahan di awal garis, menimbulkan <color=#00F6FF>{1}</color> damage normal. Meningkatkan damage sebesar <color=#00F6FF>100%</color> ketika combo awal dan sebenarnya tumpang tindih.",
  str_skill_passive_desc_410061 = "Memperoleh 1 tumpukan Negativity Mark setiap kali Active Skill digunakan, hingga <color=#00F6FF>3</color> tumpukan. Setiap tumpukan meningkatkan jumlah serangan Active Skill sebanyak 1 dan mengurangi damage final sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420061 = "Memperoleh 1 tumpukan Negativity Mark setiap kali Active Skill digunakan, hingga <color=#00F6FF>5</color> tumpukan. Setiap tumpukan meningkatkan jumlah serangan Active Skill sebanyak 1, mengurangi damage final sebesar <color=#00F6FF>{1}</color>. Setiap Mark meningkatkan damage Chain Combo sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430061 = "Memperoleh 1 tumpukan Negativity Mark setiap kali Active Skill digunakan, hingga <color=#00F6FF>5</color> tumpukan. Setiap tumpukan meningkatkan jumlah serangan Active Skill sebanyak 1, mengurangi damage final sebesar <color=#00F6FF>{1}</color>. Setiap tumpukan meningkatkan damage Chain Combo sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_414061 = "Memperoleh 1 tumpukan Negativity Mark setiap kali Active Skill digunakan, hingga <color=#00F6FF>3</color> tumpukan. Setiap tumpukan meningkatkan jumlah serangan Active Skill sebanyak 1 dan mengurangi damage final sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_424061 = "Memperoleh 1 tumpukan Negativity Mark setiap kali Active Skill digunakan, hingga <color=#00F6FF>5</color> tumpukan. Setiap tumpukan meningkatkan jumlah serangan Active Skill sebanyak 1, mengurangi damage final sebesar <color=#00F6FF>{1}</color>. Setiap Mark meningkatkan damage Chain Combo sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_434061 = "Memperoleh 1 tumpukan Negativity Mark setiap kali Active Skill digunakan, hingga <color=#00F6FF>5</color> tumpukan. Setiap tumpukan meningkatkan jumlah serangan Active Skill sebanyak 1, mengurangi damage final sebesar <color=#00F6FF>{1}</color>. Setiap tumpukan meningkatkan damage Chain Combo sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410054 = "Setiap kali lentera menghilang di akhir durasinya, lentera itu akan mengeluarkan cahaya yang menyinari <color=#00F6FF>1 klaster di sekitar</color>, menimbulkan <color=#00F6FF>{1}</color> damage dan ada <color=#00F6FF>{2}</color> peluang untuk menyebabkan <link=\"10005\"><#FFAE07><u>Blind</u></color></link> pada musuh selama 1 putaran.",
  str_skill_passive_desc_430054 = "Ketika ada lentera, lentera itu akan mengeluarkan cahaya yang menyinari <color=#00F6FF>1 klaster di sekitar</color> di akhir setiap putaran, menimbulkan <color=#00F6FF>{1}</color> damage dan ada <color=#00F6FF>{2}</color> peluang untuk menyebabkan <link=\"10005\"><#FFAE07><u>Blind</u></color></link> pada musuh selama 1 putaran.",
  str_skill_passive_desc_410016 = "Memperoleh 1 tumpukan isi setiap kali melewati tile Kuning, hingga 99 tumpukan. Setiap tumpukan meningkatkan damage Active Skill sebesar <color=#00F6FF>{1}</color>. Penggunaan Active Skill akan menghilangkan semua tumpukan.",
  str_skill_passive_desc_410046 = "Setiap tumpukan Laughter Mark akan meningkatkan damage Normal Attack Thunder Aurorian sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430046 = "Pembunuhan musuh dengan Laughter Mark akan memberikan <color=#00F6FF>1</color> tumpukan tambahan ke semua musuh lain. Setiap Mark meningkatkan damage Normal Attack Thunder Aurorian sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410044 = "Setiap kali Chain Combo menimbulkan damage pada semua musuh, Thunder Aurorian memperoleh bonus attack sebesar <color=#00F6FF>{1}</color> ATK Vivian selama putaran berlangsung.",
  str_skill_passive_desc_430044 = "Setiap kali Chain Combo menimbulkan damage pada semua musuh, Water, Thunder, dan Illumina Aurorian memperoleh bonus ATK sebesar <color=#00F6FF>{1}</color> ATK Vivian selama 2 putaran.",
  str_skill_passive_desc_410048 = "Meningkatkan damage Dayna pada musuh yang menduduki tile Kuning sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430048 = "Meningkatkan kerusakan Dayna terhadap musuh yang menduduki ubin Kuning <color=#00F6FF>{1}</color>. Juga memberikan rekan setim Thunder Aurorian <color=#00F6FF>50%</color> dari bonus itu.",
  str_skill_passive_desc_410009 = "Pada awal setiap putaran, ada <color=#00F6FF>{1}</color> peluang untuk menimbulkan <link=\"10003\"><#FFAE07><u>Fright</u></color></link> pada musuh selama 1 putaran.",
  str_skill_passive_desc_420009 = "Pada awal setiap putaran, musuh memiliki <color=#00F6FF>{1}</color> peluang untuk terkena <link=\"10003\"><#FFAE07><u>Fright</u></color></link> selama 1 putaran. Memicu ledakan setiap kali membunuh musuh yang mengalami <link=\"10003\"><#FFAE07><u>Frightened</u></color></link>, menimbulkan damage sebesar <color=#00F6FF>10%</color> HP Maks pada musuh dalam 1 klaster di sekitar.",
  str_skill_passive_desc_410012 = "Setiap Chain Combo yang mengenai musuh memberikan 1 tumpukan Judgment Mark. Setiap tumpukan meningkatkan DEF sebesar <color=#00F6FF>{1}</color>. Mark akan menghilang di akhir putaran.",
  str_skill_passive_desc_420012 = "Setiap Chain Combo yang mengenai musuh memberikan 1 tumpukan Judgment Mark (2, jika Active Skill). Setiap tumpukan meningkatkan DEF sebesar <color=#00F6FF>{1}</color>. Tetap mempertahankan 50% tumpukan di akhir putaran.",
  str_skill_passive_desc_430012 = "Setiap Chain Combo yang mengenai musuh memberikan 1 tumpukan Judgment Mark (serangan Active Skill memberikan 2 tumpukan). Setiap tumpukan meningkatkan ATK sebesar <color=#00F6FF>3%</color> dan DEF sebesar <color=#00F6FF>{1}</color>. Tetap mempertahankan 50% tumpukan di akhir putaran.",
  str_skill_passive_desc_410013 = "Pada saat shield menghilang, mengonversi <color=#00F6FF>{1}</color> Shield yang tersisa menjadi HP.",
  str_skill_passive_desc_430013 = "Pada saat shield menghilang, mengonversi <color=#00F6FF>{1}</color> Shield yang tersisa menjadi HP. Meningkatkan DEF Noah sebesar <color=#00F6FF>50%</color> jika Shield sudah ada.",
  str_skill_passive_desc_410018 = "Chain Combo menimbulkan <color=#00F6FF>{1}</color> damage yang ditingkatkan. Semakin dekat jarak musuh, damage akan semakin tinggi. Jarak yang melampaui 3 tile tidak akan memberikan bonus damage.",
  str_skill_passive_desc_420018 = "Makin dekat jarak musuh, makin tinggi damage Active Skill dan Chain Combo (hingga <color=#00F6FF>{1}</color>). Jarak yang melampaui 3 klaster tidak akan memberikan bonus damage.",
  str_skill_passive_desc_430018 = "Meningkatkan ATK sebesar <color=#00F6FF>5%</color> untuk setiap musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Semakin dekat musuh, semakin tinggi damage Skill Aktif dan Combo Rantai (hingga <color=#00F6FF>{1}</color>). Jarak di luar 3 kluster tidak memberikan bonus kerusakan.",
  str_skill_passive_desc_410033 = "Vice mendapatkan 1 tumpukan Locking Mark setiap kali dia menimbulkan damage. Setiap tumpukan meningkatkan damage sebesar <color=#00F6FF>{1}</color>. Semua tumpukan akan dihilangkan pada akhir putaran.",
  str_skill_passive_desc_430033 = "Vice mendapatkan 1 tumpukan Locking Mark setiap kali dia menimbulkan damage. Setiap tumpukan meningkatkan damage sebesar <color=#00F6FF>{1}</color> dan damage Chain Combo sebesar <color=#00F6FF>{2}</color>. Semua tumpukan akan dihilangkan pada akhir putaran.",
  str_skill_passive_desc_410036 = "Memberikan 1 Wolf Mark pada awal setiap putaran. Ketika diserang untuk pertama kalinya, memakai 1 Mark untuk menimbulkan damage setara dengan <color=#00F6FF>{1}</color> ATK Hydrad kembali pada target (damage ini mengabaikan DEF). Semua Wolf Mark dihapus pada akhir putaran.",
  str_skill_passive_desc_420036 = "Memberikan 1 Wolf Mark pada awal setiap putaran. Ketika diserang, memakai 1 Mark untuk menimbulkan damage setara dengan <color=#00F6FF>{1}</color> ATK Hydrad kembali pada target (damage ini mengabaikan DEF). Wolf Mark <color=#00F6FF>tidak dihapus</color> pada akhir putaran.",
  str_skill_passive_desc_410010 = "Pada saat memicu <link=\"30010\"><#FFAE07><u>Aurora Time</u></color></link>, HP tim langsung pulih sebesar <color=#00F6FF>{1}</color> HP Maks Louise dan meningkatkan DEF sebesar <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_420010 = "Pada saat memicu <link=\"30010\"><#FFAE07><u>Aurora Time</u></color></link>, HP tim langsung dipulihkan sebesar <color=#00F6FF>{1}</color> HP Maks Louise dan meningkatkan DEF sebesar <color=#00F6FF>50%</color> selama 2 putaran.",
  str_skill_passive_desc_410014 = "Meningkatkan DEF Schwartz sebesar <color=#00F6FF>{1}</color> untuk setiap Thunder atau Lumopolis Aurorian yang dikerahkan.",
  str_skill_passive_desc_430014 = "Meningkatkan DEF Schwartz sebesar {1} untuk setiap Thunder atau Lumopolis Aurorian yang dikerahkan (juga meningkatkan ATK setara dengan DEF yang diberikan).",
  str_skill_passive_desc_410078 = "Meningkatkan damage Robyn pada musuh yang menduduki tile Hijau sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430078 = "Meningkatkan kerusakan Robyn terhadap musuh yang menempati ubin Hijau <color=#00F6FF>{1}</color>. Juga memberikan rekan setim Forest Aurorian <color=#00F6FF>50%</color> dari bonus itu.",
  str_skill_passive_desc_410076 = "Setelah menggunakan Chain Combo, menyentuh <color=#00F6FF>4 musuh yang berdekatan dalam bentuk silang</color> dan menimbulkan <link=\"10003\"><#FFAE07><u>Fright</u></color></link> selama 1 putaran jika HP musuh kurang dari <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420076 = "Setelah menggunakan Chain Combo, menimbulkan <link=\"10003\"><#FFAE07><u>Fright</u></color></link> pada 1 musuh dengan HP paling rendah (HP kurang dari <color=#00F6FF>{1}</color>) dalam <color=#00F6FF>4 tile dalam bentuk silang</color> selama 1 putaran. Membunuh musuh yang terkena <link=\"10003\"><#FFAE07><u>Frightened</u></color></link> memiliki peluang <color=#00F6FF>50%</color> untuk menimbulkan <link=\"10003\"><#FFAE07><u>Fright</u></color></link> pada musuh dalam <color=#00F6FF>4 tile dalam bentuk silang</color>.",
  str_skill_passive_desc_410042 = "Normal Attack kini dapat dilancarkan secara diagonal dan menimbulkan <color=#00F6FF>{1}</color> damage.",
  str_skill_passive_desc_420042 = "Normal Attack kini dapat dilancarkan secara diagonal untuk menimbulkan <color=#00F6FF>{1}</color> damage dan memberikan 1 Firepower Mark yang bertahan selama 2 putaran. Normal Attack Barton menimbulkan <color=#00F6FF>10%</color> damage tambahan pada musuh yang memiliki Mark tersebut.",
  str_skill_passive_desc_430042 = "Normal Attack kini dapat dilancarkan secara diagonal untuk menimbulkan <color=#00F6FF>{1}</color> damage dan memberikan 1 Firepower Mark yang bertahan selama 2 putaran. Attack Barton menimbulkan <color=#00F6FF>10%</color> <color=#00F6FF>damage</color> tambahan pada musuh yang memiliki Mark tersebut.",
  str_skill_passive_desc_410001 = "Memberi Tanda Cermin di awal pertempuran. Selama Tanda itu ada, Nikinis keuntungan <color=#00F6FF>{1}</color> peningkatan DEF. Tanda itu menghilang sekali Nikinis kehilangan HP. Mirror Mark dapat disegarkan oleh <color=#00F6FF>menggunakan Skill Aktif</color>.",
  str_skill_passive_desc_420001 = "Memberi Tanda Cermin di awal pertempuran. Selama Tanda itu ada, Nikinis keuntungan <color=#00F6FF>{1}</color> peningkatan DEF. Tanda itu menghilang sekali Nikinis kehilangan HP. Mirror Mark dapat disegarkan oleh <color=#00F6FF>menggunakan Skill Aktif atau memasuki Aurora Time</color>.",
  str_skill_passive_desc_410011 = "Normal Attack memberikan 1 tumpukan Dragontooth Mark, hingga <color=#00F6FF>4</color> tumpukan. Setiap tumpukan meningkatkan damage Chain Combo final Sharona sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430011 = "Normal Attack memberikan 1 tumpukan Dragontooth Mark, hingga <color=#00F6FF>6</color> tumpukan. Setiap tumpukan meningkatkan <color=#00F6FF>damage Active Skill</color> dan damage Chain Combo final Sharona sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_440011 = "Serangan normal menerapkan 1 tumpukan Dragontooth Mark, hingga <color=#00F6FF>7</color> tumpukan. Setiap tumpukan meningkatkan milik Sharona <color=#00F6FF>Keterampilan Aktif</color> dan kerusakan akhir Chain Combo oleh <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410019 = "Victoria memulihkan <color=#00F6FF>{1}</color> HP Maks per tumpukan <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> setiap kali Chain Combo miliknya menyerang musuh yang terkena <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link>.",
  str_skill_passive_desc_420019 = "Victoria memulihkan <color=#00F6FF>{1}</color> HP Maks per tumpukan <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> setiap kali Chain Combo miliknya menyerang musuh yang terkena <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link>.",
  str_skill_passive_desc_430019 = "Victoria memulihkan HP setara <color=#00F6FF>{1}</color> HP Maks miliknya per tumpukan <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> setiap kali dia menyerang musuh yang terkena <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> menggunakan Chain Combo. Efek pemulihan ini akan meningkat sebesar <color=#00F6FF>50%</color> jika persentase HP musuh lebih tinggi dari tim.",
  str_skill_passive_desc_410023 = "Memperoleh 1 tumpukan Shiver Mark ketika menggunakan Chain Combo, hingga <color=#00F6FF>5</color> tumpukan. Setiap tumpukan meningkatkan damage Active Skill sebesar <color=#00F6FF>{1}</color>. Penggunaan Active Skill akan memberikan <link=\"10003\"><#FFAE07><u>Fright</u></color></link> pada sejumlah musuh setara dengan jumlah tumpukan selama <color=#00F6FF>1</color> putaran. Penggunaan Active Skill <color=#00F6FF>tidak akan menyingkirkan tumpukan</color>.",
  str_skill_passive_desc_430023 = "Memperoleh 1 tumpukan Shiver Mark ketika menggunakan Chain Combo, hingga <color=#00F6FF>5</color> tumpukan. Setiap tumpukan meningkatkan damage Active Skill sebesar <color=#00F6FF>{1}</color>. Penggunaan Active Skill akan memberikan <link=\"10003\"><#FFAE07><u>Fright</u></color></link> pada sejumlah musuh setara dengan jumlah tumpukan selama <color=#00F6FF>1</color> putaran. Penggunaan Active Skill ini <color=#00F6FF>tidak akan menyingkirkan tumpukan</color> Jika sudah ada 5 tumpukan saat menggunakan Chain Combo, Chain Combo ini akan menimbulkan damage tambahan pada 1 musuh terdekat.",
  str_skill_passive_desc_410002 = "Hiiro memasuki posisi Duel pada awal putaran. Normal Attack berikutnya menimbulkan <color=#00F6FF>{1}</color> damage pada musuh dan <color=#00F6FF>{2}</color> damage pada musuh di <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitar.",
  str_skill_passive_desc_420002 = "Hiiro memasuki posisi Duel pada awal putaran atau setiap kali melewati <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Normal Attack berikutnya menimbulkan <color=#00F6FF>{1}</color> damage pada musuh dan <color=#00F6FF>{2}</color> damage pada musuh di <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitar.",
  str_skill_passive_desc_430002 = "Hiiro memasuki posisi Duel pada awal putaran atau setiap kali melewati <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Normal Attack berikutnya menimbulkan <color=#00F6FF>{1}</color> damage pada musuh dan <color=#00F6FF>{2}</color> damage pada musuh dalam <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitar. ATK meningkat sebesar <color=#00F6FF>4%</color> pada putaran ini per penggunaan One with the Duel, hingga maksimum <color=#00F6FF>20%</color>.",
  str_skill_passive_desc_410005 = "Mia memperoleh 1 tumpukan Soul pada saat membunuh musuh dengan menggunakan Active Skill, hingga 5 tumpukan. Setiap tumpukan akan mengeluarkan Blast yang dapat menimbulkan <color=#00F6FF>{1}</color> damage ATK.",
  str_skill_passive_desc_420005 = "Mia memperoleh 1 tumpukan Soul pada saat membunuh musuh dengan menggunakan Active Skill, hingga 5 tumpukan. Setiap tumpukan akan mengeluarkan Soul Blast yang dapat menimbulkan <color=#00F6FF>{1}</color> damage ATK dan meningkatkan damage Normal Attack Mia sebesar <color=#00F6FF>3%</color> dan Chain Combo sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430005 = "Mia mendapatkan 1 tumpukan Jiwa untuk setiap musuh yang dikalahkan <color=#00F6FF>Aurora</color> di lapangan dengan Keterampilan Aktif mereka, hingga <color=#00F6FF>7</color> tumpukan. Setiap tumpukan melepaskan ledakan yang menghasilkan <color=#00F6FF>{1}</color> Kerusakan ATK pada satu target, sebagai tambahan meningkatkan Serangan Normal Mia <color=#00F6FF>3%</color>, dan kerusakan Chain Combo oleh <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410006 = "Carleen mendapatkan +<color=#00F6FF>{1}</color> ATK dasar untuk setiap 1 tile Water yang dilalui atau ditempati sepanjang putaran (hingga <color=#00F6FF>{2}</color>).",
  str_skill_passive_desc_420006 = "Carleen mendapatkan +<color=#00F6FF>{1}</color> basic ATK untuk setiap 1 tile Water yang dilalui atau ditempati sepanjang putaran (hingga <color=#00F6FF>{2}</color>). Efek menjadi berlipat ganda setelah menggunakan Active Skill.",
  str_skill_passive_desc_430006 = "Carleen mendapatkan +<color=#00F6FF>{1}</color> ATK untuk setiap 1 tile Water yang dilalui atau ditempati sepanjang putaran (hingga <color=#00F6FF>{2}</color>). Efek menjadi dua kali lipat setelah menggunakan Active Skill. Normal Attack mendapatkan Pierce pada tile Water dan menimbulkan <color=#00F6FF>40%</color> damage pada target yang berada di 1 tile di belakang musuh.",
  str_skill_passive_desc_410025 = "Menambahkan damage yang mengabaikan DEF setara dengan <color=#00F6FF>{1}</color> dari ATK untuk Normal Attack.",
  str_skill_passive_desc_430025 = "Normal Attack <color=#00F6FF>kini bisa menyerang secara diagonal</color>. Menambahkan damage yang mengabaikan DEF setara dengan <color=#00F6FF>{1}</color> dari ATK untuk Normal Attack.",
  str_skill_passive_desc_410026 = "Setiap tumpukan <link=\"10002\"><#FFAE07><u>Burn</u></color></link> meningkatkan damage Fire Aurorian sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430026 = "Pada awal setiap putaran, menerapkan 1 tumpukan <link=\"10002\"><#FFAE07><u>Burn</u></color></link> pada musuh yang menduduki tile Merah selama 2 putaran. Setiap tumpukan <link=\"10002\"><#FFAE07><u>Burn</u></color></link> meningkatkan damage Fire Aurorian sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410028 = "Setiap tile Biru yang dibuat di peta dapat memulihkan HP tim sebesar <color=#00F6FF>{1}</color> dari HP Maks Raphael.",
  str_skill_passive_desc_420028 = "Setiap tile Biru yang dibuat di peta dapat memulihkan HP tim sebesar <color=#00F6FF>{1}</color> dari HP Maks Raphael. Semakin rendah HP tim, efektivitas penyembuhan menjadi semakin tinggi, hingga dapat mencapai <color=#00F6FF>bonus 100%</color>.",
  str_skill_passive_desc_410029 = "Setidaknya 1 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> akan dibuat per <color=#00F6FF>{1}</color> tile Hijau yang dilalui pada putaran ini.",
  str_skill_passive_desc_430029 = "Setidaknya 1 <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> akan dibuat per <color=#00F6FF>{1}</color> tile Hijau yang dilalui pada putaran ini, dan tile Hijau akan dibuat enhanced terlebih dulu.",
  str_skill_passive_desc_410038 = "Memberikan 1 Magnetic Storm per 3 putaran. Chain Combo berikutnya akan menimbulkan <color=#00F6FF>{1}</color> damage tambahan pada 1 musuh dalam area serangan dan memberikan <link=\"10004\"><#FFAE07><u>Paralysis</u></color></link> selama 1 putaran.",
  str_skill_passive_desc_420038 = "Memberikan 1 Magnetic Storm per 3 putaran. Chain Combo berikutnya akan menimbulkan <color=#00F6FF>{1}</color> damage tambahan pada 1 musuh dalam area serangan dan memberikan <link=\"10004\"><#FFAE07><u>Paralysis</u></color></link> selama 1 putaran. Ada peluang <color=#00F6FF>50%</color> untuk menyerang musuh lain.",
  str_skill_passive_desc_430038 = "Memberikan 1 Magnetic Storm per 3 putaran pada awal pertempuran. Chain Combo berikutnya akan menimbulkan <color=#00F6FF>{1}</color> damage tambahan pada 1 musuh dalam area serangan dan memberikan <link=\"10004\"><#FFAE07><u>Paralysis</u></color></link>. Ada peluang <color=#00F6FF>50%</color> untuk menyerang musuh lain.",
  str_skill_passive_desc_410077 = "Aurorian yang telah menggunakan Active Skill akan menerima bonus di putaran ini, setara dengan <color=#00F6FF>{1}</color> dari ATK dasar Bethlehem.",
  str_skill_passive_desc_420077 = "Aurorian yang telah menggunakan Skill Aktif di putaran ini akan menerima bonus sebesar <color=#00F6FF>{1}</color> dari ATK dasar Bethlehem. Saat memasuki Aurora Time, tim akan menerima bonus di putaran ini sebesar <color=#00F6FF>{2}</color> dari ATK dasar Bethlehem.",
  str_skill_passive_desc_430077 = "Aurorian yang telah menggunakan Active Skill akan menerima bonus setara dengan <color=#00F6FF>{1}</color> dari ATK dasar Bethlehem di putaran ini. Bethlehem juga mendapatkan bonus ATK dasar sebesar <color=#00F6FF>{2}</color>. Bonus ATK ini yang diperoleh Bethlehem dalam putaran yang sama dapat ditumpuk. Setelah memasuki Aurora Time, tim mendapatkan bonus tambahan di putaran ini setara dengan <color=#00F6FF>{2}</color> dari ATK dasar Bethlehem.",
  str_skill_passive_desc_400092 = "Saat musuh yang memiliki Mark tewas, mendapatkan HP setara dengan <color=#00F6FF>{1}</color> HP Maks musuh dan <link=\"30007\"><#FFAE07><u>efek pemulihan</u></color></link>.",
  str_skill_passive_desc_410092 = "Saat musuh yang memiliki Mark tewas, mendapatkan HP setara dengan <color=#00F6FF>{1}</color> HP Maks musuh dan <link=\"30007\"><#FFAE07><u>efek pemulihan</u></color></link>.",
  str_skill_passive_desc_420092 = "Saat musuh yang memiliki Mark tewas, mendapatkan HP setara dengan <color=#00F6FF>{1}</color> HP Maks musuh dan <link=\"30007\"><#FFAE07><u>efek pemulihan</u></color></link>. Hingga 1 tile yang ditempati musuh akan diubah menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_passive_desc_400075 = "Normal Attack memiliki peluang <color=#00F6FF>{1}</color> untuk memberikan 1 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_passive_desc_410075 = "Normal Attack memiliki peluang <color=#00F6FF>{1}</color> untuk memberikan 1 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_passive_desc_430075 = "Serangan normal dapat menargetkan musuh <color=#00F6FF>ubin diagonal</color> dan memiliki <color=#00F6FF>{1}</color> kemungkinan menimbulkan 1 tumpukan <link=\"10001\"><#FFAE07><u>Racun</u></color></link> untuk 2 putaran.",
  str_skill_passive_desc_400086 = "Memulihkan HP setara dengan <color=#00F6FF>{1}</color> DEF Uriah pada saat melalui <link=\"20001\"><#FFAE07><u>enhanced</u></color></link> tile Hijau.",
  str_skill_passive_desc_410086 = "Memulihkan HP setara dengan <color=#00F6FF>{1}</color> DEF Uriah pada saat melalui <link=\"20001\"><#FFAE07><u>enhanced</u></color></link> tile Hijau.",
  str_skill_passive_desc_400068 = "Saat Aurorian berteleportasi, Wendy memperoleh 1 tumpukan Mark untuk tiap klaster di antara lokasi awal Aurorian dan tujuan teleportasinya. Tiap tumpukan meningkatkan damage Normal Attack Wendy berikutnya sebanyak <color=#00F6FF>{1}</color>. Melancarkan Normal Attack akan menghapus Mark.",
  str_skill_passive_desc_410068 = "Saat Aurorian berteleportasi, Wendy memperoleh 1 tumpukan Mark untuk tiap klaster di antara lokasi awal Aurorian dan tujuan teleportasinya. Tiap tumpukan meningkatkan damage Normal Attack Wendy berikutnya sebanyak <color=#00F6FF>{1}</color>. Melancarkan Normal Attack akan menghapus Mark.",
  str_skill_passive_desc_430068 = "Ketika seorang Aurorian berteleportasi, Wendy mendapatkan 1 Mark stack untuk setiap cluster antara lokasi awal Aurorian dan tujuan teleportasi mereka. Setiap tumpukan meningkatkan kerusakan serangan normal berikutnya oleh Wendy <color=#00F6FF>{1}</color>. Wendy mempertahankan <color=#00F6FF>30%</color> tumpukan Mark ini setelah meluncurkan serangan normal.",
  str_skill_passive_desc_400082 = "Chain Combo memiliki peluang <color=#00F6FF>{1}</color> untuk memberikan 1 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_passive_desc_410082 = "Chain Combo memiliki peluang <color=#00F6FF>{1}</color> untuk memberikan 1 tumpukan <link=\"10001\"><#FFAE07><u>Poison</u></color></link> selama 2 putaran.",
  str_skill_passive_desc_400057 = "Pada awal setiap putaran, tim memulihkan HP setara dengan <color=#00F6FF>{1}</color> ATK Philyshy dan <color=#00F6FF>{2}</color> HP tim yang hilang.",
  str_skill_passive_desc_410057 = "Pada awal setiap putaran, tim memulihkan HP setara dengan <color=#00F6FF>{1}</color> ATK Philyshy dan <color=#00F6FF>{2}</color> HP tim yang hilang.",
  str_skill_passive_desc_430057 = "Pada awal setiap putaran, tim memulihkan HP setara dengan <color=#00F6FF>{1}</color> ATK Philyshy dan <color=#00F6FF>{2}</color> HP tim yang hilang. Untuk setiap <color=#00F6FF>5%</color> HP tim yang hilang, ATK Philyshy meningkat sebesar <color=#00F6FF>1%</color>.",
  str_skill_passive_desc_400091 = "Saat menggunakan Active Skill atau Chain Combo, mengurangi ATK musuh dalam <color=#00F6FF>1 klaster di sekitar</color> unit sebesar <color=#00F6FF>{1}</color> selama 1 putaran.",
  str_skill_passive_desc_410091 = "Saat menggunakan Active Skill atau Chain Combo, mengurangi ATK musuh dalam <color=#00F6FF>1 klaster di sekitar</color> unit sebesar <color=#00F6FF>{1}</color> selama 1 putaran.",
  str_skill_passive_desc_420091 = "Saat menggunakan Active Skill atau Chain Combo, mengurangi ATK musuh dalam <color=#00F6FF>1 klaster di sekitar</color> unit sebesar <color=#00F6FF>{1}</color> selama 1 putaran.",
  str_skill_passive_desc_430091 = "Saat menggunakan Active Skill atau Chain Combo, mengurangi ATK dan DEF musuh dalam <color=#00F6FF>2 klaster di sekitar</color> unit sebesar <color=#00F6FF>{1}</color> selama 1 putaran.",
  str_skill_passive_desc_400079 = "Saat diserang oleh target dengan persentase HP yang lebih tinggi, <color=#00F6FF>{1}</color> dari ATK Michenny akan dikonversi menjadi DEF.",
  str_skill_passive_desc_410079 = "Saat diserang oleh target dengan persentase HP yang lebih tinggi, <color=#00F6FF>{1}</color> dari ATK Michenny akan dikonversi menjadi DEF.",
  str_skill_passive_desc_420079 = "Saat diserang oleh target dengan persentase HP yang lebih tinggi, mengonversi <color=#00F6FF>{1}</color> dari ATK Michenny menjadi DEF. Saat Michenny menimbulkan damage, mengonversi persentasi DEF Michenny yang sama menjadi ATK.",
  str_skill_passive_desc_400085 = "Saat Active Skill menimbulkan damage pada musuh, damage final meningkat sebesar <color=#00F6FF>10%</color> untuk setiap <color=#00F6FF>{1}</color> HP musuh yang hilang.",
  str_skill_passive_desc_410085 = "Saat Active Skill menimbulkan damage pada musuh, damage final meningkat sebesar <color=#00F6FF>10%</color> untuk setiap <color=#00F6FF>{1}</color> HP musuh yang hilang.",
  str_skill_passive_desc_400089 = "Memberikan 1 Gold Marsh Mark pada saat melalui <link=\"30001\"><#FFAE07><u>tile Prism</u></color></link>. Setiap tumpukan Gold Marsh Mark meningkatkan damage Chain Combo sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410089 = "Memberikan 1 Gold Marsh Mark pada saat melalui <link=\"30001\"><#FFAE07><u>tile Prism</u></color></link>. Setiap tumpukan Gold Marsh Mark meningkatkan damage Chain Combo sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420089 = "Memberikan 1 Gold Marsh Mark pada saat melalui <link=\"30001\"><#FFAE07><u>tile Prism</u></color></link>. Setiap tumpukan Gold Marsh Mark meningkatkan damage Chain Combo sebesar <color=#00F6FF>{1}</color> dan damage Normal Attack sebesar <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_430089 = "Memberikan 1 Gold Marsh Mark pada saat melalui <link=\"30001\"><#FFAE07><u>tile Prism</u></color></link>. Setiap tumpukan Gold Marsh Mark meningkatkan damage Chain Combo sebesar <color=#00F6FF>{1}</color> dan damage Normal Attack sebesar <color=#00F6FF>3%</color>. Pada saat memicu <link=\"30010\"><#FFAE07><u>Aurora Time</u></color></link>, tile awal akan dikonversi menjadi <link=\"30001\"><#FFAE07><u>tile Prism</u></color></link>.",
  str_skill_passive_desc_400027 = "Memberikan 1 tumpukan Silent Thunder Mark pada awal setiap putaran. Normal Attack memerlukan 1 tumpukan Silent Thunder Mark untuk menimbulkan damage ekstra pada musuh setara dengan <color=#00F6FF>{1}</color> HP saat ini.",
  str_skill_passive_desc_410027 = "Memberikan 1 tumpukan Silent Thunder Mark pada awal setiap putaran. Normal Attack memerlukan 1 tumpukan Silent Thunder Mark untuk menimbulkan damage ekstra pada musuh setara dengan <color=#00F6FF>{1}</color> HP saat ini.",
  str_skill_passive_desc_420027 = "Memberikan 1 tumpukan Silent Thunder Mark pada awal setiap putaran dan saat menggunakan Active Skill atau Chain Combo. Normal Attack memerlukan 1 tumpukan Silent Thunder Mark untuk menimbulkan damage ekstra pada musuh setara dengan <color=#00F6FF>{1}</color> HP saat ini.",
  str_skill_passive_desc_400060 = "Pada saat berada di status Noon, serangan normal menimbulkan <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>damage splash</u></color></link> pada semua target di <color=#00F6FF>4 tile dalam bentuk silang</color> di sekeliling musuh.",
  str_skill_passive_desc_410060 = "Pada saat berada di status Noon, serangan normal menimbulkan <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>damage splash</u></color></link> pada semua target di <color=#00F6FF>4 tile dalam bentuk silang</color> di sekeliling musuh.",
  str_skill_passive_desc_420060 = "Pada saat berada di status Noon, meningkatkan damage serangan normal sebesar <color=#00F6FF>20%</color> dan serangan normal menimbulkan <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>damage splash</u></color></link> pada semua target di <color=#00F6FF>4 tile dalam bentuk silang</color> di sekeliling musuh.",
  str_skill_passive_desc_430060 = "Pada saat berada di status Noon, meningkatkan damage serangan normal sebesar <color=#00F6FF>20%</color> dan serangan normal menimbulkan <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>damage splash</u></color></link> pada semua target di <color=#00F6FF>4 tile dalam bentuk silang</color> di sekeliling musuh.",
  str_skill_passive_desc_400064 = "Bisa <link=\"30008\"><#FFAE07><u>menyimpan Ammo</u></color></link>. Setiap kali Chain Combo menimbulkan damage, 1 Ammo akan digunakan (hingga maksimal <color=#00F6FF>3</color> Ammo bisa digunakan dalam status Overload). Untuk setiap Ammo yang digunakan, damage final meningkat sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410064 = "Bisa <link=\"30008\"><#FFAE07><u>menyimpan Ammo</u></color></link>. Setiap kali Chain Combo menimbulkan damage, 1 Ammo akan digunakan (hingga maksimal <color=#00F6FF>3</color> Ammo bisa digunakan dalam status Overload). Untuk setiap Ammo yang digunakan, damage final meningkat sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430064 = "<link=\"30009\"><#FFAE07><u>Peluru dapat disimpan</u></color></link>. Saat Chain Combo menimbulkan damage, menggunakan 1 peluru dan meningkatkan damage final sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400070 = "Normal Attack memiliki peluang <color=#00F6FF>{1}</color> untuk memicu 1 Red Dragon Attack yang menimbulkan damage setara dengan <color=#00F6FF>50%</color> damage Normal Attack Leona.",
  str_skill_passive_desc_410070 = "Normal Attack memiliki peluang <color=#00F6FF>{1}</color> untuk memicu 1 Red Dragon Attack yang menimbulkan damage setara dengan <color=#00F6FF>50%</color> damage Normal Attack Leona.",
  str_skill_passive_desc_420070 = "Normal Attack memiliki peluang <color=#00F6FF>{1}</color> untuk memicu 1 Red Dragon Attack yang menimbulkan damage setara dengan <color=#00F6FF>50%</color> damage Normal Attack Leona, dan memberikan 1 tumpukan <link=\"10002\"><#FFAE07><u>Burning</u></color></link> selama 2 putaran.",
  str_skill_passive_desc_400088 = "Meningkatkan damage Chain Combo Maggie sebesar <color=#00F6FF>{1}</color> setelah setiap <color=#00F6FF>10</color> combo.",
  str_skill_passive_desc_410088 = "Meningkatkan damage Chain Combo Maggie sebesar <color=#00F6FF>{1}</color> setelah setiap <color=#00F6FF>10</color> combo.",
  str_skill_passive_desc_420088 = "Meningkatkan damage Chain Combo Maggie sebesar <color=#00F6FF>{1}</color> setelah setiap <color=#00F6FF>10</color> combo dan mengurangi jumlah tile pemicu combo sebanyak <color=#00F6FF>1</color>.",
  str_skill_passive_desc_430088 = "Meningkatkan damage Chain Combo Maggie sebesar <color=#00F6FF>{1}</color> setelah setiap <color=#00F6FF>8</color> combo dan mengurangi jumlah tile pemicu combo sebanyak <color=#00F6FF>1</color>.",
  str_skill_passive_desc_400084 = "Setelah menggunakan Chain Combo, mengurangi ATK musuh dalam <color=#00F6FF>1 klaster di sekitar</color> unit sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410084 = "Setelah menggunakan Chain Combo, mengurangi ATK musuh dalam <color=#00F6FF>1 klaster di sekitar</color> unit sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420084 = "Setelah menggunakan Chain Combo, mengurangi ATK musuh dalam <color=#00F6FF>2 klaster di sekitar</color> unit sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400090 = "Meningkatkan damage Barbara sebesar <color=#00F6FF>{1}</color> pada musuh yang menduduki tile Merah.",
  str_skill_passive_desc_410090 = "Meningkatkan damage Barbara sebesar <color=#00F6FF>{1}</color> pada musuh yang menduduki tile Merah.",
  str_skill_passive_desc_430090 = "Meningkatkan kerusakan Barbara terhadap musuh yang menduduki ubin Merah <color=#00F6FF>{1}</color>. Juga memberikan Fire Aurorian rekan satu tim <color=#00F6FF>50%</color> dari bonus itu.",
  str_skill_passive_desc_400045 = "ATK dan DEF Nails meningkat ketika persentase HP berkurang, memberikan bonus hingga <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410045 = "ATK dan DEF Nails meningkat ketika persentase HP berkurang, memberikan bonus hingga <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400081 = "Setelah menggunakan Active Skill, ATK Fire Aurorian meningkat setara dengan <color=#00F6FF>{1}</color> ATK Brock untuk setiap musuh dalam <color=#00F6FF>1 klaster di sekitar</color> unit.",
  str_skill_passive_desc_410081 = "Setelah menggunakan Active Skill, ATK Fire Aurorian meningkat setara dengan <color=#00F6FF>{1}</color> ATK Brock untuk setiap musuh dalam <color=#00F6FF>1 klaster di sekitar</color> unit.",
  str_skill_passive_desc_430081 = "Setelah menggunakan Active Skill, ATK Fire Aurorian meningkat setara dengan <color=#00F6FF>{1}</color> ATK Brock untuk setiap musuh dalam <color=#00F6FF>2 klaster di sekitar</color> unit.",
  str_skill_passive_desc_400083 = "Active Skill memiliki peluang <color=#00F6FF>{1}</color> untuk mengurangi movement range musuh sebesar <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_410083 = "Active Skill memiliki peluang <color=#00F6FF>{1}</color> untuk mengurangi movement range musuh sebesar <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_430083 = "Active Skill memiliki peluang <color=#00F6FF>{1}</color> untuk mengurangi movement range musuh sebesar <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_400059 = "Memberikan hingga <color=#00F6FF>{1}</color> tumpukan <link=\"30002\"><#FFAE07><u>Pepi Mark</u></color></link>. Jangkauan gerak Active Skill diubah menjadi jumlah klaster di sekitar unit yang setara dengan tumpukan Mark. Penggunaan Active Skill akan menghilangkan semua tumpukan.",
  str_skill_passive_desc_410059 = "Memberikan hingga <color=#00F6FF>{1}</color> tumpukan <link=\"30002\"><#FFAE07><u>Pepi Mark</u></color></link>. Movement range Active Skill menjadi jumlah klaster di sekitar unit setara dengan tumpukan Mark. Penggunaan Active Skill akan menghilangkan semua tumpukan.",
  str_skill_passive_desc_420059 = "Memberikan hingga <color=#00F6FF>{1}</color> tumpukan <link=\"30003\"><#FFAE07><u>Pepi Mark</u></color></link>. Jangkauan gerak Active Skill diubah menjadi jumlah klaster di sekitar unit yang setara dengan tumpukan Mark. Penggunaan Active Skill akan menghilangkan semua tumpukan.",
  str_skill_passive_desc_400080 = "Saat tidak ada musuh di dalam jangkauan Chain Combo, memulihkan HP tim setara dengan <color=#00F6FF>{1}</color> ATK Unimet.",
  str_skill_passive_desc_410080 = "Saat tidak ada musuh di dalam jangkauan Chain Combo, memulihkan HP tim setara dengan <color=#00F6FF>{1}</color> ATK Unimet.",
  str_skill_passive_desc_400093 = "Setelah casting Chain Combo atau Active Skill, jika HP target lebih rendah dari <color=#00F6FF>{1}</color>, meluncurkan 1 serangan lagi yang memberikan kerusakan yang mengabaikan DEF sama dengan <color=#00F6FF>{2}</color> dari ATK.",
  str_skill_passive_desc_410093 = "Setelah casting Chain Combo atau Active Skill, jika HP target lebih rendah dari <color=#00F6FF>{1}</color>, meluncurkan 1 serangan lagi yang memberikan kerusakan yang mengabaikan DEF sama dengan <color=#00F6FF>{2}</color> dari ATK.",
  str_skill_passive_desc_430093 = "Setelah mengaktifkan Chain Combo atau Active Skill, jika HP target lebih rendah dari <color=#00F6FF>{1}</color>, meluncurkan 1 serangan lagi yang memberikan kerusakan yang mengabaikan DEF sama dengan <color=#00F6FF>{2}</color> dari ATK. Jika HP target lebih rendah dari ATK Migard setelah serangan ekstra, target terbunuh.",
  str_skill_passive_desc_400097 = "Normal Attack menjadi 2-combo attack yang menimbulkan <color=#00F6FF>{1}</color> damage dasar dalam setiap serangan yang kena.",
  str_skill_passive_desc_410097 = "Normal Attack menjadi 2-combo attack yang menimbulkan <color=#00F6FF>{1}</color> damage dasar dalam setiap serangan yang kena.",
  str_skill_passive_desc_420097 = "Normal Attack menjadi 2-combo attack yang menimbulkan <color=#00F6FF>{1}</color> damage dasar dalam setiap serangan yang kena. Setiap attack memiliki peluang <color=#00F6FF>20%</color> untuk menimbulkan <color=#00F6FF>50%</color> damage ekstra.",
  str_skill_passive_desc_430097 = "Normal Attack menjadi 2-combo attack yang menimbulkan <color=#00F6FF>{1}</color> damage dasar dalam setiap serangan yang kena. Setiap attack memiliki peluang <color=#00F6FF>20%</color> untuk menimbulkan <color=#00F6FF>50%</color> damage ekstra. Setiap combo meningkatkan peluang picu sebesar 0,5%, hingga 50%.",
  str_skill_passive_desc_400095 = "Saat menimbulkan damage pada musuh yang terkena <link=\"10001\"><#FFAE07><u>Poison</u></color></link>, setiap tumpukan Poison akan meningkatkan damage final sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410095 = "Saat menimbulkan damage pada musuh yang terkena <link=\"10001\"><#FFAE07><u>Poison</u></color></link>, setiap tumpukan Poison akan meningkatkan damage final sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420095 = "Saat menimbulkan damage pada musuh yang terkena <link=\"10001\"><#FFAE07><u>Poison</u></color></link>, setiap tumpukan Poison akan meningkatkan damage final sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430095 = "Saat menimbulkan damage pada musuh yang terkena <link=\"10001\"><#FFAE07><u>Poison</u></color></link>, setiap tumpukan Poison akan meningkatkan damage final sebesar <color=#00F6FF>{1}</color>. Ketika Active Skill atau Chain Combo mengenai target yang terkena Poison, unit akan mendapatkan 1 tumpukan Poison ekstra.",
  str_skill_passive_desc_400062 = "Saat serangan normal, Chain Combo, atau Active Skill menimbulkan damage pada 1 musuh saja, damage ini akan mengabaikan <color=#00F6FF>{1}</color> DEF target.",
  str_skill_passive_desc_410062 = "Saat serangan normal, Chain Combo, atau Active Skill menimbulkan damage pada 1 musuh saja, damage ini akan mengabaikan <color=#00F6FF>{1}</color> DEF target.",
  str_skill_passive_desc_430062 = "Saat Normal Attack, Chain Combo, atau Active Skill memberikan damage hanya ke 1 musuh, damage ini diabaikan <color=#00F6FF>{1}</color> dari DEF target. Saat hanya ada 1 musuh di papan, Skill Aktif Aurorian Hutan lain dalam tim juga mendapatkan 50% dari efek ini.",
  str_skill_passive_desc_400024 = "Normal Attack menimbulkan <color=#00F6FF>{1}</color> damage ekstra pada musuh yang menduduki tile Merah.",
  str_skill_passive_desc_410024 = "Normal Attack menimbulkan <color=#00F6FF>{1}</color> damage ekstra pada musuh yang menduduki tile Merah.",
  str_skill_passive_desc_400087 = "Saat Chain Combo mengenai target, Chain Combo juga akan menimbulkan damage pada <color=#00F6FF>{1}</color> target acak (setiap target hanya dapat memperoleh damage sekali) dalam <color=#00F6FF>1 klaster di sekitar</color> target. Damage berkurang sebesar <color=#00F6FF>{2}</color> untuk setiap serangan yang kena.",
  str_skill_passive_desc_410087 = "Saat Chain Combo mengenai target, Chain Combo juga akan menimbulkan damage pada <color=#00F6FF>{1}</color> target acak (setiap target hanya dapat memperoleh damage sekali) dalam <color=#00F6FF>1 klaster di sekitar</color> target. Damage berkurang sebesar <color=#00F6FF>{2}</color> untuk setiap serangan yang kena.",
  str_skill_passive_desc_420087 = "Saat Chain Combo mengenai target, Chain Combo juga akan menimbulkan damage pada <color=#00F6FF>{1}</color> target acak (setiap target hanya dapat memperoleh damage sekali) dalam <color=#00F6FF>2 klaster di sekitar</color> target. Damage berkurang sebesar <color=#00F6FF>{2}</color> untuk setiap serangan yang kena.",
  str_skill_passive_desc_400101 = "Meningkatkan damage yang ditimbulkan Ansia pada musuh di sepanjang tepi medan tempur (bonus damage paling tinggi ketika musuh berada di pojok), dengan peningkatan hingga <color=#00F6FF>{1}</color> damage final.",
  str_skill_passive_desc_410101 = "Meningkatkan damage yang ditimbulkan Ansia pada musuh di sepanjang tepi medan tempur (bonus damage paling tinggi ketika musuh berada di pojok), dengan peningkatan hingga <color=#00F6FF>{1}</color> damage final.",
  str_skill_passive_desc_400102 = "Hibah 1 Tessa Tandai setiap kali Thunder Aurorian dalam tim menggunakan Skill Aktif mereka. Saat menggunakan Skill Aktif, setiap mark akan bertransaksi <color=#00F6FF>{1}</color> merusak musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Mengaktifkan Skill Aktif menghapus semua tanda.",
  str_skill_passive_desc_410102 = "Hibah 1 Tessa Tandai setiap kali Thunder Aurorian dalam tim menggunakan Skill Aktif mereka. Saat menggunakan Skill Aktif, setiap mark akan bertransaksi <color=#00F6FF>{1}</color> merusak musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Mengaktifkan Skill Aktif menghapus semua tanda.",
  str_skill_passive_desc_420102 = "Hibah 1 Tessa Tandai setiap kali Thunder Aurorian dalam tim menggunakan Skill Aktif mereka atau kapan Tessa menggunakan Kombo Rantai. Saat menggunakan Skill Aktif, setiap mark akan bertransaksi <color=#00F6FF>{1}</color> merusak musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Mengaktifkan Skill Aktif menghapus semua tanda.",
  str_skill_passive_desc_430102 = "Hibah 1 Tessa Tandai setiap kali Thunder Aurorian dalam tim menggunakan Skill Aktif mereka atau kapan Tessa menggunakan Kombo Rantai. Saat menggunakan Skill Aktif, setiap mark akan bertransaksi <color=#00F6FF>{1}</color> DEF-mengabaikan kerusakan pada musuh di dalamnya <color=#00F6FF>2 cluster sekitarnya</color>. Mengaktifkan Skill Aktif menghapus semua tanda.",
  str_skill_passive_desc_400099 = "Pada saat mengontrol pedang ajaib, Normal Attack akan menembus musuh, menimbulkan <color=#00F6FF>{1}</color> damage pada target 1 tile di belakang musuh.",
  str_skill_passive_desc_410099 = "Pada saat mengontrol pedang ajaib, Normal Attack akan menembus musuh, menimbulkan <color=#00F6FF>{1}</color> damage pada target 1 tile di belakang musuh.",
  str_skill_passive_desc_400100 = "Saat Sikare menyerang musuh untuk pertama kalinya, dia akan mengambil jiwa target, menimbulkan damage yang setara dengan <color=#00F6FF>{1}</color> ATK pada musuh tersebut (damage ini mengabaikan DEF).",
  str_skill_passive_desc_410100 = "Saat Sikare menyerang musuh untuk pertama kalinya, dia akan mengambil jiwa target, menimbulkan damage yang setara dengan <color=#00F6FF>{1}</color> ATK pada musuh tersebut (damage ini mengabaikan DEF).",
  str_skill_passive_desc_430100 = "Saat Sikare menyerang musuh untuk pertama kalinya, dia akan mengambil jiwa target, menimbulkan damage setara dengan <color=#00F6FF>{1}</color> ATK plus damage yang mengabaikan DEF yang setara dengan <color=#00F6FF>5%</color> HP saat ini pada musuh tersebut.",
  str_skill_passive_desc_400098 = "Saat Chain Combo mengenai musuh, memberikan 1 tumpukan Dismember Mark. Dapat ditumpuk hingga 5 kali. Setiap tumpukan Dismember Mark akan meningkatkan damage Cuscuta sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410098 = "Saat Chain Combo mengenai musuh, memberikan 1 tumpukan Dismember Mark. Menumpuk hingga 5 kali. Setiap tumpukan Dismember Mark akan meningkatkan damage Cuscuta sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420098 = "Saat Chain Combo mengenai musuh, memberikan 1 tumpukan Dismember Mark. Dapat ditumpuk hingga 5 kali. Setiap tumpukan Dismember Mark akan meningkatkan damage Cuscuta sebesar <color=#00F6FF>{1}</color>. Normal Attack memiliki peluang <color=#00F6FF>30%</color> untuk memberikan 1 tumpukan Dismember Mark.",
  str_skill_passive_desc_4200981 = "Saat Kombo Rantai mengenai musuh, menimbulkan 1 tumpukan Tanda Dismember. Tumpuk hingga 10 kali. Setiap stack dari Dismember Mark meningkatkan damage Cuscuta sebesar <color=#00F6FF>6%</color>. Serangan normal memiliki a <color=#00F6FF>30%</color> kesempatan untuk menimbulkan 1 tumpukan Dismember Mark.",
  str_skill_passive_desc_400094 = "Setelah Chain Combo mengenai target, mengurangi ATK target sebesar <color=#00F6FF>{1}</color> selama 1 putaran.",
  str_skill_passive_desc_410094 = "Setelah Chain Combo mengenai target, mengurangi ATK target sebesar <color=#00F6FF>{1}</color> selama 1 putaran.",
  str_skill_passive_desc_400096 = "Memberikan <link=\"30013\"><#FFAE07><u>Sariel Mark</u></color></link>, hingga 8 tumpukan. Setiap tumpukan meningkatkan DEF Sariel sebesar <color=#00F6FF>{1}</color>. Tetap mempertahankan 50% tumpukan di akhir putaran.",
  str_skill_passive_desc_410096 = "Memberikan <link=\"30013\"><#FFAE07><u>Sariel Mark</u></color></link>, hingga 8 tumpukan. Setiap tumpukan meningkatkan DEF Sariel sebesar <color=#00F6FF>{1}</color>. Tetap mempertahankan 50% tumpukan di akhir putaran.",
  str_skill_passive_desc_420096 = "Memberikan <link=\"30013\"><#FFAE07><u>Sariel Mark</u></color></link>, hingga 8 tumpukan. Setiap tumpukan meningkatkan DEF Sariel sebesar <color=#00F6FF>{1}</color>, meningkatkan DEF hingga <color=#00F6FF>50%</color> berdasarkan jumlah HP yang hilang. Tetap mempertahankan 50% tumpukan di akhir putaran.",
  str_skill_passive_desc_400056 = "Saat serangan normal atau Active Skill menimbulkan damage (mana pun yang lebih besar), mengonversi <color=#00F6FF>{1}</color> damage menjadi ATK. Hanya valid untuk putaran saat ini.",
  str_skill_passive_desc_410056 = "Saat serangan normal atau Active Skill menimbulkan damage (mana pun yang lebih besar), mengonversi <color=#00F6FF>{1}</color> damage menjadi ATK. Hanya valid untuk putaran saat ini.",
  str_skill_passive_desc_430056 = "Saat serangan normal atau Active Skill menimbulkan damage (mana pun yang lebih besar), mengonversi <color=#00F6FF>{1}</color> damage menjadi ATK. Hanya valid untuk putaran saat ini. Ketika hanya ada 1 musuh di medan tempur, ATK Water Aurorian meningkat sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_400103 = "Setiap 3 putaran, Hollow dapat diaktifkan atau disimpan untuk digunakan nanti. Setelah menjadi Hollow, damage Chain Combo mengabaikan defense dan menimbulkan damage setara dengan <color=#00F6FF>{1}</color> ATK Eicy, dan memulihkan HP dengan jumlah yang sama.",
  str_skill_passive_desc_410103 = "Setiap 3 putaran, Hollow dapat diaktifkan atau disimpan untuk digunakan nanti. Setelah menjadi Hollow, damage Chain Combo mengabaikan defense dan menimbulkan damage setara dengan <color=#00F6FF>{1}</color> ATK Eicy, dan memulihkan HP dengan jumlah yang sama.",
  str_skill_passive_desc_430103 = "Memberikan status Void sekali setiap 3 putaran (jika tidak digunakan, status ini dipertahankan). Saat dalam status Void, Chain Combo menimbulkan damage setara dengan <color=#00F6FF>{1}</color> ATK Eicy (damage ini mengabaikan DEF) dan memulihkan HP dengan jumlah yang sama. Makin rendah HP tim, makin besar efektivitas penyembuhan (hingga <color=#00F6FF>50%</color>).",
  str_skill_passive_desc_410067 = "Jika HP telah dipulihkan di putaran ini, DEF dasar Alice akan meningkat sebesar <color=#00F6FF>{1}</color> selama putaran ini.",
  str_skill_passive_desc_430067 = "Jika HP telah dipulihkan di putaran ini, DEF dasar Alice akan meningkat sebesar <color=#00F6FF>{1}</color> selama putaran ini.",
  str_skill_passive_desc_400030 = "Normal Attack <color=#00F6FF>dapat menyerang secara diagonal</color>. Normal Attack diagonal memberi 1 tumpukan Shatter pada target yang dapat ditumpuk hingga 5 kali. Tiap tumpukan mengurangi DEF target setara dengan <color=#00F6FF>{1}</color> DEF dasar Sinsa selama 1 putaran.",
  str_skill_passive_desc_410030 = "Normal Attack <color=#00F6FF>dapat mengenai secara diagonal</color>. Normal Attack diagonal memberi target 1 tumpukan Shatter, yang menumpuk hingga 5 kali. Tiap tumpukan mengurangi DEF target setara dengan <color=#00F6FF>{1}</color> DEF dasar Sinsa selama 1 putaran.",
  str_skill_passive_desc_430030 = "Normal Attack <color=#00F6FF>dapat menyerang secara diagonal</color>. Normal Attack diagonal, Active Skill, dan Chain Combo memberi target 1 tumpukan Shatter yang dapat ditumpuk hingga 5 kali. Tiap tumpukan mengurangi DEF target setara dengan <color=#00F6FF>{1}</color> DEF dasar Sinsa selama 1 putaran.",
  str_skill_passive_desc_410104 = "Active Skill menandai target yang diserang. Saat Active Skill dan Chain Combo Dawn menyerang musuh yang memiliki Mark, Mark ini akan digunakan dan HP akan dipulihkan setara dengan <color=#00F6FF>{1}</color> damage yang ditimbulkan.",
  str_skill_passive_desc_430104 = "Active Skill menandai target yang diserang. Ketika Active Skill dan Chain Combo Dawn menyerang musuh yang memiliki Mark, Mark ini akan digunakan dan HP akan dipulihkan setara dengan <color=#00F6FF>{1}</color> damage yang ditimbulkan. Jika HP tim penuh, damage final attack ini akan meningkat sebesar <color=#00F6FF>25%</color>.",
  str_skill_passive_desc_410071 = "Pada awal setiap putaran, memberikan Burn Mark pada musuh yang memiliki persentase HP tertinggi, meningkatkan semua damage yang ditimbulkan Taki pada target sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430071 = "Di awal setiap ronde, terapkan Burn Mark ke musuh dengan persentase HP tertinggi, meningkatkan semua damage Taki menangani target dengan <color=#00F6FF>{1}</color>. Setiap kali musuh yang terkena Burn Mark tersingkir, ATK Taki bertambah <color=#00F6FF>3%</color>, hingga maksimum <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_400105 = "Saat Normal Attack, Chain Combo, dan Active Skill menimbulkan damage, setiap damage ke-<color=#00F6FF>10</color> juga menimbulkan <color=#00F6FF>{1}</color> damage satu kali pada <color=#00F6FF>semua</color> musuh.",
  str_skill_passive_desc_410105 = "Saat Normal Attack, Chain Combo, dan Active Skill menimbulkan damage, setiap damage ke-<color=#00F6FF>10</color> juga menimbulkan <color=#00F6FF>{1}</color> damage satu kali pada <color=#00F6FF>semua</color> musuh.",
  str_skill_passive_desc_420105 = "Saat Normal Attack, Chain Combo, dan Active Skill menimbulkan damage, setiap damage ke-<color=#00F6FF>8</color> juga menimbulkan <color=#00F6FF>{1}</color> damage satu kali pada <color=#00F6FF>semua</color> musuh.",
  str_skill_passive_desc_430105 = "Saat Normal Attack, Chain Combo, dan Active Skill menimbulkan damage, setiap damage ke-<color=#00F6FF>8</color> juga menimbulkan <color=#00F6FF>{1}</color> damage satu kali pada <color=#00F6FF>semua</color> musuh.",
  str_skill_passive_desc_430109 = "Mendapatkan <color=#00F6FF>5</color> Vis pada awal setiap putaran.",
  str_skill_passive_desc_433109 = "Memperoleh <color=#00F6FF>5</color> Vis di awal setiap putaran. Memperoleh <color=#00F6FF>1</color> Vis untuk serangan normal pertama yang dilancarkan setiap putaran dan meningkatkan damage yang ditimbulkan serangan normal ini sebesar <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_430110 = "Memperoleh <color=#00F6FF>5</color> Vis di awal setiap putaran. Normal Attack memiliki peluang <color=#00F6FF>30%</color> untuk mengeluarkan 1 petir untuk menyerang musuh yang paling jauh.",
  str_skill_passive_desc_433110 = "Memperoleh <color=#00F6FF>5</color> Vis di awal setiap putaran. Memperoleh <color=#00F6FF>2</color> Vis ekstra ketika berhasil membunuh target dengan Active Skill. Normal Attack memiliki peluang <color=#00F6FF>30%</color> untuk mengeluarkan 1 petir untuk menyerang musuh yang paling jauh.",
  str_skill_passive_desc_430107 = "Memperoleh 10 Vis pada awal pertempuran. Saat mengakhiri putaran dalam status non-augmented, memperoleh <color=#00F6FF>5</color> Vis (memperoleh 1 Vis ekstra untuk setiap 20% HP yang hilang).",
  str_skill_passive_desc_436107 = "Memperoleh 10 Vis di awal pertempuran. Di awal setiap putaran, untuk setiap 1 musuh yang ada <color=#00F6FF>dalam 4 tile dalam bentuk silang</color> di sekitar, memperoleh <color=#00F6FF>1</color> Vis. Saat mengakhiri putaran dalam status non-augmented, memperoleh <color=#00F6FF>5</color> Vis (memperoleh 1 Vis ekstra untuk setiap 20% HP yang hilang).",
  str_skill_passive_desc_430108 = "Memperoleh <color=#00F6FF>5</color> Vis di awal setiap putaran. Memperoleh <color=#00F6FF>5</color> Vis ekstra ketika berhasil membunuh target dengan Active Skill.",
  str_skill_passive_desc_400116 = "Semua damage yang ditimbulkan Fleur pada musuh dengan HP Maks kurang dari 40% akan ditingkatkan sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410112 = "Smokey memicu <color=#00F6FF>Manticore's Kiss</color> <color=#00F6FF>setiap kali</color> dia menyerang satu musuh dengan <color=#00F6FF>Active Skill atau Chain Combo, atau kali pertama dia menyerang mereka dengan Normal Attack tiap putaran</color>, menimbulkan damage tambahan yang akan mengabaikan DEF, setara dengan <color=#00F6FF>{1}</color> ATK. Efek ini berkurang saat diaktifkan berulang, turun hingga minimum <color=#00F6FF>20%</color> dari damage awal.",
  str_skill_passive_desc_420112 = "Smokey mengaktifkan <color=#00F6FF>Manticore's Kiss</color> <color=#00F6FF>setiap kali</color> dia menyerang satu musuh dengan <color=#00F6FF>Active Skill atau Chain Combo, atau kali pertama dia menyerang mereka dengan Normal Attack tiap putaran</color>, menimbulkan damage tambahan yang akan mengabaikan DEF, setara dengan <color=#00F6FF>{1}</color> ATK. Efek ini berkurang saat diaktifkan berulang, turun hingga minimum <color=#00F6FF>20%</color> dari damage awal. <color=#00F6FF>Manticore's Kiss</color> menimbulkan damage <color=#00F6FF>ganda</color> pada musuh di Tile Merah.",
  str_skill_passive_desc_430112 = "Smokey mengaktifkan <color=#00F6FF>Manticore's Kiss</color> <color=#00F6FF>setiap kali</color> dia menyerang satu musuh dengan <color=#00F6FF>Active Skill atau Chain Combo, atau kali pertama dia menyerang mereka dengan Normal Attack tiap putaran</color>, menimbulkan damage tambahan yang akan mengabaikan DEF, setara dengan <color=#00F6FF>{1}</color> ATK. Efek ini berkurang saat diaktifkan berulang, turun hingga minimum <color=#00F6FF>20%</color> dari damage awal. <color=#00F6FF>Manticore's Kiss</color> menimbulkan damage <color=#00F6FF>ganda</color> pada musuh di Tile Merah.",
  str_skill_passive_desc_400113 = "Memperoleh Divine Mark pada awal pertempuran atau saat menggunakan Active Skill. Pada saat Mark masih ada, DEF Bonacie meningkat sebesar <color=#00F6FF>{1}</color>. Mark ini akan menghilang setelah HP Bonacie berkurang.",
  str_skill_passive_desc_410113 = "Memperoleh Divine Mark pada awal pertempuran atau saat menggunakan Active Skill. Pada saat Mark masih ada, DEF Bonacie meningkat sebesar <color=#00F6FF>{1}</color>. Mark ini akan menghilang setelah HP Bonacie berkurang.",
  str_skill_passive_desc_420113 = "Memperoleh Divine Mark pada awal pertempuran atau saat menggunakan Active Skill. Pada saat Mark masih ada, DEF Bonacie meningkat sebesar <color=#00F6FF>{1}</color>. Mark ini akan menghilang setelah HP Bonacie berkurang. Saat Mark ini ada, damage Chain Combo yang ditimbulkan oleh Thunder Aurorian meningkat sebesar <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_400114 = "Saat Active Skill menimbulkan damage, memulihkan HP tim dengan jumlah setara dengan <color=#00F6FF>{1}</color> damage yang ditimbulkan.",
  str_skill_passive_desc_410114 = "Saat Active Skill menimbulkan damage, memulihkan HP tim dengan jumlah setara dengan <color=#00F6FF>{1}</color> damage yang ditimbulkan.",
  str_skill_passive_desc_430114 = "Saat Active Skill menimbulkan damage, memulihkan HP tim dengan jumlah setara dengan <color=#00F6FF>{1}</color> damage yang ditimbulkan dan meningkatkan damage Chain Combo yang ditimbulkan oleh Fire Aurorian sebesar <color=#00F6FF>10%</color> pada putaran ini.",
  str_skill_passive_desc_410127 = "Di awal tiap putaran, jika ada musuh dalam <color=#00F6FF>2 klaster di sekitar</color>, melemparkan belati pada 1 musuh akan menimbulkan <color=#00F6FF>{1}</color> damage dan memberikan 1 tumpukan status <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> selama 2 putaran.",
  str_skill_passive_desc_430127 = "Di awal tiap putaran, jika ada musuh dalam <color=#00F6FF>2 klaster di sekitar</color>, melemparkan belati pada 1 musuh akan menimbulkan <color=#00F6FF>{1}</color> damage dan memberikan 1 tumpukan status <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> selama 2 putaran. Belati akan terpicu saat melewati Paper Crane.",
  str_skill_desc_3351221 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color> yang berpusat pada 1 tile yang dipilih. Damage yang ditimbulkan pada tile yang dipilih akan mengabaikan DEF. Menyingkirkan efek <color=#00F6FF>Tile Hancur</color> dari tile dalam jangkauan ini. Saat Blessing mencapai 10 tumpuk, jangkauan Active Skill menjadi <color=#00F6FF>jangkauan berbentuk lingkaran maksimum</color>.",
  str_skill_passive_desc_410117 = "Bisa mengakumulasi <link=\"30016\"><#FFAE07><u>Fury</u></color></link>. Setiap tumpuk Fury meningkatkan ATK dasar Gram sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430117 = "Bisa mengakumulasi <link=\"30017\"><#FFAE07><u>Fury</u></color></link>. Setiap tumpuk Fury meningkatkan ATK dasar Gram sebesar <color=#00F6FF>{1}</color>. Tidak ada batasan berapa banyak Fury yang bisa didapatkan dari Active Skill miliknya. Efek ini akan disingkirkan di akhir setiap gelombang. Untuk setiap tumpuk yang disingkirkan, HP Gram akan dipulihkan dengan jumlah yang setara dengan <color=#00F6FF>5%</color> HP Maks.",
  str_skill_passive_desc_410119 = "Bisa menumpuk <link=\"30018\"><#FFAE07><u>Dauntless Heart</u></color></link>. Setiap tumpuk Dauntless Heart meningkatkan ATK dasar Revy sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420119 = "Bisa menumpuk <link=\"30018\"><#FFAE07><u>Dauntless Heart</u></color></link>. Setiap tumpuk Dauntless Heart meningkatkan ATK dasar Revy sebesar <color=#00F6FF>{1}</color> dan damage Active Skill sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430119 = "Bisa menumpuk <link=\"30018\"><#FFAE07><u>Dauntless Heart</u></color></link>. Setiap tumpukan Dauntless Heart meningkatkan ATK dasar Revy sebesar <color=#00F6FF>{1}</color> dan damage Active Skill sebesar <color=#00F6FF>5%</color>. Normal Attack <color=#00F6FF>bisa menyerang secara diagonal</color>.",
  str_skill_passive_desc_410122 = "Bisa mendapatkan <link=\"30019\"><#FFAE07><u>Blessing</u></color></link>. Setiap tumpuk Blessing meningkatkan damage Active Skill milik Allura sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410121 = "Mendapatkan 1 tumpuk Barbed Mark setiap melewati <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Mark akan menghilang di akhir putaran. Setiap tumpuk meningkatkan damage berantai sebesar <color=#00F6FF>{1}</color>. Mempertahankan 50% tumpuk di akhir putaran.",
  str_skill_passive_desc_430121 = "Mendapatkan 1 tumpuk Barbed Mark setiap melewati <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Setiap tumpuk meningkatkan damage Chain Combo dan Normal Attack sebesar <color=#00F6FF>{1}</color>. Mempertahankan 50% tumpuk di akhir putaran.",
  str_skill_passive_desc_410065 = "Setiap Chain Combo yang mengenai musuh memberikan 1 tumpukan Snowpuff Mark. Setiap tumpuk meningkatkan DEF sebesar <color=#00F6FF>{1}</color>. Mark akan menghilang di akhir putaran.",
  str_skill_passive_desc_410115 = "Mendapatkan 1 tumpuk Emerald Mark setiap melewati <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Setiap tumpuk memberikan <color=#00F6FF>{1}</color> dari ATK dasar Naroxel. Mempertahankan 50% tumpuk di akhir putaran.",
  str_skill_passive_desc_430115 = "Mendapatkan 1 tumpuk Emerald Mark setiap melewati <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Setiap tumpuk memberi seluruh tim <color=#00F6FF>{1}</color> dari ATK dasar Naroxel. Mempertahankan 50% tumpuk di akhir putaran.",
  str_skill_passive_desc_410126 = "Memanggil <link=\"30024\"><#FFAE07><u>Frankel</u></color></link> ke tile yang dipilih Active Skill. Setiap kali unit menggunakan Active Skill, Frankel mengeluarkan <color=#00F6FF>Roar</color>, memberikan <color=#00F6FF>{1}</color> damage pada musuh dalam <color=#00F6FF>1 klaster sekitarnya</color>. Frankel juga mengeluarkan <color=#00F6FF>Roar</color> saat menghilang.",
  str_skill_passive_desc_420126 = "Memanggil <link=\"30024\"><#FFAE07><u>Frankel</u></color></link> ke tile yang dipilih Active Skill. Setiap kali unit menggunakan Active Skill, Frankel mengeluarkan <color=#00F6FF>Roar</color>, memberikan <color=#00F6FF>{1}</color> damage pada musuh dalam <color=#00F6FF>1 klaster sekitarnya</color>. Jika hanya satu musuh yang berada dalam jangkauan, melepaskan <color=#00F6FF>Sundering Claw</color>, meningkatkan damage sebesar <color=#00F6FF>50%</color>. Frankel juga mengeluarkan <color=#00F6FF>Roar</color> saat menghilang.",
  str_skill_passive_desc_410129 = "Active Skill dan Chain Combo memberikan 1 tumpuk Parasitic Mark setiap kali mereka menimbulkan damage. Parasitic Mark menumpuk maksimal <color=#00F6FF>9</color> kali. Setiap kali musuh bergerak 1 tile, setiap tumpuk Parasitic Mark menimbulkan <color=#00F6FF>{1}</color> damage.",
  str_skill_passive_desc_420129 = "Active Skill dan Chain Combo memberikan 1 tumpuk Parasitic Mark setiap kali mereka menimbulkan damage. Parasitic Mark menumpuk maksimal <color=#00F6FF>9</color> kali. Setiap kali musuh bergerak 1 tile, setiap tumpuk Parasitic Mark menimbulkan <color=#00F6FF>{1}</color> damage. Serangan normal dan Chain Combo milik Luke menimbulkan <color=#00F6FF>30%</color> damage yang ditingkatkan pada musuh yang berafiliasi dengan jumlah maksimum tumpukan Parasitic Mark.",
  str_skill_passive_desc_430129 = "Active Skill dan Chain Combo memberikan 1 tumpuk Parasitic Mark setiap kali mereka menimbulkan damage. Parasitic Mark menumpuk maksimal <color=#00F6FF>9</color> kali. Setiap kali musuh bergerak 1 tile, setiap tumpuk Parasitic Mark menimbulkan <color=#00F6FF>{1}</color> damage. Damage ini meningkat ke <color=#00F6FF>{2}</color> bagi musuh dengan jumlah tumpukan tertinggi di medan pertempuran. Serangan normal dan Chain Combo milik Luke menimbulkan <color=#00F6FF>30%</color> damage yang ditingkatkan pada musuh yang berafiliasi dengan jumlah maksimum tumpukan Parasitic Mark.",
  str_skill_passive_desc_410055 = "Memperoleh 1 tumpuk Battle Mark saat diserang. Bisa menumpuk maksimal <color=#00F6FF>15</color> kali. Setiap tumpuk Battle Mark meningkatkan ATK sebesar <color=#00F6FF>{1}</color>. Tumpukan Battle Mark berkurang sebesar 50% setiap putaran.",
  str_skill_passive_desc_420055 = "Memperoleh 1 tumpuk Battle Mark saat diserang. Bisa menumpuk maksimal <color=#00F6FF>15</color> kali. Setiap tumpuk Battle Mark meningkatkan ATK dan DEF sebesar <color=#00F6FF>{1}</color>. Tumpukan Battle Mark berkurang sebesar 50% setiap putaran.",
  str_skill_passive_desc_430055 = "Memperoleh 1 tumpuk Battle Mark saat diserang. Bisa menumpuk maksimal <color=#00F6FF>15</color> kali. Setiap tumpuk Battle Mark meningkatkan ATK dan DEF sebesar <color=#00F6FF>{1}</color>. Tumpukan Battle Mark berkurang sebesar 50% setiap putaran. Memperoleh Shield yang setara dengan <color=#00F6FF>12%</color> HP Maks milik Pittman untuk setiap tumpuk Battle Mark yang hilang.",
  str_skill_passive_desc_410120 = "Saat menggunakan Chain Combo dan Active Skill, ATK Hedy digantikan dengan ATK Pompey. ATK Pompey setara dengan <color=#00F6FF>{1}</color> ATK Hedy.",
  str_skill_passive_desc_430120 = "Saat menggunakan Chain Combo dan Active Skill, ATK Hedy digantikan dengan ATK Pompey. ATK Pompey setara dengan <color=#00F6FF>{1}</color> ATK Hedy. Selama Aurora Time, ATK Pompey meningkat sebesar <color=#00F6FF>2%</color> dengan setiap sambungan tile, hingga maksimal <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_410123 = "Untuk setiap musuh pada <color=#00F6FF>12 tile dalam bentuk wajik</color>, ATK Cordy meningkat sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430123 = "Untuk setiap musuh dalam <color=#00F6FF>2 klaster</color>, ATK dan DEF Cordy meningkat sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410015 = "Untuk setiap klaster yang dilalui granat sebelum Active Skill menimbulkan damage, damage final meningkat sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420015 = "Untuk setiap klaster yang dilalui granat sebelum Active Skill menimbulkan damage, damage final meningkat sebesar <color=#00F6FF>{1}</color>. Untuk setiap klaster yang dilalui granat sebelum Chain Combo menimbulkan damage, damage final meningkat sebesar <color=#00F6FF>{2}</color>.",
  str_skill_passive_desc_410131 = "Jika HP tim tidak penuh sebelum menggunakan serangan normal, efek serangan normal ini akan memulihkan HP yang setara dengan <color=#00F6FF>{1}</color> ATK Novio.",
  str_skill_passive_desc_430131 = "Jika HP tim tidak penuh sebelum menggunakan serangan normal, efek serangan normal ini akan memulihkan HP yang setara dengan <color=#00F6FF>{1}</color> ATK Novio. Jika HP tim tidak penuh, serangan ini dan damage Chain Combo akan meningkat sebesar <color=#00F6FF>10%</color>. Damage bonus akan meningkat menjadi <color=#00F6FF>25%</color> jika Shield sudah ada.",
  str_skill_passive_desc_410132 = "Selama Aurora Time, ATK ditingkatkan sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430132 = "Selama Aurora Time, ATK ditingkatkan sebesar <color=#00F6FF>{1}</color>, dan memicu Chain Combo saat melewati tile. Damage Chain Combo akan selalu dianggap sebagai elemen Forest.",
  str_skill_passive_desc_410133 = "Setiap Combo meningkatkan Chain Combo Damage sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430133 = "Setiap Combo meningkatkan Chain Combo Damage sebesar <color=#00F6FF>{1}</color> dan Splash Damage sebesar <color=#00F6FF>{2}</color>.",
  str_skill_passive_desc_410137 = "Active Skill menimbulkan damage pada musuh yang dipilih, setiap <color=#00F6FF>1</color> tile Biru di kaki musuh, menimbulkan <color=#00F6FF>{1}</color> damage ATK Fafnir.",
  str_skill_passive_desc_430137 = "Active Skill menimbulkan damage pada musuh yang dipilih, setiap <color=#00F6FF>1</color> tile Biru di kaki musuh menimbulkan <color=#00F6FF>{1}</color> damage ATK Fafnir. Active Skill dari karakter Dragon Maid lainnya juga akan memicu efek damage ini ketika mengenai musuh.",
  str_skill_passive_desc_410134 = "Kanna mendapatkan 3 charge saat menggunakan Active Skill dan 1 charge saat Thunder Aurorian atau karakter Dragon Maid menggunakan Active Skill mereka, hingga maksimal 10 charge. Setiap charge meningkatkan ATK dasar sebesar <color=#00F6FF>{1}</color>, dan akan hilang setelah putaran berakhir.",
  str_skill_passive_desc_430134 = "Kanna mendapatkan 3 charge saat menggunakan Active Skill dan 1 charge saat Thunder Aurorian atau karakter Dragon Maid menggunakan Active Skill mereka, hingga maksimal 10 charge. Setiap charge meningkatkan ATK dasar sebesar <color=#00F6FF>{1}</color>, dan setengah dari charge akan hilang setelah putaran berakhir.",
  str_skill_passive_desc_416134 = "Kanna mendapatkan 3 charge saat menggunakan Active Skill dan 1 charge saat Thunder Aurorian atau karakter Dragon Maid menggunakan Active Skill mereka, hingga maksimal 10 charge. Setiap charge meningkatkan ATK dasar sebesar <color=#00F6FF>{1}</color>, dan akan hilang setelah putaran berakhir. Kanna mendapatkan 2 charge di awal setiap gelombang.",
  str_skill_passive_desc_436134 = "Kanna mendapatkan 3 charge saat menggunakan Active Skill dan 1 charge saat Thunder Aurorian atau karakter Dragon Maid menggunakan Active Skill mereka, hingga maksimal 10 charge. Setiap charge meningkatkan ATK dasar sebesar <color=#00F6FF>{1}</color>, dan setengah dari charge akan hilang setelah putaran berakhir. Kanna mendapatkan 2 charge di awal setiap gelombang.",
  str_skill_passive_desc_410135 = "Meningkatkan damage Chain Combo sebesar <color=#00F6FF>{1}</color> ketika HP penuh.",
  str_skill_passive_desc_430135 = "Meningkatkan damage Normal Attack, Chain Combo, dan Active Skill sebesar <color=#00F6FF>{1}</color> ketika HP penuh.",
  str_skill_passive_desc_410136 = "Ketika Chain Combo mengenai musuh, menimbulkan 1 tumpukan Mortality Mark. Setiap tumpukan Mark meningkatkan damage Active Skill yang diterima musuh ini dari semua Aurorian sebesar <color=#00F6FF>{1}</color>. Maksimum <color=#00F6FF>10</color> tumpukan, dan berlangsung selama pertempuran.",
