  str_skill_desc_1020121 = "Thornspike yang berubah menjadi Spikeneedle di putaran berikutnya. Berubah menjadi Thornspike baru saat digabungkan dengan yang lain.",
  str_skill_name_290150110 = "Basilisk - Maul",
  str_skill_desc_290150110 = "Gretel bergerak ke arah pemain, memanggil klonanya untuk menyerang dalam jarak dekat di depannya.",
  str_skill_name_290150120 = "Basilisk - Tail Sweep",
  str_skill_desc_290150120 = "Klona Gretel melakukan Tail Sweep dengan jangkauan luas, mendorong pemain di luar jangkauan serangannya.",
  str_skill_name_290150130 = "Reincarnation Baptism",
  str_skill_desc_290150130 = "Gretel menarik kembali klonanya sebelum melepaskannya lagi, menimbulkan Full-screen Damage.",
  str_skill_name_290160110 = "Ironstomp - Groundbreaker",
  str_skill_desc_290160110 = "Ironstomp mengentakkan kaki di tempat, menimbulkan damage pada unit terdekat dan membuat Tile Rusak.",
  str_skill_name_290160120 = "Ironstomp - Ground Shatter",
  str_skill_desc_290160120 = "Bergerak ke arah pemain, menimbulkan damage pada unit, dan membuat Tile Rusak dalam 1 klaster di sekitar. Tile Rusak akan muncul di sepanjang jalan yang dilaluinya.",
  str_skill_name_290160130 = "Reincarnation Baptism",
  str_skill_desc_290160130 = "Menarik kembali Ironstomp untuk mengisi daya sebelum melepaskannya lagi, menimbulkan Full-screen Damage.",
  str_skill_name_290170110 = "Kittypus - Mockery",
  str_skill_desc_290170110 = "Kittypus bergerak ke arah pemain dan menampar musuh dalam jangkauan berbentuk silang dengan tentakelnya, menimbulkan damage.",
  str_skill_name_290170120 = "Kittypus - Abyss",
