  str_skill_passive_name_430139 = "Paranormal Thunder",
  str_skill_upgrade_desc_15013912 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_15013915 = "Active Skill Enhancement: Pilih salah satu dari <color=#FFFF00>8</color> arah mata angin mana pun.",
  str_skill_desc_300139 = "Menyerang salah satu dari <color=#00F6FF>4</color> arah mana pun dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalur dan tile yang berdekatan. Mereset semua tile <color=#00F6FF>non-Kuning</color>.",
  str_skill_desc_302139 = "Menyerang salah satu dari <color=#00F6FF>8</color> arah mana pun dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalur dan tile yang berdekatan. Mereset semua tile <color=#00F6FF>non-Kuning</color>.",
  str_skill_desc_320139 = "Menyerang salah satu dari <color=#00F6FF>4</color> arah mana pun dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalur dan tile yang berdekatan selagi menimbulkan efek <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> pada 1 musuh acak di sepanjang jalur. Mereset semua tile <color=#00F6FF>non-Kuning</color>.",
  str_skill_desc_322139 = "Menyerang salah satu dari <color=#00F6FF>8</color> arah mana pun dan menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh di sepanjang jalur dan tile yang berdekatan selagi menimbulkan efek <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> pada 1 musuh acak di sepanjang jalur. Mereset semua tile <color=#00F6FF>non-Kuning</color>.",
  str_skill_desc_2001391 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 kolom</color>.",
  str_skill_desc_2001392 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom</color>.",
  str_skill_desc_2001393 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom</color>.",
  str_skill_passive_desc_410139 = "Meningkatkan damage Erica sebesar <color=#00F6FF>{1}</color> pada musuh di tile Kuning untuk setiap klaster jauhnya.",
  str_skill_passive_desc_430139 = "Meningkatkan damage Erica sebesar <color=#00F6FF>{1}</color> pada musuh di tile Kuning untuk setiap klaster yang terbentang antara dirinya dan musuh itu serta memberikan 50% dari damage bonus itu kepada rekan tim Thunder Aurorian.",
  str_skill_name_300138 = "Spider Domain",
  str_skill_name_320138 = "Spider Domain",
  str_skill_name_330138 = "Spider Domain",
  str_skill_name_2001381 = "Spider Rupture",
  str_skill_name_2001382 = "Spider Rupture",
  str_skill_name_2001383 = "Spider Rupture",
  str_skill_passive_name_410138 = "Web Shield",
  str_skill_passive_name_416138 = "Web Shield",
  str_skill_upgrade_desc_16013813 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16013816 = "Equipment Skill Enhancement: Mendapatkan Shield tambahan yang setara dengan <color=#00F6FF>15%</color> dari HP Siobhan saat memperoleh Shield dari <link=\"30025\"><#FFAE07><u>Web Mark</u></color></link> apabila ada lebih dari 10 tumpukan Mark.",
  str_skill_desc_300138 = "Memilih 1 tile, dan memilih tile lain untuk mengonfirmasi jangkauan 2×2 atau 1×4 dan mengonversi tile di dalam jangkauan tersebut menjadi Hijau.",
  str_skill_desc_320138 = "Memilih 1 tile dan memilih tile lain untuk mengonfirmasi jangkauan 2×2 atau 1×4, lalu mengonversi tile di dalamnya menjadi Hijau. Dua tile yang dipilih akan menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_330138 = "Memilih 1 tile dan memilih tile lain untuk mengonfirmasi jangkauan 2×2 atau 1×4, lali mengonversi tile di dalamnya menjadi Hijau. Dua tile yang dipilih akan menjadi <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. Selama Aurora Time, mencapai 15 Chain Combo akan mengurangi cooldown Active Skill sebanyak <color=#00F6FF>1</color> putaran.",
  str_skill_desc_2001381 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dalam <color=#00F6FF>4 klaster di sekitar</color>.",
  str_skill_desc_2001382 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh terdekat dalam <color=#00F6FF>4 klaster di sekitar</color>.",
  str_skill_desc_2001383 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh dalam <color=#00F6FF>4 klaster di sekitar</color>.",
  str_skill_passive_desc_410138 = "Mendapatkan <link=\"30025\"><#FFAE07><u>Web Mark</u></color></link>. Menghilangkan semua tumpukan sebelum menerima damage dan mendapatkan Shield yang setara dengan <color=#00F6FF>{1}</color> DEF Siobhan untuk setiap tumpukan yang dihilangkan.",
  str_skill_passive_desc_416138 = "Mendapatkan <link=\"30025\"><#FFAE07><u>Web Mark</u></color></link>. Menghilangkan semua tumpukan sebelum menerima damage dan mendapatkan Shield yang setara dengan <color=#00F6FF>{1}</color> DEF Siobhan untuk setiap tumpukan yang dihilangkan. Jika tumpukan Web Mark lebih dari 10, mendapatkan Shield tambahan yang setara dengan <color=#00F6FF>15%</color> HP Siobhan saat memperoleh Shield dari <link=\"30025\"><#FFAE07><u>Web Mark</u></color></link>.",
  str_skill_upgrade_desc_16014113 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16014116 = "Active Skill Enhancement: Ketuk tile di bawah kakinya untuk mengganti arah dorongan dan Tile-Converting.",
  str_skill_desc_2001411 = "Menimbulkan <color=#00F6FF>115%</color> damage pada 2 musuh terdekat. Jika hanya ada 1 target musuh, menimbulkan damage dua kali.",
  str_skill_desc_2001412 = "Menimbulkan <color=#00F6FF>130%</color> damage pada 2 musuh terdekat. Jika hanya ada 1 target musuh, menimbulkan damage dua kali.",
  str_skill_desc_2001413 = "Menimbulkan <color=#00F6FF>150%</color> damage pada 2 musuh terdekat. Jika hanya ada 1 target musuh, menimbulkan damage dua kali.",
  str_skill_desc_300141 = "Pilih jangkauan <color=#00F6FF>berbentuk silang maks</color> atau <color=#00F6FF>berbentuk X maks</color>, menimbulkan <color=#00F6FF>{1}%</color> damage, mendorong musuh dan mengubah tile dalam jangkauan serangannya menjadi tile Biru.",
  str_skill_desc_306141 = "Pilih jangkauan <color=#00F6FF>berbentuk silang maks</color> atau <color=#00F6FF>berbentuk X maks</color>, menimbulkan <color=#00F6FF>{1}%</color> damage, mendorong musuh dan mengubah tile dalam jangkauan serangannya menjadi tile Biru. Ketuk tile yang dipijak untuk mengubah arah dorongan dan melakukan Tile-Converting.",
  str_skill_desc_320141 = "Pilih jangkauan <color=#00F6FF>berbentuk silang maks</color> atau <color=#00F6FF>berbentuk X maks</color>, menimbulkan <color=#00F6FF>{1}%</color> damage, mendorong musuh dan mengubah tile dalam jangkauan serangannya menjadi tile Biru. Menimbulkan damage satu kali pada target musuh yang terkena berdasarkan level Equipment Skill saat ini.",
  str_skill_desc_326141 = "Pilih jangkauan <color=#00F6FF>berbentuk silang maks</color> atau <color=#00F6FF>berbentuk X maks</color>, menimbulkan <color=#00F6FF>{1}%</color> damage, mendorong musuh dan mengubah tile dalam jangkauan serangannya menjadi tile Biru. Ketuk tile yang dipijak untuk mengubah arah dorongan dan melakukan Tile-Converting. Menimbulkan damage satu kali pada target musuh yang terkena berdasarkan level Equipment Skill saat ini.",
  str_skill_passive_desc_410141 = "Untuk setiap <color=#00F6FF>3</color> kali Chain Combo menimbulkan damage pada target yang sama, menimbulkan damage ekstra yang setara dengan <color=#00F6FF>{1}</color> HP target saat ini.",
  str_skill_passive_desc_420141 = "Untuk setiap <color=#00F6FF>3</color> kali Chain Combo menimbulkan damage pada target yang sama, timbulkan damage ekstra yang setara dengan <color=#00F6FF>{1}</color> HP target saat ini.",
  str_skill_passive_desc_430141 = "Untuk setiap <color=#00F6FF>3</color> kali Chain Combo menimbulkan damage pada target yang sama, menimbulkan damage ekstra yang setara dengan <color=#00F6FF>{1}</color> HP target saat ini, tidak kurang dari <color=#00F6FF>{2}</color> DEF dasar Ruby.",
