  str_skill_desc_300142 = "Pilih 1 dari <color=#00F6FF>13 tile dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada tile yang dipilih dan <color=#00F6FF>2 klaster di sekitar</color> serta memaksa musuh <color=#00F6FF>non-Boss</color> dalam jangkauan untuk bergerak sejauh <color=#00F6FF>2</color> tile menuju tile yang dipilih. Damage berkurang sebesar 53% per klaster.",
  str_skill_desc_302142 = "Pilih 1 dari <color=#00F6FF>13 tile dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada tile yang dipilih dan <color=#00F6FF>2 klaster di sekitar</color> serta memaksa musuh <color=#00F6FF>non-Boss</color> dalam jangkauan untuk bergerak sejauh <color=#00F6FF>2</color> tile menuju tile yang dipilih. Damage berkurang sebesar 53% per klaster.",
  str_skill_desc_320142 = "Pilih 1 dari <color=#00F6FF>13 tile dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada tile yang dipilih dan <color=#00F6FF>3 klaster di sekitar</color> serta memaksa musuh <color=#00F6FF>non-Boss</color> dalam jangkauan untuk bergerak sejauh <color=#00F6FF>2</color> tile menuju tile yang dipilih. Damage berkurang sebesar 53% per klaster.",
  str_skill_desc_322142 = "Pilih 1 dari <color=#00F6FF>13 tile dalam bentuk wajik</color>, menimbulkan <color=#00F6FF>{1}%</color> damage pada tile yang dipilih dan <color=#00F6FF>3 klaster di sekitar</color> serta memaksa musuh <color=#00F6FF>non-Boss</color> dalam jangkauan untuk bergerak sejauh <color=#00F6FF>2</color> tile menuju tile yang dipilih. Damage berkurang sebesar 53% per klaster.",
  str_skill_passive_desc_410142 = "Untuk setiap Normal Attack <color=#00F6FF>ke-3</color>, persentase HP saat ini pada target meningkatkan damage Normal Attack. Jika HP target maks, batas damage meningkat sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420142 = "Untuk setiap Normal Attack <color=#00F6FF>ke-3</color> dan <color=#00F6FF>ke-5</color>, persentase HP saat ini pada target meningkatkan damage Normal Attack. Jika HP target maks, batas damage meningkat sebesar <color=#00F6FF>{1}</color>.",
