  str_skill_desc_2001401 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2001402 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color>.",
  str_skill_desc_2001403 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_300140 = "Setelah digunakan, Thunder Aurorian akan melepaskan Chain Combo <color=#00F6FF>dua kali</color> selama putaran ini. Untuk pelepasan <color=#00F6FF>kedua</color>, seluruh ATK Thunder Aurorian menjadi setara dengan <color=#00F6FF>80%</color> ATK Florine.",
  str_skill_desc_306140 = "Setelah digunakan, Thunder Aurorian akan melepaskan Chain Combo <color=#00F6FF>dua kali</color> selama putaran ini. Untuk pelepasan <color=#00F6FF>kedua</color>, seluruh ATK Thunder Aurorian sebesar <color=#00F6FF>80%</color> ATK Florine.",
  str_skill_desc_320140 = "Setelah digunakan, Thunder Aurorian akan melepaskan Chain Combo <color=#00F6FF>dua kali</color> selama putaran ini. Untuk pelepasan <color=#00F6FF>kedua</color>, seluruh ATK Thunder Aurorian menjadi setara dengan <color=#00F6FF>80%</color> ATK Florine. Di waktu yang bersamaan, jumlah tile yang dibutuhkan untuk memicu Thunder Aurorian Chain Combo adalah <color=#00F6FF>-1</color>.",
  str_skill_desc_326140 = "Setelah digunakan, Thunder Aurorian akan melepaskan Chain Combo <color=#00F6FF>dua kali</color> selama putaran ini. Untuk pelepasan <color=#00F6FF>kedua</color>, seluruh ATK Thunder Aurorian sebesar <color=#00F6FF>80%</color> ATK Florine. Di waktu yang bersamaan, jumlah tile yang dibutuhkan untuk memicu Thunder Aurorian Chain Combo adalah <color=#00F6FF>-1</color>.",
  str_skill_desc_330140 = "Setelah digunakan, Thunder Aurorian akan melepaskan Chain Combo <color=#00F6FF>dua kali</color> selama putaran ini. Untuk pelepasan <color=#00F6FF>kedua</color>, seluruh ATK Thunder Aurorian menjadi setara dengan <color=#00F6FF>95%</color> ATK Florine. Di waktu yang bersamaan, jumlah tile yang dibutuhkan untuk memicu Thunder Aurorian Chain Combo adalah <color=#00F6FF>-1</color>.",
  str_skill_desc_336140 = "Setelah digunakan, Thunder Aurorian akan melepaskan Chain Combo <color=#00F6FF>dua kali</color> selama putaran ini. Untuk pelepasan <color=#00F6FF>kedua</color>, seluruh ATK Thunder Aurorian sebesar <color=#00F6FF>95%</color> ATK Florine. Di waktu yang bersamaan, jumlah tile yang dibutuhkan untuk memicu Thunder Aurorian Chain Combo adalah <color=#00F6FF>-1</color>.",
  str_skill_passive_desc_410140 = "Damage untuk semua Chain Combo Thunder Aurorian dari peringkat yang berbeda masing-masing ditingkatkan sebesar <color=#00F6FF>{1}</color>/<color=#00F6FF>{2}</color>/<color=#00F6FF>{3}</color>.",
  str_skill_name_200150110 = "Ghost - Rip",
  str_skill_desc_200150110 = "Menebas target dalam jangkauan dengan cakar tajamnya.",
  str_skill_name_290200101 = "Shadow Nobutora",
  str_skill_desc_290200101 = "Ketika musuh berada dalam 2 klaster di sekitarnya, berteleportasi ke satu lokasi sejauh 6 tile dari musuh dan meninggalkan Shadow Nobutora.",
  str_skill_name_290200102 = "Counterattack",
  str_skill_desc_290200102 = "Ketika tidak ada musuh dalam 2 klaster di sekitarnya, ia akan memberikan serangan jarak jauh pada unit musuh dalam jangkauannya, mengacak urutan tim Aurorian.",
  str_skill_name_290200112 = "Counterattack",
  str_skill_desc_290200112 = "Ketika tidak ada musuh dalam 2 klaster di sekitarnya, ia akan memberikan serangan jarak jauh pada unit musuh dalam jangkauannya, mengacak urutan tim Aurorian, dan menimbulkan damage yang meningkat seiring jarak antara Nobutora Fujikumo dan targetnya.",
  str_skill_name_290200201 = "Shadow Strike",
  str_skill_desc_290200201 = "Shadow Nobutora menyerang target dalam jangkauan.",
  str_skill_upgrade_desc_16014313 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16014316 = "Equipment Skill Enhancement: Perubahan Kapten untuk pertempuran: <color=#FFFF00>+1</color>.",
  str_skill_desc_2001431 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh dalam <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_2001432 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_desc_2001433 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh dalam <color=#00F6FF>4 klaster di sekitar</color>.",
  str_skill_desc_300143 = "Memanggil Barrier yang menutupi <color=#00F6FF>2 klaster di sekitarnya</color> selama 2 putaran. Saat memanggil atau saat putaran berakhir, mengubah <color=#00F6FF>3</color> tile non-Merah acak di dalam Barrier menjadi Merah dan memberikan efek <link=\"30020\"><#FFAE07><u>Purify</u></color></link> pada semua tile Merah dalam jangkauan.",
  str_skill_desc_306143 = "Memanggil Barrier yang menutupi <color=#00F6FF>2 klaster di sekitarnya</color> selama 2 putaran. Saat memanggil atau saat putaran berakhir, mengubah <color=#00F6FF>3</color> tile non-Merah acak di dalam Barrier menjadi Merah dan memberikan efek <link=\"30020\"><#FFAE07><u>Purify</u></color></link> pada semua tile Merah dalam jangkauan.",
  str_skill_desc_330143 = "Memanggil Barrier yang menutupi <color=#00F6FF>2 klaster di sekitarnya</color> selama 2 putaran. Saat memanggil atau saat putaran berakhir, mengubah <color=#00F6FF>3</color> tile non-Merah acak di dalam Barrier menjadi Merah dan memberikan efek <link=\"30020\"><#FFAE07><u>Purify</u></color></link> pada semua tile Merah dalam jangkauan. Saat berada dalam Barrier, DEF Rinne meningkat sebesar <color=#00F6FF>50%</color>, sedangkan DEF rekan tim Fire Aurorian lain meningkat sebesar <color=#00F6FF>10%</color>.",
  str_skill_desc_336143 = "Memanggil Barrier yang menutupi <color=#00F6FF>2 klaster di sekitarnya</color> selama 2 putaran. Saat memanggil atau saat putaran berakhir, mengubah <color=#00F6FF>3</color> tile non-Merah acak di dalam Barrier menjadi Merah dan memberikan efek <link=\"30020\"><#FFAE07><u>Purify</u></color></link> pada semua tile Merah dalam jangkauan. Saat berada dalam Barrier, DEF Rinne meningkat sebesar <color=#00F6FF>50%</color>, sedangkan DEF rekan tim Fire Aurorian lain meningkat sebesar <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_410143 = "Saat posisi Rinne berubah dari anggota tim menjadi Kapten selama pertempuran, dia memulihkan HP yang setara dengan <color=#00F6FF>{1}</color> DEF miliknya saat ini. Dapat dipicu hingga <color=#00F6FF>1</color> kali per putaran.",
  str_skill_passive_desc_416143 = "Saat posisi Rinne berubah dari anggota tim menjadi Kapten selama pertempuran, dia memulihkan HP yang setara dengan <color=#00F6FF>{1}</color> DEF miliknya saat ini. Dapat dipicu hingga <color=#00F6FF>1</color> kali per putaran. Perubahan Kapten untuk pertempuran: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_420143 = "Saat posisi Rinne berubah dari anggota tim menjadi Kapten selama pertempuran, dia memulihkan HP yang setara dengan <color=#00F6FF>{1}</color> DEF miliknya saat ini. Jika HP penuh setelah dipicu, tile Biru terdekat akan diubah menjadi Merah. Dapat dipicu hingga <color=#00F6FF>1</color> kali per putaran.",
  str_skill_passive_desc_426143 = "Saat posisi Rinne berubah dari anggota tim menjadi Kapten selama pertempuran, dia memulihkan HP yang setara dengan <color=#00F6FF>{1}</color> DEF miliknya saat ini. Jika HP penuh setelah dipicu, tile Biru terdekat akan diubah menjadi Merah. Dapat dipicu hingga <color=#00F6FF>1</color> kali per putaran. Perubahan Kapten untuk pertempuran: <color=#00F6FF>+1</color>.",
