  str_skill_name_290190110 = "Sword of the Underworld - Assault",
  str_skill_desc_290190110 = "Menyerang ke arah pemain, memberikan sejumlah besar damage, dan mendorong Kapten ke bagian belakang tim. Jika pemain tidak berada di area berbentuk silang dan jauh, dia akan menggunakan serangan jarak jauh.",
  str_skill_name_290190120 = "Sword of the Underworld - Strike",
  str_skill_desc_290190120 = "Menebas pemain di sampingnya dan menimbulkan damage dalam jumlah besar. Jika pemain tidak berada di area berbentuk silang dan jauh, dia akan menggunakan serangan jarak jauh.",
  str_skill_desc_490190120 = "Setelah berlari, menebas musuh yang berdekatan, memberikan kerusakan yang sangat besar.",
  str_skill_name_290190130 = "Sword of the Underworld - Hack",
  str_skill_desc_290190130 = "Setelah bergerak menuju tengah Alchemy Board, dia mengeluarkan senapannya dan menimbulkan damage pada pemain yang tidak berada di area berbentuk silang dan jauh.",
  str_skill_desc_490190130 = "Membidik dan menembak, memberikan damage jarak jauh ke musuh di luar jangkauan serangan tebasan.",
  str_skill_name_290191110 = "Nagi - Dual Slash",
  str_skill_desc_290191110 = "Ketika pemain berada di sebelahnya, dia menyerang dengan tebasan horizontal dan tusukan ke arah depan.",
  str_skill_name_290191120 = "Nagi - Charge Attack",
  str_skill_desc_290191120 = "Saat pemain jauh, dia akan menerjang ke depan ke arah mereka untuk menimbulkan damage.",
  str_skill_name_290191130 = "Nagi - Burst Attack",
  str_skill_desc_290191130 = "Dia bergerak dengan cepat ke tengah medan tempur dan menimbulkan sejumlah besar damage ke sekelilingnya. Jika terkena, Kapten akan terlempar ke belakang tim.",
  str_skill_name_290210101 = "Devour - Wholesome",
  str_skill_desc_290210101 = "Saat target berada dalam jangkauan, Aurorian beserta Hantu dalam dua kluster di arah depan akan dimangsa. Kemudian, Aurorian menerima damage dan akan dimuntahkan ke tepi papan. Kapten akan terkena kutukan yang memaksanya mundur ke belakang tim.",
  str_skill_desc_291210101 = "Saat target berada dalam jangkauan, Aurorian beserta Hantu dalam dua kluster di arah depan akan dimangsa. Kemudian, Aurorian menerima damage dan akan dimuntahkan ke tepi papan, memaksa Kapten untuk mundur ke belakang tim.",
  str_skill_name_290210102 = "Devour - Obliterate",
  str_skill_desc_290210102 = "Memberikan damage dalam jumlah besar kepada target yang berada dalam jangkauan. Urutan tim Aurorian akan tercampur aduk dan Hantu di sekitar target akan tersingkir dalam sekejap.",
  str_skill_name_290210201 = "Devour - Ghost Army",
  str_skill_desc_290210201 = "Memanggil hantu dalam jumlah banyak saat target berada dalam jangkauan dan memperkuat semua hantu di medan tempur.",
  str_skill_desc_291210201 = "Memanggil hantu dalam jumlah banyak saat target berada dalam jangkauan dan memperkuat serta memulihkan HP semua hantu di medan tempur.",
  str_skill_name_290210301 = "Devour - Wholesome",
  str_skill_desc_290210301 = "Saat target berada dalam jangkauan, Aurorian beserta Hantu dalam dua kluster di arah depan akan dimangsa, menimbulkan damage sebenarnya pada Aurorian. Semakin banyak Hantu yang dimangsa, semakin tinggi pula damage yang ditimbulkan. Kemudian, Aurorian akan dimuntahkan ke tepi papan sementara Kapten akan terkena kutukan yang memaksanya mundur ke belakang tim.",
  str_skill_name_290042201 = "Wicked Dragon Rupture",
  str_skill_desc_290042201 = "Hakudoma membuka ruang di hadapannya, menimbulkan damage pada target di dalam area serangan.",
  str_skill_name_290042211 = "Wicked Dragon Rupture",
  str_skill_desc_290042211 = "Hakudoma membuka ruang di hadapannya, menimbulkan damage pada target di dalam area serangan, dan menghancurkan sejumlah tile di medan tempur.",
  str_skill_name_290042202 = "Hakudoma Reincarnation",
  str_skill_desc_290042202 = "Mengumpulkan kekuatan untuk melawan arus pasang, Hakudoma mengepakkan sayapnya, mendorong target ke tepi papan dan memanggil Spikepest ke medan tempur.",
  str_skill_name_290042204 = "High Tide Apostle",
  str_skill_desc_290042204 = "Hakudoma terbang ke depan, mendorong semua tile ke atas hingga 4 tile, dan mengebom area tetap setelahnya.",
  str_skill_name_290042214 = "High Tide Apostle",
  str_skill_desc_290042214 = "Hakudoma terbang ke depan dan mengebom area tetap. Target terdorong ke tepi papan terlepas dari target terkena serangan atau tidak. Saat Hakudoma mendarat, ia memanggil Spikepest di depan dirinya.",
  str_skill_upgrade_desc_16014513 = "Active Skill Enhancement: Mendapatkan <color=#FFFF00>1</color> poin Ninja Power pada permulaan setiap gelombang.",
  str_skill_upgrade_desc_16014516 = "Equipment Skill Enhancement: Perubahan Kapten untuk pertempuran: <color=#FFFF00>+1</color>.",
  str_skill_name_2001451 = "Relentless",
  str_skill_name_2001452 = "Relentless",
  str_skill_name_2001453 = "Relentless",
  str_skill_desc_2001451 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>8 tile dalam bentuk silang</color>.",
  str_skill_desc_2001452 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color> dan memanggil <color=#00F6FF>1</color> katana di tile yang bisa dilewati secara acak.",
  str_skill_desc_2001453 = "Menimbulkan <color=#00F6FF>{1}%</color> damage dalam <color=#00F6FF>1 klaster di sekitar</color> dan <color=#00F6FF>bentuk silang hingga jangkauan maksimumnya</color> dan memanggil masing-masing 1 katana di <color=#00F6FF>2</color> tile yang bisa dilewati secara acak.",
