  str_skill_name_3301454 = "Shadow Trace",
  str_skill_name_3331454 = "Shadow Trace",
  str_skill_desc_300145 = "Menggunakan <color=#00F6FF>2</color> poin <link=\"30028\"><#FFAE07><u>Ninja Power</u></color></link> dan memilih <color=#00F6FF>1</color> tile yang bisa dilalui untuk memanggil 1 katana. Jika ada katana di tile yang dipilih, Amemori akan segera berteleportasi ke lokasi itu untuk mengambil katana, mendapatkan <color=#00F6FF>1</color> poin <link=\"30028\"><#FFAE07><u>Ninja Power</u></color></link>.",
  str_skill_desc_330145 = "Menggunakan <color=#00F6FF>2</color> poin <link=\"30028\"><#FFAE07><u>Ninja Power</u></color></link> dan memilih <color=#00F6FF>1</color> tile yang bisa dilalui untuk memanggil 1 katana. Jika ada katana di tile yang dipilih, Amemori akan segera berteleportasi ke lokasi itu untuk mengambil katana, mendapatkan <color=#00F6FF>1</color> poin <link=\"30028\"><#FFAE07><u>Ninja Power</u></color></link>.",
  str_skill_desc_303145 = "Menggunakan <color=#00F6FF>2</color> poin <link=\"30029\"><#FFAE07><u>Ninja Power</u></color></link> dan memilih <color=#00F6FF>1</color> tile yang bisa dilalui untuk memanggil 1 katana. Jika ada katana di tile yang dipilih, Amemori akan segera berteleportasi ke lokasi itu untuk mengambil katana, mendapatkan <color=#00F6FF>1</color> poin <link=\"30029\"><#FFAE07><u>Ninja Power</u></color></link>.",
  str_skill_desc_333145 = "Menggunakan <color=#00F6FF>2</color> poin <link=\"30029\"><#FFAE07><u>Ninja Power</u></color></link> dan memilih <color=#00F6FF>1</color> tile yang bisa dilalui untuk memanggil 1 katana. Jika ada katana di tile yang dipilih, Amemori akan segera berteleportasi ke lokasi itu untuk mengambil katana, mendapatkan <color=#00F6FF>1</color> poin <link=\"30029\"><#FFAE07><u>Ninja Power</u></color></link>.",
  str_skill_passive_name_410145 = "Katana Slash",
  str_skill_passive_name_413145 = "Katana Slash",
  str_skill_passive_name_416145 = "Katana Slash",
  str_skill_passive_name_420145 = "Katana Slash",
  str_skill_passive_name_423145 = "Katana Slash",
  str_skill_passive_name_426145 = "Katana Slash",
  str_skill_passive_name_430145 = "Katana Slash",
  str_skill_passive_name_433145 = "Katana Slash",
  str_skill_passive_name_436145 = "Katana Slash",
  str_skill_passive_desc_410145 = "Setelah mengambil kembali semua katana dengan menggunakan Active Skill—Teleport, setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli).",
  str_skill_passive_desc_413145 = "Setelah mengambil kembali semua katana dengan menggunakan Active Skill—Teleport, setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli).",
  str_skill_passive_desc_416145 = "Setelah mengambil kembali semua katana dengan menggunakan Active Skill—Teleport, setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli). Pergantian Kapten di putaran ini: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_420145 = "Mengambil kembali semua katana setelah berpindah tempat menggunakan Active Skill. Setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli). Jika katana yang diambil sekurang-kurangnya berjumlah <color=#00F6FF>4</color>, <color=#00F6FF>1</color> katana akan dipanggil.",
  str_skill_passive_desc_423145 = "Mengambil kembali semua katana setelah berpindah tempat menggunakan Active Skill. Setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli). Jika katana yang diambil sekurang-kurangnya berjumlah <color=#00F6FF>4</color>, <color=#00F6FF>1</color> katana akan dipanggil.",
  str_skill_passive_desc_426145 = "Mengambil kembali semua katana setelah berpindah tempat menggunakan Active Skill. Setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli). Jika katana yang diambil sekurang-kurangnya berjumlah <color=#00F6FF>4</color>, <color=#00F6FF>1</color> katana akan dipanggil. Pergantian Kapten untuk pertempuran: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_430145 = "Mengambil kembali semua katana setelah berpindah tempat menggunakan Active Skill. Setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli). Jika katana yang diambil sekurang-kurangnya berjumlah <color=#00F6FF>4</color>, <color=#00F6FF>1</color> katana akan dipanggil. Saat Amemori menjadi Kapten, dia mendapatkan <color=#00F6FF>1</color><link=\"30028\"><#FFAE07><u>Ninja Power</u></color></link>. Dapat dipicu hingga <color=#00F6FF>3</color> kali per putaran.",
  str_skill_passive_desc_433145 = "Mengambil kembali semua katana setelah berpindah tempat menggunakan Active Skill. Setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli). Jika katana yang diambil sekurang-kurangnya berjumlah <color=#00F6FF>4</color>, <color=#00F6FF>1</color> katana akan dipanggil. Saat Amemori menjadi Kapten, dia mendapatkan <color=#00F6FF>1</color><link=\"30029\"><#FFAE07><u>Ninja Power</u></color></link>. Dapat dipicu hingga <color=#00F6FF>3</color> kali per putaran.",
  str_skill_passive_desc_436145 = "Mengambil kembali semua katana setelah berpindah tempat menggunakan Active Skill. Setiap katana memberikan <color=#00F6FF>{1}</color> damage ke <color=#00F6FF>1</color> musuh terdekat tanpa menghiraukan DEF-nya. Semakin jauh jaraknya, semakin kecil pula damage yang diberikan (minimal 20% damage asli). Jika katana yang diambil sekurang-kurangnya berjumlah <color=#00F6FF>4</color>, <color=#00F6FF>1</color> katana akan dipanggil. Saat Amemori menjadi Kapten, dia mendapatkan <color=#00F6FF>1</color><link=\"30029\"><#FFAE07><u>Ninja Power</u></color></link>. Dapat dipicu hingga <color=#00F6FF>3</color> kali per putaran. Pergantian Kapten untuk pertempuran: <color=#00F6FF>+1</color>.",
