  str_skill_name_333146 = "Heaven-sent",
  str_skill_desc_300146 = "Bertukar posisi dengan Kapten saat ini dan damage Chain Combo di putaran ini menimbulkan damage 2 kali lipat ke <color=#00F6FF>4 tile yang berdekatan</color>. Saat putaran berakhir, bertukar posisi dengan Aurorian yang berada di akhir tim.",
  str_skill_desc_303146 = "Bertukar posisi dengan Kapten saat ini dan damage Chain Combo di putaran ini menimbulkan damage 2 kali lipat ke <color=#00F6FF>4 tile yang berdekatan</color>. Saat putaran berakhir, bertukar posisi dengan Aurorian yang berada di akhir tim.",
  str_skill_desc_320146 = "Bertukar posisi dengan Kapten saat ini, mendapatkan 1 tumpuk <link=\"30026\"><#FFAE07><u>Heroic Mark</u></color></link>, dan Chain Combo di putaran ini menimbulkan damage 2 kali lipat ke <color=#00F6FF>4 tile yang berdekatan</color>. Saat putaran berakhir, bertukar posisi dengan Aurorian yang berada di akhir tim.",
  str_skill_desc_323146 = "Bertukar posisi dengan Kapten saat ini, mendapatkan 1 tumpuk <link=\"30026\"><#FFAE07><u>Heroic Mark</u></color></link>, dan Chain Combo di putaran ini menimbulkan damage 2 kali lipat ke <color=#00F6FF>4 tile yang berdekatan</color>. Saat putaran berakhir, bertukar posisi dengan Aurorian yang berada di akhir tim.",
  str_skill_desc_330146 = "Bertukar posisi dengan Kapten saat ini, mendapatkan 1 tumpuk <link=\"30026\"><#FFAE07><u>Heroic Mark</u></color></link>, dan Chain Combo di putaran ini menimbulkan damage 2 kali lipat ke <color=#00F6FF>4 tile yang berdekatan</color>. Saat putaran berakhir, bertukar posisi dengan Aurorian yang berada di akhir tim.",
  str_skill_desc_333146 = "Bertukar posisi dengan Kapten saat ini, mendapatkan 1 tumpuk <link=\"30026\"><#FFAE07><u>Heroic Mark</u></color></link>, dan Chain Combo di putaran ini menimbulkan damage 2 kali lipat ke <color=#00F6FF>4 tile yang berdekatan</color>. Saat putaran berakhir, bertukar posisi dengan Aurorian yang berada di akhir tim.",
  str_skill_passive_name_410146 = "Crossed Path",
  str_skill_passive_name_416146 = "Crossed Path",
  str_skill_passive_name_430146 = "Crossed Path",
  str_skill_passive_name_436146 = "Crossed Path",
  str_skill_passive_desc_410146 = "Mendapatkan <link=\"30026\"><#FFAE07><u>Heroic Mark</u></color></link>. Jika Yao sudah menjadi Kapten di putaran ini, setiap tumpuk Heroic Mark meningkatkan ATK dasar Yao sebesar <color=#00F6FF>{1}</color>. Bonus dan tumpukan dihapus di akhir putaran.",
  str_skill_passive_desc_416146 = "Mendapatkan <link=\"30026\"><#FFAE07><u>Heroic Mark</u></color></link>. Jika Yao sudah menjadi Kapten di putaran ini, setiap tumpuk Heroic Mark meningkatkan ATK dasar Yao sebesar <color=#00F6FF>{1}</color>. Bonus dan tumpukan dihapus di akhir putaran. Pergantian Kapten di putaran ini: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_430146 = "Mendapatkan <link=\"30027\"><#FFAE07><u>Heroic Mark</u></color></link>. Jika Yao sudah menjadi Kapten di putaran ini, setiap tumpuk Heroic Mark meningkatkan ATK dasar Yao sebesar <color=#00F6FF>{1}</color>. Bonus dan tumpukan dihapus di akhir putaran. Setiap kali Yao menjadi Kapten, <color=#00F6FF>1</color> tumpuk <link=\"30027\"><#FFAE07><u>Heroic Mark</u></color></link> akan didapatkan.",
  str_skill_passive_desc_436146 = "Mendapatkan <link=\"30027\"><#FFAE07><u>Heroic Mark</u></color></link>. Jika Yao sudah menjadi Kapten di putaran ini, setiap tumpuk Heroic Mark meningkatkan ATK dasar Yao sebesar <color=#00F6FF>{1}</color>. Bonus dan tumpukan dihapus di akhir putaran. Setiap kali Yao menjadi Kapten, <color=#00F6FF>1</color> tumpuk <link=\"30027\"><#FFAE07><u>Heroic Mark</u></color></link> akan didapatkan. Pergantian Kapten di putaran ini: <color=#00F6FF>+1</color>.",
  str_skill_upgrade_desc_15014712 = "Active Skill Enhancement: Mengurangi cooldown skill sebanyak <color=#FFFF00>1</color> putaran saat menjadi Kapten. Dapat dipicu hingga <color=#00F6FF>3</color> kali per putaran.",
  str_skill_upgrade_desc_15014715 = "Equipment Skill Enhancement: Perubahan Kapten untuk pertempuran: <color=#FFFF00>+1</color>.",
  str_skill_desc_2001471 = "Menimbulkan <color=#00F6FF>150%</color> damage sebanyak 2 kali pada unit musuh acak dalam <color=#00F6FF>3 klaster di sekitar</color>. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_2001472 = "Menimbulkan <color=#00F6FF>160%</color> damage 3 kali, ditetapkan secara acak pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> unit ini. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_2001473 = "Menimbulkan <color=#00F6FF>160%</color> damage 4 kali pada unit musuh acak dalam <color=#00F6FF>3 klaster di sekitar</color> pengguna. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_300147 = "Menimbulkan <color=#00F6FF>{1}%</color> damage <color=#00F6FF>8</color> kali pada 1 tile yang dipilih dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_desc_302147 = "Menimbulkan <color=#00F6FF>{1}%</color> damage <color=#00F6FF>8</color> kali pada 1 tile yang dipilih dalam <color=#00F6FF>3 klaster di sekitar</color>. Mengurangi cooldown skill sebanyak <color=#FFFF00>1</color> putaran saat menjadi Kapten. Dapat dipicu hingga <color=#00F6FF>3</color> kali per putaran.",
  str_skill_desc_320147 = "Menimbulkan <color=#00F6FF>{1}%</color> damage <color=#00F6FF>8</color> kali pada 1 tile yang dipilih dalam <color=#00F6FF>3 klaster di sekitar</color>, lalu menimbulkan <color=#00F6FF>188%</color> damage tambahan pada tile yang sama dan dalam <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_322147 = "Menimbulkan <color=#00F6FF>{1}%</color> damage <color=#00F6FF>8</color> kali pada 1 tile yang dipilih dalam <color=#00F6FF>3 klaster di sekitar</color>, lalu menimbulkan <color=#00F6FF>188%</color> damage tambahan pada tile yang sama dan dalam <color=#00F6FF>1 klaster di sekitar</color>. Mengurangi cooldown Active Skill sebanyak <color=#FFFF00>1</color> putaran saat menjadi Kapten. Dapat dipicu hingga <color=#00F6FF>3</color> kali per putaran.",
  str_skill_passive_desc_410147 = "Di awal setiap putaran, Momo & Anzu akan menjadi Kapten secara otomatis sementara anggota tim lainnya mundur 1 posisi. Setiap kali Momo & Anzu menjadi Kapten, <link=\"30030\"><#FFAE07><u>Special Kaniya Cuisine</u></color></link> akan didapat disertai dengan <color=#00F6FF>{1}</color> peluang <color=#00F6FF>untuk tambahan satu</color>.",
  str_skill_passive_desc_415147 = "Di awal setiap putaran, Momo & Anzu akan menjadi Kapten secara otomatis sementara anggota tim lainnya mundur 1 posisi. Setiap kali Momo & Anzu menjadi Kapten, <link=\"30030\"><#FFAE07><u>Special Kaniya Cuisine</u></color></link> akan didapat dengan <color=#00F6FF>{1}</color> peluang <color=#00F6FF>untuk tambahan satu</color>. Perubahan Kapten di putaran ini: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_430147 = "Pada awal setiap putaran, Momo & Anzu akan menjadi Kapten secara otomatis sementara anggota tim lainnya mundur 1 posisi. Setiap kali Momo & Anzu menjadi Kapten, <link=\"30030\"><#FFAE07><u>Special Kaniya Cuisine</u></color></link> akan didapat disertai dengan <color=#00F6FF>{1}</color> peluang <color=#00F6FF>untuk mendapatkan satu lagi</color>!",
  str_skill_passive_desc_435147 = "Pada awal setiap putaran, Momo & Anzu akan menjadi Kapten secara otomatis sementara anggota tim lainnya mundur 1 posisi. Setiap kali Momo & Anzu menjadi Kapten, <link=\"30030\"><#FFAE07><u>Special Kaniya Cuisine</u></color></link> akan didapat disertai dengan <color=#00F6FF>{1}</color> peluang <color=#00F6FF>untuk mendapatkan satu lagi</color>! Pergantian Kapten untuk pertempuran: <color=#00F6FF>+1</color>.",
