  str_skill_desc_2301519 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada musuh dengan persentase HP paling rendah 2 kali. Saat Sanity Point di bawah <color=#00F6FF>60|25|0</color>, ia menimbulkan damage tambahan 1|2|3 kali. Mengurangi Damage Final setiap kali sebesar <color=#00F6FF>5%</color>.",
  str_skill_desc_300151 = "Giles terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Menggunakan <color=#00F6FF>15</color> Sanity Point untuk menimbulkan <color=#00F6FF>{1}%</color> DMG pada musuh dalam 4 Tile yang berdekatan dalam <color=#00F6FF>bentuk silang</color> di sekitar 1 Tile yang dipilih. Menimbulkan 2× damage jika Tile pengguna dipilih.",
  str_skill_desc_3001510 = "Giles terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Menggunakan <color=#00F6FF>15</color> Sanity Point untuk menimbulkan <color=#00F6FF>{1}%</color> DMG pada musuh dalam 4 Tile yang berdekatan dalam <color=#00F6FF>bentuk silang</color> di sekitar 1 Tile yang dipilih. Menimbulkan 2× damage jika Tile pengguna dipilih. Setelah menyingkirkan target, Active Skill bisa digunakan lagi untuk menimbulkan 2x Damage Final dengan menggunakan Sanity Point sebanyak dua kali lipat.",
  str_skill_desc_3001511 = "Giles terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Menggunakan <color=#00F6FF>30</color> Sanity Point untuk menimbulkan <color=#00F6FF>{1}%</color> DMG pada musuh dalam 4 Tile yang berdekatan dalam <color=#00F6FF>bentuk silang</color> di sekitar 1 Tile yang dipilih. Menimbulkan 2× damage jika Tile pengguna dipilih. Setelah menyingkirkan target, Active Skill bisa digunakan lagi untuk menimbulkan 2x Damage Final dengan menggunakan Sanity Point sebanyak dua kali lipat.",
  str_skill_desc_3001512 = "Giles terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Menggunakan <color=#00F6FF>60</color> Sanity Point untuk menimbulkan <color=#00F6FF>{1}%</color> DMG pada musuh dalam 4 Tile yang berdekatan dalam <color=#00F6FF>bentuk silang</color> di sekitar 1 Tile yang dipilih. Menimbulkan 2× damage jika Tile pengguna dipilih. Setelah menyingkirkan target, Active Skill bisa digunakan lagi untuk menimbulkan 2x Damage Final dengan menggunakan Sanity Point sebanyak dua kali lipat.",
  str_skill_desc_3001513 = "Giles terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Menggunakan <color=#00F6FF>120</color> Sanity Point untuk menimbulkan <color=#00F6FF>{1}%</color> DMG pada musuh dalam 4 Tile yang berdekatan dalam <color=#00F6FF>bentuk silang</color> di sekitar 1 Tile yang dipilih. Menimbulkan 2× damage jika Tile pengguna dipilih. Setelah menyingkirkan target, Active Skill bisa digunakan lagi untuk menimbulkan 2x Damage Final dengan menggunakan Sanity Point sebanyak dua kali lipat.",
  str_skill_desc_3001514 = "Giles terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Menggunakan <color=#00F6FF>240</color> Sanity Point untuk menimbulkan <color=#00F6FF>{1}%</color> DMG pada musuh dalam 4 Tile yang berdekatan dalam <color=#00F6FF>bentuk silang</color> di sekitar 1 Tile yang dipilih. Menimbulkan 2× damage jika Tile pengguna dipilih. Setelah menyingkirkan target, Active Skill bisa digunakan lagi untuk menimbulkan 2x Damage Final dengan menggunakan Sanity Point sebanyak dua kali lipat.",
  str_skill_passive_desc_410151 = "<color=#00F6FF>Diaktifkan setelah menyingkirkan musuh</color> di putaran ini: Saat Giles menimbulkan damage, ATK miliknya ditingkatkan sesuai Sanity Point saat ini. Semakin rendah Sanity Point, semakin besar damage yang ditimbulkan, hingga <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_413151 = "<color=#00F6FF>Diaktifkan setelah menyingkirkan musuh</color> di putaran ini: Saat Giles menimbulkan damage, DMG ditingkatkan sesuai Sanity saat ini. Semakin rendah Sanity, semakin tinggi peningkatan damage, hingga <color=#00F6FF>{1}</color>. Penyingkiran <color=#00F6FF>Mirage</color> mana pun juga meningkatkan bonus sebesar <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_416151 = "<color=#00F6FF>Diaktifkan setelah menyingkirkan musuh</color> di putaran ini: Saat Giles menimbulkan damage, DMG ditingkatkan sesuai Sanity saat ini. Semakin rendah Sanity, semakin tinggi peningkatan damage, hingga <color=#00F6FF>{1}</color>. Penyingkiran <color=#00F6FF>Mirage</color> mana pun juga meningkatkan bonus sebesar <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_430151 = "<color=#00F6FF>Diaktifkan setelah menyingkirkan musuh</color> di putaran ini: Saat Giles menimbulkan damage, DMG ditingkatkan sesuai Sanity saat ini. Semakin rendah Sanity, semakin tinggi peningkatan damage, hingga <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_433151 = "<color=#00F6FF>Diaktifkan setelah menyingkirkan musuh</color> di putaran ini: Saat Giles menimbulkan damage, DMG ditingkatkan sesuai Sanity saat ini. Semakin rendah Sanity, semakin tinggi peningkatan damage, hingga <color=#00F6FF>{1}</color>. Penyingkiran <color=#00F6FF>Mirage</color> mana pun juga meningkatkan bonus sebesar <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_436151 = "<color=#00F6FF>Diaktifkan setelah menyingkirkan musuh</color> di putaran ini: Saat Giles menimbulkan damage, DMG ditingkatkan sesuai Sanity saat ini. Semakin rendah Sanity, semakin tinggi peningkatan damage, hingga <color=#00F6FF>{1}</color>. Penyingkiran <color=#00F6FF>Mirage</color> mana pun juga meningkatkan bonus sebesar <color=#00F6FF>10%</color>.",
