  str_skill_desc_22015012 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 baris</color>.",
  str_skill_desc_22015013 = "Menimbulkan <color=#00F6FF>{1}%</color> damage ke <color=#00F6FF>5 baris</color>. Saat Sanity Point berkurang hingga di bawah <color=#00F6FF>75</color>, kondisi pemicu berkurang menjadi <color=#00F6FF>15</color>. Jika dalam <color=#00F6FF>Insane State</color>, kondisi pemicu berkurang menjadi <color=#00F6FF>5</color>.",
  str_skill_desc_23015011 = "Menimbulkan <color=#00F6FF>{1}%</color> DMG ke <color=#00F6FF>1 baris</color>. Semakin rendah Sanity, semakin tinggi peningkatan DMG, hingga <color=#00F6FF>80%</color>.",
  str_skill_desc_23015012 = "Menimbulkan <color=#00F6FF>{1}%</color> DMG ke <color=#00F6FF>3 baris</color>. Semakin rendah Sanity, semakin tinggi peningkatan DMG, hingga <color=#00F6FF>80%</color>.",
  str_skill_desc_23015013 = "Menimbulkan <color=#00F6FF>{1}%</color> damage ke <color=#00F6FF>5 baris</color>. Saat Sanity Point berkurang hingga di bawah <color=#00F6FF>75</color>, kondisi pemicu berkurang menjadi <color=#00F6FF>15</color>. Jika dalam <color=#00F6FF>Insane State</color>, kondisi pemicu berkurang menjadi <color=#00F6FF>5</color>. Semakin rendah Sanity, semakin besar peningkatan DMG, hingga <color=#00F6FF>80%</color>.",
  str_skill_desc_23615011 = "Menimbulkan <color=#00F6FF>{1}%</color> DMG ke <color=#00F6FF>1 baris</color>. Semakin rendah Sanity, semakin tinggi peningkatan DMG, hingga <color=#00F6FF>100%</color>.",
  str_skill_desc_23615012 = "Menimbulkan <color=#00F6FF>{1}%</color> DMG ke <color=#00F6FF>3 baris</color>. Semakin rendah Sanity, semakin tinggi peningkatan DMG, hingga <color=#00F6FF>100%</color>.",
  str_skill_desc_23615013 = "Menimbulkan <color=#00F6FF>{1}%</color> damage ke <color=#00F6FF>5 baris</color>. Saat Sanity Point berkurang hingga di bawah <color=#00F6FF>75</color>, kondisi pemicu berkurang menjadi <color=#00F6FF>15</color>. Jika dalam <color=#00F6FF>Insane State</color>, kondisi pemicu berkurang menjadi <color=#00F6FF>5</color>. Semakin rendah Sanity, semakin besar peningkatan DMG, hingga <color=#00F6FF>100%</color>.",
  str_skill_desc_3001501 = "Lenore terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Pilih 1 Tile mana pun lalu pilih 1 Tile lagi dalam <color=#00F6FF>2 klaster di sekitar</color> untuk menciptakan area persegi panjang, yang di dalamnya menimbulkan <color=#00F6FF>333%</color> DMG pada Tile. Setiap Tile dalam persegi panjang mengurangi <color=#00F6FF>3</color> Sanity Point. Jika musuh menerima damage lebih dari sekali, efek selanjutnya berkurang menjadi <color=#00F6FF>33%</color>.",
  str_skill_desc_3031501 = "Lenore terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Pilih 1 Tile mana pun lalu pilih 1 Tile lagi dalam <color=#00F6FF>2 klaster di sekitar</color> untuk menciptakan area persegi panjang, yang di dalamnya menimbulkan <color=#00F6FF>333%</color> DMG pada Tile. Setiap Tile dalam persegi panjang mengurangi <color=#00F6FF>3</color> Sanity Point. Jika unit musuh menerima damage lebih dari sekali, efek selanjutnya berkurang menjadi <color=#00F6FF>33%</color>. Setiap kali Active Skill menimbulkan DMG, HP Maks Lenore meningkat sebesar <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_410150 = "Jika tidak dalam <color=#00F6FF>Calm State</color> pada permulaan setiap putaran, timbulkan DMG yang setara dengan <color=#00F6FF>{1}</color> dari HP Maks tim pada semua musuh. Semakin rendah Sanity, semakin tinggi peningkatan damage, hingga <color=#00F6FF>{2}</color> dari HP Maks tim.",
