  str_skill_name_3001541 = "Target Secured",
  str_skill_name_320154 = "Target Secured",
  str_skill_name_330154 = "Target Secured",
  str_skill_desc_300154 = "Memilih dan <color=#00F6FF>mengunci</color> 1 musuh. Jumlah maksimum target yang dikunci sekaligus adalah <color=#00F6FF>1</color>. Jika target yang dikunci masih hidup, Chain Combo dari Vice: Keen Sight hanya akan <color=#00F6FF>menargetnya</color>. Jika musuh yang dipilih sudah dikunci, <color=#00F6FF>100%</color> damage akan ditimbulkan padanya.",
  str_skill_desc_330154 = "Memilih dan <color=#00F6FF>mengunci</color> 1 musuh. Jumlah maksimum target yang dikunci sekaligus adalah <color=#00F6FF>1</color>. Jika target yang dikunci masih hidup, Chain Combo dari Vice: Keen Sight akan selalu <color=#00F6FF>menargetnya</color>. Jika musuh yang dipilih sudah dikunci, <color=#00F6FF>100%</color> damage akan ditimbulkan padanya satu kali. Setiap tumpukan <link=\"30042\"><#FFAE07><u>Timeless Mark</u></color></link> pada target akan meningkatkan tambahan damage sebesar <color=#00F6FF>5%</color>.",
  str_skill_desc_200154 = "Menimbulkan <color=#00F6FF>100%</color> damage satu kali pada target terdekat untuk setiap <color=#00F6FF>3</color> Tile berturut-turut yang dilalui. Damage ini tidak terpengaruh oleh jumlah Tile yang terhubung.",
  str_skill_desc_203154 = "Menimbulkan <color=#00F6FF>100%</color> damage satu kali pada target terdekat untuk setiap <color=#00F6FF>3</color> Tile berturut-turut yang dilalui. Damage ini tidak terpengaruh oleh jumlah Tile yang terhubung. Jumlah serangan Chain Combo akan selalu <color=#00F6FF>+1</color>.",
  str_skill_desc_206154 = "Menimbulkan <color=#00F6FF>100%</color> damage satu kali pada target terdekat untuk setiap <color=#00F6FF>3</color> Tile berturut-turut yang dilalui. Damage ini tidak terpengaruh oleh jumlah Tile yang terhubung. Jumlah serangan Chain Combo akan selalu <color=#00F6FF>+1</color>.",
  str_skill_passive_name_410154 = "Timeless Insignia",
  str_skill_passive_name_420154 = "Timeless Insignia",
  str_skill_passive_desc_410154 = "Memberikan <link=\"30042\"><#FFAE07><u>Timeless Mark</u></color></link> pada target yang dikunci. Setiap tumpukan <link=\"30042\"><#FFAE07><u>Timeless Mark</u></color></link> akan meningkatkan damage yang Vice: Keen Sight timbulkan pada target sebesar <color=#00F6FF>{1}</color>.",
