  str_skill_desc_20015510 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_20015520 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color>.",
  str_skill_desc_20015530 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_passive_desc_410155 = "Saat dalam <color=#00F6FF>Lone State, </color> Normal Attack menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Tile non-target menerima <color=#00F6FF>{1}</color> damage normal.",
  str_skill_passive_desc_416155 = "Saat dalam <color=#00F6FF>Lone State, </color> Normal Attack menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Tile non-target menerima <color=#00F6FF>{1}</color> damage normal.",
  str_skill_passive_desc_420155 = "Saat dalam <color=#00F6FF>Lone State</color>, Normal Attack menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Tile non-target menerima <color=#00F6FF>{1}</color> damage normal. Saat dalam <color=#00F6FF>Lone State</color>, serangan normal pertama pada setiap musuh setiap ronde akan diikuti dengan serangan normal tambahan, menimbulkan <color=#00F6FF>{1}</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_passive_desc_426155 = "Saat dalam <color=#00F6FF>Lone State</color>, Normal Attack menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Tile non-target menerima <color=#00F6FF>{1}</color> damage normal. Saat dalam <color=#00F6FF>Lone State</color>, serangan normal pertama pada setiap musuh setiap ronde akan diikuti dengan serangan normal tambahan, menimbulkan <color=#00F6FF>{1}</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_passive_desc_430155 = "Normal Attack bisa <color=#00F6FF>menarget musuh pada Tile diagonal</color>. Saat dalam <color=#00F6FF>Lone State, </color> Normal Attack menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Tile non-target menerima <color=#00F6FF>{1}</color> damage normal. Saat dalam <color=#00F6FF>Lone State</color>, serangan normal pertama pada setiap musuh setiap ronde akan diikuti dengan serangan normal tambahan, menimbulkan <color=#00F6FF>{1}</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_passive_desc_436155 = "Normal Attack bisa <color=#00F6FF>menarget musuh pada Tile diagonal</color>. Saat dalam <color=#00F6FF>Lone State, </color> Normal Attack menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Tile non-target menerima <color=#00F6FF>{1}</color> damage normal. Saat dalam <color=#00F6FF>Lone State</color>, serangan normal pertama pada setiap musuh setiap ronde akan diikuti dengan serangan normal tambahan, menimbulkan <color=#00F6FF>{1}</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_upgrade_desc_16015513 = "Active Skill Enhancement: Mendapatkan <color=#00F6FF>20</color> Lone Energy pada permulaan setiap pertempuran.",
  str_skill_upgrade_desc_16015516 = "Active Skill Enhancement: Mendapatkan <color=#00F6FF>5</color> Lone Energy seketika setelah penggunaan Active Skill.",
  str_skill_passive_desc_440153 = "Normal Attack bisa <color=#00F6FF>menarget musuh pada Tile diagonal</color>. Saat dalam <color=#00F6FF>Lone State, </color> Normal Attack menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Tile non-target menerima <color=#00F6FF>65%</color> damage normal. Saat dalam <color=#00F6FF>Lone State</color>, serangan normal pertama pada setiap musuh setiap ronde akan diikuti dengan serangan normal tambahan, menimbulkan <color=#00F6FF>65%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_350155 = "20 <link=\"30045\"><#FFAE07><u>Lone Energy</u></color></link> digunakan untuk memasuki <color=#00F6FF>Lone State</color> di putaran saat ini sehingga jangkauan Chain Combo dan damage meningkat. Di akhir putaran, jika sisa Lone Energy di akhir putaran kurang dari <color=#00F6FF>8</color>, Lone Energy akan <color=#00F6FF>dibagi dua</color> (mengurangi setidaknya 8 poin) dan <color=#00F6FF>Lone State akan dipertahankan</color> di putaran berikutnya.",
  str_skill_desc_353155 = "20 <link=\"30046\"><#FFAE07><u>Lone Energy</u></color></link> digunakan untuk memasuki <color=#00F6FF>Lone State</color> di putaran saat ini sehingga jangkauan Chain Combo dan damage meningkat. Di akhir putaran, jika sisa Lone Energy di akhir putaran kurang dari <color=#00F6FF>8</color>, Lone Energy akan <color=#00F6FF>dibagi dua</color> (mengurangi setidaknya 8 poin) dan <color=#00F6FF>Lone State akan dipertahankan</color> di putaran berikutnya.",
  str_skill_desc_356155 = "20 <link=\"30047\"><#FFAE07><u>Lone Energy</u></color></link> digunakan untuk memasuki <color=#00F6FF>Lone State</color> di putaran saat ini sehingga jangkauan Chain Combo dan damage meningkat. Di akhir putaran, jika sisa Lone Energy di akhir putaran kurang dari <color=#00F6FF>8</color>, Lone Energy akan <color=#00F6FF>dibagi dua</color> (mengurangi setidaknya 8 poin) dan <color=#00F6FF>Lone State akan dipertahankan</color> di putaran berikutnya.",
  str_skill_desc_360155 = "16 <link=\"30045\"><#FFAE07><u>Lone Energy</u></color></link> digunakan untuk memasuki <color=#00F6FF>Lone State</color> di putaran saat ini sehingga jangkauan Chain Combo dan damage meningkat. Di akhir putaran, jika sisa Lone Energy di akhir putaran kurang dari <color=#00F6FF>8</color>, Lone Energy akan <color=#00F6FF>dibagi dua</color> (mengurangi setidaknya 8 poin) dan <color=#00F6FF>Lone State akan dipertahankan</color> di putaran berikutnya.",
  str_skill_desc_363155 = "16 <link=\"30046\"><#FFAE07><u>Lone Energy</u></color></link> digunakan untuk memasuki <color=#00F6FF>Lone State</color> di putaran saat ini sehingga jangkauan Chain Combo dan damage meningkat. Di akhir putaran, jika sisa Lone Energy di akhir putaran kurang dari <color=#00F6FF>8</color>, Lone Energy akan <color=#00F6FF>dibagi dua</color> (mengurangi setidaknya 8 poin) dan <color=#00F6FF>Lone State akan dipertahankan</color> di putaran berikutnya.",
  str_skill_desc_366155 = "16 <link=\"30047\"><#FFAE07><u>Lone Energy</u></color></link> digunakan untuk memasuki <color=#00F6FF>Lone State</color> di putaran saat ini sehingga jangkauan Chain Combo dan damage meningkat. Di akhir putaran, jika sisa Lone Energy di akhir putaran kurang dari <color=#00F6FF>8</color>, Lone Energy akan <color=#00F6FF>dibagi dua</color> (mengurangi setidaknya 8 poin) dan <color=#00F6FF>Lone State akan dipertahankan</color> di putaran berikutnya.",
  str_skill_upgrade_refine_desc_16015511 = "Peningkatan Keterampilan Peralatan: Saat dalam Lone State, Normal Attack menimbulkan <color=#00F6FF>65%</color> damage normal pada Tile non-target.",
  str_skill_upgrade_refine_desc_16015512 = "Active Skill Enhancement: Di akhir putaran, jika sisa Lone Energy di akhir putaran tidak kurang dari <color=#00F6FF>8</color>, Lone Energy akan <color=#00F6FF>dibagi dua</color> (mengurangi setidaknya 8 poin) dan <color=#00F6FF>Lone State akan dipertahankan</color> di putaran berikutnya.",
  str_skill_upgrade_refine_desc_16015513 = "Active Skill Enhancement: Menggunakan <color=#00F6FF>16</color> Lone Energy untuk memasuki Lone State.",
  str_skill_upgrade_desc_16015313 = [[
Peningkatan Skill Aktif: Mengubah Skill Aktif menjadi <color=#FFFF00>Serangan Preemptive</color>. Tersedia saat memasuki pertempuran.
Peningkatan Skill Peralatan: Setelah memasuki pertempuran, langsung mendapatkan <color=#FFFF00>2</color> Finale. (Berlaku untuk Ascension I)]],
  str_skill_upgrade_desc_16015316 = [[
