  str_skill_passive_name_436153 = "Power of Illumina",
  str_skill_passive_desc_410153 = "Mendapatkan <link=\"30043\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_413153 = "Mendapatkan <link=\"30043\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>{1}</color>. Saat memasuki pertempuran, langsung mendapatkan <color=#00F6FF>2</color> Finale.",
  str_skill_passive_desc_420153 = "Mendapatkan <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>{1}</color>. Setiap kali melewati Dark Tile, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale. Finale tambahan ini menghilang saat memasuki Aurora Time, atau di akhir ronde.",
  str_skill_passive_desc_423153 = "Mendapatkan <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>{1}</color>. Saat memasuki pertempuran, langsung mendapatkan <color=#00F6FF>2</color> Finale. Setiap kali melewati Dark Tile, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale. Finale tambahan ini menghilang saat memasuki Aurora Time, atau di akhir ronde.",
  str_skill_passive_desc_426153 = "Mendapatkan <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>{1}</color>. Saat memasuki pertempuran, langsung mendapatkan <color=#00F6FF>2</color> Finale. Setiap kali melewati Dark Tile, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale, dan meningkatkan faktor damage Chain Combo sebesar <color=#00F6FF>2%</color>. Finale tambahan ini dan bonus Chain Combo menghilang saat memasuki Aurora Time, atau di akhir ronde.",
  str_skill_passive_desc_430153 = "Mendapatkan <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>{1}</color>. <color=#00F6FF>Thunder</color> Aurorian atau <color=#00F6FF>Illumina Federation</color> Aurorian akan mendapatkan 50% Finale</color> bonus berdasarkan <color=#00F6FF>ATK</color> mereka. Setiap kali melewati Dark Tile, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale. Finale tambahan ini menghilang saat memasuki Aurora Time, atau di akhir putaran.",
  str_skill_passive_desc_433153 = "Mendapatkan <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>{1}</color>. <color=#00F6FF>Thunder</color> Aurorian atau <color=#00F6FF>Illumina Federation</color> Aurorian akan mendapatkan 50% Finale</color> bonus berdasarkan <color=#00F6FF>ATK</color> mereka. Saat memasuki pertempuran, langsung mendapatkan <color=#00F6FF>2</color> Finale. Setiap kali melewati Dark Tile, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale. Finale tambahan ini hilang saat memasuki Aurora Time, atau di akhir putaran.",
  str_skill_passive_desc_436153 = "Mendapatkan <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>{1}</color>. <color=#00F6FF>Thunder</color> Aurorian atau <color=#00F6FF>Illumina Federation</color> Aurorian akan mendapatkan 50% Finale</color> bonus berdasarkan <color=#00F6FF>ATK</color> mereka. Saat memasuki pertempuran, langsung mendapatkan <color=#00F6FF>2</color> Finale. Setiap kali melewati Tile Gelap, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale, dan meningkatkan faktor kerusakan Chain Combo sebesar <color=#00F6FF>2%</color>. Finale tambahan ini dan bonus Chain Combo menghilang saat memasuki Aurora Time, atau di akhir putaran.",
  str_skill_upgrade_refine_desc_16015311 = "Active Skill Enhancement: Memperoleh <color=#00F6FF>6</color> Finale sementara setelah memasuki Finality State.",
  str_skill_upgrade_refine_desc_16015312 = "Chain Combo Enhancement: Meningkatkan damage sebesar <color=#00F6FF>10%</color>.",
  str_skill_upgrade_refine_desc_16015313 = "Active Skill Enhancement: Jika Chain Combo menimbulkan beberapa instance damage ke Tile yang sama setelah memasuki keadaan Finality, setiap damage terakhir berikutnya berkurang sebesar <color=#00F6FF>15%</color>.",
  str_skill_desc_2501531 = "Penawaran <color=#00F6FF>150%</color> kerusakan pada 3 musuh terdekat dalam <color=#00F6FF>3 cluster sekitarnya</color>.",
  str_skill_desc_2501532 = "Menimbulkan <color=#00F6FF>160%</color> kerusakan pada 4 musuh terdekat dalam <color=#00F6FF>4 klaster di sekitar</color>.",
  str_skill_desc_2501533 = "Penawaran <color=#00F6FF>170%</color> merusak semua musuh di dalamnya <color=#00F6FF>4 cluster sekitarnya</color>.",
  str_skill_desc_340153 = "Memilih <color=#00F6FF>4</color> Tile secara acak, memanggil Air Raid Beacon yang akan bertahan selama <color=#00F6FF>2</color> putaran, lalu masuk ke <color=#00F6FF>Finality State</color> selama 2 putaran. Saat berada dalam Finality State, Normal Attack akan meluas ke <color=#00F6FF>Tile diagonal</color>. Sementara itu, skill Chain Combo akan menimbulkan setengah damage tambahan untuk damage saat ini pada Tile tempat Air Raid Beacon berada dan 4 Tile di sekitarnya. Saat menimbulkan damage berkali-kali pada Tile yang sama, setiap damage final yang mengikutinya akan berkurang sebesar <color=#00F6FF>20%</color>. Mendapatkan tambahan <color=#00F6FF>6</color> <link=\"300443\"><#FFAE07><u>Finale</u></color></link> tanpa memandang batas saat berada dalam status Finality.",
  str_skill_desc_360153 = "Memilih <color=#00F6FF>4</color> Tile secara acak, memanggil Air Raid Beacon yang akan bertahan selama <color=#00F6FF>2</color> putaran, lalu masuk ke <color=#00F6FF>Finality State</color> selama 2 putaran. Saat berada dalam Finality State, Normal Attack akan meluas ke <color=#00F6FF>Tile diagonal</color>. Sementara itu, skill Chain Combo akan menimbulkan setengah damage tambahan untuk damage saat ini pada Tile tempat Air Raid Beacon berada dan 4 Tile di sekitarnya. Saat menimbulkan damage berkali-kali pada Tile yang sama, setiap damage final yang mengikutinya akan berkurang sebesar <color=#00F6FF>15%</color>. Memperoleh tambahan <color=#00F6FF>6</color> <link=\"300443\"><#FFAE07><u>Finale</u></color></link> tanpa menghiraukan batas saat berada dalam Finality State.",
  str_skill_passive_desc_450153 = "Mendapatkan <link=\"300443\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>3%</color>. <color=#00F6FF>Thunder</color> Aurorian atau <color=#00F6FF>Illumina Federation</color> Aurorian akan mendapatkan 50% Finale</color> bonus berdasarkan <color=#00F6FF>ATK</color> mereka. Setiap kali melewati Dark Tile, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale. Finale tambahan ini menghilang saat memasuki Aurora Time, atau di akhir ronde.",
  str_skill_passive_desc_453153 = "Mendapatkan <link=\"300443\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>3%</color>. <color=#00F6FF>Thunder</color> Aurorian atau <color=#00F6FF>Illumina Federation</color> Aurorian akan mendapatkan 50% Finale</color> bonus berdasarkan <color=#00F6FF>ATK</color> mereka. Saat memasuki pertempuran, langsung mendapatkan <color=#00F6FF>2</color> Finale. Setiap kali melewati Dark Tile, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale. Finale tambahan ini hilang saat memasuki Aurora Time, atau di akhir putaran.",
  str_skill_passive_desc_456153 = "Mendapatkan <link=\"300443\"><#FFAE07><u>Finale</u></color></link>, dan setiap Finale akan meningkatkan ATK sebesar <color=#00F6FF>3%</color>. <color=#00F6FF>Thunder</color> Aurorian atau <color=#00F6FF>Illumina Federation</color> Aurorian akan mendapatkan 50% Finale</color> bonus berdasarkan <color=#00F6FF>ATK</color> mereka. Saat memasuki pertempuran, langsung mendapatkan <color=#00F6FF>2</color> Finale. Setiap kali melewati Tile Gelap, mendapatkan <color=#00F6FF>1</color> Finale sementara yang dapat melebihi batas Finale, dan meningkatkan faktor kerusakan Chain Combo sebesar <color=#00F6FF>2%</color>. Finale tambahan ini dan bonus Chain Combo menghilang saat memasuki Aurora Time, atau di akhir putaran.",
  str_skill_name_290230101 = "Claudia: Meteor Smash",
  str_skill_name_290230102 = "Claudia: Meteor Smash",
  str_skill_name_290230103 = "Claudia: Meteor Smash",
  str_skill_name_290230104 = "Claudia: Meteor Smash",
  str_skill_name_290230201 = "Claudia: Leaping Cleave",
  str_skill_name_290230202 = "Claudia: Leaping Cleave",
  str_skill_name_290230203 = "Claudia: Leaping Cleave",
  str_skill_name_290230301 = "Claudia: Sever",
  str_skill_name_290230401 = "Emerging Platform",
  str_skill_name_290240101 = "Asher: Assault",
  str_skill_desc_290230101 = "Saat Claudia berdiri di atas tanah, semua platform dalam jangkauan berbentuk silang di sekitar musuh akan dipanggil untuk saling berbenturan sehingga menimbulkan damage beberapa kali kepada musuh.",
  str_skill_desc_290230102 = "Saat Claudia berdiri di platform, semua platform dalam jangkauan berbentuk silang di sekitar musuh akan dipanggil untuk saling berbenturan. Jika Claudia ada dalam jangkauan, musuh akan terkena Stun.",
  str_skill_desc_290230103 = "Saat Claudia berdiri di Asher, semua platform dalam jangkauan berbentuk silang di sekitar musuh akan dipanggil untuk saling berbenturan. Jika Asher juga ada dalam jangkauan, musuh akan terkena Stun dan Knock Back.",
  str_skill_desc_290230104 = "Jika tidak ada platform dalam jangkauan berbentuk silang di sekitar musuh, Claudia akan memanggil 4 platform di lokasi acak dalam radius 5×5 Tile di pusat medan tempur, lalu membuat satu platform di posisi terjauh dari musuh di medan tempur, dan berteleportasi ke sana.",
  str_skill_desc_290230201 = "Jika musuh berada dalam jangkauan serang, Claudia akan berteleportasi ke sebelah musuh, sehingga menimbulkan damage besar, lalu mundur sedikit. Jika tidak ada musuh dalam jangkauan serang, Claudia akan membuat platform dalam radius 5×5 Tile di pusat medan tempur, lalu berteleportasi ke posisi terjauh dari musuh ke medan tempur.",
  str_skill_desc_290230202 = "Jika musuh berada dalam jangkauan serang, Claudia akan berteleportasi ke sebelah musuh, sehingga menimbulkan damage besar, lalu mundur sedikit. Jika tidak ada musuh dalam jangkauan serang, Claudia akan membuat platform dalam radius 5×5 Tile di pusat medan tempur, lalu berteleportasi ke posisi terjauh dari musuh ke medan tempur.",
  str_skill_desc_290230203 = "Jika musuh berada dalam jangkauan serang, Claudia akan berteleportasi ke sebelah musuh, sehingga menimbulkan damage besar, lalu mundur sedikit. Jika tidak ada musuh dalam jangkauan serang, Claudia akan membuat platform dalam radius 5×5 Tile di pusat medan tempur, lalu berteleportasi ke posisi terjauh dari musuh ke medan tempur.",
  str_skill_desc_290230301 = "Claudia membuat platform di tengah medan tempur dan di Tile musuh, lalu berteleportasi ke platform itu dan menyerang, sehingga menimbulkan full-screen damage kepada semua musuh.",
  str_skill_desc_290230401 = "Saat putaran dimulai. Claudia akan memanggil maks 10 platform di tepi medan tempur.",
  str_skill_desc_290240101 = "Asher mendekati musuh dalam jangkauan serang, lalu menyerang satu kali sambil menghancurkan semua platform di sepanjang jalan. Jika tidak ada musuh yang bisa diserang, Asher akan tetap menunggu di tempatnya.",
  str_skill_name_290250101 = "Immolation Finale",
  str_skill_desc_290250101 = "Selama jangka waktu tertentu, Minos bergerak secara acak di lapangan dan mereset semua Tile yang dilalui. Setelah bergerak, Minos menembak pemain dan menimbulkan damage besar satu kali.",
  str_skill_name_290250102 = "Phantom Attack",
  str_skill_desc_290250102 = "Jika Minos melewati Enhanced Tile, sesosok hantu akan dipanggil pada Enhanced Tile untuk menimbulkan damage tunggal pada pemain. Damage yang ditimbulkan oleh hantu itu akan meningkatkan tumpukan Mark milik Minos.",
  str_skill_name_290250201 = "Restoration Phantom",
  str_skill_desc_290250201 = "Minos menyerap semua Enhanced Tile dan Weakened Tile di papan, lalu menimbulkan damage pada pemain. Minos menimbulkan damage 1 kali lagi untuk setiap Enhanced Tile yang dia serap. Damage yang ditimbulkan akan meningkatkan tumpukan Mark milik Minos.",
  str_skill_name_390250101 = "Nefarious - Phantom Attack",
  str_skill_desc_390250101 = "Nefarious Minos memilih jalur yang memiliki Weakened Tile paling banyak, lalu bergerak sejauh 5 Tile, menyerap Enhanced Tile dan Weakened Tile yang dilewatinya. Setiap kali dia menyerap Weakened Tile, sesosok hantu akan dipanggil untuk menimbulkan damage tunggal pada pemain. Jika tidak ada Weakened Tile di jalur atau di papan, Minos akan memunculkan 7 Weakened Tile dalam 3 klaster di sekitar.",
  str_skill_name_390250102 = "Nefarious - Immolation Finale",
  str_skill_desc_390250102 = "Nefarious Minos mengunci target dan menembak sehingga menimbulkan Full-Screen Damage.",
  str_skill_name_390310106 = "Nefarious - Sweet Kiss",
  str_skill_desc_390310106 = "Nefarious Barbara bergerak ke lokasi terjauh dari target dengan menghubungkan Tile, lalu menimbulkan damage area yang luas kecuali zona aman dan menghancurkan Tile merah di luar zona aman.",
  str_skill_name_390310107 = "Nefarious - Final Note",
  str_skill_desc_390310107 = "Nefarious Barbara bergerak ke lokasi terjauh dari target dengan menghubungkan Tile, lalu memanggil sekutu di pusat papan, dan menimbulkan Full-Screen Damage dan memukul mundur target.",
  str_skill_name_390320102 = "Nefarious Concerto of Dread",
  str_skill_name_390320103 = "Nefarious Sonata of Abyss",
  str_skill_desc_390320102 = "Nefarious Connolly bergerak ke titik terjauh yang masih bisa menjangkau target dengan menghubungkan Tile dan menimbulkan damage pada semua unit musuh dalam 2 klaster di sekitar. Jika aksi ini tidak menyerang target, Tentacle akan dipanggil di tempat acak.",
  str_skill_desc_390320103 = "Nefarious Connolly bergerak ke lokasi terjauh dari target dengan menghubungkan Tile, lalu menimbulkan damage pada semua target di layar.",
  str_skill_name_390330102 = "Nefarious Hidden Bloom",
  str_skill_name_390330103 = "Nefarious Crystal Domain",
  str_skill_desc_390330102 = "Nefarious Beryl bergerak ke titik terjauh yang masih bisa menjangkau target dengan menghubungkan Tile dan menimbulkan damage pada semua unit musuh dalam 16 Tile dalam bentuk lingkaran. Jika aksi ini tidak menyerang target, Sanguine Crystal akan dipanggil di tempat acak.",
  str_skill_desc_390330103 = "Nefarious Beryl bergerak ke lokasi terjauh dari target dengan menghubungkan Tile, lalu menimbulkan damage pada semua target di layar.",
