  str_skill_passive_desc_410156 = "Saat beralih dari <color=#00F6FF>Unarmed Mode</color> ke <color=#00F6FF>Parasol Mode</color>, akan segera menimbulkan damage sebesar <color=#00F6FF>{1}</color> pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_passive_desc_420156 = "Dalam <color=#00F6FF>Unarmed Mode</color>, Normal Attack<color=#00F6FF> bisa menarget musuh pada Tile diagonal</color>. Saat beralih dari <color=#00F6FF>Unarmed Mode</color> ke <color=#00F6FF>Parasol Mode</color>, akan segera menimbulkan damage sebesar <color=#00F6FF>{1}</color> pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_upgrade_desc_16015613 = "Active Skill Enhancement: Menimbulkan Equipment Skill Damage 1 kali lagi pada <color=#00F6FF>1 klaster di sekitar</color> sekeliling lokasi yang dipilih.",
  str_skill_upgrade_desc_16015616 = "Active Skill Enhancement: Meningkatkan faktor damage Active Skill sebesar <color=#00F6FF>100%</color> dalam <color=#00F6FF>Parasol Mode</color> dan <color=#00F6FF>1.000%</color> saat dalam <color=#00F6FF>Unarmed Mode</color>.",
