  str_skill_desc_2001571 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_2001572 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2001573 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color>.",
  str_skill_desc_300157 = "Menggunakan <color=#00F6FF>3</color> <link=\"30050\"><#FFAE07><u>Thread Point</u></color></link> untuk memanggil <color=#00F6FF>Manae</color> pada Tile yang dipilih atau menggunakan <color=#00F6FF>1</color> <link=\"30050\"><#FFAE07><u>Thread Point</u></color></link> untuk menggerakkan <color=#00F6FF>Manae</color> ke Tile yang dipilih. Manae akan kembali ke Sanae pada akhir putaran pemain. Manae akan <color=#00F6FF>menjaga posisi relatif</color> terhadap Sanae saat bergerak dan menimbulkan damage yang mengabaikan DEF yang <color=#00F6FF>setara dengan ATK Manae</color> pada target yang ditemuinya di sepanjang jalan. Manae mewarisi <color=#00F6FF>70%</color> ATK dasar Sanae.",
  str_skill_desc_310157 = "Menggunakan <color=#00F6FF>3</color> <link=\"30050\"><#FFAE07><u>Thread Point</u></color></link> untuk memanggil <color=#00F6FF>Manae</color> pada Tile yang dipilih atau menggunakan <color=#00F6FF>1</color> <link=\"30050\"><#FFAE07><u>Thread Point</u></color></link> untuk menggerakkan <color=#00F6FF>Manae</color> ke Tile yang dipilih. Manae akan kembali ke Sanae pada akhir putaran pemain. Manae akan <color=#00F6FF>menjaga posisi relatif</color> terhadap Sanae saat bergerak dan menimbulkan damage yang mengabaikan DEF yang <color=#00F6FF>setara dengan ATK Manae</color> pada target yang ditemuinya di sepanjang jalan. Manae mewarisi <color=#00F6FF>70%</color> ATK dasar Sanae.",
  str_skill_desc_320157 = "Menggunakan <color=#00F6FF>3</color> <link=\"30050\"><#FFAE07><u>Thread Point</u></color></link> untuk memanggil <color=#00F6FF>Manae</color> pada Tile yang dipilih atau menggunakan <color=#00F6FF>1</color> <link=\"30050\"><#FFAE07><u>Thread Point</u></color></link> untuk menggerakkan <color=#00F6FF>Manae</color> ke Tile yang dipilih. Manae akan kembali ke Sanae pada akhir putaran pemain. Manae akan <color=#00F6FF>menjaga posisi relatif</color> terhadap Sanae saat bergerak dan menimbulkan damage yang mengabaikan DEF yang <color=#00F6FF>setara dengan ATK Manae</color> pada target yang ditemuinya di sepanjang jalan. Manae mewarisi <color=#00F6FF>70%</color> ATK dasar Sanae.",
  str_skill_desc_330157 = "Menggunakan <color=#00F6FF>3</color> <link=\"30050\"><#FFAE07><u>Thread Point</u></color></link> untuk memanggil <color=#00F6FF>Manae</color> pada Tile yang dipilih atau menggunakan <color=#00F6FF>1</color> <link=\"30050\"><#FFAE07><u>Thread Point</u></color></link> untuk menggerakkan <color=#00F6FF>Manae</color> ke Tile yang dipilih. Manae akan kembali ke Sanae pada akhir putaran pemain. Manae akan <color=#00F6FF>menjaga posisi relatif</color> terhadap Sanae saat bergerak dan menimbulkan damage yang mengabaikan DEF yang <color=#00F6FF>setara dengan ATK Manae</color> pada target yang ditemuinya di sepanjang jalan. Manae mewarisi <color=#00F6FF>70%</color> ATK dasar Sanae. Memasuki Aurora Time akan memberikan Manae kemampuan untuk <color=#00F6FF>bergerak</color> 1 kali lagi.",
