  str_skill_passive_name_400165 = "Domain Panah Surya",
  str_skill_passive_desc_400165 = "<color=#00F6FF>Kapan pun</color> kombo rantai mengenai target, ia meninggalkan a <color=#00F6FF>Tambang Panah Surya</color> pada ubin acak di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> itu <color=#00F6FF>memicu dan meledak</color> ketika musuh melewatinya, memberikan kerusakan mengabaikan DEF sama dengan <color=#00F6FF>{1}</color> dari ATK Ciel ke <color=#00F6FF>5 ubin dalam bentuk salib</color>. <color=#00F6FF>Tambang Panah Surya</color> menghilang setelah mereka <color=#00F6FF>meledak</color> atau setelah <color=#00F6FF>akhir putaran</color>.",
  str_skill_passive_name_420165 = "Domain Panah Surya",
