  str_skill_desc_2001682 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh terdekat, lalu memunculkan <link=\"30061\"><#FFAE07><u>Sunshower Mark</u></color></link> pada 1 Tile acak yang ditempati musuh.",
  str_skill_desc_2001683 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 4 musuh terdekat, lalu memunculkan <link=\"30061\"><#FFAE07><u>Sunshower Mark</u></color></link> pada 1 Tile acak yang ditempati musuh.",
  str_skill_desc_300168 = "Mengaktifkan semua <link=\"30061\"><#FFAE07><u>Sunshower Marks</u></color></link> di medan tempur dan menimbulkan <color=#00F6FF>240%</color> damage pada <color=#00F6FF>5 Tile dalam bentuk silang</color> di sekitarnya. Jika target menerima damage lebih dari sekali, damage berikutnya dari setiap serangan yang mengenai target akan berkurang sebesar <color=#00F6FF>10%</color> dari damage asli.",
  str_skill_desc_320168 = "Mengaktifkan semua <link=\"30061\"><#FFAE07><u>Sunshower Marks</u></color></link> di medan tempur dan menimbulkan <color=#00F6FF>240%</color> damage pada <color=#00F6FF>9 Tile dalam bentuk kotak</color> di sekitarnya. Jika target menerima damage lebih dari sekali, damage berikutnya dari setiap serangan yang mengenai target akan berkurang sebesar <color=#00F6FF>10%</color> dari damage asli.",
  str_skill_desc_330168 = "Mengaktifkan semua <link=\"30061\"><#FFAE07><u>Sunshower Marks</u></color></link> di medan tempur dan menimbulkan <color=#00F6FF>240%</color> damage pada <color=#00F6FF>9 Tile dalam bentuk kotak</color> di sekitarnya. Jika target menerima damage lebih dari sekali, damage berikutnya dari setiap serangan yang mengenai target akan berkurang sebesar <color=#00F6FF>10%</color> dari damage asli. Jika ada Tile di medan tempur yang memiliki <color=#00F6FF>3</color> Mark yang aktif tanpa Sunshower Mark, 1 Sunshower Mark baru akan muncul di Tile tersebut.",
  str_skill_passive_name_410168 = "Protection Bubble",
  str_skill_passive_name_415168 = "Protection Bubble",
  str_skill_passive_desc_410168 = "Memberikan perisai yang <color=#00F6FF>{1}</color> DEF Rainbow dan bertahan selama 1 ronde saat melewati a <link=\"30061\"><#FFAE07><u>Tanda Pancuran Matahari</u></color></link>.",
  str_skill_passive_desc_415168 = "Memberikan perisai yaitu <color=#00F6FF>{1}</color> DEF Rainbow dan bertahan selama 1 ronde saat melewati a <link=\"30061\"><#FFAE07><u>Tanda Pancuran Matahari</u></color></link>. Menghasilkan Tanda Sunshower pada <color=#00F6FF>1</color> ubin Biru acak di awal setiap putaran.",
  str_skill_upgrade_desc_15016812 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_15016815 = "Equipment Skill Enhancement: Sunshower Mark akan muncul di <color=#00F6FF>1</color> Tile Biru acak di awal setiap putaran.",
