  str_skill_name_326167 = "Devil's House of Cards",
  str_skill_desc_2001671 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh terdekat dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_desc_2001672 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 4 musuh terdekat dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_desc_2001673 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada semua musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_desc_300167 = "Jeno memulai pertempuran dengan <link=\"30058\"><#FFAE07><u>Origin Deck</u></color></link> dan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Memperoleh 1 Origin Card acak untuk setiap <color=#00F6FF>{1}</color> poin Sanity yang digunakan. Saat diaktifkan lagi di putaran yang sama, penggunaan akan meningkat sebesar <color=#00F6FF>5</color>.",
  str_skill_desc_303167 = "Jeno memulai pertempuran dengan <link=\"30059\"><#FFAE07><u>Origin Deck</u></color></link> dan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Memperoleh 1 Origin Card acak untuk setiap <color=#00F6FF>{1}</color> poin Sanity yang digunakan. Saat diaktifkan lagi di putaran yang sama, penggunaan akan meningkat sebesar <color=#00F6FF>5</color>.",
  str_skill_desc_306167 = "Jeno memulai pertempuran dengan <link=\"30060\"><#FFAE07><u>Origin Deck</u></color></link> dan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Memperoleh 1 Origin Card acak untuk setiap <color=#00F6FF>{1}</color> poin Sanity yang digunakan. Saat diaktifkan lagi di putaran yang sama, penggunaan akan meningkat sebesar <color=#00F6FF>5</color>.",
  str_skill_desc_320167 = "Jeno memulai pertempuran dengan <link=\"30058\"><#FFAE07><u>Origin Deck</u></color></link> dan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Memperoleh 1 Origin Card acak untuk setiap <color=#00F6FF>{1}</color> poin Sanity yang digunakan. Saat diaktifkan lagi di putaran yang sama, penggunaan akan meningkat sebesar <color=#00F6FF>5</color>. Semakin rendah Sanity, semakin tinggi bonus ATK, hingga maks <color=#00F6FF>66,6%</color>, khusus bagi Aurorian yang diperkuat secara serentak dengan Luminous Cluster dan Astronomical Transit.",
  str_skill_desc_323167 = "Jeno memulai pertempuran dengan <link=\"30059\"><#FFAE07><u>Origin Deck</u></color></link> dan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Memperoleh 1 Origin Card acak untuk setiap <color=#00F6FF>{1}</color> poin Sanity yang digunakan. Saat diaktifkan lagi di putaran yang sama, penggunaan akan meningkat sebesar <color=#00F6FF>5</color>. Semakin rendah Sanity, semakin tinggi bonus ATK, hingga maks <color=#00F6FF>66,6%</color>, khusus bagi Aurorian yang diperkuat secara serentak dengan Luminous Cluster dan Astronomical Transit.",
  str_skill_desc_326167 = "Jeno memulai pertempuran dengan <link=\"30060\"><#FFAE07><u>Origin Deck</u></color></link> dan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Memperoleh 1 Origin Card acak untuk setiap <color=#00F6FF>{1}</color> poin Sanity yang digunakan. Saat diaktifkan lagi di putaran yang sama, penggunaan akan meningkat sebesar <color=#00F6FF>5</color>. Semakin rendah Sanity, semakin tinggi bonus ATK, hingga maks <color=#00F6FF>66,6%</color>, khusus bagi Aurorian yang diperkuat secara serentak dengan Luminous Cluster dan Astronomical Transit.",
  str_skill_passive_name_410167 = "Change of Heart",
  str_skill_passive_desc_410167 = "Saat mengaktifkan Origin Deck, HP tim akan dipulihkan sebesar <color=#00F6FF>{1}</color> ATK dasar Jeno. Efek ini tidak dipengaruhi oleh Sanity System. Semakin rendah HP tim, semakin tinggi efek pemulihan, hingga maks 100%.",
  str_skill_passive_name_413167 = "Change of Heart",
  str_skill_passive_desc_413167 = "Saat mengaktifkan Origin Deck, HP tim akan dipulihkan sebesar <color=#00F6FF>{1}</color> ATK dasar Jeno. Efek ini tidak dipengaruhi oleh Sanity System. Semakin rendah HP tim, semakin tinggi efek pemulihan, hingga maks 100%. Memperoleh <color=#00F6FF>2</color> kartu acak di awal pertempuran.",
  str_skill_passive_name_416167 = "Change of Heart",
  str_skill_passive_desc_416167 = "Saat mengaktifkan Origin Deck, HP tim akan dipulihkan sebesar <color=#00F6FF>{1}</color> ATK dasar Jeno. Efek ini tidak dipengaruhi oleh Sanity System. Semakin rendah HP tim, semakin tinggi efek pemulihan, hingga maks 100%. Memperoleh <color=#00F6FF>2</color> kartu acak di awal pertempuran.",
  str_skill_passive_name_430167 = "Change of Heart",
  str_skill_passive_desc_430167 = "Saat mengaktifkan Origin Deck, HP tim akan dipulihkan sebesar <color=#00F6FF>{1}</color> ATK dasar Jeno. Efek ini tidak dipengaruhi oleh Sanity System. Semakin rendah HP tim, semakin tinggi efek pemulihan, hingga maks 100%. Memperoleh 1 kartu acak saat memasuki Aurora Time.",
  str_skill_passive_name_433167 = "Change of Heart",
  str_skill_passive_desc_433167 = "Saat mengaktifkan Origin Deck, HP tim akan dipulihkan sebesar <color=#00F6FF>{1}</color> ATK dasar Jeno. Efek ini tidak dipengaruhi oleh Sanity System. Semakin rendah HP tim, semakin tinggi efek pemulihan, hingga maks 100%. Memperoleh <color=#00F6FF>2</color> kartu acak di awal pertempuran dan memperoleh 1 kartu acak saat memasuki Aurora Time.",
  str_skill_passive_name_436167 = "Change of Heart",
  str_skill_passive_desc_436167 = "Saat mengaktifkan Origin Deck, HP tim akan dipulihkan sebesar <color=#00F6FF>{1}</color> ATK dasar Jeno. Efek ini tidak dipengaruhi oleh Sanity System. Semakin rendah HP tim, semakin tinggi efek pemulihan, hingga maks 100%. Memperoleh <color=#00F6FF>2</color> kartu acak di awal pertempuran dan memperoleh 1 kartu acak saat memasuki Aurora Time.",
  str_skill_upgrade_desc_16016713 = "Memperoleh <color=#00F6FF>2</color> <link=\"30059\"><#FFAE07><u>Origin Cards</u></color></link> acak di awal pertempuran.",
  str_skill_upgrade_desc_16016716 = "Origin Deck Skill Enhancement: Discolored Brilliance memulihkan <color=#00F6FF>25%</color> Sanity yang hilang.",
  str_skill_name_3001670 = "Astronomical Transit",
  str_skill_desc_3001670 = "Aurorian <color=#00F6FF>di posisi paling belakang dalam tim</color> memperoleh ATK tambahan sebesar <color=#00F6FF>7%</color> ATK dasar Jeno.",
  str_skill_name_3001671 = "Luminous Cluster",
  str_skill_desc_3001671 = "<color=#00F6FF>Kapten saat ini</color> memperoleh ATK tambahan sebesar <color=#00F6FF>8%</color> ATK dasar Jeno.",
  str_skill_name_3001674 = "Discolored Brilliance",
  str_skill_desc_3001674 = "Perubahan Captain dalam pertempuran +1. Memulihkan <color=#00F6FF>25%</color> Sanity yang hilang.",
  str_skill_name_30016740 = "Discolored Brilliance",
  str_skill_desc_30016740 = "Perubahan Captain dalam pertempuran +1. Memulihkan <color=#00F6FF>18%</color> Sanity yang hilang.",
  str_skill_name_10071413 = "Sanity Fluctuation",
  str_skill_desc_10071413 = "Tentaclaw akan mempengaruhi Aurorian Sanity. Pada awal setiap putaran, setiap Tentaclaw yang ada mengurangi Sanity sebesar 2, dan kematian setiap Tentaclaw mengembalikan Sanity sebesar 3.",
  str_skill_upgrade_desc_16016613 = "Active Skill Enhancement: Mendapatkan <color=#00F6FF>1</color> poin Bait Value pada awal setiap gelombang.",
  str_skill_upgrade_desc_16016616 = "Active Skill Enhancement: Saat Hunt Mark muncul di putaran <color=#00F6FF>2/3</color>, Kyllo menimbulkan damage sebesar <color=#00F6FF>350%/500%</color>.",
  str_skill_passive_name_410166 = "Swelling Tides",
  str_skill_passive_name_430166 = "Swelling Tides",
  str_skill_passive_desc_410166 = "Fia meluncur cepat di Tile <color=#00F6FF>Biru</color>, menimbulkan damage pada musuh di dekatnya. Saat <link=\"30057\"><#FFAE07><u>berbalik</u></color></link>, menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Memberikan efek Damp pada target yang bertahan selama 1 putaran: meningkatkan faktor damage elemen yang berlawanan sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430166 = "Fia meluncur cepat di Tile <color=#00F6FF>Biru</color>, menimbulkan damage pada musuh di dekatnya. Saat <link=\"30057\"><#FFAE07><u>berbalik</u></color></link>, menimbulkan damage pada <color=#00F6FF>1 klaster di sekitar</color>. Memberikan efek Damp pada target yang bertahan selama 1 putaran: meningkatkan faktor damage elemen yang berlawanan sebesar <color=#00F6FF>{1}</color>. Efek Damp meningkat sebesar <color=#00F6FF>50%</color> kepada musuh berelemen Fire.",
  str_skill_name_300166 = "The Kyllo Strategy",
  str_skill_name_320166 = "The Kyllo Strategy",
  str_skill_name_303166 = "The Kyllo Strategy",
  str_skill_name_306166 = "The Kyllo Strategy",
  str_skill_name_323166 = "The Kyllo Strategy",
  str_skill_name_326166 = "The Kyllo Strategy",
  str_skill_desc_300166 = "Memakai <color=#00F6FF>1</color> poin <link=\"30055\"><#FFAE07><u>Bait Value</u></color></link> untuk meletakkan 1 Hunt Mark di Tile mana pun, atau memilih 1 Hunt Mark untuk melepaskan Kyllo. Saat Hunt Mark aktif selama <color=#00F6FF>0/1/2/3</color> putaran, Kyllo menyerang <color=#00F6FF>Tile dengan Hunt Mark/5 Tile dalam bentuk silang/13 Tile dalam bentuk wajik/25 Tile dalam bentuk kotak</color>, menimbulkan <color=#00F6FF>150%/200%/250%/300%</color> damage.",
  str_skill_desc_320166 = "Memakai <color=#00F6FF>1</color> poin <link=\"30055\"><#FFAE07><u>Bait Value</u></color></link> untuk meletakkan 1 Hunt Mark di Tile mana pun, atau memilih 1 Hunt Mark untuk melepaskan Kyllo. Saat Hunt Mark aktif selama <color=#00F6FF>0/1/2/3</color> putaran, Kyllo menyerang <color=#00F6FF>Tile dengan Hunt Mark/5 Tile dalam bentuk silang/13 Tile dalam bentuk wajik/25 Tile dalam bentuk kotak</color>, menimbulkan <color=#00F6FF>150%/200%/250%/300%</color> damage. Mengurangi DEF dasar target sebesar <color=#00F6FF>5%</color> selama putaran itu. Efek bisa ditumpuk.",
  str_skill_desc_303166 = "Memakai <color=#00F6FF>1</color> poin <link=\"30056\"><#FFAE07><u>Bait Value</u></color></link> untuk meletakkan 1 Hunt Mark di Tile mana pun, atau memilih 1 Hunt Mark untuk melepaskan Kyllo. Saat Hunt Mark aktif selama <color=#00F6FF>0/1/2/3</color> putaran, Kyllo menyerang <color=#00F6FF>Tile dengan Hunt Mark/5 Tile dalam bentuk silang/13 Tile dalam bentuk wajik/25 Tile dalam bentuk kotak</color>, menimbulkan <color=#00F6FF>150%/200%/250%/300%</color> damage.",
  str_skill_desc_306166 = "Memakai <color=#00F6FF>1</color> poin <link=\"30056\"><#FFAE07><u>Bait Value</u></color></link> untuk meletakkan 1 Hunt Mark di Tile mana pun, atau memilih 1 Hunt Mark untuk melepaskan Kyllo. Saat Hunt Mark aktif selama <color=#00F6FF>0/1/2/3</color> putaran, Kyllo menyerang <color=#00F6FF>Tile dengan Hunt Mark/5 Tile dalam bentuk silang/13 Tile dalam bentuk wajik/25 Tile dalam bentuk kotak</color>, menimbulkan <color=#00F6FF>150%/200%/350%/500%</color> damage.",
  str_skill_desc_323166 = "Memakai <color=#00F6FF>1</color> poin <link=\"30056\"><#FFAE07><u>Bait Value</u></color></link> untuk meletakkan 1 Hunt Mark di Tile mana pun, atau memilih 1 Hunt Mark untuk melepaskan Kyllo. Saat Hunt Mark aktif selama <color=#00F6FF>0/1/2/3</color> putaran, Kyllo menyerang <color=#00F6FF>Tile dengan Hunt Mark/5 Tile dalam bentuk silang/13 Tile dalam bentuk wajik/25 Tile dalam bentuk kotak</color>, menimbulkan <color=#00F6FF>150%/200%/250%/300%</color> damage. Mengurangi DEF dasar target sebesar <color=#00F6FF>5%</color> selama putaran itu. Efek bisa ditumpuk.",
  str_skill_desc_326166 = "Memakai <color=#00F6FF>1</color> poin <link=\"30056\"><#FFAE07><u>Bait Value</u></color></link> untuk meletakkan 1 Hunt Mark di Tile mana pun, atau memilih 1 Hunt Mark untuk melepaskan Kyllo. Saat Hunt Mark aktif selama <color=#00F6FF>0/1/2/3</color> putaran, Kyllo menyerang <color=#00F6FF>Tile dengan Hunt Mark/5 Tile dalam bentuk silang/13 Tile dalam bentuk wajik/25 Tile dalam bentuk kotak</color>, menimbulkan <color=#00F6FF>150%/200%/350%/500%</color> damage. Mengurangi DEF dasar target sebesar <color=#00F6FF>5%</color> selama putaran itu. Efek bisa ditumpuk.",
