  str_skill_name_29039011 = "Serangan Tunggal: Serangan",
  str_skill_name_29039013 = "Berbagi Itu Peduli: Pemeran",
  str_skill_desc_29039011 = "Jika seorang Aurorian tidak dalam bentuk salib sampai batas maksimum jangkauannya, bergerak menuju Aurorian dan menyerang ketika berada dalam 4 ubin yang berdekatan dari Aurorian.",
  str_skill_desc_290390111 = "Jika Aurorian tidak dalam bentuk radial ke jangkauan maksimum, bergerak ke arah Aurorian dan menyerang ketika berada dalam 1 cluster di sekitar Aurorian.",
  str_skill_desc_29039013 = "Jika seorang Aurorian berada dalam bentuk salib sampai batas maksimum jangkauannya, berikan skill di tempat untuk memberikan damage pada Aurorian.",
  str_skill_desc_290390131 = "Jika Aurorian berada dalam bentuk radial hingga jangkauan maksimum, gunakan skill di tempat untuk memberikan damage pada Aurorian.",
  str_skill_name_291030101 = "Cermin Serangan",
  str_skill_name_291030102 = "Mirror Berkedip",
  str_skill_name_291030103 = "Panggilan Cermin",
  str_skill_desc_291030101 = "Nepolis bergerak dan menimbulkan damage pada target di depan melalui citra cermin.",
  str_skill_desc_291030102 = "Jika bentuk asli Nepolis lebih dekat ke pemain, dia bertukar posisi dengan bayangan cerminnya, menimbulkan damage pada target di sepanjang jalur.",
  str_skill_desc_291030103 = "Memanggil makhluk cermin yang menghancurkan diri sendiri di ronde berikutnya, mengutuk Aurorian acak selama 2 ronde.",
  str_skill_name_5220011 = "Caltrop mengamuk",
