  str_skill_name_2001303 = "Saya Hakim Ketua!",
  str_skill_desc_2001301 = "Tingkat <link=\"30062\"><#FFAE07><u>Statua Hukum</u></color></link> dalam <color=#00F6FF>1 cluster sekitarnya</color> <color=#00F6FF>+1</color>.",
  str_skill_desc_2001302 = "Tingkat <link=\"30062\"><#FFAE07><u>Statues of Law</u></color></link> dalam <color=#00F6FF>12 ubin berbentuk berlian</color> <color=#00F6FF>+1</color>.",
  str_skill_desc_2001303 = "Tingkat <link=\"30062\"><#FFAE07><u>Statua Hukum</u></color></link> dalam <color=#00F6FF>2 cluster sekitarnya</color> <color=#00F6FF>+1</color>.",
  str_skill_name_300130 = "Duduk!",
  str_skill_desc_300130 = "<color=#00F6FF>Menghancurkan</color> semua <link=\"30062\"><#FFAE07><u>Statua Hukum</u></color></link> dalam 2 cluster sekitarnya yang berpusat pada 1 traversable yang dipilih ubin, dan menghasilkan Patung Hukum baru pada ubin yang dipilih, dengan level yang sama dengan <color=#00F6FF>jumlah semua level Patung yang dihancurkan</color>. Jika tidak ada Patung Hukum yang terdeteksi dalam jangkauan, menghasilkan Lv. 1 Patung Hukum di ubin yang dipilih sebagai gantinya.",
  str_skill_passive_name_400130 = "Keadilan Dilayani!",
  str_skill_passive_desc_400130 = "Menghasilkan 1 Lv. 1 <link=\"30062\"><#FFAE07><u>Statua Hukum</u></color></link> untuk setiap 5 ubin yang dilalui. Untuk Patung Hukum saat ini, <color=#00F6FF>level +1</color>.",
