  str_skill_passive_name_430171 = "Serangan tunggal",
  str_skill_desc_2001711 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>8 tile dalam bentuk silang</color>.",
  str_skill_desc_2001712 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk silang</color>.",
  str_skill_desc_2001713 = "Menimbulkan <color=#00F6FF>{1}%</color> damage <color=#00F6FF>dalam bentuk silang hingga jangkauan maksimum</color>.",
  str_skill_desc_2201711 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>8 ubin berbentuk salib</color>, yang menyebar untuk memengaruhi 1 ubin tambahan di sisi kiri dan kanan saat diblokir .",
  str_skill_desc_2201712 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>12 ubin dalam bentuk silang</color>, yang menyebar untuk memengaruhi 1 ubin tambahan di sisi kiri dan kanan saat diblokir .",
  str_skill_desc_2201713 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan <color=#00F6FF>dalam bentuk silang hingga jangkauan maksimum</color>, yang menyebar untuk memengaruhi 1 ubin tambahan di sisi kiri dan kanan saat diblokir.",
  str_skill_desc_3001711 = "Biaya <color=#00F6FF>2</color> <link=\"30063\"><#FFAE07><u>Titik Pemicu</u></color></link> dan menghapus poin yang tersisa. Memberikan <color=#00F6FF>200%</color> kerusakan pada <color=#00F6FF>1 cluster di sekitarnya</color> setelah serangan Chain Combo pada ronde ini berakhir. Kerusakan akhir meningkat <color=#00F6FF>20%</color> untuk setiap Titik Pemicu yang diselesaikan.",
  str_skill_desc_3021711 = "Biaya <color=#00F6FF>2</color> <link=\"30064\"><#FFAE07><u>Titik Pemicu</u></color></link> dan menghapus poin yang tersisa. Memberikan <color=#00F6FF>200%</color> kerusakan pada <color=#00F6FF>1 cluster di sekitarnya</color> setelah serangan Chain Combo pada ronde ini berakhir. Kerusakan akhir meningkat <color=#00F6FF>20%</color> untuk setiap Poin Pemicu yang diselesaikan.",
  str_skill_desc_3051711 = "Biaya <color=#00F6FF>2</color> <link=\"30064\"><#FFAE07><u>Titik Pemicu</u></color></link> dan menghapus poin yang tersisa. Memberikan <color=#00F6FF>200%</color> kerusakan pada <color=#00F6FF>1 cluster di sekitarnya</color> setelah serangan Chain Combo pada ronde ini berakhir. Kerusakan akhir meningkat <color=#00F6FF>25%</color> untuk setiap Poin Pemicu yang diselesaikan.",
  str_skill_passive_desc_400171 = "Spot 1 <color=#00F6FF>Kelemahan Lawan</color> saat menghubungkan 1 ubin Hijau atau ubin yang Ditingkatkan. Setelah menemukan 6 kelemahan, Serangan Normal berikutnya memberikan Kerusakan Crit acak dari <color=#00F6FF>120%-{1}</color>. Menyetel ulang tumpukan <color=#00F6FF>Kelemahan Lawan</color>.",
  str_skill_passive_desc_430171 = "Bintik 1 <color=#00F6FF>Titik Lemah</color> saat menghubungkan 1 ubin Hijau atau ubin yang disempurnakan. Setelah menemukan 6 Titik Lemah, Serangan Normal berikutnya memberikan Kerusakan Crit acak dari <color=#00F6FF>120%-{1}</color>. Menyetel ulang tumpukan <color=#00F6FF>Titik Lemah</color>, dan memperoleh 1 Poin Pemicu.",
  str_skill_upgrade_desc_15017112 = "Peningkatan Keterampilan Aktif: Mendapatkan <color=#00F6FF>2</color> Poin Pemicu tambahan di awal setiap pertempuran.",
  str_skill_upgrade_desc_15017115 = "Peningkatan Keterampilan Aktif: Kerusakan akhir meningkat <color=#00F6FF>25%</color> untuk setiap Poin Pemicu yang diselesaikan.",
