  str_skill_name_336170 = "Ekspansi Peluru",
  str_skill_passive_name_410170 = "Tepat sasaran",
  str_skill_passive_name_420170 = "Tepat sasaran",
  str_skill_desc_2001701 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_2001702 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada ubin Kuning di dalam <color=#00F6FF>1 cluster di sekitarnya</color> dan area <color=#00F6FF>meluas dalam bentuk silang</color >.",
  str_skill_desc_2001703 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada ubin Kuning dalam <color=#00F6FF>1 kluster di sekitarnya</color> dan area <color=#00F6FF>meluas ke 8 arah</color >.",
  str_skill_desc_300170 = "Memilih 1 ubin, lalu memilih arah ke kanan atau kiri ubin yang dipilih. Warna semua ubin di arah yang dipilih akan menggeser satu kolom ke arah itu, dan semua ubin di <color=#00F6FF>kolom yang sama dengan ubin yang dipilih</color> akan menjadi ubin Kuning.",
  str_skill_desc_306170 = "Memilih 1 ubin, lalu memilih arah ke kanan atau kiri ubin yang dipilih. Warna semua ubin di arah yang dipilih akan menggeser satu kolom ke arah itu, dan semua ubin di <color=#00F6FF>kolom yang sama dengan ubin yang dipilih</color> akan menjadi ubin Kuning.",
  str_skill_desc_320170 = "Memilih 1 ubin, lalu memilih arah ke kanan atau kiri ubin yang dipilih. Warna semua ubin di arah yang dipilih akan menggeser satu kolom ke arah itu, dan semua ubin di <color=#00F6FF>kolom yang sama dengan ubin yang dipilih</color> akan menjadi ubin Kuning. Menimbulkan kerusakan <color=#00F6FF>250%</color> pada kolom ubin yang dipilih.",
  str_skill_desc_326170 = "Memilih 1 ubin, lalu memilih arah ke kanan atau kiri ubin yang dipilih. Warna semua ubin di arah yang dipilih akan menggeser satu kolom ke arah itu, dan semua ubin di <color=#00F6FF>kolom yang sama dengan ubin yang dipilih</color> akan menjadi ubin Kuning. Menimbulkan kerusakan <color=#00F6FF>250%</color> pada kolom ubin yang dipilih.",
  str_skill_desc_330170 = "Memilih 1 ubin, lalu memilih arah ke kanan atau kiri ubin yang dipilih. Warna semua ubin di arah yang dipilih akan menggeser satu kolom ke arah itu, dan semua ubin di <color=#00F6FF>kolom yang sama dengan ubin yang dipilih</color> akan menjadi ubin Kuning. Menimbulkan kerusakan <color=#00F6FF>250%</color> pada kolom ubin yang dipilih, dan jika ubin yang dipilih berada di kaki <color=#00F6FF>musuh satu ubin</color>, target akan dipaksa untuk memindahkan 1 ubin ke arah yang dipilih.",
  str_skill_desc_336170 = "Memilih 1 ubin, lalu memilih arah ke kanan atau kiri ubin yang dipilih. Warna semua ubin di arah yang dipilih akan menggeser satu kolom ke arah itu, dan semua ubin di <color=#00F6FF>kolom yang sama dengan ubin yang dipilih</color> akan menjadi ubin Kuning. Menimbulkan kerusakan <color=#00F6FF>250%</color> pada kolom ubin yang dipilih, dan jika ubin yang dipilih berada di kaki <color=#00F6FF>musuh satu ubin</color>, target akan dipaksa untuk memindahkan 1 ubin ke arah yang dipilih.",
  str_skill_passive_desc_410170 = "Ketika Chain Combo memberikan damage, semakin jauh targetnya, semakin banyak damage yang diberikan. Kerusakan akhir meningkat sebesar <color=#00F6FF>{1}</color> per klaster.",
  str_skill_passive_desc_420170 = "Saat Chain Combo dan Skill Aktif memberikan damage, semakin jauh targetnya, semakin banyak damage yang diberikan. Kerusakan akhir meningkat sebesar <color=#00F6FF>{1}</color> per cluster.",
  str_skill_upgrade_desc_16017013 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16017016 = "Active Skill Enhancement: Mengurangi cooldown skill sebanyak <color=#FFFF00>1</color> putaran.",
  str_skill_name_290370121 = "Meriam Utama Turret - Guncangan",
  str_skill_desc_290370121 = "Setelah bergerak sejauh 1 ubin, meriam utama menembakkan serangan kejut yang berdampak pada area dengan 4 ubin di depannya, memberikan kerusakan pada target dalam jangkauan dan menjatuhkan mereka kembali sebanyak 3 ubin.",
  str_skill_desc_290370123 = "Meriam utama menembakkan serangan kejut yang berdampak pada area dengan 4 ubin di depannya, memberikan kerusakan pada target dalam jangkauan dan menjatuhkan mereka kembali sebanyak 3 ubin.",
  str_skill_name_290370122 = "Meriam Utama Overrun - Shock",
  str_skill_desc_290370122 = "Setelah bergerak dengan 2 ubin, meriam utama menembakkan serangan kejut yang berdampak pada area dengan 4 ubin di depannya, memberikan kerusakan besar pada target dalam jangkauan dan menjatuhkan mereka kembali sebanyak 3 ubin.",
  str_skill_name_290370131 = "Strafe Bahu - Kiri",
  str_skill_desc_290370131 = "Setelah bergerak sebanyak 1 ubin, kunci musuh di area berbentuk kipas dan tembakkan beberapa tembakan, memberikan kerusakan.",
  str_skill_desc_290370133 = "Kunci musuh di area berbentuk kipas dan tembakkan beberapa tembakan, memberikan kerusakan.",
  str_skill_name_290370132 = "Overrun Strafe - Kiri",
  str_skill_desc_290370132 = "Setelah bergerak dengan 2 ubin, kunci musuh di area berbentuk kipas dan tembakkan beberapa tembakan, menghasilkan kerusakan besar.",
  str_skill_name_290370141 = "Strafe Bahu - Kanan",
  str_skill_desc_290370141 = "Setelah bergerak sebanyak 1 ubin, kunci musuh di area berbentuk kipas dan tembakkan beberapa tembakan, memberikan kerusakan.",
  str_skill_desc_290370143 = "Kunci musuh di area berbentuk kipas dan tembakkan beberapa tembakan, memberikan kerusakan.",
  str_skill_name_290370142 = "Overrun Strafe - Kanan",
  str_skill_desc_290370142 = "Setelah bergerak dengan 2 ubin, kunci musuh di area berbentuk kipas dan tembakkan beberapa tembakan, menghasilkan kerusakan besar.",
  str_skill_name_290370151 = "Menyerbu",
  str_skill_desc_290370151 = "Memasuki kondisi overrun, yang meningkatkan jarak gerakan dan ATK.",
  str_skill_name_490370401 = "Pemeliharaan Darurat",
  str_skill_desc_490370401 = "Mengunci HP dan melakukan perawatan darurat. Mengetuk Aurorian kembali ke tepi lapangan dengan meriamnya, lalu memberikan Perisai untuk dirinya sendiri. Setelah 1 ronde, HP akan pulih setara dengan menggandakan nilai perisai.",
  str_skill_name_40004451 = "Contamination",
  str_skill_desc_40004451 = "Murkmite memberikan kerusakan pada target dalam jangkauan dan menjatuhkan mereka kembali.",
  str_skill_name_49004213 = "Reincarnator",
  str_skill_desc_49004213 = "Nozard mengisi daya untuk Rising Tide yang akan datang, dan memanggil Thumper untuk perlindungan.",
  str_skill_name_49004215 = "Rising Tide",
  str_skill_desc_49004215 = "Nozard melakukan pengeboman di area tetap di lapangan, dan mengunci ubin dalam jangkauan.",
  str_skill_name_400060101 = "Combat Boost",
  str_skill_desc_400060101 = "Lurker menempelkan dirinya ke Eclipsite dalam 1 cluster di sekitarnya, memberikan Eclipsite dengan Shield dan meningkatkan ATK dan ACT-nya.",
  str_skill_name_400060201 = "Enhanced Regenerate",
  str_skill_desc_400060201 = "Saat berada dalam 1 cluster Dawn di sekitarnya, bergabung dengannya untuk memulihkan HP, meningkatkan ATK, dan memberinya perisai.",
  str_skill_desc_400071502 = "Memberikan kerusakan yang setara dengan persentase HP maksimum target ke target dalam jangkauan bentuk radial maksimumnya. Jika tidak ada target di 8 arah di sekitarnya, ia mendapatkan penghalang pertahanan.",
  str_skill_desc_400072502 = "Memberikan kerusakan yang setara dengan persentase dari HP maksimum target ke target dalam bentuk radial hingga jangkauan maksimum yang terpusat pada unit. Jika tidak ada target di 8 arah di sekitar unit, memulihkan HP ke unit yang bersahabat.",
  str_skill_desc_490050302 = "Solmorph memberikan kerusakan pada target dalam area serangan dan menarik mereka. Mengonversi ubin dalam 2 cluster sekitarnya terlepas dari apakah serangan itu mengenai musuh atau tidak, dan mengunci ubin dalam 1 cluster sekitarnya yang berpusat pada target saat mendaratkan pukulan.",
  str_skill_desc_491050301 = "Solmorph melepaskan gelombang ledakan selebar 2 ubin di lokasi target, memberikan kerusakan pada target di sepanjang jalan. Mengatur ulang ubin dalam jangkauan serangan.",
  str_skill_desc_491050302 = "Solmorph memberikan kerusakan pada target dalam area serangan dan menarik mereka. Mereset ubin dalam 3 cluster sekitarnya terlepas dari apakah serangan itu mengenai musuh atau tidak.",
  str_skill_desc_490028304 = "The Dark Summoner memanggil 4 beacon dan kemudian menyembuhkan semua beacon.",
  str_skill_desc_491028304 = "The Dark Summoner memanggil 4 beacon dan kemudian menyembuhkan semua beacon.",
  str_skill_desc_490025102 = "Panggil 1 Rabid Phantasm untuk membantu Phantom. Phantasm yang ada akan dipanggil kembali sebelum yang baru dipanggil. Meningkatkan ATK Phantom secara permanen setelah recall berhasil.",
  str_skill_desc_490025201 = "Phantom fanatik menyerang 2 kali, memanggil Phantasm untuk membantu.",
  str_skill_name_491025203 = "Ingatan Ilusi",
  str_skill_desc_491025203 = "Phantasm yang ada akan dipanggil kembali sebelum yang baru dipanggil, dan efek pemulihan HP, peningkatan ATK dan ACT menghilang. Meningkatkan ACT sendiri tanpa Phantasm di medan perang.",
  str_skill_name_215007811 = "Normal Attack",
  str_skill_desc_215007811 = "Robyn menyerang target dalam jangkauan serangan.",
  str_skill_name_215007812 = "Slither Drop",
  str_skill_desc_215007812 = "Memberikan kerusakan pada target dalam 2 cluster di sekitarnya.",
  str_skill_name_215007813 = "Slithering Breath",
  str_skill_desc_215007813 = "Memberikan kerusakan pada target di medan perang.",
  str_skill_name_214004811 = "Palpitations",
  str_skill_desc_214004811 = "Menimbulkan damage pada target dalam jangkauan.",
  str_skill_name_214004812 = "Capricious Thunder",
  str_skill_desc_214004812 = "Memberikan kerusakan pada target di medan perang.",
  str_skill_name_212005011 = "Bloody Devour",
  str_skill_desc_212005011 = "Memberikan kerusakan pada target dalam jangkauan dan menjatuhkan mereka kembali.",
  str_skill_name_212005012 = "Mass Rend",
  str_skill_desc_212005012 = "Menimbulkan damage pada target dalam jangkauan.",
  str_skill_name_213004911 = "Leaping Cleave",
  str_skill_desc_213004911 = "Menimbulkan damage pada target dalam jangkauan.",
  str_skill_name_213004912 = "Roar of Fury",
  str_skill_desc_213004912 = "Memberikan kerusakan pada target dalam 1 cluster di sekitarnya. Menempatkan semua ubin non-Biru dalam jangkauan.",
  str_skill_name_214009111 = "Psalm of Support",
  str_skill_desc_214009111 = "Saat dilemparkan, setiap ubin Biru di medan perang memberikan bonus ATK kepada semua anggota sekutu yang setara dengan 0,5% ATK Chloe untuk putaran tersebut.",
  str_skill_name_214009112 = "Shimmering Sorrow",
  str_skill_desc_214009112 = "Memberikan kerusakan pada target di medan perang.",
  str_skill_name_214009121 = "Psalm of Support",
  str_skill_desc_214009121 = "Saat dilemparkan, ACT dari semua anggota sekutu +1, dan setiap ubin Biru di medan perang memberi anggota sekutu bonus ATK setara dengan 0,5%.",
  str_skill_desc_490022306 = "Kebosanan mengumpulkan kekuatan untuk serangan Api berbentuk salib, yang memberikan kerusakan pada target dan menimbulkan Burn. Kebosanan memanggil Dreadblade untuk perlindungan saat mengumpulkan kekuatan, dan meningkatkan ACT untuk Eclipsites lain di medan perang setelah pemanggilan berhasil.",
  str_skill_desc_490022310 = "Kebosanan mengumpulkan kekuatan untuk serangan Guntur berbentuk salib, yang memberikan kerusakan pada target dan menimbulkan Kelumpuhan. Kebosanan memanggil Dreadblade untuk perlindungan saat mengumpulkan kekuatan, dan meningkatkan ACT untuk Eclipsites lain di medan perang setelah pemanggilan berhasil.",
  str_skill_desc_490064302 = "Energi Caracalune meluap, memberikan kerusakan pada 4 kolom dan baris.",
  str_skill_desc_490060103 = "Memberikan damage ke 7 area acak 2×2, dan menghasilkan api dalam jangkauan. Mengonversi semua ubin dalam 1 kluster sekitar Aurorian yang terkena pukulan, dan memberikan Kutukan pada Kapten tim.",
  str_skill_desc_49006811 = "Flash tanpa bentuk ke tepi Alchemy Board, jauh dari lokasi tim Anda, lalu lakukan serangan jarak jauh. Ini meluncurkan 2 Nonentities dan 1 Jurang ke lokasi acak dalam rentang tertentu di mana Aurorian Anda terhubung.",
  str_skill_desc_49006812 = "Formless meluncurkan 4 Nonentities ke lokasi acak di seluruh medan perang.",
  str_skill_desc_490091202 = "Meluncurkan sinar impak ke arah lokasi target di ronde terakhir, memberikan kerusakan pada target di jalur sinar dan di lokasi target. Menimbulkan Terkutuklah pada Kapten tim Aurorian setelah mendaratkan pukulan.",
  str_skill_desc_490091203 = "Menimbulkan damage pada target dalam jangkauan.",
  str_skill_desc_490006301 = "Nozard mendistorsi dan merobek ruang di depan, memberikan kerusakan elemen. Setiap pukulan Aurorian akan dibutakan.",
  str_skill_desc_490006302 = "Nozard memukul mundur Aurorian dan mengisi daya untuk badai yang akan datang.",
  str_skill_desc_490006304 = "Nozard mengebom area tertentu berulang kali, dan memanggil Skill Banning Stele di setiap area.",
  str_skill_desc_490006306 = "Nozard mengebom area tertentu berulang kali, dan memanggil Skill Banning Stele di setiap area.",
  str_skill_desc_491006304 = "Nozard mengebom area tetap berulang kali, dan menghancurkan ubin di dalam area tersebut.",
  str_skill_desc_491006305 = "Nozard mengebom area tetap berulang kali, dan menghancurkan ubin di dalam area tersebut.",
  str_skill_desc_491006302 = "Nozard memukul mundur Aurorian, memanggil Thumper ke lapangan, dan mengisi daya untuk badai yang akan datang.",
  str_skill_desc_492006306 = "Nozard mengebom area tetap berulang kali, dan menghancurkan ubin di dalam area tersebut.",
  str_skill_desc_490110101 = "Maude meluncurkan gelombang kejut ke depan dalam bentuk persegi panjang 2 ubin yang bergerak sejauh mungkin, memberikan kerusakan pada target yang terkena. Jika target terkena, memulihkan HP ke dirinya sendiri.",
  str_skill_desc_490110201 = "Maude meluncurkan gelombang kejut ke depan dalam bentuk persegi panjang 2 ubin yang bergerak sejauh mungkin, memberikan kerusakan pada target yang terkena. Jika target terkena, menghabiskan target.",
  str_skill_name_490110301 = "Tanduk Perang Solus",
  str_skill_desc_490110301 = "Maude meningkatkan ATK dan ACT untuk Eclipsites di lapangan.",
  str_skill_name_400040101 = "Darkness Cross",
  str_skill_desc_400040101 = "Saat Dark Summoner menyimpan energi, Beacon menyerang target dalam area berbentuk salib.",
  str_skill_name_810410092 = "Panggilan Terumbu",
  str_skill_desc_810410092 = "Memanggil 2 Rune Spesial, yang akan berubah menjadi Skill Banning Steles setelah ronde tertentu.",
  str_skill_desc_490040103 = "Schummer memanggil Lightning Power untuk memberikan damage ke beberapa area berbentuk salib di field. Musuh di tengah area akan terbunuh seketika.",
  str_skill_desc_490040106 = "Schummer memanggil Lightning Power untuk memberikan damage ke beberapa area berbentuk salib di field, dan memanggil Eclipsites kecil ke field.",
  str_skill_desc_490040108 = "Schummer mengontrol Colossus untuk melepaskan Sonic Blast, memberikan damage ke semua target. Eclipsites kecil akan langsung terbunuh. Setiap pembunuhan memulihkan 1% HP.",
  str_skill_desc_490067201 = "Schummer mengontrol Colossus untuk melepaskan Sonic Blast, memberikan damage ke semua target, dan mengubah ubin tertentu di lapangan.",
  str_skill_desc_490067202 = "Schummer melepaskan energi fanatik, menyerang semua target di papan, dan mengubah warna pada ubin tertentu di lapangan. Semakin jauh target dari Schummer, semakin banyak kerusakan yang akan terjadi.",
  str_skill_desc_490021101 = "Umbrahulk memanggil 4 Pebble secara acak ke medan perang dan memanggil 1 Skill Banning Stele di dekat posisi Aurorian di awal ronde.",
  str_skill_desc_490021102 = "Umbrahulk menjauh dari pemain dan memanggil 4 Kerikil di sebelah pemain.",
  str_skill_name_490310101 = "Support Fire",
  str_skill_desc_490310101 = "Ketika musuh berada dalam 2 cluster di sekitarnya, memberikan kerusakan pada target dan menjatuhkan mereka kembali sebanyak 1 ubin.",
  str_skill_name_490310102 = "Panggilan untuk Dukungan",
  str_skill_desc_490310102 = "Memanggil 4 Nonentitas ketika musuh berada di luar 2 cluster di sekitarnya.",
  str_skill_name_490310105 = "Barbara Normal Attack",
  str_skill_desc_490310105 = "Mendekati musuh, meluncurkan serangan dan menjatuhkan mereka kembali.",
  str_skill_name_491018101 = "Final Note",
  str_skill_desc_491018101 = "Saat musuh berada dalam 1 cluster di sekitarnya, Solar Storm meledak, memberikan damage pada musuh dan membuat mereka terlempar ke belakang.",
  str_skill_name_491018102 = "Serangan Normal Regina",
  str_skill_desc_491018102 = "Mendekati target dan menyerang.",
  str_skill_name_491105101 = "Tornado Mata Merah: Kecil",
  str_skill_desc_491105101 = "Jika ada musuh dalam 2 cluster di sekitarnya, menjauhlah dari musuh dan berikan damage kepada mereka 10 kali.",
  str_skill_name_491105102 = "Tornado Mata Merah: Mayor",
  str_skill_desc_491105102 = "Jika musuh berada di luar 2 cluster di sekitarnya, kunci musuh dan berikan damage kepada mereka 20 kali.",
  str_skill_name_491030101 = "Sinsa Normal Attack",
  str_skill_desc_491030101 = "Mendekati musuh dan melancarkan serangan.",
  str_skill_name_491030102 = "Splatterfire",
  str_skill_desc_491030102 = "Memberikan damage besar dalam bentuk radial hingga jangkauan maksimum.",
  str_skill_desc_490060101 = "Mengisi target dan menjatuhkannya ke ubin yang berdekatan, mengubah semua ubin di 3 cluster sekitarnya di akhir pengisian daya.",
