  str_skill_name_3361731 = "Putusan Cepat",
  str_skill_desc_3001731 = "Pilih 1 ubin mana saja, lalu pilih 1 ubin lain di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> untuk menentukan luas persegi panjang. <link=\"30065\"><#FFAE07><u>Menyerap</u></color></link> itu <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> dalam area ini dan penawaran <color=#00F6FF>100%</color> kerusakan pada musuh di area ini. Meningkatkan kerusakan akhir sebesar <color=#00F6FF>50%</color> untuk setiap 1 ubin yang disempurnakan yang diserap.",
  str_skill_desc_3061731 = "Pilih 1 ubin mana saja, lalu pilih 1 ubin lain di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> untuk menentukan luas persegi panjang. <link=\"30065\"><#FFAE07><u>Menyerap</u></color></link> itu <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> dalam area ini dan penawaran <color=#00F6FF>100%</color> kerusakan pada musuh di dalam area ini. Meningkatkan kerusakan akhir sebesar <color=#00F6FF>50%</color> untuk setiap 1 ubin yang disempurnakan yang diserap. Skill Aktif dapat digunakan 1 kali lagi setelah memasuki Waktu Aurora.",
  str_skill_desc_3201731 = "Pilih 1 ubin mana saja, lalu pilih 1 ubin lain di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> untuk menentukan luas persegi panjang. <link=\"30065\"><#FFAE07><u>Menyerap</u></color></link> itu <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> dalam area ini dan penawaran <color=#00F6FF>100%</color> kerusakan pada musuh di area ini. Meningkatkan kerusakan akhir sebesar <color=#00F6FF>50%</color> untuk setiap 1 ubin yang disempurnakan yang diserap.",
  str_skill_desc_3231731 = "Pilih 1 ubin mana saja, lalu pilih 1 ubin lain di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> untuk menentukan luas persegi panjang. <link=\"30065\"><#FFAE07><u>Menyerap</u></color></link> itu <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> dalam area ini dan penawaran <color=#00F6FF>100%</color> kerusakan pada musuh di dalam area ini. Meningkatkan kerusakan akhir sebesar <color=#00F6FF>50%</color> untuk setiap 1 ubin yang disempurnakan yang diserap. Setiap kali damage diberikan, menghilangkan 1 tumpukan Mortal Mark.",
  str_skill_desc_3261731 = "Pilih 1 ubin mana saja, lalu pilih 1 ubin lain di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> untuk menentukan luas persegi panjang. <link=\"30065\"><#FFAE07><u>Menyerap</u></color></link> itu <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> dalam area ini dan penawaran <color=#00F6FF>100%</color> kerusakan pada musuh di dalam area ini. Meningkatkan kerusakan akhir sebesar <color=#00F6FF>50%</color> untuk setiap 1 ubin yang disempurnakan yang diserap. Setiap kali damage diberikan, menghilangkan 1 tumpukan Mortal Mark. Skill Aktif dapat digunakan 1 kali lagi setelah memasuki Waktu Aurora.",
  str_skill_desc_3301731 = "Pilih 1 ubin mana saja, lalu pilih 1 ubin lain di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> untuk menentukan luas persegi panjang. <link=\"30065\"><#FFAE07><u>Menyerap</u></color></link> itu <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> dalam area ini dan penawaran <color=#00F6FF>100%</color> kerusakan pada musuh di dalam area ini. Meningkatkan kerusakan akhir sebesar <color=#00F6FF>50%</color> untuk setiap 1 ubin yang disempurnakan yang diserap. Setiap kali 1 ubin yang ditingkatkan diserap, menghapus 1 tumpukan Tanda Mortal.",
  str_skill_desc_3331731 = "Pilih 1 ubin mana saja, lalu pilih 1 ubin lain di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> untuk menentukan luas persegi panjang. <link=\"30065\"><#FFAE07><u>Menyerap</u></color></link> itu <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> dalam area ini dan penawaran <color=#00F6FF>100%</color> kerusakan pada musuh di area ini. Meningkatkan kerusakan akhir sebesar <color=#00F6FF>50%</color> untuk setiap 1 ubin yang disempurnakan yang diserap. Setiap kali kerusakan ditangani atau 1 ubin yang ditingkatkan diserap, menghapus 1 tumpukan Tanda Mortal.",
  str_skill_desc_3361731 = "Pilih 1 ubin mana saja, lalu pilih 1 ubin lain di dalamnya <color=#00F6FF>2 cluster sekitarnya</color> untuk menentukan luas persegi panjang. <link=\"30065\"><#FFAE07><u>Menyerap</u></color></link> itu <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> dalam area ini dan penawaran <color=#00F6FF>100%</color> kerusakan pada musuh di area ini. Meningkatkan kerusakan akhir sebesar <color=#00F6FF>50%</color> untuk setiap 1 ubin yang disempurnakan yang diserap. Setiap kali kerusakan ditangani atau 1 ubin yang ditingkatkan diserap, menghapus 1 tumpukan Tanda Mortal. Skill Aktif dapat digunakan 1 kali lagi setelah memasuki Waktu Aurora.",
  str_skill_name_2001731 = "Akhir Fantasi",
