  str_skill_name_2301733 = "Akhir Fantasi",
  str_skill_desc_2001731 = "Penawaran <color=#00F6FF>140%</color> kerusakan pada target terdekat dan terjauh, tetapi kerusakan berikutnya diberikan pada target yang sama adalah <color=#00F6FF>dibelah dua</color>. Panggilan <color=#00F6FF>hingga 1</color> <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> di kaki sasaran.",
  str_skill_desc_2001732 = "Penawaran <color=#00F6FF>160%</color> kerusakan pada target terdekat dan terjauh, tetapi kerusakan berikutnya diberikan pada target yang sama adalah <color=#00F6FF>dibelah dua</color>. Panggilan <color=#00F6FF>hingga 1</color> <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> di kaki sasaran.",
  str_skill_desc_2001733 = "Penawaran <color=#00F6FF>180%</color> kerusakan pada target terdekat dan terjauh, tetapi kerusakan berikutnya diberikan pada target yang sama adalah <color=#00F6FF>dibelah dua</color>. Panggilan <color=#00F6FF>hingga 1</color> <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> di kaki sasaran.",
  str_skill_desc_2301731 = "Penawaran <color=#00F6FF>140%</color> kerusakan pada target terdekat dan terjauh, tetapi kerusakan berikutnya diberikan pada target yang sama adalah <color=#00F6FF>dibelah dua</color>. Panggilan <color=#00F6FF>hingga 1</color> <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> di kaki sasaran.",
  str_skill_desc_2301732 = "Penawaran <color=#00F6FF>160%</color> kerusakan pada target terdekat dan terjauh, tetapi kerusakan berikutnya diberikan pada target yang sama adalah <color=#00F6FF>dibelah dua</color>. Panggilan <color=#00F6FF>hingga 1</color> <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> di kaki sasaran.",
  str_skill_desc_2301733 = "Penawaran <color=#00F6FF>180%</color> kerusakan pada target terdekat dan terjauh, tetapi kerusakan berikutnya diberikan pada target yang sama adalah <color=#00F6FF>dibelah dua</color>. Panggilan <color=#00F6FF>hingga 1</color> <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> di kaki sasaran.",
  str_skill_passive_name_410173 = "Pelepasan Mahakuasa",
  str_skill_passive_name_420173 = "Pelepasan Mahakuasa",
  str_skill_passive_name_423173 = "Pelepasan Mahakuasa",
  str_skill_passive_desc_410173 = "Segera deal <color=#00F6FF>{1}</color> kerusakan pada <color=#00F6FF>1</color> target acak di lapangan setiap kali tim memperoleh <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>mengasyikkan</u></color></link>).",
  str_skill_passive_desc_420173 = "Segera deal <color=#00F6FF>{1}</color> kerusakan pada <color=#00F6FF>1</color> target acak di lapangan setiap kali tim memperoleh <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>penyerapan</u></color></link>). Mulai pertempuran dengan <color=#00F6FF>33</color> Tanda Mortal menumpuk dan berkurang <color=#00F6FF>1</color> tumpukan untuk setiap ubin yang ditingkatkan yang diperoleh. Minos memasuki Negara Minotaur ketika semua Tanda telah dihapus, meningkatkan ATK dasarnya sebesar <color=#00F6FF>20%</color>, memungkinkan serangan normalnya mengenai ubin diagonal, meningkatkan kerusakan Skill Peralatan ke <color=#00F6FF>2.5</color> kali, dan membiarkan Kombo Rantainya memberikan kerusakan normal ketika mengenai target yang sama lagi.",
  str_skill_passive_desc_423173 = "Segera deal <color=#00F6FF>{1}</color> kerusakan pada <color=#00F6FF>1</color> target acak di lapangan setiap kali tim memperoleh <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>penyerapan</u></color></link>). Mulai pertempuran dengan <color=#00F6FF>33</color> Tanda Mortal menumpuk dan berkurang <color=#00F6FF>1</color> tumpukan untuk setiap ubin yang ditingkatkan yang diperoleh. Minos memasuki Negara Minotaur ketika semua Tanda telah dihapus, meningkatkan ATK dasarnya sebesar <color=#00F6FF>25%</color>, memungkinkan serangan normalnya mengenai ubin diagonal, meningkatkan kerusakan Skill Peralatan ke <color=#00F6FF>2.5</color> kali, dan membiarkan Kombo Rantainya memberikan kerusakan normal ketika mengenai target yang sama lagi.",
