  str_skill_desc_2001721 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>1 cluster sekitarnya</color>. Jika berdiri di luar a <color=#00F6FF>array yang mempesona</color>, menghasilkan rentang array yang mempesona <color=#00F6FF>1 cluster sekitarnya</color> di lokasi saat ini.",
  str_skill_desc_2001722 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>1 cluster sekitarnya</color>. Jika berdiri di luar a <color=#00F6FF>array yang mempesona</color>, menghasilkan rentang array yang mempesona <color=#00F6FF>1 cluster sekitarnya</color> di lokasi saat ini.",
  str_skill_desc_2001723 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Jika berdiri di luar a <color=#00F6FF>array yang mempesona</color>, menghasilkan rentang array yang mempesona <color=#00F6FF>12 ubin dalam bentuk berlian</color> di lokasi saat ini.",
  str_skill_desc_3001721 = "Teleport ke lokasi mana pun dalam a <link=\"30066\"><#FFAE07><u>array yang mempesona</u></color></link>. Hanya ada <color=#00F6FF>2</color> array yang mempesona di lapangan setiap saat.",
  str_skill_desc_3201721 = "Teleport ke lokasi mana pun dalam a <link=\"30066\"><#FFAE07><u>array yang mempesona</u></color></link> dan penawaran <color=#00F6FF>{1}%</color> kerusakan ubin dalam rentang <color=#00F6FF>array yang mempesona</color>. Hanya ada <color=#00F6FF>2</color> array yang mempesona di lapangan setiap saat.",
  str_skill_desc_3031721 = "Teleport ke lokasi mana pun dalam a <link=\"30067\"><#FFAE07><u>array yang mempesona</u></color></link>. Hanya ada <color=#00F6FF>3</color> array yang mempesona di lapangan setiap saat.",
  str_skill_desc_3231721 = "Teleport ke lokasi mana pun dalam a <link=\"30067\"><#FFAE07><u>array yang mempesona</u></color></link> dan penawaran <color=#00F6FF>{1}%</color> kerusakan ubin dalam rentang <color=#00F6FF>array yang mempesona</color>. Hanya ada <color=#00F6FF>3</color> array yang mempesona di lapangan setiap saat.",
  str_skill_desc_3061721 = "Teleport ke lokasi mana pun dalam a <link=\"30068\"><#FFAE07><u>array yang mempesona</u></color></link>. Hanya ada <color=#00F6FF>3</color> array yang mempesona di lapangan setiap saat.",
  str_skill_desc_3261721 = "Teleport ke lokasi mana pun dalam a <link=\"30068\"><#FFAE07><u>array yang mempesona</u></color></link> dan penawaran <color=#00F6FF>{1}%</color> kerusakan ubin dalam rentang <color=#00F6FF>array yang mempesona</color>. Hanya ada <color=#00F6FF>3</color> array yang mempesona di lapangan setiap saat.",
  str_skill_passive_desc_410172 = "Dapatkan perisai yang setara dengan <color=#00F6FF>{1}</color> DEF Lilica saat ini untuk setiap ubin yang dilalui dalam a <color=#00F6FF>array yang mempesona</color>.",
  str_skill_passive_desc_430172 = "Dapatkan perisai yang setara dengan <color=#00F6FF>{1}</color> DEF Lilica saat ini untuk setiap ubin yang dilalui dalam a <color=#00F6FF>array yang mempesona</color>. Di akhir ronde, memberikan kerusakan nyata yang setara dengan perisai yang tersisa ke semua ubin dalam rentang semua <color=#00F6FF>array yang mempesona</color>.",
  str_skill_upgrade_desc_16017213 = "Peningkatan Keterampilan Aktif: Hanya ada <color=#00F6FF>3</color> array yang mempesona di lapangan setiap saat.",
  str_skill_upgrade_desc_16017216 = "Peningkatan Keterampilan Aktif: Mengubah Keterampilan Aktif menjadi <color=#FFFF00>Serangan pendahuluan</color>. Tersedia saat memasuki pertempuran. Pada awal pertempuran, menghasilkan array yang mempesona yaitu <color=#00F6FF>12 ubin dalam bentuk berlian</color> di lokasi awal.",
  str_skill_name_29038011 = "Anda disana!",
  str_skill_desc_29038011 = "Setiap kali Aurorian berada di dekatnya, Astor berbalik menghadap pemain, memberikan kerusakan pada unit terdekat di area berbentuk berlian dan menjatuhkan mereka kembali.",
  str_skill_name_29038012 = "Ingin Melarikan Diri?",
  str_skill_desc_29038012 = "Setiap kali Aurorian berada dalam jangkauan berbentuk salib di sekitar Astor, Astor berbalik menghadap pemain dan menyerang mereka, memberikan kerusakan pada unit di depannya dan menjatuhkan mereka kembali.",
  str_skill_upgrade_desc_14016912 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_14016915 = "Peningkatan Keterampilan Aktif: Keterampilan Aktif mengetuk target kembali dengan <color=#FFFF00>3</color> ubin.",
  str_skill_name_2001691 = "Hancurkan mereka",
  str_skill_name_2001692 = "Hancurkan mereka",
  str_skill_name_2001693 = "Hancurkan mereka",
  str_skill_desc_2001691 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>8 tile dalam bentuk silang</color>.",
  str_skill_desc_2001692 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2001693 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color>.",
  str_skill_name_300169 = "Bola Terbang",
  str_skill_name_305169 = "Bola Terbang",
  str_skill_name_330169 = "Bola Terbang",
  str_skill_name_335169 = "Bola Terbang",
  str_skill_desc_300169 = "Penawaran <color=#00F6FF>300%</color> kerusakan pada 1 musuh yang berdekatan di a <color=#00F6FF>bentuk silang</color> dan mengetuknya kembali dengan 2 ubin. Kapan <color=#00F6FF>diblokir</color> saat dipukul mundur, dibutuhkan tambahan <color=#00F6FF>200%</color> kerusakan dan <color=#00F6FF>tertegun</color> untuk 1 putaran.",
  str_skill_desc_305169 = "Penawaran <color=#00F6FF>300%</color> kerusakan pada 1 musuh yang berdekatan di a <color=#00F6FF>bentuk salib</color> dan menjatuhkannya kembali dengan 3 ubin. Kapan <color=#00F6FF>diblokir</color> saat dipukul mundur, dibutuhkan tambahan <color=#00F6FF>200%</color> kerusakan dan adalah <color=#00F6FF>tercengang</color> untuk 1 putaran.",
  str_skill_desc_330169 = "Penawaran <color=#00F6FF>300%</color> kerusakan pada 1 musuh yang berdekatan di a <color=#00F6FF>bentuk silang</color> dan mengetuknya kembali dengan 2 ubin. Kapan <color=#00F6FF>diblokir</color> saat dipukul mundur, dibutuhkan tambahan <color=#00F6FF>200%</color> kerusakan dan <color=#00F6FF>tertegun</color> untuk 1 putaran. Jika diblokir oleh musuh lain, musuh tersebut juga terkena damage dan stun.",
  str_skill_desc_335169 = "Penawaran <color=#00F6FF>300%</color> kerusakan pada 1 musuh yang berdekatan di a <color=#00F6FF>bentuk silang</color> dan mengetuknya kembali sebanyak 3 ubin. Kapan <color=#00F6FF>diblokir</color> saat dipukul mundur, dibutuhkan tambahan <color=#00F6FF>200%</color> kerusakan dan <color=#00F6FF>tertegun</color> untuk 1 putaran. Jika diblokir oleh musuh lain, musuh tersebut juga terkena damage dan stun.",
  str_skill_passive_name_410169 = "Ayunan Adonan",
  str_skill_passive_name_420169 = "Ayunan Adonan",
  str_skill_passive_desc_410169 = "Meningkatkan ATK dasar Sadie sebesar <color=#00F6FF>{1}</color>. Sadie menawarkan hingga <color=#00F6FF>3</color> serangan normal saat menghubungkan ubin. Setelah 3 serangan, dapatkan 1 <color=#00F6FF>Titik Kecelakaan</color> saat melakukan serangan normal berikutnya. Setiap Poin Kecelakaan meningkatkan faktor kerusakan Skill Aktif sebesar <color=#00F6FF>{2}</color>, dan semua Poin Kecelakaan dihapus setelah menggunakan Keterampilan Aktif.",
  str_skill_passive_desc_420169 = "Meningkatkan ATK dasar Sadie sebesar <color=#00F6FF>{1}</color>. Sadie menawarkan hingga <color=#00F6FF>3</color> serangan normal saat menghubungkan ubin, dan serangan normal ke-3 memberikan kerusakan ganda. Setelah 3 serangan, dapatkan 1 <color=#00F6FF>Titik Kecelakaan</color> saat melakukan serangan normal berikutnya. Setiap Poin Kecelakaan meningkatkan faktor kerusakan Skill Aktif sebesar <color=#00F6FF>{2}</color>, dan semua Poin Kecelakaan dihapus setelah menggunakan Keterampilan Aktif.",
  str_skill_desc_1601751001 = "Prism tile",
  str_skill_desc_1601751003 = "katana",
  str_skill_desc_1601751004 = "Suar Serangan Udara",
  str_skill_desc_1601751005 = "Mechanical Bee",
  str_skill_desc_1601751006 = "Tambang Panah Surya",
  str_skill_desc_1601751007 = "Spanduk",
  str_skill_desc_1601751008 = "Lantern",
  str_skill_desc_1601751009 = "Kadal Besi",
  str_skill_desc_1601751010 = "Tile Gelap",
  str_skill_desc_160175101 = "Mengkonsumsi <color=#00F6FF>2</color> Energi Kubik untuk mengonversi 1 ubin mana saja menjadi Prism Tile.",
  str_skill_desc_160175103 = "Mengkonsumsi <color=#00F6FF>2</color> Energi Kubik untuk memanggil 1 Katana di petak mana pun yang tidak memiliki Katana di atasnya.",
  str_skill_desc_160175104 = "Mengkonsumsi <color=#00F6FF>1</color> Energi Kubik untuk memanggil 1 Suar Serangan Udara di petak mana pun yang dapat dilalui tanpa Suar Serangan Udara di atasnya.",
  str_skill_desc_160175105 = "Mengkonsumsi <color=#00F6FF>1</color> Energi Kubik untuk memanggil 1 Lebah Mekanik di petak mana pun yang dapat dilalui dalam 3 kluster di sekitarnya tanpa Lebah Mekanik yang ada di atasnya. Hingga 4 Lebah Mekanik dapat hadir di medan perang dalam satu waktu.",
  str_skill_desc_160175106 = "Mengkonsumsi <color=#00F6FF>1</color> Energi Kubik untuk memanggil 1 Tambang Panah Surya di ubin mana pun yang dapat dilalui tanpa Tambang Panah Surya yang ada di atasnya.",
  str_skill_desc_160175107 = "Mengkonsumsi <color=#00F6FF>3</color> Energi Kubik untuk memanggil 1 Spanduk di petak mana pun yang dapat dilalui. Maksimal 1 Spanduk dapat muncul di medan perang dalam satu waktu.",
  str_skill_desc_160175108 = "Mengkonsumsi <color=#00F6FF>4</color> Energi Kubik untuk memanggil 1 Lentera pada petak yang dapat dilalui tanpa Lentera yang ada di atasnya. Hingga 1 Lentera dapat hadir di medan perang dalam satu waktu.",
  str_skill_desc_160175109 = "Mengonsumsi <color=#00F6FF>2</color> Energi Kubik untuk memanggil 1 Kadal Besi di 1 ubin yang dapat dilalui yang dipilih tanpa Kadal Besi.",
  str_skill_desc_160175110 = "Mengkonsumsi <color=#00F6FF>2</color> Energi Kubik untuk mengonversi 1 ubin mana saja menjadi Ubin Gelap.",
  str_skill_upgrade_desc_16017513 = "Peningkatan Keterampilan Aktif: Keuntungan <color=#FFFF00>2</color> Cubic Energy di awal pertempuran.",
  str_skill_upgrade_desc_16017516 = [[
