  str_skill_name_30017513 = "Putaran Surgawi",
  str_skill_desc_30017511 = "Mengkonsumsi 1 <link=\"30069\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30072\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Healing Orbs menghilang saat disentuh oleh musuh.",
  str_skill_desc_30317511 = "Mengkonsumsi 1 <link=\"30070\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30072\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Healing Orbs menghilang saat disentuh oleh musuh.",
  str_skill_desc_30617511 = "Mengkonsumsi 1 <link=\"30070\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30073\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Healing Orbs menghilang saat disentuh oleh musuh.",
  str_skill_desc_32017511 = "Mengkonsumsi 1 <link=\"30069\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30072\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Bola Penyembuh menghilang saat disentuh oleh musuh, masing-masing mengembalikan 1 Energi Kubik.",
  str_skill_desc_32317511 = "Mengkonsumsi 1 <link=\"30070\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30072\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Bola Penyembuh menghilang saat disentuh oleh musuh, masing-masing mengembalikan 1 Energi Kubik.",
  str_skill_desc_32617511 = "Mengkonsumsi 1 <link=\"30070\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30073\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Bola Penyembuh menghilang saat disentuh oleh musuh, masing-masing mengembalikan 1 Energi Kubik.",
  str_skill_desc_33017511 = "Mengkonsumsi 1 <link=\"30069\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30072\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Bola Penyembuh menghilang saat disentuh oleh musuh, masing-masing mengembalikan 1 Energi Kubik. Axelia dapat menggunakan <link=\"30071\"><#FFAE07><u>Modul Otoritas</u></color></link> untuk memanggil objek yang dapat dipanggil dari Keterampilan Aktif Thunder Aurorian tertentu lainnya.",
  str_skill_desc_33317511 = "Mengkonsumsi 1 <link=\"30070\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30072\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Bola Penyembuh menghilang saat disentuh oleh musuh, masing-masing mengembalikan 1 Energi Kubik. Axelia dapat menggunakan <link=\"30071\"><#FFAE07><u>Modul Otoritas</u></color></link> untuk memanggil objek yang dapat dipanggil dari Keterampilan Aktif Thunder Aurorian tertentu lainnya.",
  str_skill_desc_33617511 = "Mengkonsumsi 1 <link=\"30070\"><#FFAE07><u>Energi Kubik</u></color></link> untuk memanggil 1 <link=\"30073\"><#FFAE07><u>Bola Penyembuh</u></color></link> pada petak yang dapat dilalui, atau untuk memilih Orb Penyembuhan yang sudah ada di lapangan dan menyerapnya untuk memulihkan HP berdasarkan jumlah putaran yang telah ada di lapangan. Bola Penyembuh menghilang saat disentuh oleh musuh, masing-masing mengembalikan 1 Energi Kubik. Axelia dapat menggunakan <link=\"30071\"><#FFAE07><u>Modul Otoritas</u></color></link> untuk memanggil objek yang dapat dipanggil dari Keterampilan Aktif Thunder Aurorian tertentu lainnya.",
  str_skill_desc_330175111 = "Mengkonsumsi 1 <color=#D1970C><b>Energi Kubik</b></color> untuk memanggil 1 Orb Penyembuhan pada petak mana saja yang dapat dilalui, yang akan memulihkan HP sebesar <color=#D1970C><b>40%/100%/200%</b></color> ATK Axelia kepada Aurorian yang melewati orb ini setelah berada di lapangan <color=#D1970C><b>0/1/2</b></color> putaran. Alternatifnya, pilih Healing Orb yang sudah ada di lapangan dan serap untuk memulihkan HP yang setara <color=#D1970C><b>40%/100%/200%</b></color> ATK Axelia berdasarkan jumlah putaran yang telah dilakukan di lapangan. Bola Penyembuh menghilang saat disentuh oleh musuh, masing-masing mengembalikan 1 Energi Kubik.",
  str_skill_desc_336175111 = "Mengkonsumsi 1 <color=#D1970C><b>Energi Kubik</b></color> untuk memanggil 1 Orb Penyembuhan pada petak mana saja yang dapat dilalui, yang akan memulihkan HP sebesar <color=#D1970C><b>40%/100%/250%</b></color> ATK Axelia kepada Aurorian yang melewati orb ini setelah berada di lapangan <color=#D1970C><b>0/1/2</b></color> putaran. Alternatifnya, pilih Healing Orb yang sudah ada di lapangan dan serap untuk memulihkan HP yang setara <color=#D1970C><b>80%/180%/400%</b></color> ATK Axelia berdasarkan jumlah putaran yang telah dilakukan di lapangan. Bola Penyembuh menghilang saat disentuh oleh musuh, masing-masing mengembalikan 1 Energi Kubik.",
  str_skill_passive_name_4101751 = "Sakelar Kubik",
  str_skill_passive_desc_4101751 = "Setelah Thunder Aurorian di tim menggunakan Skill Aktif, Axelia memperoleh keuntungan <color=#00F6FF>1</color> tumpukan Energi Konversi. Menggunakan Kombo Rantai akan menghapus semua tumpukan Energi Konversi dan kesepakatan <color=#00F6FF>{1}</color> kerusakan untuk setiap tumpukan ke musuh dengan HP tertinggi di lapangan.",
  str_skill_name_2001751 = "Berkat Surgawi",
  str_skill_name_2001752 = "Berkat Surgawi",
  str_skill_name_2001753 = "Berkat Surgawi",
  str_skill_desc_2001751 = "Memulihkan HP tim dengan <color=#00F6FF>135%</color> dari ATK Axelia.",
  str_skill_desc_2001752 = "Memulihkan HP tim dengan <color=#00F6FF>160%</color> dari ATK Axelia.",
  str_skill_desc_2001753 = "Memulihkan HP tim dengan <color=#00F6FF>190%</color> dari ATK Axelia.",
  str_skill_name_29036011 = "Korosi",
  str_skill_desc_29036011 = "Memberikan kerusakan parah pada target saat seorang Aurorian berada dalam 1 cluster Diavola di sekitarnya dan menimbulkan Toxin.",
  str_skill_name_29036012 = "Umpan Cacing",
  str_skill_desc_29036012 = "Saat Aurorian menjauh dari Diavola, Dawn Sprite dipanggil ke lokasi acak di lapangan.",
  str_skill_name_20006091 = "Enhancement",
  str_skill_desc_20006091 = "Saat berada dalam 1 cluster Diavola di sekitarnya, tingkatkan serangan Diavola dengan menggabungkannya.",
  str_skill_name_200190101 = "Roh Lentera: Tautan",
  str_skill_desc_200190101 = "Jika Roh Lentera dapat melintasi Aurorian saat menyerang, ia memberikan kerusakan dan membentuk hubungan dengan Aurorian. Jika tidak, itu hanya akan memberikan kerusakan pada Aurorian, dan mendapatkan dorongan ACT.",
  str_skill_name_290340101 = "Asmodeus: Rantai Mimpi Buruk",
  str_skill_desc_290340101 = "Asmodeus menyerang semua Aurorian dalam jangkauan, menghubungkan dirinya dengan mereka dengan Chain of Nightmares miliknya. Aurorian yang terhubung dengan Chain of Nightmares akan menerima damage untuk setiap 1 petak yang mereka lalui. Jika seorang Aurorian sudah terhubung dengan Chain of Nightmares saat Asmodeus menyerang, dia memberikan lebih banyak damage dan mendapatkan Life Drain.",
  str_skill_name_290341101 = "Asmodeus: Rantai Mimpi Buruk",
  str_skill_desc_290341101 = "Asmodeus menyerang semua Aurorian dalam jangkauan, menghubungkan dirinya dengan mereka dengan Chain of Nightmares miliknya. Ketika Chain of Nightmares rusak, itu memberikan kerusakan tinggi pada Aurorian. Jika seorang Aurorian sudah terhubung dengan Chain of Nightmares saat Asmodeus menyerang, dia memberikan lebih banyak damage dan mendapatkan Life Drain.",
  str_skill_name_290340102 = "Asmodeus: Intensifikasi",
  str_skill_desc_290340102 = "Jika Asmodeus tidak dapat menyerang Aurorian mana pun, ACT-nya akan terus meningkat hingga dia mengenai Aurorian.",
  str_skill_name_290340201 = "Asmodeus: Menyala",
  str_skill_desc_290340201 = "Asmodeus berteleportasi ke ubin terjauh yang bisa dia serang dari Aurorian dan menyerang mereka.",
