  str_skill_passive_name_4251761 = "Penguat Australia",
  str_skill_passive_name_4301761 = "Penguat Australia",
  str_skill_passive_name_4351761 = "Penguat Australia",
  str_skill_desc_2001761 = "Penawaran <color=#00F6FF>60%</color> damage 2 kali ke musuh acak di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Setiap kali kerusakan ditangani, meningkatkan jumlah <color=#00F6FF>Tombak Australis</color> pada musuh yang ditargetkan sebesar 1. Ketika memberikan kerusakan pada target lebih dari satu kali, kerusakan dari kedua kalinya akan berkurang setengahnya.",
  str_skill_desc_2001762 = "Penawaran <color=#00F6FF>80%</color> damage 3 kali ke musuh acak di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Setiap kali kerusakan ditangani, meningkatkan jumlah <color=#00F6FF>Tombak Australis</color> pada musuh yang ditargetkan sebesar 1. Ketika memberikan kerusakan pada target lebih dari satu kali, kerusakan dari kedua kalinya akan berkurang setengahnya.",
  str_skill_desc_2001763 = "Penawaran <color=#00F6FF>100%</color> damage 4 kali ke musuh acak di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Setiap kali kerusakan ditangani, meningkatkan jumlah <color=#00F6FF>Tombak Australis</color> pada musuh yang ditargetkan sebesar 1. Ketika memberikan kerusakan pada target lebih dari satu kali, kerusakan dari kedua kalinya akan berkurang setengahnya.",
  str_skill_desc_3001761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>2 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%</color> kerusakan untuk setiap Tombak Australis yang ditarik keluar.",
  str_skill_desc_3021761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%</color> kerusakan untuk setiap Tombak Australis yang ditarik keluar.",
  str_skill_desc_3051761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%–120%</color> kerusakan untuk setiap Tombak Australis yang ditarik keluar. Semakin rendah HP target saat ini, semakin tinggi faktor kerusakannya.",
  str_skill_desc_3201761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>2 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar.",
  str_skill_desc_3221761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar.",
  str_skill_desc_3251761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%–120%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar. Semakin rendah HP target saat ini, semakin tinggi faktor kerusakannya.",
  str_skill_desc_3301761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>2 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%–15%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_desc_3321761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%–15%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_desc_3351761 = "Menarik Australis Spears dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>80%–120%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%–15% dari</color> kerusakan ditangani dengan cara ini untuk masing-masing <color=#00F6FF>Tombak Australis</color> ditarik. Semakin rendah HP target saat ini, semakin tinggi faktor kerusakannya. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_passive_desc_4101761 = "Setiap <color=#00F6FF>{1}</color> serangan normal, Beretta menembus targetnya saat ini <color=#00F6FF>1</color> <color=#00F6FF>Tombak Australis</color>.",
  str_skill_passive_desc_4151761 = "Setiap <color=#00F6FF>{1}</color> serangan normal, Beretta menembus targetnya saat ini <color=#00F6FF>1</color> <color=#00F6FF>Tombak Australis</color>.",
  str_skill_passive_desc_4201761 = "Setiap <color=#00F6FF>{1}</color> serangan normal, Beretta menembus targetnya saat ini <color=#00F6FF>1</color> <color=#00F6FF>Tombak Australis</color>.",
  str_skill_passive_desc_4251761 = "Setiap <color=#00F6FF>{1}</color> serangan normal, Beretta menembus targetnya saat ini <color=#00F6FF>1</color> <color=#00F6FF>Tombak Australis</color>.",
  str_skill_passive_desc_4301761 = "Setiap <color=#00F6FF>{1}</color> serangan normal, Beretta menembus targetnya saat ini <color=#00F6FF>1</color> <color=#00F6FF>Tombak Australis</color>.",
  str_skill_passive_desc_4351761 = "Setiap <color=#00F6FF>{1}</color> serangan normal, Beretta menembus targetnya saat ini <color=#00F6FF>1</color> <color=#00F6FF>Tombak Australis</color>.",
  str_skill_upgrade_desc_15017612 = "Active Skill Enhancement: Meningkatkan jangkauan skill hingga seluas <color=#FFFF00>3 klaster di sekitar</color>.",
  str_skill_upgrade_desc_15017615 = "Peningkatan Keterampilan Aktif: Semakin rendah HP target, semakin tinggi faktor kerusakan, hingga <color=#00F6FF>40%</color>.",
  str_skill_name_290350103 = "Cerritus: Menghancurkan Smash",
  str_skill_desc_290350103 = "Cerritus menghancurkan ubin di bawah kakinya dan menyerang Aurorian, menjatuhkan mereka kembali dan menghancurkan semua Kerikil di sepanjang jalurnya dan menyebabkan Aurorian menabraknya dengan Kelelahan.",
  str_skill_name_290350104 = "Cerritus: Gempa yang Menghancurkan",
  str_skill_desc_290350104 = "Cerritus menghancurkan 2 ubin di depannya setelah bergerak, memberikan kerusakan besar dan menghancurkan ubin.",
  str_skill_desc_290350203 = "Cerritus menghancurkan ubin di bawah kakinya dan menyerang Aurorian, menjatuhkan mereka kembali dan menghancurkan semua Kerikil di sepanjang jalurnya.",
  str_skill_desc_290350204 = "Cerritus menghancurkan 2 ubin di depannya setelah bergerak, memberikan kerusakan besar dan menghancurkan ubin. Aurorian akan mendapatkan kondisi Lelah setelah terkena damage.",
  str_skill_name_216003811 = "Megashock!",
  str_skill_desc_216003811 = "Phantom Gronru memberikan damage ke 1 kolom.",
  str_skill_name_91001641 = "Enhancement",
  str_skill_desc_91001641 = "Meningkatkan ACT dan ATK semua Eclipsite kecuali dirinya sendiri. Efek ini dapat menumpuk.",
  str_skill_name_290290101 = "Keserakahan: Lonjakan",
  str_skill_desc_290290101 = "Menghancurkan Aurorian tetangga, menimbulkan kerusakan besar yang mengabaikan pertahanan musuh dan menjatuhkan mereka sebanyak 1 petak. Jika 4 ubin di sebelah Aurorian diblokir, mereka langsung dikalahkan.",
  str_skill_desc_290291131 = "Hancurkan Aurorian tetangga, kalahkan mereka seketika!",
  str_skill_name_290290104 = "Keserakahan: Fraktur",
  str_skill_desc_290290104 = "Jika tidak ada Aurorian yang berdekatan, ia bergerak 1 petak ke arah lokasi Aurorian saat ini dan kemudian memberikan kerusakan area dalam 1 cluster di sekeliling kepalanya.",
  str_skill_name_290290100 = "Tubuh Jormungand",
  str_skill_desc_290290100 = "Tubuh Jormungand dilindungi oleh energi khusus yang dapat meniadakan semua serangan. Tubuhnya memiliki kemampuan untuk mereplikasi dirinya sendiri.",
  str_skill_name_290290102 = "Ekor Jormungand",
  str_skill_desc_290290102 = "Kerusakan yang diberikan pada ekornya ditransmisikan ke kepalanya.",
  str_skill_upgrade_desc_15018012 = "Active Skill Enhancement: Jika skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#FFFF00>1</color> di putaran ini.",
  str_skill_upgrade_desc_15018015 = "Active Skill Enhancement: Meningkatkan hitungan Tile-Converting sebanyak <color=#FFFF00>1</color>.",
