  str_skill_desc_2201801 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan terdekat dan <color=#00F6FF>terkecil</color> musuh, kemudian menimbulkan a </color>Tanda Pengintaian<color=#00F6FF> di atasnya.",
