  str_skill_desc_2201803 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan terdekat dan <color=#00F6FF>terkecil</color> musuh, kemudian menimbulkan a </color>Tanda Pengintaian<color=#00F6FF> di atasnya.",
  str_skill_passive_desc_410180 = "Keterampilan Aktif menimbulkan a <color=#00F6FF>Tanda Pengintaian</color> pada musuh yang meningkatkan kerusakan akhir yang mereka ambil dari skill Chain Combo instan <color=#00F6FF>{1}</color>. Berlangsung hingga putaran Aurorian berakhir.",
  str_skill_passive_desc_420180 = "Skill Aktif dan Kombo Rantai menimbulkan a <color=#00F6FF>Tanda Pengintaian</color> pada musuh yang meningkatkan kerusakan akhir yang mereka ambil dari skill Chain Combo instan <color=#00F6FF>{1}</color>. Berlangsung hingga putaran Aurorian berakhir.",
