  str_skill_passive_desc_410177 = "Setiap kali tim menang <color=#00F6FF>{1}</color> <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> (termasuk melalui <link=\"30065\"><#FFAE07><u>Penyerapan</u></color></link>), menghasilkan 1 ubin yang ditingkatkan pada yang terdekat <color=#00F6FF>ubin non-Hijau</color>.",
  str_skill_upgrade_desc_16017713 = "Peningkatan Skill Aktif: Mengubah Skill Aktif menjadi <color=#FFFF00>Serangan Preemptive</color>. Tersedia saat memasuki pertempuran. Menghasilkan <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> secara acak <color=#00F6FF>ubin non-Hijau</color>.",
  str_skill_upgrade_desc_16017716 = "Peningkatan Keterampilan Aktif: Cooldown keterampilan <color=#FFFF00>-1</color>. Jika Skill Aktif sudah siap di ronde terakhir, maka dalam Mode Warsong, petak tempat musuh berdiri dapat terhubung selama <color=#00F6FF>Aurora Time</color>, dan <link=\"20001\"><#FFAE07 ><u>ubin yang disempurnakan</u></color></link> dianggap sebagai ubin berwarna. (Berlaku untuk Ascension III)",
  str_skill_desc_290420101 = "Bergerak ke arah Aurorian dan mengayunkan lengan bawahnya untuk memberikan damage pada musuh dalam jarak 2 petak di depan.",
  str_skill_desc_290420102 = "Memberikan kerusakan pada semua musuh di lapangan.",
  str_skill_name_200200101 = "Bola Venomex",
  str_skill_desc_200200101 = "Memuntahkan Bola Venomex, memberikan kerusakan pada target dalam jangkauan. Bola memercik melintasi 4 ubin dalam bentuk salib, meracuni semua musuh dan sekutu dalam jangkauan percikan.",
  str_skill_name_200210001 = "Pembunuhan Cozen",
  str_skill_desc_200210001 = "Saat hitungan mundur Crud berakhir, Cozen melompat keluar untuk menyerang Aurorian sebelum kembali bersembunyi.",
  str_skill_name_200210101 = "Pembunuhan Cozen",
  str_skill_desc_200210101 = "Saat hitungan mundur Crud berakhir, Cozen melompat keluar untuk menyerang Aurorian sebelum kembali bersembunyi.",
  str_skill_name_200210102 = "Pembunuhan Cozen",
  str_skill_desc_200210102 = "Saat hitungan mundur Crud berakhir, Cozen melompat keluar untuk menyerang Aurorian sebelum kembali bersembunyi.",
  str_skill_name_290400101 = "Bennu Bash",
  str_skill_desc_290400101 = "Bennuguardian menggunakan cakarnya untuk memberikan kerusakan pada target di dalam area serangannya.",
  str_skill_name_290400102 = "Bennu Leap",
  str_skill_desc_290400102 = "Bennuguardian melompat ke arah target, menghantam tanah saat mendarat untuk memberikan damage besar ke target di 1 cluster sekitarnya.",
  str_skill_name_290400103 = "Bennu Fury",
  str_skill_desc_290400103 = "Bennuguardian yang marah melepaskan keterampilan kuat yang memberikan kerusakan pada semua target di lapangan.",
  str_skill_name_5220012 = "Gel Penyembuh",
  str_skill_desc_5220012 = "Mengembalikan <color=#00F6FF>20%</color> dari Max HP tim.",
  str_skill_name_5220013 = "Penganalisa Jalur",
  str_skill_desc_5220013 = "Mengaktifkan perangkat dan melakukan teleportasi ke petak yang dapat dilalui.",
  str_skill_name_290430101 = "Regal: Badai",
  str_skill_desc_290430101 = "Regal bergerak mendekati target dengan menghubungkan petak dua elemen: miliknya dan milik Aurorian Legendaris lainnya di lapangan. Dia kemudian meluncurkan serangan normal ke 8 arah, lalu setelah rantai berakhir, memberikan damage ke 1 cluster di sekitarnya.",
  str_skill_name_290440101 = "Requiem: Tombak Suci",
  str_skill_desc_290440101 = "Requiem bergerak mendekati target dengan menghubungkan petak dua elemen: miliknya dan milik Aurorian Legendaris lainnya di lapangan. Dia kemudian meluncurkan serangan normal ke 4 arah, lalu setelah rantai berakhir, memberikan damage ke 1 cluster di sekitarnya. Setiap 3 serangan normal, dia memberikan damage tambahan yang setara dengan persentase dari Max HP target.",
  str_skill_name_290450101 = "Frostfire: Kepunahan",
  str_skill_desc_290450101 = "Frostfire bergerak jauh dari target dengan menghubungkan ubin dua elemen: miliknya dan milik Aurorian Legendaris lainnya di lapangan. Setelah bergerak, dia memberikan kerusakan pada semua target di lapangan.",
  str_skill_name_290460101 = "Mitos: Kanopi yang Menjulang",
  str_skill_desc_290460101 = "Mythos bergerak jauh dari target dengan menghubungkan petak dua elemen: miliknya dan milik Aurorian Legendaris lainnya di lapangan. Setelah bergerak, berikan kerusakan pada semua target di lapangan.",
  str_skill_name_2801101 = "Tanda Perintah",
  str_skill_desc_2801101 = "Diserap oleh Aurorian ketika mereka melewatinya. Meningkatkan berapa kali Kapten dapat diubah.",
  str_skill_name_5000881 = "Blade",
  str_skill_desc_5000881 = "Menyerap oleh Aurorian saat melewatinya. Meningkatkan ATK Aurorian.",
  str_skill_name_5000891 = "Shield",
  str_skill_desc_5000891 = "Menyerap oleh Aurorian saat melewatinya. Meningkatkan DEF Aurorian.",
  str_skill_name_2002101 = "Sword Buff",
  str_skill_desc_2002101 = "Setelah diambil, menimbulkan Keheningan tetapi meningkatkan ATK secara besar-besaran.",
  str_skill_desc_2002201 = "Setelah diambil, meningkatkan damage Chain Combo sebesar 8%.",
  str_skill_upgrade_desc_15018312 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_15018315 = "Peningkatan Keterampilan Aktif: Jumlah efek berulang kali meningkat menjadi <color=#00F6FF>2-5</color> waktu. (Berlaku untuk Ascension III)",
  str_skill_name_3001831 = "Antara Hidup dan Mati",
  str_skill_name_3051831 = "Antara Hidup dan Mati",
  str_skill_name_3201831 = "Antara Hidup dan Mati",
  str_skill_name_3251831 = "Antara Hidup dan Mati",
  str_skill_desc_3001831 = "Pilih 1 musuh dan paksakan HP mereka <color=#00F6FF>tidak kurang dari 1</color> sebelum ronde musuh dimulai. Musuh target secara acak terkena salah satu efek berikut: Kerusakan akhir diambil dari <color=#00F6FF>Serangan Normal/Kombo Berantai/Skill Aktif</color> meningkat sebesar <color=#00F6FF>5%/5%/7%</color>.",
  str_skill_desc_3201831 = "Pilih 1 musuh dan paksakan HP mereka <color=#00F6FF>tidak kurang dari 1</color> sebelum ronde musuh dimulai. Musuh target secara acak terkena salah satu efek berikut: Kerusakan akhir diambil dari <color=#00F6FF>Serangan Normal/Kombo Berantai/Skill Aktif</color> meningkat sebesar <color=#00F6FF>5%/5%/7%</color>. Efek diulang <color=#00F6FF>1 sampai 3</color> waktu.",
  str_skill_desc_3251831 = "Pilih 1 musuh dan paksakan HP mereka <color=#00F6FF>tidak kurang dari 1</color> sebelum ronde musuh dimulai. Musuh target secara acak terkena salah satu efek berikut: Kerusakan akhir diambil dari <color=#00F6FF>Serangan Normal/Kombo Berantai/Skill Aktif</color> meningkat sebesar <color=#00F6FF>5%/5%/7%</color>. Efek diulang <color=#00F6FF>2 sampai 5</color> waktu.",
  str_skill_name_2001831 = "Penerbangan Kuratif",
  str_skill_name_2001832 = "Penerbangan Kuratif",
  str_skill_name_2001833 = "Penerbangan Kuratif",
  str_skill_desc_2001831 = "Mengembalikan HP tim dengan jumlah yang sama dengan <color=#00F6FF>155%</color> dari ATK Liqing.",
  str_skill_desc_2001832 = "Mengembalikan HP tim dengan jumlah yang sama dengan <color=#00F6FF>190%</color> dari ATK Liqing.",
  str_skill_desc_2001833 = "Mengembalikan HP tim dengan jumlah yang sama dengan <color=#00F6FF>225%</color> dari ATK Liqing.",
  str_skill_passive_desc_410183 = "Serangan Normal Liqing tidak lagi memberikan kerusakan langsung. Sebaliknya, itu menerapkan 1 tumpukan Moxa pada target. Di akhir belokan, Moxa meledak, menangani <color=#00F6FF>{1}</color> kerusakan per tumpukan. Moxa berlangsung selama <color=#00F6FF>2 putaran</color>. Setiap tumpukan dihitung secara terpisah.",
  str_skill_passive_desc_430183 = "Serangan Normal Liqing tidak lagi memberikan kerusakan langsung. Sebaliknya, itu menerapkan 1 tumpukan Moxa pada target. Di akhir belokan, Moxa meledak, menangani <color=#00F6FF>{1}</color> kerusakan per tumpukan. Setiap tumpukan Moxa pada target meningkatkan kerusakan akhir yang ditimbulkan <color=#00F6FF>3%</color>. Moxa berlangsung selama <color=#00F6FF>2 putaran</color>. Setiap tumpukan dihitung secara terpisah.",
