  str_skill_desc_2361821 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>1 cluster sekitarnya</color>. Selama Waktu Aurora, biaya pemicuan dikurangi menjadi <color=#00F6FF>0</color>.",
  str_skill_desc_2361822 = "Jika 1st Serpent Flare sudah menyala, keluarkan Combo Rantai <color=#00F6FF>tingkatan sebelumnya</color>. Jika tidak, nyalakan Serpent Flare ke-1 dan lompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>180%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>. Selama Waktu Aurora, jarak lompatan meluas <color=#00F6FF>2 cluster sekitarnya</color> dan biaya pemicu dikurangi menjadi <color=#00F6FF>0</color>.",
  str_skill_desc_2361823 = "Jika 2nd Serpent Flare telah menyala, lepaskan Chain Combo dari <color=#00F6FF>tingkatan sebelumnya</color>. Jika tidak, nyalakan Serpent Flare ke-2 dan lompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>180%</color> kerusakan pada <color=#00F6FF>17 ubin dalam bentuk radial</color>. Selama Waktu Aurora, jarak lompatan meluas <color=#00F6FF>2 cluster sekitarnya</color> dan biaya pemicu dikurangi menjadi <color=#00F6FF>3</color>.",
  str_skill_desc_2361824 = "Jika 3rd Serpent Flare sudah menyala, keluarkan Combo Rantai <color=#00F6FF>tingkatan sebelumnya</color>. Jika tidak, nyalakan Serpent Flare ke-3 dan lompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>180%</color> kerusakan pada <color=#00F6FF>25 ubin dalam bentuk persegi</color>. Selama Waktu Aurora, jarak lompatan meluas <color=#00F6FF>2 cluster sekitarnya</color> dan biaya pemicu dikurangi menjadi <color=#00F6FF>7</color>.",
  str_skill_desc_3001821 = "Skill Aktif dapat dilepaskan saat <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Suar Ular</u></color></link> menyala. Memilih 1 ubin dan penawaran <color=#00F6FF>300%</color> kerusakan pada <color=#00F6FF>9 ubin dalam bentuk persegi</color>. Semua Serpent Flare akan padam setelah menggunakan Skill Aktif.",
  str_skill_desc_3101821 = "Skill Aktif dapat dilepaskan saat <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Suar Ular</u></color></link> menyala. Memilih 1 ubin dan penawaran <color=#00F6FF>300%</color> kerusakan pada <color=#00F6FF>9 ubin dalam bentuk persegi</color>. Semua Serpent Flare akan padam setelah menggunakan Skill Aktif.",
  str_skill_desc_3201821 = "Skill Aktif dapat dilepaskan saat <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Suar Ular</u></color></link> menyala. Memilih 1 ubin dan penawaran <color=#00F6FF>300%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>. Semua Serpent Flare akan padam setelah menggunakan Skill Aktif.",
