  str_skill_name_330181123 = "Strategi Gigih",
  str_skill_desc_3001811 = "Memanggil <color=#00F6FF>1</color> Api Leluhur dan mengubah ubin yang dipilih menjadi ubin Merah. Api Leluhur dapat dipanggil ke ubin tempat musuh berdiri dan akan bergerak bersama target. <color=#00F6FF>Sebelum memindahkan dan menghubungkan ubin</color>, semua ubin di sepanjang jalur yang dilalui Api Leluhur akan <color=#00F6FF>diubah menjadi ubin Merah</color>. Api Leluhur pada musuh akan menghilang <color=#00F6FF>ketika Aurorian mulai bergerak di sepanjang ubin yang terhubung</color>.",
  str_skill_desc_30018112 = "Mengkonsumsi 8 Insight Points. Memaksa 1 musuh non-bos untuk memindahkan 1 petak. Hanya dapat dilemparkan 1 kali setiap putaran.",
  str_skill_desc_300181121 = "Mengkonsumsi 7 Insight Points. Memaksa 1 musuh non-bos untuk memindahkan 1 petak. Hanya dapat dilemparkan 1 kali setiap putaran.",
  str_skill_desc_300181122 = "Mengkonsumsi 6 Insight Points. Memaksa 1 musuh non-bos untuk memindahkan 1 petak. Hanya dapat dilemparkan 1 kali setiap putaran.",
  str_skill_desc_300181123 = "Mengkonsumsi 5 Insight Points. Memaksa 1 musuh non-bos untuk memindahkan 1 petak. Hanya dapat dilemparkan 1 kali setiap putaran.",
  str_skill_desc_32018112 = "Menggunakan 8 Insight Points untuk memaksa 1 musuh non-boss memindahkan 1 petak. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (setiap penggunaan akan dikenakan biaya <color=#00F6FF>8</color> lebih banyak poin dari penggunaan sebelumnya).",
  str_skill_desc_320181121 = "Menggunakan 7 Insight Points untuk memaksa 1 musuh non-bos memindahkan 1 petak. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (setiap penggunaan akan dikenakan biaya <color=#00F6FF>7</color> lebih banyak poin dari penggunaan sebelumnya).",
  str_skill_desc_320181122 = "Menggunakan 6 Insight Points untuk memaksa 1 musuh non-boss memindahkan 1 petak. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (setiap penggunaan akan dikenakan biaya <color=#00F6FF>6</color> lebih banyak poin dari penggunaan sebelumnya).",
  str_skill_desc_320181123 = "Menggunakan 5 Insight Points untuk memaksa 1 musuh non-boss memindahkan 1 petak. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (setiap penggunaan akan dikenakan biaya <color=#00F6FF>5</color> lebih banyak poin dari penggunaan sebelumnya).",
  str_skill_desc_33018112 = "Menggunakan 8 Insight Points untuk memaksa 1 musuh non-boss memindahkan 1 petak, atau menghabiskan 8 Insight Points untuk memindahkan 1 petak Ancestral Flame. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (bergerak satu <color=#00F6FF>musuh/Api Leluhur</color> akan berharga <color=#00F6FF>8/8</color> lebih banyak poin dari penggunaan sebelumnya).",
  str_skill_desc_330181121 = "Menggunakan 7 Insight Points untuk memaksa 1 musuh non-bos memindahkan 1 petak, atau menghabiskan 8 Insight Points untuk memindahkan 1 petak Ancestral Flame. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (bergerak satu <color=#00F6FF>musuh/Api Leluhur</color> akan berharga <color=#00F6FF>7/8</color> lebih banyak poin dari penggunaan sebelumnya).",
  str_skill_desc_330181122 = "Menggunakan 6 Insight Points untuk memaksa 1 musuh non-boss memindahkan 1 petak, atau menghabiskan 8 Insight Points untuk memindahkan 1 petak Ancestral Flame. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (bergerak satu <color=#00F6FF>musuh/Api Leluhur</color> akan berharga <color=#00F6FF>6/8</color> lebih banyak poin dari penggunaan sebelumnya).",
