  str_skill_passive_desc_423181 = "Dapatkan Keterampilan Aktif Baru: Mengkonsumsi <color=#00F6FF>{1}</color> <link=\"30076\"><#FFAE07><u>Poin Wawasan</u></color></link> memaksa 1 <color=#00F6FF>musuh non-bos</color> untuk memindahkan 1 ubin. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (setiap penggunaan akan dikenakan biaya <color=#00F6FF>{1}</color> lebih banyak poin dari penggunaan sebelumnya). Zhong Xu mendapatkan 1 Insight Point setiap kali melewati 1 <color=#00F6FF>Ubin merah</color>.",
  str_skill_passive_desc_426181 = "Dapatkan Keterampilan Aktif Baru: Mengkonsumsi <color=#00F6FF>{1}</color> <link=\"30077\"><#FFAE07><u>Poin Wawasan</u></color></link> memaksa 1 <color=#00F6FF>musuh non-bos</color> untuk memindahkan 1 ubin. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (setiap penggunaan akan dikenakan biaya <color=#00F6FF>{1}</color> lebih banyak poin dari penggunaan sebelumnya). Zhong Xu mendapatkan 1 Insight Point setiap kali melewati 1 <color=#00F6FF>ubin</color>.",
  str_skill_passive_desc_430181 = "Dapatkan Keterampilan Aktif Baru: Mengkonsumsi <color=#00F6FF>{1}</color> <link=\"30075\"><#FFAE07><u>Poin Wawasan</u></color></link> untuk memaksa 1 <color=#00F6FF>musuh non-bos</color> memindahkan 1 ubin, atau menghabiskan 8 Poin Wawasan untuk <color=#00F6FF>memindahkan Api Leluhur</color> 1 ubin. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (memindahkan <color=#00F6FF>musuh/Api Leluhur</color> akan berharga <color=#00F6FF>{1}/8</color> lebih banyak poin dari penggunaan sebelumnya). Zhong Xu mendapatkan 1 Insight Point setiap kali melewati 1 <color=#00F6FF>Ubin merah</color>.",
  str_skill_passive_desc_433181 = "Dapatkan Keterampilan Aktif Baru: Mengkonsumsi <color=#00F6FF>{1}</color> <link=\"30076\"><#FFAE07><u>Poin Wawasan</u></color></link> untuk memaksa 1 <color=#00F6FF>musuh non-bos</color> memindahkan 1 ubin, atau menghabiskan 8 Poin Wawasan untuk <color=#00F6FF>memindahkan Api Leluhur</color> 1 ubin. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (memindahkan <color=#00F6FF>musuh/Api Leluhur</color> akan berharga <color=#00F6FF>{1}/8</color> lebih banyak poin dari penggunaan sebelumnya). Zhong Xu mendapatkan 1 Insight Point setiap kali melewati 1 <color=#00F6FF>Ubin merah</color>.",
  str_skill_passive_desc_436181 = "Dapatkan Keterampilan Aktif Baru: Mengkonsumsi <color=#00F6FF>{1}</color> <link=\"30077\"><#FFAE07><u>Poin Wawasan</u></color></link> untuk memaksa 1 <color=#00F6FF>musuh non-bos</color> bergerak 1 ubin, atau menghabiskan 8 Poin Wawasan untuk <color=#00F6FF>memindahkan Api Leluhur</color> 1 ubin. Biaya Insight Point berlipat ganda saat skill ini dilemparkan beberapa kali dalam putaran yang sama (memindahkan <color=#00F6FF>musuh/Api Leluhur</color> akan berharga <color=#00F6FF>{1}/8</color> lebih banyak poin dari penggunaan sebelumnya). Zhong Xu mendapatkan 1 Insight Point setiap kali melewati 1 <color=#00F6FF>ubin</color>.",
