  str_skill_desc_300184 = "Teleportasi ke posisi yang dipilih di dalam <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Jika titik pendaratan adalah <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link>, Anda dapat memilih titik pendaratan lain di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Menyerap semua ubin yang ditingkatkan di sepanjang jalur. Setiap kesepakatan penyerapan <color=#00F6FF>100%</color> kerusakan pada 12 ubin dalam bentuk berlian.",
  str_skill_desc_303184 = "Teleportasi ke posisi yang dipilih di dalam <color=#00F6FF>2 cluster sekitarnya</color>. Jika titik pendaratan adalah <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link>, Anda dapat memilih titik pendaratan lain di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Menyerap semua ubin yang ditingkatkan di sepanjang jalur. Setiap kesepakatan penyerapan <color=#00F6FF>100%</color> kerusakan pada 12 ubin dalam bentuk berlian.",
  str_skill_name_306184 = "Keributan Bulu",
  str_skill_desc_306184 = "Tersedia saat Aurora Time aktif: berteleportasi ke posisi mana pun di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>.",
  str_skill_passive_name_410184 = "Pembisik Pembicara",
  str_skill_passive_name_430184 = "Pembisik Pembicara",
  str_skill_passive_desc_410184 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Meningkatkan kerusakan akhir berikutnya sebesar <color=#00F6FF>{2}</color> untuk setiap ubin yang disempurnakan diserap.",
  str_skill_passive_desc_430184 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada <color=#00F6FF>12 ubin dalam bentuk berlian</color> dan menghasilkan 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> dalam area yang terkena dampak. Meningkatkan kerusakan akhir berikutnya sebesar <color=#00F6FF>{2}</color> untuk setiap ubin yang disempurnakan diserap.",
  str_skill_name_280061101 = "Banteng - Menara",
  str_skill_desc_280061101 = "Meluncurkan airdrop. Memilih satu petak yang dapat dilalui untuk memanggil a <color=#00F6FF>Perangkap Menara</color> untuk itu.",
  str_skill_name_280061102 = "Banteng - Traksi",
  str_skill_desc_280061102 = "Meluncurkan airdrop. Memilih satu petak yang dapat dilalui untuk memanggil a <color=#00F6FF>Penyeret</color> untuk itu.",
  str_skill_name_280061103 = "Banteng - Api",
  str_skill_desc_280061103 = "Meluncurkan airdrop. Memilih satu petak yang dapat dilalui untuk memanggil a <color=#00F6FF>Jebakan api</color> untuk itu.",
  str_skill_name_280061104 = "Banteng - Kehancuran",
  str_skill_desc_280061104 = "Memilih jebakan yang dipanggil oleh Bullock 8 dan menghancurkannya.",
  str_skill_name_280061105 = "Bullock - Emergency Repair",
  str_skill_desc_280061105 = "Perbaikan darurat! Memulihkan 3 tile HP ke Bullock 8.",
  str_skill_desc_140127101 = "Memilih hingga 4 ubin (termasuk Abyssal Tiles) dan menempatkan Paper Cranes di atasnya sambil mengonversinya menjadi ubin berwarna. Bangau Kertas akan menghilang setelah rekan satu tim melewatinya.",
