  str_skill_desc_3001851 = "Teleportasi ke posisi mana pun di dalamnya <color=#00F6FF>12 ubin dalam bentuk salib</color>.",
  str_skill_desc_3001852 = "Buka kunci setelah terakumulasi <color=#00F6FF>8</color> tumpukan Kekuatan Kyanite: Pilih musuh dan teleportasi ke posisi terdekat <color=#00F6FF>1 cluster sekitarnya</color> sekitar sasaran.",
  str_skill_desc_3361852 = "Buka kunci setelah terakumulasi <color=#00F6FF>5</color> tumpukan Kekuatan Kyanite: Pilih musuh dan teleportasi ke posisi terdekat <color=#00F6FF>1 cluster sekitarnya</color> sekitar sasaran.",
  str_skill_passive_desc_410185 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada musuh yang memiliki HP terendah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>.",
  str_skill_passive_desc_416185 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada musuh yang memiliki HP terendah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> dan keuntungan <color=#00F6FF>1</color> tumpukan Kekuatan Kyanite. Setiap tumpukan akan meningkatkan kerusakan sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_420185 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada musuh yang memiliki HP terendah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Saat Skill Aktif Kya memicu efek ini, damage terakhirnya akan meningkat sebesar <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_426185 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada musuh yang memiliki HP terendah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> dan keuntungan <color=#00F6FF>1</color> tumpukan Kekuatan Kyanite. Saat Skill Aktif Kya memicu efek ini, damage terakhirnya akan meningkat sebesar <color=#00F6FF>60%</color>. Setiap stack dari Kyanite Power akan meningkatkan damage sebesar <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430185 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada musuh yang memiliki HP terendah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> dan keuntungan <color=#00F6FF>1</color> tumpukan Kekuatan Kyanite. Saat Skill Aktif Kya memicu efek ini, damage terakhirnya akan meningkat sebesar <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_432185 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada musuh yang memiliki HP terendah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> dan keuntungan <color=#00F6FF>1</color> tumpukan Kekuatan Kyanite. Saat Skill Aktif Kya memicu efek ini, damage terakhirnya akan meningkat sebesar <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_436185 = "Saat tim berteleportasi dengan Skill Aktif, deal <color=#00F6FF>{1}</color> kerusakan pada musuh yang memiliki HP terendah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> dan keuntungan <color=#00F6FF>1</color> tumpukan Kekuatan Kyanite. Saat Skill Aktif Kya memicu efek ini, damage terakhirnya akan meningkat sebesar <color=#00F6FF>60%</color>. Setiap stack dari Kyanite Power akan meningkatkan damage sebesar <color=#00F6FF>5%</color>.",
  str_skill_upgrade_desc_15018512 = "Peningkatan Keterampilan Aktif: Jumlah tumpukan yang diperlukan untuk Blink of an Eye berkurang menjadi <color=#00F6FF>5</color>. (Berlaku untuk Ascension III)",
  str_skill_upgrade_desc_15018515 = "Peningkatan Keterampilan Peralatan: Setiap pemicu keterampilan akan dihasilkan <color=#00F6FF>1</color> tumpukan Kekuatan Kyanite. Setiap stack dari Kyanite Power akan meningkatkan damage Skill Equipment Kya sebesar <color=#00F6FF>5%</color>.",
  str_skill_name_28005016 = "Penyeret",
  str_skill_desc_28005016 = "Menarik Eclipsites dalam rentang kecil di depan petak Dragger 1 ke arahnya. Setiap Eclipsite hanya dapat dipengaruhi oleh efek tarikan Dragger satu kali per giliran.",
  str_skill_name_400054101 = "Uproot",
  str_skill_desc_400054101 = "Memberikan kerusakan pada semua target dalam jangkauan dan menghancurkan semua ubin dalam jangkauan, menghancurkan semua panggilan Bullock 8 pada mereka.",
  str_skill_desc_5410100 = "Menggunakan tombak untuk menyerang Eclipsites dalam jangkauan serangan.",
  str_skill_desc_888426101 = "Setelah pemain menggunakan Skill Aktif 3 kali berturut-turut, memanggil Lumo Piker ke medan perang.",
  str_skill_desc_4100002 = "Memanggil Fire Dreadblade setiap ronde hingga 4 Fire Dreadblade berada di medan perang.",
  str_skill_desc_4100004 = "Memanggil Thunder Dreadblade setiap ronde hingga 4 Thunder Dreadblade berada di medan perang.",
  str_skill_desc_4100005 = "Panggil Enferno setiap putaran hingga 2 Enferno berada di medan perang.",
  str_skill_desc_4100006 = "Memanggil Enferno ke medan perang setiap putaran. Tidak akan dipanggil jika sudah ada Enferno di medan pertempuran.",
  str_skill_desc_5401005 = "Enferno memanggil hujan yang membakar di lokasi acak di dekat Pembuat Lumo, memberikan kerusakan elemen dan target yang terbakar.",
  str_skill_name_290470111 = "Pemburu Mekanis: Musnahkan",
  str_skill_desc_290470111 = "Channels Darkflow dengan palu raksasanya, memberikan damage besar ke semua target di lapangan. Serangan ini mengurangi HP Aurorian di dalam zona yang dijaga menjadi 1.",
  str_skill_name_290470121 = "Pemburu Mekanik: Memburu",
  str_skill_desc_290470121 = "Jika targetnya berada di zona yang dijaga, ia bergerak di sebelahnya dan memberikan kerusakan jarak dekat. Jika target berada di luar zona yang dijaga, ia mengaitkan target di baris atau kolom yang sama dan menarik target ke dekatnya.",
  str_skill_desc_290470122 = "Jika targetnya berada di zona yang dijaga, ia bergerak di sebelahnya dan memberikan kerusakan jarak dekat. Jika target berada di luar zona yang dijaga, ia mengaitkan target di baris atau kolom yang sama dan menarik target ke dekatnya.",
  str_skill_name_290470131 = "Pemburu Mekanik: Usir",
  str_skill_desc_290470131 = "Mengirimkan gelombang energi turbulen dengan palu raksasanya, memberikan kerusakan pada semua musuh di lapangan. Pemain akan terlempar ke tepi lapangan oleh energi jika berada di dalam zona yang dijaga.",
  str_skill_name_290490101 = "Empat Ksatria: Pertempuran Tim",
  str_skill_desc_290490101 = "Berpindah ke petak diagonal dari anggota Empat Ksatria yang terdekat dengan target (jika kastor adalah anggota Empat Ksatria terdekat, mereka akan tetap berada di petak yang sama), lalu menyerang target dalam 1 kelompok sekitarnya.",
  str_skill_desc_290490103 = "Bergerak ke petak diagonal dari anggota Empat Ksatria yang terdekat dengan target (jika kastor adalah anggota Empat Ksatria terdekat, mereka akan tetap berada di petak yang sama), lalu menyerang target dalam 1 kelompok di sekitarnya, menimbulkan Kerapuhan pada Aurorian . Setiap tumpukan Fragility mengurangi DEF Aurorian sebesar 2%.",
  str_skill_desc_290490107 = "Menyerang target dalam 1 cluster di sekitarnya.",
  str_skill_name_290490102 = "Empat Ksatria: Serangan Cepat",
  str_skill_desc_290490102 = "Empat Ksatria berpencar, bergegas ke pinggir lapangan, lalu menyerang sasaran.",
  str_skill_desc_290490108 = "Menyerang target sambil tetap di tempat.",
  str_skill_name_290550101 = "Setan Hati: Api Kobalt",
  str_skill_desc_290550101 = "Setan Hati kehilangan 15% dari HP-nya saat ini dan melakukan teleportasi sedekat mungkin dengan musuh dalam 12 ubin dalam bentuk berlian, lalu memberikan kerusakan pada musuh dalam 1 cluster di sekitarnya. Jika dia mencapai target, dia memulihkan 15% dari HPnya yang hilang.",
  str_skill_name_290550111 = "Setan Hati: Cobalt Flame+",
  str_skill_desc_290550111 = "Setan Hati kehilangan 15% dari HP-nya saat ini dan melakukan teleportasi sedekat mungkin dengan musuh dalam 2 klaster di sekitarnya, lalu memberikan kerusakan pada musuh dalam 1 klaster di sekitarnya. Jika dia mencapai target, dia memulihkan 15% dari HPnya yang hilang.",
  str_skill_name_290550121 = "Setan Hati: Cobalt Flame++",
  str_skill_desc_290550121 = "Setan Hati kehilangan 15% dari HP-nya saat ini dan melakukan teleportasi sedekat mungkin ke musuh dalam 2 cluster di sekitarnya, lalu memberikan kerusakan pada musuh di dalam 2 cluster di sekitarnya. Jika dia mencapai target, dia memulihkan 15% dari HPnya yang hilang.",
  str_skill_name_290550102 = "Setan Hati: Api Nether",
  str_skill_desc_290550102 = "Setan Hati berteleportasi di sebelah Aurorian dan mengkonsumsi 15% dari HP-nya saat ini untuk memberikan kerusakan besar pada Aurorian. Jika dia mengenai Aurorian, dia memulihkan 15% dari HPnya yang hilang.",
  str_skill_name_2001891 = "Retribusi Segera",
  str_skill_name_2001892 = "Retribusi Segera",
  str_skill_name_2001893 = "Retribusi Segera",
  str_skill_desc_2001891 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
