  str_skill_name_3061892 = "Pembantaian Angin Puyuh",
  str_skill_name_3301892 = "Pertempuran Overload",
  str_skill_name_3331892 = "Pertempuran Overload",
  str_skill_desc_3001890 = "Memilih 1 ubin dari <color=#00F6FF>4 ubin dalam bentuk salib</color> di lokasi dan penawaran saat ini <color=#00F6FF>100%</color> kerusakan pada <color=#00F6FF>2 baris dalam bentuk kipas</color> ke arah ini.",
  str_skill_desc_3001891 = "Memilih 1 ubin dari <color=#00F6FF>4 ubin dalam bentuk salib</color> di lokasi dan penawaran saat ini <color=#00F6FF>100%</color> kerusakan pada <color=#00F6FF>2 baris dalam bentuk kipas</color> ke arah ini. Zeal meningkatkan kerusakan dan jangkauan, menangani hingga <color=#00F6FF>400%</color> kerusakan pada <color=#00F6FF>7 baris dalam bentuk kipas</color>. Semangat akan hilang setelah casting skill.",
  str_skill_desc_3001892 = "Memilih 1 ubin dari <color=#00F6FF>4 ubin dalam bentuk salib</color> di lokasi dan penawaran saat ini <color=#00F6FF>100%</color> kerusakan pada <color=#00F6FF>2 baris dalam bentuk kipas</color> ke arah ini. Zeal meningkatkan kerusakan dan jangkauan, menangani hingga <color=#00F6FF>400%</color> kerusakan pada <color=#00F6FF>7 baris dalam bentuk kipas</color>. Semangat akan hilang setelah casting skill.",
  str_skill_desc_3061891 = "Memilih 1 ubin dari <color=#00F6FF>4 ubin dalam bentuk salib</color> di lokasi dan penawaran saat ini <color=#00F6FF>100%</color> kerusakan pada <color=#00F6FF>2 baris dalam bentuk kipas</color> ke arah ini. Zeal meningkatkan kerusakan dan jangkauan, menangani hingga <color=#00F6FF>400%</color> kerusakan pada <color=#00F6FF>7 baris dalam bentuk kipas</color>. Semangat akan hilang setelah casting skill. Jika Anda memilih untuk melemparkan keterampilan ini dengan ubin Anda saat ini, itu akan meningkatkan semangat <color=#00F6FF>35</color> poin alih-alih menangani kerusakan.",
  str_skill_desc_3061892 = "Memilih 1 ubin dari <color=#00F6FF>4 ubin dalam bentuk salib</color> di lokasi dan penawaran saat ini <color=#00F6FF>100%</color> kerusakan pada <color=#00F6FF>2 baris dalam bentuk kipas</color> ke arah ini. Zeal meningkatkan kerusakan dan jangkauan, menangani hingga <color=#00F6FF>400%</color> kerusakan pada <color=#00F6FF>7 baris dalam bentuk kipas</color>. Semangat akan hilang setelah casting skill. Jika Anda memilih untuk melemparkan keterampilan ini dengan ubin Anda saat ini, itu akan meningkatkan semangat <color=#00F6FF>35</color> poin alih-alih menangani kerusakan.",
  str_skill_desc_3301892 = "Masih bisa menggunakan Normal Attacks dalam keadaan Overzealous di ronde ini. Semangat akan menghilang di akhir putaran.",
  str_skill_desc_3331892 = "Meningkatkan Semangat untuk <color=#00F6FF>100</color>. Masih bisa menggunakan Normal Attacks dalam keadaan Overzealous di ronde ini. Semangat akan menghilang di akhir putaran.",
