  str_skill_desc_2001901 = "Penawaran <color=#00F6FF>140%</color> kerusakan pada 2 musuh terdekat dalam <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_desc_2001902 = "Penawaran <color=#00F6FF>155%</color> kerusakan pada 2 musuh terdekat dalam <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_desc_2001903 = "Penawaran <color=#00F6FF>160%</color> kerusakan pada 2 musuh terdekat dalam <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_desc_2001933 = "Penawaran <color=#00F6FF>160%</color> kerusakan pada 2 musuh terdekat dalam <color=#00F6FF>2 cluster sekitarnya</color>. Setiap kali Fire Aurorian mengeluarkan Skill Aktif, kondisi pemicunya meningkat <color=#00F6FF>1</color>. Selain itu, jumlah target yang terkena bertambah 1, atau jangkauan skill bertambah <color=#00F6FF>1</color> gugus.",
  str_skill_desc_3001901 = "Mengubah <color=#00F6FF>4</color> ubin Hijau terdekat ke Merah.",
  str_skill_desc_3001902 = "Mengonversi ubin Hijau <color=#00F6FF>4</color> terdekat menjadi Merah. Jika Keahlian Aktif sudah siap di babak terakhir, tingkatkan jumlah konversi petak sebanyak <color=#00F6FF>1</color> di babak ini.",
