  str_skill_desc_3051901 = "Mengonversi ubin Hijau <color=#00F6FF>5</color> terdekat menjadi Merah. Jika Keahlian Aktif sudah siap di babak terakhir, tingkatkan jumlah konversi petak sebanyak <color=#00F6FF>1</color> di babak ini.",
  str_skill_passive_name_410189 = "Blitz Api",
