  str_skill_passive_name_410190 = "Penjaga Kesucian",
  str_skill_passive_name_420190 = "Penjaga Kesucian",
  str_skill_passive_name_430190 = "Penjaga Kesucian",
  str_skill_passive_desc_410189 = "Serangan Normal Leyn mendapatkan bonus kerusakan hingga <color=#00F6FF>{1}</color> berdasarkan miliknya <link=\"30078\"><#FFAE07><u>Semangat</u></color></link>, semakin tinggi Zeal, semakin tinggi bonus kerusakannya. Saat Zeal mencapai <color=#00F6FF>100</color>, dia memasuki kondisi Overzealous dan tidak dapat menggunakan Serangan Normal.",
  str_skill_passive_desc_420189 = "Serangan Normal Leyn mendapatkan bonus kerusakan hingga <color=#00F6FF>{1}</color> berdasarkan miliknya <link=\"30078\"><#FFAE07><u>Semangat</u></color></link>, semakin tinggi Zeal, semakin tinggi bonus kerusakannya. Ketika Zeal mencapai <color=#00F6FF>100</color>, dia memasuki kondisi Overzealous dan tidak dapat menggunakan Serangan Normal. Namun, damage terakhir dari Chain Combo-nya meningkat <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_430189 = "Serangan Normal Leyn mendapatkan bonus kerusakan hingga <color=#00F6FF>{1}</color> berdasarkan miliknya <link=\"30078\"><#FFAE07><u>Semangat</u></color></link>, semakin tinggi Zeal, semakin tinggi bonus kerusakannya. Saat Zeal mencapai <color=#00F6FF>100</color>, dia memasuki kondisi Overzealous dan tidak dapat menggunakan Serangan Normal. Namun, damage terakhir dari Chain Combo-nya meningkat <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_433189 = "Serangan Normal Leyn mendapatkan bonus kerusakan hingga <color=#00F6FF>{1}</color> berdasarkan miliknya <link=\"30078\"><#FFAE07><u>Semangat</u></color></link>, semakin tinggi Zeal, semakin tinggi bonus kerusakannya. Saat Zeal mencapai <color=#00F6FF>100</color>, dia memasuki kondisi Overzealous dan tidak dapat menggunakan Serangan Normal. Namun, damage terakhir dari Chain Combo-nya meningkat <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_410190 = "<color=#00F6FF>50%</color> damage yang diberikan oleh Chain Combo diubah menjadi perisai. Nilai perisai ini tidak boleh melebihi <color=#00F6FF>{1}</color> dari ATK Matthieu.",
  str_skill_passive_desc_420190 = "<color=#00F6FF>50%</color> damage yang diberikan oleh Chain Combo diubah menjadi perisai. Nilai perisai ini tidak boleh melebihi <color=#00F6FF>{1}</color> dari ATK Matthieu. Setiap kali Fire Aurorian mengeluarkan Skill Aktif, dapatkan perisai yang setara dengan <color=#00F6FF>10%</color> dari ATK Matthieu.",
  str_skill_passive_desc_430190 = "<color=#00F6FF>50%</color> damage yang diberikan oleh Chain Combo diubah menjadi perisai. Nilai perisai ini tidak boleh melebihi <color=#00F6FF>{1}</color> dari ATK Matthieu. Setiap kali Fire Aurorian mengeluarkan Skill Aktif, dapatkan perisai yang setara dengan <color=#00F6FF>10%</color> dari ATK Matthieu.",
  str_skill_upgrade_desc_16018613 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16018616 = "Peningkatan Keterampilan Aktif: Meningkatkan jumlah ubin yang dapat Anda hubungkan <color=#00F6FF>1</color>.",
