  str_skill_desc_2001863 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom</color>.",
  str_skill_passive_name_410186 = "Pancaran yang Menakjubkan",
  str_skill_passive_name_430186 = "Pancaran yang Menakjubkan",
  str_skill_passive_desc_410186 = "Meningkatkan contoh kerusakan pertama yang ditangani Tina setiap putaran oleh <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430186 = "Meningkatkan contoh kerusakan pertama yang ditangani Tina setiap putaran oleh <color=#00F6FF>{1}</color>. Jika Tina tidak mengambil tindakan di babak terakhir, efeknya berlipat ganda di babak ini.",
  str_skill_name_3001861 = "Beristirahatlah dalam Cahaya Suci",
  str_skill_name_3061861 = "Beristirahatlah dalam Cahaya Suci",
  str_skill_name_3201861 = "Beristirahatlah dalam Cahaya Suci",
  str_skill_name_3261861 = "Beristirahatlah dalam Cahaya Suci",
  str_skill_desc_3001861 = "Tina mulai berjalan sambil tidur, mengabaikan warna ubin hingga <color=#00F6FF>3</color> ubin berturut-turut sementara <color=#00F6FF>mengonversi ubin yang dilewatinya</color> menjadi Biru, lalu kembali ke ubin awalnya.",
  str_skill_desc_3061861 = "Tina mulai berjalan sambil tidur, mengabaikan warna ubin hingga <color=#00F6FF>4</color> ubin berturut-turut sementara <color=#00F6FF>mengonversi ubin yang dilewatinya</color> menjadi Biru, lalu kembali ke ubin awalnya.",
  str_skill_desc_3201861 = "Tina mulai berjalan dalam tidur, mengabaikan warna ubin hingga <color=#00F6FF>3</color> ubin berturut-turut sementara <color=#00F6FF>mengonversi ubin awalnya dan ubin yang dilewatinya</color> menjadi ubin Biru sebelum kembali ke ubinnya ubin awal. Jika ada musuh di ujung jalannya, dia dapat memilih untuk turun ke musuh untuk memberikan <color=#00F6FF>200%</color> kerusakan pada mereka, sebelum mendarat di ubin tepat di depan musuh.",
  str_skill_desc_3261861 = "Tina mulai berjalan sambil tidur, mengabaikan warna ubin hingga <color=#00F6FF>4</color> ubin berturut-turut sementara <color=#00F6FF>mengonversi ubin awalnya dan ubin yang dilewatinya</color> menjadi ubin Biru sebelum kembali ke ubinnya ubin awal. Jika ada musuh di ujung jalannya, dia dapat memilih untuk turun ke musuh untuk memberikan <color=#00F6FF>200%</color> kerusakan pada mereka, sebelum mendarat di ubin tepat di depan musuh.",
  str_skill_upgrade_desc_16018913 = "Peningkatan Skill Aktif: Combat Overload menjadi a <color=#FFFF00>Serangan Preemptive</color> dan meningkatkan semangat untuk <color=#00F6FF>100</color> saat diaktifkan. (Berlaku untuk Ascension III)",
  str_skill_upgrade_desc_16018916 = "Peningkatan Keterampilan Aktif: Dapat memilih ubin saat ini untuk meningkatkan Semangat <color=#00F6FF>35</color> bukannya menangani kerusakan. (Berlaku untuk Kenaikan I)",
  str_skill_upgrade_desc_15019012 = "Active Skill Enhancement: Jika skill siap di putaran sebelumnya, meningkatkan hitungan Tile-Converting sebanyak <color=#FFFF00>1</color> di putaran ini.",
  str_skill_upgrade_desc_15019015 = "Active Skill Enhancement: Meningkatkan hitungan Tile-Converting sebanyak <color=#FFFF00>1</color>.",
  str_skill_upgrade_refine_desc_16001111 = "Peningkatan Keterampilan Peralatan: Berlaku hingga <color=#00F6FF>7</color> tumpukan Dragontooth Mark pada musuh.",
  str_skill_upgrade_refine_desc_16001112 = "<color=#00F6FF>Varian Skill Aktif Baru I</color>: <color=#FFFF00>Cooldown skill -1 setelah casting</color>. Teleportasi ke lokasi yang dipilih di dalamnya <color=#FFFF00>3 cluster sekitarnya</color>, penawaran <color=#FFFF00>200%</color> kerusakan pada <color=#FFFF00>1 cluster sekitarnya</color>, dan menerapkan 2 tumpukan Tanda Gigi Naga (jika dia membunuh musuh, tumpukan Tanda Gigi Naga maksimum diterapkan ke musuh lain di dalam area).",
  str_skill_upgrade_refine_desc_16001113 = "<color=#00F6FF>Varian Skill Aktif Baru II</color>: <color=#FFFF00>Cooldown skill +1 setelah casting</color>. Teleport ke <color=#FFFF00>lokasi manapun</color>, penawaran <color=#FFFF00>360%</color> kerusakan pada <color=#FFFF00>3 cluster sekitarnya</color>, dan menerapkan 2 tumpukan Tanda Gigi Naga (jika dia membunuh musuh, tumpukan Tanda Gigi Naga maksimum diterapkan ke musuh lain di dalam area).",
  str_skill_desc_3300111 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Teleportasi ke lokasi yang dipilih di dalamnya <color=#FFFF00>3 cluster sekitarnya</color>, penawaran <color=#FFFF00>200%</color> kerusakan pada <color=#FFFF00>1 cluster sekitarnya</color>, dan menerapkan 2 tumpukan Tanda Gigi Naga (jika dia membunuh musuh, tumpukan Tanda Gigi Naga maksimum diterapkan ke musuh lain di dalam area).",
  str_skill_desc_3300112 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Teleport ke <color=#FFFF00>lokasi manapun</color>, penawaran <color=#FFFF00>360%</color> kerusakan pada <color=#FFFF00>3 cluster sekitarnya</color>, dan menerapkan 2 tumpukan Tanda Gigi Naga (jika dia membunuh musuh, tumpukan Tanda Gigi Naga maksimum diterapkan ke musuh lain di dalam area).",
  str_skill_upgrade_desc_16019113 = "Dapatkan Keterampilan Aktif Baru: Mengkonsumsi <color=#00F6FF>10%</color> dari HP tim saat ini untuk menangani 250% kerusakan <color=#00F6FF>1 cluster sekitarnya</color>.",
  str_skill_upgrade_desc_16019116 = "Peningkatan Skill Aktif: Mengurangi cooldown skill sebanyak 1 putaran.",
