  str_skill_desc_2001911 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>150%</color> kerusakan pada <color=#00F6FF>9 ubin dalam bentuk persegi</color>.",
  str_skill_desc_2001912 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>160%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>.",
  str_skill_desc_2001913 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>170%</color> kerusakan pada <color=#00F6FF>17 ubin dalam bentuk radial</color>.",
  str_skill_desc_2301911 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>150%</color> kerusakan pada <color=#00F6FF>9 ubin dalam bentuk persegi</color>. Ketika HP lebih rendah dari 40%, jarak lompatan diperluas menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_desc_2301912 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>160%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>. Ketika HP lebih rendah dari 40%, jarak lompatan diperluas menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_desc_2301913 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>170%</color> kerusakan pada <color=#00F6FF>17 ubin dalam bentuk radial</color>. Ketika HP lebih rendah dari 40%, jarak lompatan diperluas menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_name_3001911 = "Pengejaran yang Membara",
  str_skill_name_3201911 = "Pengejaran yang Membara",
  str_skill_name_32019111 = "Pengejaran yang Membara",
  str_skill_desc_3001911 = "Memilih 1 musuh di dalamnya <color=#00F6FF>24 ubin dalam bentuk berlian</color>, lalu teleportasi ke petak terdekat dengan target dan berurusan <color=#00F6FF>150%</color> kerusakan pada mereka.",
  str_skill_desc_3201911 = "Memilih 1 musuh di dalamnya <color=#00F6FF>24 ubin dalam bentuk berlian</color>, lalu teleportasi ke petak terdekat dengan target dan berurusan <color=#00F6FF>150%</color> kerusakan pada mereka. Jika Skill Aktif sudah siap di babak terakhir, rentang pemilihan di babak ini menjadi <color=#00F6FF>4 cluster sekitarnya</color>.",
  str_skill_desc_32019112 = "Memilih 1 musuh di dalamnya <color=#00F6FF>24 ubin dalam bentuk berlian</color>, lalu teleportasi ke petak terdekat dengan target dan berurusan <color=#00F6FF>150%</color> kerusakan pada mereka. Jika Skill Aktif sudah siap di babak terakhir, rentang pemilihan di babak ini menjadi <color=#00F6FF>4 cluster sekitarnya</color> dan kerusakan meningkat menjadi <color=#00F6FF>200%</color>.",
  str_skill_desc_32019113 = "Memilih 1 musuh di dalamnya <color=#00F6FF>24 ubin dalam bentuk berlian</color>, lalu teleportasi ke petak terdekat dengan target dan berurusan <color=#00F6FF>150%</color> kerusakan pada 5 ubin dalam bentuk salib. Jika Skill Aktif sudah siap di babak terakhir, rentang pemilihan di babak ini menjadi <color=#00F6FF>4 cluster sekitarnya</color> dan kerusakan meningkat menjadi <color=#00F6FF>200%</color>.",
  str_skill_name_3001912 = "Api yang Menjijikkan",
  str_skill_name_3061912 = "Api yang Menjijikkan",
  str_skill_desc_3001912 = "Mengkonsumsi <color=#00F6FF>10%</color> dari HP tim saat ini untuk menangani {1}% kerusakan <color=#00F6FF>1 cluster sekitarnya</color>.",
  str_skill_passive_name_410191 = "Membakar Cakar",
  str_skill_passive_desc_410191 = "Kerusakan Hati meningkat saat HP tim berkurang, hingga <color=#00F6FF>{1}</color> ketika HP tim lebih rendah dari <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_4101911 = "Kerusakan Hati meningkat saat HP tim berkurang, hingga <color=#00F6FF>60%</color> ketika HP tim lebih rendah dari <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16019111 = "Peningkatan Keterampilan Peralatan: Bonus naik hingga <color=#00F6FF>60%</color> ketika HP tim lebih rendah dari 30%.",
  str_skill_upgrade_refine_desc_16019112 = "Efek Skill Aktif Baru: Jika Skill Aktif sudah siap di babak terakhir, rentang pemilihan di babak ini menjadi 4 cluster sekitarnya <color=#00F6FF>dan kerusakan meningkat menjadi 200%</color>.",
  str_skill_upgrade_refine_desc_16019113 = "Peningkatan Keterampilan Aktif: Memberikan kerusakan pada <color=#00F6FF>5 ubin dalam bentuk salib</color> bukan 1 tujuan.",
