  str_skill_name_3401932 = "To The Heavens Varian II",
  str_skill_desc_2001931 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>8 tile dalam bentuk silang</color>.",
  str_skill_desc_2001932 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_20019333 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color> dan musuh dalam <color=#00F6FF>bentuk silang hingga jangkauan maksimum</color>.",
  str_skill_desc_2201931 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>8 ubin dalam bentuk salib</color>. Meningkatkan kerusakan yang diberikan kepada musuh di sepanjang bentuk salib sebesar 30%.",
  str_skill_desc_2201932 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Meningkatkan kerusakan yang diberikan kepada musuh di sepanjang bentuk salib sebesar 30%.",
  str_skill_desc_2201933 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>1 cluster sekitarnya</color> Dan <color=#00F6FF>bentuk silang ke jangkauan maksimum</color>. Meningkatkan kerusakan yang diberikan kepada musuh di sepanjang bentuk salib sebesar 30%.",
  str_skill_desc_3001931 = "Menyerang ke 1 arah mana pun yang dipilih, menangani <color=#00F6FF>160%</color> kerusakan pada semua musuh ke arah ini.",
  str_skill_desc_3051931 = "Menyerang ke 1 arah mana pun yang dipilih, menangani <color=#00F6FF>200%</color> kerusakan pada semua musuh ke arah ini.",
  str_skill_desc_3301931 = "Menyerang ke 1 arah mana pun yang dipilih, menangani <color=#00F6FF>160%</color> kerusakan pada semua musuh ke arah ini. Semakin jauh targetnya, semakin banyak damage yang diberikan. Kerusakan akhir meningkat sebesar <color=#00F6FF>10%</color> per klaster.",
  str_skill_desc_3351931 = "Menyerang ke 1 arah mana pun yang dipilih, menangani <color=#00F6FF>200%</color> kerusakan pada semua musuh ke arah ini. Semakin jauh targetnya, semakin banyak damage yang diberikan. Kerusakan akhir meningkat sebesar <color=#00F6FF>10%</color> per klaster.",
  str_skill_desc_3401931 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Menimbulkan 160% kerusakan pada semua musuh dalam 1 arah yang dipilih, lalu bertukar posisi dengan <color=#FFFF00>mendahului</color> anggota tim. Semakin jauh targetnya, semakin banyak damage yang diberikan. Kerusakan akhir meningkat sebesar 10% per cluster. <color=#FFFF00>Jika petak luar dipilih, Kristen bergerak maju sebanyak 1 petak sebelum menggunakan skill</color>.",
  str_skill_desc_3451931 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Menimbulkan 200% kerusakan pada semua musuh dalam 1 arah yang dipilih, lalu bertukar posisi dengan <color=#FFFF00>mendahului</color> anggota tim. Semakin jauh targetnya, semakin banyak damage yang diberikan. Kerusakan akhir meningkat sebesar 10% per cluster. <color=#FFFF00>Jika petak luar dipilih, Kristen bergerak maju sebanyak 1 petak sebelum menggunakan skill</color>.",
  str_skill_desc_3401932 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. <color=#FFFF00>Tanpa menyerang</color>, bertukar posisi dengan <color=#FFFF00>berhasil</color> anggota tim. <color=#FFFF00>Meningkatkan damage Skill Aktif berikutnya sebesar 50%</color>. Bonus kerusakan ini tidak menumpuk saat dilemparkan lebih dari satu kali.",
  str_skill_passive_name_410193 = "Laser aliran jet",
  str_skill_passive_name_430193 = "Laser aliran jet",
  str_skill_passive_desc_410193 = "Serangan normal akan menembus musuh, menangani <color=#00F6FF>{1}</color> merusak target 1 petak di belakang musuh.",
  str_skill_passive_desc_430193 = "Serangan normal akan menembus musuh, menangani <color=#00F6FF>{1}</color> kerusakan target 1 ubin di belakang musuh.",
  str_skill_passive_desc_4401933 = "Serangan normal akan menembus musuh, menangani <color=#00F6FF>60%</color> kerusakan target 1 ubin di belakang musuh. Perubahan kapten untuk pertempuran meningkat <color=#00F6FF>1</color> Kapan Kristen bertukar posisi dengan anggota tim. Memicu hingga 1 kali per putaran.",
  str_skill_upgrade_refine_desc_15019311 = "<color=#00F6FF>Varian Skill Aktif Baru I</color>: <color=#FFFF00>Cooldown skill +1 setelah casting</color>. Menimbulkan kerusakan pada semua musuh dalam 1 arah yang dipilih, lalu bertukar posisi dengan <color=#FFFF00>mendahului</color> anggota tim. Semakin jauh targetnya, semakin banyak damage yang diberikan. Kerusakan akhir meningkat sebesar 10% per cluster. <color=#FFFF00>Jika petak luar dipilih, Kristen bergerak maju sebanyak 1 petak sebelum menggunakan skill</color>.",
  str_skill_upgrade_refine_desc_15019312 = "<color=#00F6FF>Varian Skill Aktif Baru II</color>: <color=#FFFF00>Cooldown skill -1 setelah casting</color>. <color=#FFFF00>Tanpa menyerang</color>, bertukar posisi dengan <color=#FFFF00>berhasil</color> anggota tim. <color=#FFFF00>Meningkatkan damage Skill Aktif berikutnya sebesar 50%</color>. Bonus kerusakan ini tidak menumpuk saat dilemparkan lebih dari satu kali.",
  str_skill_upgrade_refine_desc_15019313 = "Peningkatan Keterampilan Peralatan: Perubahan kapten untuk pertempuran bertambah 1 saat Kristen bertukar posisi dengan anggota tim. Memicu hingga 1 kali per putaran.",
  str_skill_upgrade_desc_15019312 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_15019315 = "Active Skill Enhancement: Meningkatkan damage Active Skill sebesar <color=#FFFF00>40%</color>.",
  str_skill_upgrade_refine_desc_14004811 = "Peningkatan Keterampilan Peralatan: Untuk setiap 1 ubin Kuning di kaki musuh, kerusakan meningkat <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_14004812 = "Peningkatan Keterampilan Aktif: Memberikan kerusakan ganda pada petak di tengah jangkauan keterampilan.",
  str_skill_upgrade_refine_desc_14004813 = "Peningkatan Keterampilan Aktif: Jika Keterampilan Aktif sudah siap di babak terakhir, rentang pemilihan menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_passive_desc_4400481 = "Meningkatkan kerusakan Dayna terhadap musuh yang menduduki ubin Kuning <color=#00F6FF>10%</color>. Untuk setiap ubin Kuning di kaki musuh, bonus kerusakan bertambah <color=#00F6FF>1%</color>. Juga memberikan rekan setim Thunder Aurorian <color=#00F6FF>50%</color> dari bonus ini.",
  str_skill_name_3400482 = "Capricious Thunder",
  str_skill_name_3420482 = "Capricious Thunder",
  str_skill_name_3400483 = "Capricious Thunder",
  str_skill_name_3420483 = "Capricious Thunder",
  str_skill_desc_3400482 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih. Kerusakan yang diberikan pada petak tengah yang dipilih digandakan.",
  str_skill_desc_3420482 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih. Kerusakan yang diberikan pada petak tengah yang dipilih digandakan. Mengubah hingga 1 petak di bawah musuh menjadi Kuning.",
  str_skill_desc_3400483 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih. Kerusakan yang diberikan pada petak tengah yang dipilih digandakan. Jika Skill Aktif ini sudah siap di ronde terakhir, rentang pilihannya menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_desc_3420483 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih. Kerusakan yang diberikan pada petak tengah yang dipilih digandakan. Mengubah hingga 1 petak di bawah musuh menjadi Kuning. Jika Skill Aktif ini sudah siap di ronde terakhir, rentang pilihannya menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_upgrade_refine_desc_15009811 = "Peningkatan Kombo Rantai: Meningkatkan faktor kerusakan Kombo Rantai sebesar <color=#00F6FF>15%/20%/20%</color>.",
  str_skill_upgrade_refine_desc_15009812 = "Peningkatan Keterampilan Peralatan: Dismember Mark menumpuk hingga <color=#00F6FF>10 Kali</color> dan setiap tumpukan meningkatkan kerusakan sebesar 6%.",
  str_skill_upgrade_refine_desc_15009813 = "Peningkatan Keterampilan Aktif: Meningkatkan faktor kerusakan Keterampilan Aktif menjadi <color=#00F6FF>500%</color>. Jika musuh yang dipilih Skill Aktif ini tidak bisa tergeser, <color=#00F6FF>cooldown keterampilan -1</color> setelah pengecoran.",
  str_skill_desc_2009811 = "Penawaran <color=#00F6FF>150%</color> merusak 3 musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>.",
  str_skill_desc_2009821 = "Penawaran <color=#00F6FF>160%</color> merusak 4 musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>.",
  str_skill_desc_2009831 = "Penawaran <color=#00F6FF>170%</color> merusak semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>.",
  str_skill_desc_3300981 = "Memilih 1 musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> dan penawaran <color=#00F6FF>500%</color> merusaknya. Jika musuh menempati satu ubin dan dapat dipukul mundur, pindahkan ke posisi yang dipilih dalam jangkauan serangan. Jika musuh tidak dapat dipukul mundur, <color=#00F6FF>cooldown skill berkurang 1</color> setelah pengecoran. Jika target yang memiliki Tanda terbunuh, memberikan kerusakan yang mengabaikan DEF sama dengan <color=#00F6FF>40%</color> ATK Cuscuta ke musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>.",
  str_skill_desc_3350981 = "Memilih 1 musuh dan berurusan <color=#00F6FF>500%</color> merusaknya. Jika musuh menempati satu ubin dan dapat dipukul mundur, ia dipindahkan ke posisi yang dipilih dalam jangkauan serangan. Jika musuh tidak dapat dipukul mundur, <color=#00F6FF>cooldown skill berkurang 1</color> setelah pengecoran. Jika target yang memiliki Tanda terbunuh, memberikan kerusakan yang mengabaikan DEF sama dengan <color=#00F6FF>40%</color> ATK Cuscuta ke musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>.",
  str_skill_desc_3200331 = "Penawaran <color=#00F6FF>95%</color> kerusakan <color=#00F6FF>5</color> kali untuk musuh acak di medan perang. Meluncurkan 1 serangan tambahan untuk setiap ubin Biru di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> dari lokasi saat ini. Contoh kerusakan pertama yang diberikan ke setiap target adalah <color=#00F6FF>dua kali lipat</color>.",
  str_skill_desc_3250331 = "Penawaran <color=#00F6FF>95%</color> kerusakan <color=#00F6FF>6</color> kali untuk musuh acak di medan perang. Meluncurkan 1 serangan tambahan untuk setiap ubin Biru di dalamnya <color=#00F6FF>12 cluster sekitarnya</color> unit. Contoh kerusakan pertama yang diberikan ke setiap target adalah <color=#00F6FF>dua kali lipat</color>.",
  str_skill_passive_desc_4300331 = "Vice mendapatkan 1 stack Locking Mark setiap kali dia memberikan damage. Setiap tumpukan meningkatkan kerusakan sebesar <color=#00F6FF>2,5%</color> dan kerusakan Chain Combo oleh <color=#00F6FF>5%</color>. Semua tumpukan dibersihkan di akhir putaran.",
  str_skill_passive_desc_4300332 = "Vice mendapatkan 1 stack Locking Mark setiap kali dia memberikan damage. Setiap tumpukan meningkatkan kerusakan sebesar <color=#00F6FF>2,5%</color> dan kerusakan Chain Combo oleh <color=#00F6FF>5%</color>, serta meningkatkan ATK dasar Vice sebesar 0,5%. Semua tumpukan dibersihkan di akhir putaran.",
  str_skill_upgrade_refine_desc_15003311 = "Peningkatan Keterampilan Peralatan: Setiap tumpukan Mark meningkatkan kerusakan sebesar <color=#00F6FF>2,5%</color> dan kerusakan Chain Combo oleh <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_15003312 = "Peningkatan Keterampilan Aktif: Kerusakan pertama yang diberikan ke setiap target adalah <color=#00F6FF>dua kali lipat</color>.",
  str_skill_upgrade_refine_desc_15003313 = "Peningkatan Keterampilan Peralatan: Setiap tumpukan Mark meningkatkan ATK dasar sebesar <color=#00F6FF>0,5%</color>.",
  str_skill_desc_340093 = "Teleportasi ke lokasi mana pun di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> dan penawaran <color=#00F6FF>250%</color> merusak musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Kerusakan digandakan saat hanya ada 1 musuh di area serangan. Kerusakan akhir meningkat sebesar <color=#00F6FF>15%</color> untuk setiap musuh yang terbunuh. Tumpuk hingga 10 kali. Jarak teleportasi meningkat sebesar 1 cluster di sekitarnya untuk setiap 5 musuh yang terbunuh.",
  str_skill_desc_346093 = "Teleportasi ke lokasi mana pun di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> dan penawaran <color=#00F6FF>250%</color> merusak musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Kerusakan digandakan saat hanya ada 1 musuh di area serangan. Kerusakan akhir meningkat sebesar <color=#00F6FF>15%</color> untuk setiap musuh yang terbunuh. Tumpuk hingga 10 kali. Menghapus cooldown Skill Aktif jika target dikalahkan dengan skill (sekali per putaran). Jarak teleportasi meningkat sebesar 1 cluster di sekitarnya untuk setiap 5 musuh yang terbunuh.",
  str_skill_passive_desc_4300931 = "Setelah casting Chain Combo atau Active Skill, jika HP target lebih rendah dari <color=#00F6FF>30%</color>, meluncurkan 1 serangan lagi yang memberikan kerusakan yang mengabaikan DEF sama dengan <color=#00F6FF>120%</color> dari ATK. Jika target memiliki HP lebih sedikit dari ATK Migard setelah serangan ekstra ini, target terbunuh.",
  str_skill_passive_desc_4300932 = "Setelah casting Chain Combo atau Active Skill, jika HP target lebih rendah dari <color=#00F6FF>30%</color>, meluncurkan 1 serangan lagi yang memberikan kerusakan yang mengabaikan DEF sama dengan <color=#00F6FF>120%</color> dari ATK. Jika target memiliki HP kurang dari 250% dari ATK Migard setelah serangan ekstra ini, target akan terbunuh.",
  str_skill_upgrade_refine_desc_16009311 = "Peningkatan Keterampilan Peralatan: Kerusakan serangan ekstra meningkat menjadi <color=#00F6FF>120%</color>.",
  str_skill_upgrade_refine_desc_16009312 = "Peningkatan Keterampilan Aktif: Setiap <color=#00F6FF>5 kali</color> Skill Aktif ini mendapatkan bonus damage, jangkauan seleksi bertambah <color=#00F6FF>1 kluster</color>.",
  str_skill_upgrade_refine_desc_16009313 = "Peningkatan Keterampilan Peralatan: Jika HP target lebih rendah dari <color=#00F6FF>250%</color> dari ATK Migard setelah serangan ekstra, itu terbunuh.",
  str_skill_upgrade_refine_desc_15001811 = "Peningkatan Keterampilan Peralatan: Semakin dekat musuh, semakin banyak kerusakan yang diberikan Keterampilan Aktif dan Kombo Rantai (hingga <color=#00F6FF>110%</color>).",
  str_skill_upgrade_refine_desc_15001812 = "Peningkatan Kombo Rantai: Meningkatkan faktor kerusakan Kombo Rantai sebesar <color=#00F6FF>10%/15%/20%</color>.",
  str_skill_upgrade_refine_desc_15001813 = "Peningkatan Keterampilan Peralatan: Rentang efek meningkat menjadi <color=#00F6FF>5 cluster</color>.",
  str_skill_passive_desc_440018 = "Meningkatkan ATK sebesar <color=#00F6FF>5%</color> untuk setiap musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Semakin dekat musuh, semakin banyak damage Skill Aktif dan Kombo Rantai (hingga <color=#00F6FF>110%</color>). Jarak di luar 3 cluster tidak menawarkan bonus kerusakan.",
  str_skill_passive_desc_450018 = "Meningkatkan ATK sebesar <color=#00F6FF>5%</color> untuk setiap musuh di dalamnya <color=#00F6FF>1 cluster sekitarnya</color>. Semakin dekat musuh, semakin banyak damage Skill Aktif dan Kombo Rantai (hingga <color=#00F6FF>110%</color>). Jarak di luar 5 cluster tidak menawarkan bonus kerusakan.",
  str_skill_desc_2400181 = "Penawaran <color=#00F6FF>115%</color> kerusakan pada <color=#00F6FF>1 kolom</color>.",
  str_skill_desc_2400182 = "Penawaran <color=#00F6FF>125%</color> kerusakan pada <color=#00F6FF>3 kolom</color>.",
  str_skill_desc_2400183 = "Penawaran <color=#00F6FF>130%</color> kerusakan pada <color=#00F6FF>5 kolom</color>.",
  str_skill_upgrade_refine_desc_16006411 = "Peningkatan Skill Aktif: Cooldown Skill berkurang sebesar <color=#00F6FF>2</color> di awal setiap pertempuran.",
  str_skill_upgrade_refine_desc_16006412 = "Peningkatan Keterampilan Peralatan: <color=#00F6FF>5</color> peluru bisa dipesan saat menggunakan Skill Aktif. <color=#00F6FF>1</color> peluru dapat dipesan saat Aurorian mana pun menggunakan Skill Aktif mereka.",
  str_skill_upgrade_refine_desc_16006413 = "Peningkatan Keterampilan Peralatan: Anda dapat secara manual beralih apakah Chain Combo mengkonsumsi amunisi.",
  str_skill_passive_desc_440064 = "Bisa <link=\"30079\"><#FFAE07><u>amunisi cadangan</u></color></link>. Setiap kali Kombo Rantai menimbulkan kerusakan, 1 Amunisi dikonsumsi (hingga <color=#00F6FF>3</color> Amunisi dapat dikonsumsi dalam keadaan Overload). Untuk setiap Amunisi yang dikonsumsi, kerusakan akhir bertambah <color=#00F6FF>30%</color>.",
  str_skill_desc_341064 = "Memasuki status Overload, di mana kerusakan Kombo Rantai Wrath meningkat <color=#00F6FF>50%</color> dan memberikan damage ke musuh terdekat sebanyak 2 kali. Berlangsung selama 2 putaran. Cooldown skill berkurang sebesar <color=#00F6FF>2</color> di awal setiap pertempuran.",
  str_skill_upgrade_refine_desc_16001911 = [[
Victoria bergabung dalam pertempuran dengan <link="30039"><#FFAE07><u>Sistem Kewarasan</u></color></link>.
<color=#00F6FF>Varian Skill Aktif Baru I</color>: <color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>300%</color> merusak hingga 3 musuh dalam jangkauan. Penawaran <color=#FFFF00>300%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Memulihkan HP setara dengan persentase kerusakan yang diberikan. <color=#FFFF00>Selain itu kehilangan Sanity sama dengan persentase HP yang dipulihkan</color>.]],
  str_skill_upgrade_refine_desc_16001912 = "Peningkatan Skill Aktif: Skill Aktif dapat menyerang 1 musuh tambahan.",
  str_skill_upgrade_refine_desc_16001913 = "<color=#00F6FF>Varian Skill Aktif Baru II</color>: <color=#FFFF00>Cooldown skill +1 setelah casting</color>. Memberikan 250% kerusakan hingga 4 musuh dalam jangkauan. Menimbulkan 250% kerusakan mengabaikan DEF saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Memulihkan HP setara dengan persentase kerusakan yang diberikan. <color=#FFFF00>Selain itu memulihkan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_3200192 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>300%</color> kerusakan hingga 3 musuh dalam 3 cluster sekitarnya. Penawaran <color=#FFFF00>300%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 25% dari damage yang diberikan. <color=#FFFF00>Selain itu kehilangan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_3200191 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Memberikan 250% kerusakan hingga 3 musuh dalam 3 kelompok sekitarnya. Menimbulkan 250% kerusakan mengabaikan DEF saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 25% dari damage yang diberikan. <color=#FFFF00>Selain itu memulihkan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_3230192 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>300%</color> kerusakan hingga 3 musuh dalam 3 cluster sekitarnya. Penawaran <color=#FFFF00>300%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan. <color=#FFFF00>Selain itu kehilangan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_3230191 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Memberikan 250% kerusakan hingga 3 musuh dalam 3 kelompok sekitarnya. Menimbulkan 250% kerusakan mengabaikan DEF saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan. <color=#FFFF00>Selain itu memulihkan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_3260192 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>300%</color> kerusakan pada 3 musuh terdekat. Penawaran <color=#FFFF00>300%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan. <color=#FFFF00>Selain itu kehilangan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_3260191 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Memberikan 250% kerusakan pada 3 musuh terdekat. Menimbulkan 250% kerusakan mengabaikan DEF saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan. <color=#FFFF00>Selain itu memulihkan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_32001922 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>300%</color> kerusakan hingga 4 musuh dalam 3 cluster sekitarnya. Penawaran <color=#FFFF00>300%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 25% dari damage yang diberikan. <color=#FFFF00>Selain itu kehilangan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_32001912 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Memberikan 250% kerusakan hingga 4 musuh dalam 3 kelompok sekitarnya. Menimbulkan 250% kerusakan mengabaikan DEF saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 25% dari damage yang diberikan. <color=#FFFF00>Selain itu memulihkan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_32301922 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>300%</color> kerusakan hingga 4 musuh dalam 3 cluster sekitarnya. Penawaran <color=#FFFF00>300%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan. <color=#FFFF00>Selain itu kehilangan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_32301912 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Memberikan 250% kerusakan hingga 4 musuh dalam 3 kelompok sekitarnya. Menimbulkan 250% kerusakan mengabaikan DEF saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan. <color=#FFFF00>Selain itu memulihkan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_32601922 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>300%</color> kerusakan pada 4 musuh terdekat. Penawaran <color=#FFFF00>300%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan. <color=#FFFF00>Selain itu kehilangan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_32601912 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Memberikan 250% kerusakan pada 4 musuh terdekat. Menimbulkan 250% kerusakan mengabaikan DEF saat hanya ada 1 musuh dalam jangkauan. Kerusakan akhir yang diberikan kepada target meningkat sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan. <color=#FFFF00>Selain itu memulihkan Sanity sama dengan persentase HP yang dipulihkan</color>.",
  str_skill_desc_340019 = "Penawaran <color=#00F6FF>250%</color> kerusakan hingga 4 musuh dalam <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>250%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Meningkatkan kerusakan akhir yang diberikan kepada target sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 25% dari damage yang diberikan.",
  str_skill_desc_343019 = "Penawaran <color=#00F6FF>250%</color> kerusakan hingga 4 musuh dalam <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>250%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Meningkatkan kerusakan akhir yang diberikan kepada target sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan.",
  str_skill_desc_346019 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada 4 musuh terdekat. Penawaran <color=#00F6FF>250%</color> DEF-mengabaikan kerusakan saat hanya ada 1 musuh dalam jangkauan. Meningkatkan kerusakan akhir yang diberikan kepada target sebesar 10% untuk setiap tumpukan Pendarahan yang mereka miliki. Mengembalikan HP sebesar 35% dari damage yang diberikan.",
  str_skill_name_290510101 = "Bidang Pengeboran",
  str_skill_desc_290510101 = "Pengebor secara acak memilih area terbuka untuk bergerak, memberikan kerusakan pelepasan ke 4 ubin yang berdekatan. Di akhir gerakan, skill menghasilkan sejumlah Bidang Energi dan Bidang Pendukung dalam 2 cluster di sekitarnya.",
  str_skill_desc_290511102 = "Pengebor secara acak memilih area terbuka untuk bergerak, memberikan kerusakan pelepasan ke 4 ubin yang berdekatan. Di akhir gerakan, skill ini menghasilkan sejumlah Bidang Energi dan Bidang Pendukung.",
  str_skill_desc_290511103 = "Saat mengambil tindakan, hasilkan sejumlah Medan Energi dan Bidang Pendukung di area sekitarnya.",
  str_skill_name_290510102 = "Bidang Energi Pengebor",
  str_skill_desc_290510102 = "Pengebor menyerap Medan Energi di lapangan, mengubahnya menjadi Platform Pengeboran di tempat, dan menimbulkan kerusakan di seluruh lapangan.",
  str_skill_name_290510203 = "Lapangan Dukungan Pengebor",
  str_skill_desc_290510203 = "Pengebor mengunci lokasi Aurorian dengan Platform Pengeboran dan mengarahkan 5 Lapangan Dukungan terdekat ke pemain untuk memberikan kerusakan pada pemain. Hitung mundur muatan energi dalam 2.",
  str_skill_desc_290510213 = "Pengebor mengunci lokasi Aurorian dengan Platform Pengeboran dan mengarahkan 3 Lapangan Dukungan terdekat ke pemain untuk memberikan kerusakan pada pemain. Hitung mundur muatan energi dalam 1.",
  str_skill_name_290510204 = "Anjungan Pengebor Hancur Sendiri",
  str_skill_desc_290510204 = "Platform Pengeboran hancur sendiri setelah mengumpulkan energi penuh, memberikan kerusakan besar ke seluruh medan.",
  str_skill_name_290510123 = "Dalam operasi",
  str_skill_desc_290510123 = "Pengebor beroperasi di belakang anjungan. Pengebor dan Anjungan Pengebor memiliki HP independen.",
  str_skill_desc_290511101 = "Pengebor bergerak ke arah pemain, memberikan kerusakan pelepasan ke 4 ubin yang berdekatan. Di akhir gerakan, skill menghasilkan Bidang Dukungan pada 4 petak yang berdekatan.",
  str_skill_desc_290511203 = "Pengebor mengunci lokasi pemain dengan Platform Pengebor dan menggunakan semua Bidang Dukungan untuk memberikan kerusakan pada pemain. Jumlah kerusakan yang diberikan kepada pemain meningkat dengan jumlah Bidang Dukungan.",
  str_skill_desc_290512101 = "Pengebor berfokus pada penggalian, menghasilkan sejumlah kecil Medan Energi dan Medan Pendukung di sekitarnya pada awal putaran.",
  str_skill_upgrade_desc_16019913 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16019916 = "Peningkatan Keterampilan Peralatan: Kapan Yingel memberikan kerusakan pada target yang memiliki Luka Terbuka, dia mengabaikannya <color=#00F6FF>5%</color> dari DEF mereka untuk setiap 1 Luka Terbuka yang mereka miliki. (Berlaku untuk Ascension III).",
  str_skill_name_2001991 = "Fokus Hiper",
  str_skill_name_2001992 = "Fokus Hiper",
  str_skill_name_2001993 = "Fokus Hiper",
  str_skill_desc_2001991 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada musuh terdekat.",
  str_skill_desc_2001992 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada musuh terdekat.",
  str_skill_desc_2001993 = "Penawaran <color=#00F6FF>{1}%</color> kerusakan pada musuh terdekat.",
