  str_skill_name_2201992 = "Fokus Hiper",
  str_skill_name_2201993 = "Fokus Hiper",
  str_skill_desc_2201991 = "Penawaran <color=#00F6FF>{1}%</color> damage ke musuh yang memiliki HP tertinggi dan Open Wounds terbanyak, atau serang musuh terdekat.",
  str_skill_desc_2201992 = "Penawaran <color=#00F6FF>{1}%</color> damage ke musuh yang memiliki HP tertinggi dan Open Wounds terbanyak, atau serang musuh terdekat.",
  str_skill_desc_2201993 = "Penawaran <color=#00F6FF>{1}%</color> damage ke musuh yang memiliki HP tertinggi dan Open Wounds terbanyak, atau serang musuh terdekat.",
  str_skill_name_3001991 = "Resonansi Surga",
  str_skill_desc_3001991 = "Mengonversi setiap 1 ubin yang dipilih menjadi Kuning <link=\"30080\"><#FFAE07><u>ubin Prisma berbentuk salib</u></color></link>.",
  str_skill_passive_name_410199 = "Isi Ulang Khusus",
  str_skill_passive_name_420199 = "Isi Ulang Khusus",
  str_skill_passive_name_430199 = "Isi Ulang Khusus",
  str_skill_passive_name_436199 = "Isi Ulang Khusus",
  str_skill_passive_desc_410199 = "Serangan Normal Yingel memang merusak setiap <color=#00F6FF>Kedua</color> Serangan Biasa. Pengganda kerusakannya meningkat menjadi <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420199 = "Serangan Normal Yingel memang merusak setiap <color=#00F6FF>Kedua</color> Serangan Biasa. Pengganda kerusakannya meningkat menjadi <color=#00F6FF>{1}</color> dan menimbulkan 1 Luka Terbuka, hingga 20 tumpukan. Untuk setiap Luka Terbuka yang dimiliki target, kerusakan akhir Kombo Rantai Yingel meningkat <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_430199 = "Serangan Normal Yingel memang merusak setiap <color=#00F6FF>Kedua</color> Serangan Biasa. Pengganda kerusakannya meningkat menjadi <color=#00F6FF>{1}</color> dan menimbulkan 1 Luka Terbuka, hingga 20 tumpukan. Untuk setiap Luka Terbuka yang dimiliki target, serangan Yingel diabaikan <color=#00F6FF>3%</color> DEF mereka dan kerusakan akhir Chain Combo-nya meningkat sebesar <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_436199 = "Serangan Normal Yingel memang merusak setiap <color=#00F6FF>Kedua</color> Serangan Biasa. Pengganda kerusakannya meningkat menjadi <color=#00F6FF>{1}</color> dan menimbulkan 1 Luka Terbuka, hingga 20 tumpukan. Untuk setiap Luka Terbuka yang dimiliki target, serangan Yingel diabaikan <color=#00F6FF>5%</color> DEF mereka dan kerusakan akhir Chain Combo-nya meningkat sebesar <color=#00F6FF>3%</color>.",
  str_skill_desc_1601751002 = "Ubin Prisma Berbentuk Silang",
  str_skill_desc_160175102 = "Mengkonsumsi <color=#00F6FF>3</color> Energi Kubik untuk mengubah 1 ubin apa saja menjadi ubin Prisma Berbentuk Silang.",
  str_skill_name_3400231 = "Sonata of Abyss Varian I",
  str_skill_name_3430231 = "Sonata of Abyss Varian I",
  str_skill_name_3400232 = "Sonata dari Abyss Varian II",
  str_skill_name_3430232 = "Sonata dari Abyss Varian II",
  str_skill_desc_3400231 = "<color=#FFFF00>Cooldown skill -2 setelah casting</color>. Penawaran <color=#FFFF00>250%</color> kerusakan pada semua musuh. Varian ini tidak dapat memicu efek Menakut-nakuti Skill Peralatan.",
  str_skill_desc_3430231 = "<color=#FFFF00>Cooldown skill -2 setelah casting</color>. Penawaran <color=#FFFF00>250%</color> kerusakan pada semua musuh. Varian ini tidak dapat memicu efek Menakut-nakuti Skill Peralatan.",
  str_skill_desc_3400232 = "<color=#FFFF00>Cooldown skill +2 setelah casting</color>. <color=#FFFF00>Menimbulkan semua musuh dengan <link=\"10003\"><#FFAE07><u>Menakuti</u></color></link> untuk 1 putaran</color> dan penawaran <color=#FFFF00>550%</color> kerusakan pada mereka.",
  str_skill_desc_3430232 = "<color=#FFFF00>Cooldown skill +2 setelah casting</color>. <color=#FFFF00>Menimbulkan semua musuh dengan <link=\"10003\"><#FFAE07><u>Menakuti</u></color></link> untuk 1 putaran</color> dan penawaran <color=#FFFF00>550%</color> kerusakan pada mereka.",
  str_skill_passive_desc_440023 = "Mendapatkan 1 stack Shiver Mark saat menggunakan Chain Combo, hingga <color=#00F6FF>5</color> tumpukan. Setiap tumpukan meningkatkan kerusakan Skill Aktif sebesar <color=#00F6FF>20%</color>. Menggunakan Skill Aktif menyebabkan <link=\"10003\"><#FFAE07><u>Menakuti</u></color></link> pada sejumlah musuh setara dengan jumlah tumpukan untuk <color=#00F6FF>1</color> bulat. Mengaktifkan Skill Aktif <color=#00F6FF>tidak membersihkan tumpukan</color>. Jika sudah ada 5 stack sebelum mengeluarkan skill Chain Combo, maka akan memberikan damage tambahan pada musuh terdekat. Connolly memberikan tambahan 15% kerusakan akhir pada <link=\"10003\"><#FFAE07><u>Takut</u></color></link> musuh.",
  str_skill_upgrade_refine_desc_16002311 = "<color=#00F6FF>Varian Skill Aktif Baru I</color>: <color=#FFFF00>Cooldown skill -2 setelah casting</color>. Penawaran <color=#FFFF00>250%</color> kerusakan pada semua musuh. Varian ini tidak dapat memicu efek Menakut-nakuti Skill Peralatan.",
  str_skill_upgrade_refine_desc_16002312 = "Peningkatan Keterampilan Peralatan: Connolly penawaran <color=#00F6FF>tambahan 15% kerusakan akhir</color> untuk musuh yang ditimbulkan oleh Ketakutan.",
  str_skill_upgrade_refine_desc_16002313 = "<color=#00F6FF>Varian Skill Aktif Baru II</color>: <color=#FFFF00>Cooldown skill +2 setelah casting</color>. <color=#FFFF00>Menimbulkan semua musuh dengan <link=\"10003\"><#FFAE07><u>Menakuti</u></color></link> untuk 1 putaran</color> dan penawaran <color=#FFFF00>550%</color> kerusakan pada mereka.",
  str_skill_name_290520101 = "Gumulan Ganas",
  str_skill_desc_290520101 = "Bergerak menuju Aurorian dan memberikan banyak kerusakan, lalu mundur dari target.",
  str_skill_name_290520102 = "Gumulan Ganas",
  str_skill_desc_290520102 = "Memberikan kerusakan pada semua Aurorian dalam jangkauan setelah bergerak.",
  str_skill_name_200250101 = "Mendekati Api",
  str_skill_desc_200250101 = "Meluncurkan serangan jarak jauh pada target dalam jangkauan.",
  str_skill_name_200250102 = "Pisau Serangan",
  str_skill_desc_200250102 = "Meluncurkan serangan jarak dekat pada target dalam jangkauan.",
  str_skill_name_290500122 = "Telur laba-laba",
  str_skill_desc_290500122 = "Telur laba-laba yang diletakkan oleh Spider Queen. Ia menetas menjadi Spider Hatchling dalam waktu singkat.",
  str_skill_name_3400901 = "Sweet Kiss Varian I",
