  str_skill_name_3420902 = "Sweet Kiss Varian II",
  str_skill_desc_3400901 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Penawaran <color=#FFFF00>{1}%</color> kerusakan pada semua musuh <color=#FFFF00>dan mengejutkan mereka</color>.",
  str_skill_desc_3420901 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Penawaran <color=#FFFF00>{1}%</color> kerusakan pada semua musuh <color=#FFFF00>dan mengejutkan mereka</color>.",
  str_skill_desc_3400902 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>{1}%</color> kerusakan pada semua musuh.",
  str_skill_desc_3420902 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>{1}%</color> kerusakan pada semua musuh.",
  str_skill_passive_desc_440090 = "Meningkatkan kerusakan Barbara terhadap musuh yang menduduki ubin Merah <color=#00F6FF>10%</color>. Untuk setiap ubin Merah di kaki musuh, bonus kerusakan bertambah <color=#00F6FF>1%</color>. Juga memberikan Fire Aurorian rekan satu tim <color=#00F6FF>50%</color> dari bonus ini.",
  str_skill_upgrade_refine_desc_15009011 = "Peningkatan Keterampilan Peralatan: Untuk setiap 1 ubin Merah di kaki musuh, bonus kerusakan bertambah <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15009012 = "<color=#00F6FF>Varian Skill Aktif Baru I</color>: <color=#FFFF00>Cooldown skill +1 setelah casting</color>. Penawaran <color=#FFFF00>600%</color> kerusakan pada semua musuh <color=#FFFF00>dan mengejutkan mereka</color>.",
  str_skill_upgrade_refine_desc_15009013 = "<color=#00F6FF>Varian Skill Aktif Baru II</color>: <color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#FFFF00>450%</color> kerusakan pada semua musuh.",
  str_skill_name_5000961 = "Tautkan",
  str_skill_desc_5000961 = "Ketika Aurorian masuk ke dalam 2 kelompok Spikepest di sekitarnya, sebuah tautan dibuat secara otomatis di antara mereka. Tautan putus saat Aurorian memindahkan 4 kelompok di sekitarnya menjauh dari Spikepest. Saat ditautkan, Spikepest membagikan 50% kerusakan yang diterima pemain.",
  str_skill_desc_4001531 = "Melemparkan keterampilan untuk menjatuhkan musuh dalam 3 kelompok di sekitarnya sebanyak 1 petak dan mengubah petak di bawah musuh menjadi petak Kuning.",
  str_skill_desc_4001751 = "Saat menggunakan skill, setiap kali pemain menerima damage di ronde ini, 1 ubin dengan elemen yang sama dengan kapten akan disegarkan, dan sejumlah kecil HP tim akan dipulihkan.",
