  str_skill_desc_3401921 = "Biaya <color=#00F6FF>5</color> Duri: Di babak ini, serangan normal dapat diluncurkan secara diagonal, dan kerusakan serangan normal meningkat <color=#00F6FF>20%</color> (dapat ditumpuk bila digunakan lebih dari satu kali). Serangan ini tidak dianggap sebagai Skill Aktif.",
  str_skill_passive_name_410192 = "Segel Duri",
  str_skill_passive_name_416192 = "Segel Duri",
  str_skill_passive_name_430192 = "Segel Duri",
  str_skill_passive_name_436192 = "Segel Duri",
  str_skill_passive_desc_410192 = "Keuntungan 1 <color=#00F6FF>Duri</color> untuk setiap 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> diperoleh oleh tim (termasuk <link=\"30065\"><#FFAE07><u>terserap</u></color></link> ubin). Setiap Thorn meningkatkan tingkat kerusakan Chain Combo sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_416192 = "Keuntungan 1 <color=#00F6FF>Duri</color> untuk setiap 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> diperoleh oleh tim (termasuk <link=\"30065\"><#FFAE07><u>terserap</u></color></link> ubin). Setiap Thorn meningkatkan tingkat kerusakan Chain Combo sebesar <color=#00F6FF>{1}</color>. Keuntungan <color=#00F6FF>5</color> Duri di awal setiap gelombang.",
  str_skill_passive_desc_430192 = "Keuntungan 1 <color=#00F6FF>Duri</color> untuk setiap 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> diperoleh oleh tim (termasuk <link=\"30065\"><#FFAE07><u>terserap</u></color></link> ubin). Setiap Thorn meningkatkan tingkat kerusakan Chain Combo sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_436192 = "Keuntungan 1 <color=#00F6FF>Duri</color> untuk setiap 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> diperoleh oleh tim (termasuk <link=\"30065\"><#FFAE07><u>terserap</u></color></link> ubin). Setiap Thorn meningkatkan tingkat kerusakan Chain Combo sebesar <color=#00F6FF>{1}</color>. Keuntungan <color=#00F6FF>5</color> Duri di awal setiap gelombang.",
  str_skill_passive_desc_440192 = "Keuntungan 1 <color=#00F6FF>Duri</color> untuk setiap 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> diperoleh oleh tim (termasuk <link=\"30065\"><#FFAE07><u>terserap</u></color></link> ubin). Setiap Thorn meningkatkan tingkat kerusakan Chain Combo sebesar <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_446192 = "Keuntungan 1 <color=#00F6FF>Duri</color> untuk setiap 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> diperoleh oleh tim (termasuk <link=\"30065\"><#FFAE07><u>terserap</u></color></link> ubin). Setiap Thorn meningkatkan tingkat kerusakan Chain Combo sebesar <color=#00F6FF>3%</color>. Keuntungan <color=#00F6FF>5</color> Duri di awal setiap gelombang.",
  str_skill_upgrade_refine_desc_16019211 = "Peningkatan Keterampilan Peralatan: Setiap Duri meningkatkan kerusakan Kombo Rantai sebesar <color=#00F6FF>3%</color>.",
  str_skill_upgrade_refine_desc_16019212 = "Peningkatan Keterampilan Peralatan: Keuntungan <color=#00F6FF>5</color> Duri di awal pertempuran.",
  str_skill_upgrade_refine_desc_16019213 = "Peningkatan Keterampilan Aktif: Menghasilkan <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> secara acak dalam area efek.",
  str_skill_passive_desc_440193 = "Keuntungan 1 <color=#00F6FF>Duri</color> untuk setiap 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> diperoleh oleh tim (termasuk <link=\"30065\"><#FFAE07><u>terserap</u></color></link> ubin). Setiap Thorn meningkatkan kerusakan Chain Combo sebesar <color=#00F6FF>3%</color>. Keuntungan <color=#00F6FF>5</color> Duri di awal pertempuran.",
  str_skill_passive_desc_446193 = "Keuntungan 1 <color=#00F6FF>Duri</color> untuk setiap 1 <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link> diperoleh oleh tim (termasuk <link=\"30065\"><#FFAE07><u>terserap</u></color></link> ubin). Setiap Thorn meningkatkan tingkat kerusakan Chain Combo sebesar <color=#00F6FF>3%</color>. Keuntungan <color=#00F6FF>5</color> Duri di awal pertempuran dan awal setiap gelombang.",
