  str_skill_upgrade_desc_16019216 = "Peningkatan Keterampilan Peralatan: Keuntungan <color=#00F6FF>5</color> Duri di awal setiap gelombang.",
  str_skill_name_5010152 = "Encourage",
  str_skill_desc_5010152 = "Shadow Walker bergerak ke area dengan unit paling ramah dan menerapkan Tanda Kekuatan ke semua sekutu, memberikan peningkatan ATK.",
  str_skill_name_888450061 = "Karang Cozen",
  str_skill_desc_888450061 = "Memanggil 1 Cozen yang menyerang Aurorian setiap 2 ronde.",
  str_skill_desc_888450081 = "Siphorb menyerap energi dari ubin tempatnya berdiri dan ubin yang memiliki elemen yang sama dalam 1 cluster di sekitarnya, lalu melepaskan Bola Energi yang menyerang semua musuh. Kerusakan meningkat dengan jumlah ubin yang diserap. Menghasilkan Area Berbahaya di mana Aurorian berdiri 2 putaran setelah memukul Aurorian.",
  str_skill_upgrade_refine_desc_13004611 = "Peningkatan Keterampilan Peralatan: <color=#00F6FF>Ganda</color> bonus kerusakan Serangan Normal Keating terima dari setiap Tanda Tertawa.",
  str_skill_upgrade_refine_desc_13004613 = "Peningkatan Keterampilan Peralatan: Setiap Serangan Normal Keating kesepakatan memiliki <color=#00F6FF>35%</color> kesempatan untuk menimbulkan 1 Tanda Tertawa pada musuh.",
  str_skill_passive_desc_4400461 = "Membunuh musuh dengan efek Laughter Mark <color=#00F6FF>1</color> stack tambahan dari Laughter Mark ke semua musuh yang tersisa. Setiap tanda meningkatkan kerusakan Serangan Normal Thunder Aurorian sebesar <color=#00F6FF>1,8%</color>. Bonusnya Keating menerima adalah <color=#00F6FF>dua kali lipat</color>.",
  str_skill_desc_340046 = "Mengurangi cooldown skill sebanyak <color=#00F6FF>2</color> di awal pertempuran. Menghasilkan tiruan pada petak terpilih yang menarik musuh dalam <color=#00F6FF>3 cluster di sekitarnya</color> dan menyebabkan <link=\"10006\"><#FFAE07><u>Lambat</u></color> </link> pada musuh dengan 5 tumpukan Mark selama 2 putaran.",
  str_skill_desc_342046 = "Mengurangi cooldown skill sebanyak <color=#00F6FF>2</color> di awal pertempuran. Menghasilkan tiruan pada petak terpilih yang menarik musuh dalam <color=#00F6FF>3 cluster di sekitarnya</color> dan menyebabkan <link=\"10006\"><#FFAE07><u>Lambat</u></color> </link> pada musuh dengan 4 tumpukan Mark selama 2 putaran dan menimbulkan <link=\"10004\"><#FFAE07><u>Kelumpuhan</u></color></link> pada musuh dengan 6 tumpukan Mark untuk 1 putaran.",
  str_skill_desc_345046 = "Mengurangi cooldown skill sebanyak <color=#00F6FF>2</color> di awal pertempuran. Menghasilkan tiruan pada petak terpilih yang menarik <color=#00F6FF>semua</color> musuh dan menyebabkan <link=\"10006\"><#FFAE07><u>Lambat</u></color></link > pada musuh dengan 4 tumpukan Mark selama 2 putaran dan memberikan <link=\"10004\"><#FFAE07><u>Kelumpuhan</u></color></link> pada musuh dengan 6 tumpukan Mark selama 1 putaran .",
  str_skill_passive_desc_4400463 = "Membunuh musuh dengan Laughter Mark memberikan <color=#00F6FF>+1</color> stack tambahan ke semua musuh yang tersisa. Setiap tanda meningkatkan kerusakan Serangan Normal Thunder Aurorian sebesar <color=#00F6FF>2%</color>. Bonus yang diterima Keating adalah <color=#00F6FF>berlipat ganda</color>. Setiap Serangan Normal yang dilakukan Keating memiliki peluang <color=#00F6FF>35%</color> untuk menimbulkan 1 Tanda Tertawa pada musuh.",
  str_skill_upgrade_refine_desc_16006011 = "Peningkatan Keahlian Peralatan: Meningkatkan kerusakan percikan dari Serangan Normal yang diberikan pada kondisi Siang hari menjadi <color=#00F6FF>60%</color>.",
  str_skill_upgrade_refine_desc_16006012 = "Peningkatan Keahlian Peralatan: Meningkatkan kerusakan Serangan Normal yang diberikan pada kondisi Siang sebesar <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_16006013 = "Peningkatan Kombo Rantai: Meningkatkan jangkauan Kombo Rantai sebesar 1 klaster di sekitarnya dalam keadaan Siang.",
  str_skill_passive_desc_4400601 = "Dalam kondisi Siang, Serangan Normal memberikan <color=#00F6FF>20%</color> peningkatan kerusakan dan tambahan <color=#00F6FF>60%</color> <link=\"30015\"><#FFAE07><u >Splash</u></color></link> kerusakan ke semua target di <color=#00F6FF>4 ubin dalam bentuk salib</color> di sekitar musuh.",
  str_skill_passive_desc_4400602 = "Dalam kondisi Siang, Serangan Normal memberikan <color=#00F6FF>25%</color> peningkatan kerusakan dan tambahan <color=#00F6FF>60%</color> <link=\"30015\"><#FFAE07><u >Splash</u></color></link> kerusakan ke semua target di <color=#00F6FF>4 ubin dalam bentuk salib</color> di sekitar musuh.",
  str_skill_desc_243601 = "Penawaran <color=#00F6FF>155%</color> merusak 4 musuh di dalamnya <color=#00F6FF>2 cluster sekitarnya</color>. Meningkatkan jangkauan sebanyak 1 klaster di sekitarnya dalam kondisi Siang.",
  str_skill_desc_243602 = "Penawaran <color=#00F6FF>160%</color> merusak 4 musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Meningkatkan jangkauan sebanyak 1 klaster di sekitarnya dalam kondisi Siang.",
  str_skill_desc_243603 = "Penawaran <color=#00F6FF>175%</color> merusak 4 musuh di dalamnya <color=#00F6FF>4 cluster sekitarnya</color>. Meningkatkan jangkauan sebanyak 1 klaster di sekitarnya dalam kondisi Siang.",
  str_skill_name_2002001 = "Kegelapan Datang",
