  str_skill_name_325200 = "Ode untuk Kedalaman",
  str_skill_passive_name_410200 = "Analisis Kelemahan",
  str_skill_passive_name_430200 = "Analisis Kelemahan",
  str_skill_desc_2002001 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_desc_2002002 = "Penawaran <color=#00F6FF>{1}%</color> merusak 3 musuh di dalamnya <color=#00F6FF>4 cluster sekitarnya</color>.",
  str_skill_desc_2002003 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh terdekat.",
  str_skill_desc_2102001 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_desc_2102002 = "Penawaran <color=#00F6FF>{1}%</color> merusak 3 musuh di dalamnya <color=#00F6FF>4 cluster sekitarnya</color>.",
  str_skill_desc_2102003 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh terdekat.",
  str_skill_desc_300200 = "Memilih hingga 2 musuh melalui ubin di bawah mereka, menangani <color=#00F6FF>{1}%</color> kerusakan pada mereka. Semua musuh di petak yang dipilih dan petak di antaranya <link=\"30081\"><#FFAE07><u>ditarik</u></color></link> ke pusat daerah ini. Jika hanya satu musuh yang dipilih, mereka hanya akan menerima damage dan tidak akan ditarik.",
  str_skill_desc_305200 = "Pilih hingga 2 musuh melalui ubin yang mereka tempati dan berikan <color=#00F6FF>{1}%</color> kerusakan pada mereka. Semua musuh pada petak yang dipilih dan petak di antaranya <link=\"30081\"><#FFAE07><u>ditarik</u></color></link> ke tengah area yang terbentuk. Jika hanya 1 musuh yang dipilih, mereka hanya akan menerima damage tetapi tidak akan ditarik. Kerusakan akhir meningkat sebesar <color=#00F6FF>10%</color> untuk setiap ubin <color=#00F6FF>1</color> yang ditepi musuh.",
  str_skill_desc_320200 = "Pilih hingga 2 musuh melalui ubin yang mereka tempati dan berikan <color=#00F6FF>{1}%</color> kerusakan pada mereka. Semua musuh pada petak yang dipilih dan petak di antaranya <link=\"30081\"><#FFAE07><u>ditarik</u></color></link> ke tengah area yang terbentuk. Jika hanya 1 musuh yang dipilih, Anatoli akan menggantikannya sebagai target kedua dan berkumpul di tengah.",
  str_skill_desc_325200 = "Pilih hingga 2 musuh melalui ubin yang mereka tempati dan berikan <color=#00F6FF>{1}%</color> kerusakan pada mereka. Semua musuh pada petak yang dipilih dan petak di antaranya <link=\"30081\"><#FFAE07><u>ditarik</u></color></link> ke tengah area yang terbentuk. Jika hanya 1 musuh yang dipilih, Anatoli akan menggantikannya sebagai target kedua dan berkumpul di tengah. Kerusakan akhir meningkat sebesar <color=#00F6FF>10%</color> untuk setiap ubin <color=#00F6FF>1</color> yang ditepi musuh.",
  str_skill_passive_desc_410200 = "Combo Rantai Anatoli memberikan tambahan <color=#00F6FF>{1}</color> kerusakan pada musuh acak yang berdekatan dengan target.",
  str_skill_passive_desc_430200 = "Combo Rantai Anatoli memberikan tambahan <color=#00F6FF>{1}</color> kerusakan pada musuh acak yang berdekatan dengan target. <color=#00F6FF>Target tunggal</color> Kombo Rantai dari semua kesepakatan sekutu <color=#00F6FF>7%</color> peningkatan kerusakan akhir <link=\"30082\"><#FFAE07><u>berkerumun</u></color></link> musuh.",
  str_skill_upgrade_desc_15020012 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_15020015 = "Peningkatan Keterampilan Aktif: Meningkatkan kerusakan akhir sebesar <color=#00F6FF>10%</color> untuk setiap <color=#00F6FF>1</color> ubin musuh ditarik.",
  str_skill_name_290530101 = "Tanda Teror",
  str_skill_desc_290530101 = "Memberikan kerusakan pada target secara langsung dan menghasilkan tanda pada petak tempat target berada.",
  str_skill_name_290530102 = "Ketakutan Terburu-buru",
  str_skill_desc_290530102 = "Maju hingga 2 ubin ke arah target, memberikan kerusakan pada target di sepanjang jalan dan dalam 4 ubin dalam bentuk silang di tempat tujuan. Jika Dread Rush meleset dari target, Helios melepaskan Terror Mark tambahan.",
  str_skill_desc_290530312 = "Maju hingga 2 ubin ke arah target, memberikan kerusakan pada target di sepanjang jalan dan ke 4 ubin dalam bentuk silang di tempat tujuan.",
  str_skill_name_290530103 = "Lompatan Teror",
  str_skill_desc_290530103 = "Jika target berada dalam jangkauan, Helios akan melompat ke samping target, memberikan damage yang besar kepada mereka dan menjatuhkan mereka ke belakang saat mendarat. Jika Leap of Terror meleset dari target atau target tidak berada dalam jangkauan, Helios akan mengeluarkan Terror Mark tambahan.",
  str_skill_name_290530104 = "Kegilaan Marah",
  str_skill_desc_290530104 = "Helios bergerak ke lokasi Tanda Teror sesuai dengan urutan pembuatannya, lalu bergegas mendekati target, memberikan kerusakan besar pada target di sepanjang jalan dan dalam jarak tertentu di tempat tujuan. Pada saat yang sama, Helios mengubah sebagian dari akumulasi Memarnya menjadi HP.",
  str_skill_name_215009011 = "Normal Attack",
  str_skill_desc_215009011 = "Menyerang musuh dalam jangkauan sekali setelah bergerak.",
  str_skill_name_11150713 = "Sumber Bahaya",
  str_skill_desc_11150713 = "Kembali ke Area Berbahaya, memulihkan beberapa HP, dan meningkatkan dirinya secara permanen.",
  str_skill_name_290530302 = "Terburu-buru Takut",
  str_skill_desc_290530302 = "Maju hingga 2 ubin ke arah target, memberikan kerusakan pada target di sepanjang jalan dan ke 4 ubin dalam bentuk silang di tempat tujuan.",
  str_skill_desc_11150313 = "Kristal Cahaya misterius yang dapat dipicu dengan melewatinya, memanggil petir untuk menyerang semua target, termasuk Aurorian.",
  str_skill_name_290500102 = "Mangsa",
  str_skill_name_290500112 = "Mangsa: Menelurkan",
  str_skill_name_290500103 = "Berburu",
  str_skill_name_290500113 = "Berburu+",
  str_skill_name_290500104 = "Rapat umum",
  str_skill_name_290500114 = "Reli +",
  str_skill_desc_290500102 = "Ratu Laba-laba menukik ke arah mangsanya, memasang jaring untuk mengunci ubin dan merusak Aurorian.",
  str_skill_desc_290500112 = "Ratu Laba-laba menukik mangsanya, memutar jaring untuk mengunci ubin dan merusak Aurorian sambil memanggil tukik ke medan perang.",
  str_skill_desc_290500103 = "Ratu Laba-laba membuat jaring untuk mengunci ubin di sekitar Aurorian, lalu memanggil tukiknya untuk menerkam mereka untuk memberikan kerusakan.",
  str_skill_desc_290500113 = "Spider Queen memutar jaring untuk mengunci ubin di sekitar Aurorian, lalu memanggil tukiknya untuk menerkam mereka dan memberikan kerusakan. Ubin yang terkunci kembali ke keadaan semula setelah 1 putaran.",
  str_skill_desc_290500104 = "Ratu Laba-laba memanggil tukiknya untuk menyerang. Mereka akan meletakkan jaring laba-laba dan mengunci sejumlah besar ubin.",
  str_skill_desc_290500114 = "Ratu Laba-laba memanggil tukiknya untuk menyerang. Mereka akan memutar jaring laba-laba, mengunci sejumlah besar ubin. Ubin yang terkunci kembali ke keadaan semula setelah 1 putaran.",
  str_skill_name_200240102 = "Patroli",
  str_skill_name_200240103 = "Mangsa",
  str_skill_name_200240104 = "Rapat umum",
  str_skill_desc_200240102 = "Spider Hatchlings berpatroli di wilayah mereka dan menyerang musuh yang mereka deteksi.",
  str_skill_desc_200240103 = "Spider Hatchling menerkam mangsanya dan mencoba membunuh mereka dalam satu pukulan.",
  str_skill_desc_200240104 = "Setelah menerima panggilan Spider Queen, Spider Hatchling bersatu untuk melakukan serangan bersama.",
  str_skill_name_290530204 = "Kegilaan Marah",
  str_skill_desc_290530204 = "Helios bergerak ke lokasi Tanda Teror sesuai dengan urutan pembuatannya, lalu bergegas mendekati target, memberikan kerusakan pada target di sepanjang jalan dan dalam jarak tertentu di tempat tujuan. Pada saat yang sama, Helios menghapus semua Tanda Teror di medan perang dan mengubah sebagian dari Memar yang terkumpul menjadi HP berdasarkan jumlah Tanda Teror yang dibersihkan.",
  str_skill_name_290530404 = "Kegilaan Marah",
  str_skill_desc_290530404 = "Helios bergerak ke lokasi Tanda Teror sesuai dengan urutan pembuatannya, lalu bergegas mendekati target, memberikan kerusakan besar pada target di sepanjang jalan dan dalam jarak tertentu di tempat tujuan. Pada saat yang sama, Helios mengubah sebagian dari akumulasi Memarnya menjadi HP.",
  str_skill_upgrade_desc_16020113 = "Peningkatan Keterampilan Aktif: Perubahan <color=#FFFF00>Pemanggilan</color> ke <color=#FFFF00>Serangan Preemptive</color>. Tersedia saat memasuki pertempuran.",
  str_skill_upgrade_desc_16020116 = "Peningkatan Skill Aktif: Mengurangi cooldown dari <color=#FFFF00>Kelahiran Baba Yaga</color> oleh <color=#FFFF00>1</color>.",
  str_skill_upgrade_refine_desc_16020111 = "Peningkatan Keterampilan Peralatan: Saat dilengkapi dengan perisai, meningkatkan bonus kerusakan dasar menjadi <color=#FFFF00>15%</color>.",
  str_skill_upgrade_refine_desc_16020112 = "Peningkatan Keterampilan Aktif: Meningkatkan Perisai yang diperoleh dari <color=#FFFF00>Pemanggilan</color> ke <color=#FFFF00>90%</color> dari HP.",
  str_skill_upgrade_refine_desc_16020113 = "Peningkatan Keterampilan Peralatan: Saat HP turun ke minimum, dapatkan bonus kerusakan tambahan hingga <color=#00F6FF>10%</color>.",
  str_skill_name_2002011 = "Tidak ada yang tersisa",
  str_skill_name_2002012 = "Tidak ada yang tersisa",
  str_skill_name_2002013 = "Tidak ada yang tersisa",
  str_skill_desc_2002011 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2002012 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color>.",
  str_skill_desc_2002013 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_passive_name_410201 = "Bantuan Veronica",
  str_skill_passive_desc_410201 = "Saat terlindung, semuanya Mia: Damage Lustrous Soul meningkat sebesar <color=#00F6FF>{1}</color>, dan dia mendapatkan kerusakan bonus berdasarkan nilai perisai. Ketika nilai perisai mencapai 50% dari HP maksimum tim, kerusakan bonus akan mencapai maksimum <color=#00F6FF>10%</color>.",
  str_skill_passive_name_420201 = "Bantuan Veronica",
  str_skill_passive_desc_420201 = "Saat terlindung, semuanya Mia: Damage Lustrous Soul meningkat sebesar <color=#00F6FF>{1}</color>, dan dia mendapatkan kerusakan bonus berdasarkan nilai perisai dan persentase HP saat ini. Ketika nilai perisai mencapai 50% dari HP maksimum tim, kerusakan bonus akan mencapai maksimum <color=#00F6FF>10%</color>, dan ketika HP mencapai titik terendah, kerusakan bonus dimaksimalkan <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_4202011 = "Saat terlindung, semuanya Mia: Damage Lustrous Soul meningkat sebesar <color=#00F6FF>15%</color>, dan dia mendapatkan kerusakan bonus berdasarkan nilai perisai dan persentase HP saat ini. Ketika nilai perisai mencapai 50% dari HP maksimum tim, kerusakan bonus akan mencapai maksimum <color=#00F6FF>10%</color>, dan ketika HP mencapai titik terendah, kerusakan bonus akan maksimal <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_4432011 = "Saat terlindung, semuanya Mia: Damage Lustrous Soul meningkat sebesar <color=#00F6FF>15%</color>, dan dia mendapatkan kerusakan bonus berdasarkan nilai perisai dan persentase HP saat ini. Ketika nilai perisai mencapai 50% dari HP maksimum tim, kerusakan bonus akan mencapai maksimum <color=#00F6FF>10%</color>, dan ketika HP mencapai titik terendah, kerusakan bonus akan maksimal <color=#00F6FF>10%</color>.",
