  str_skill_desc_2002023 = [[
Penawaran <color=#00F6FF>{1}%</color> kerusakan di a <color=#00F6FF>bentuk radial ke jangkauan maksimum</color> dan menghasilkan 1 Blade of Dawn pada salah satu ubin yang dapat dilalui paling jauh. Memicu hingga 1 kali per putaran.

]],
  str_skill_desc_3002021 = "Di awal pertempuran, kurangi cooldown skill sebesar <color=#00F6FF>3</color>. Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>500%</color> kerusakan. Kemudian, buat Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setiap Pisau dari Dawn dijemput mengurangi cooldown skill oleh <color=#00F6FF>1</color>.",
  str_skill_desc_3032021 = "Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>500%</color> kerusakan. Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setiap Pisau dari Dawn dijemput mengurangi cooldown skill oleh <color=#00F6FF>1</color>.",
  str_skill_desc_3202021 = "Di awal pertempuran, kurangi cooldown skill <color=#00F6FF>3</color>. Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>500%</color> kerusakan, ditambah kerusakan tambahan itu <color=#00F6FF>4%</color> dari target <color=#00F6FF>maks</color> HP (dipengaruhi oleh penghitung elemen). Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setiap Pisau dari Dawn dijemput mengurangi cooldown skill oleh <color=#00F6FF>1</color>.",
  str_skill_desc_3232021 = "Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>500%</color> kerusakan, ditambah kerusakan tambahan itu <color=#00F6FF>4%</color> dari mereka <color=#00F6FF>maks</color> HP (dipengaruhi oleh penghitung elemen). Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setiap Pisau dari Dawn dijemput mengurangi cooldown skill oleh <color=#00F6FF>1</color>.",
  str_skill_desc_3402021 = "Di awal pertempuran, kurangi cooldown skill <color=#00F6FF>3</color>. Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>500%</color> kerusakan, ditambah kerusakan tambahan itu <color=#00F6FF>4%</color> dari target <color=#00F6FF>maks</color> HP (dipengaruhi oleh penghitung elemen). Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setiap Pisau dari Dawn diambil atau diambil mengurangi cooldown skill <color=#00F6FF>1</color>.",
  str_skill_desc_3432021 = "Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>500%</color> kerusakan, ditambah kerusakan tambahan itu <color=#00F6FF>4%</color> dari mereka <color=#00F6FF>maks</color> HP (dipengaruhi oleh penghitung elemen). Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setiap Pisau dari Dawn diambil atau diambil mengurangi cooldown skill <color=#00F6FF>1</color>.",
  str_skill_desc_3402022 = "Di awal pertempuran, kurangi cooldown skill <color=#00F6FF>3</color>. Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>650%</color> kerusakan, ditambah kerusakan tambahan itu <color=#00F6FF>4%</color> dari target <color=#00F6FF>maks</color> HP (dipengaruhi oleh penghitung elemen). Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setiap Pisau dari Dawn diambil atau diambil mengurangi cooldown skill <color=#00F6FF>1</color>.",
  str_skill_desc_3432022 = "Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>650%</color> kerusakan, ditambah kerusakan tambahan itu <color=#00F6FF>4%</color> dari mereka <color=#00F6FF>maks</color> HP (dipengaruhi oleh penghitung elemen). Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setiap Pisau dari Dawn diambil atau diambil mengurangi cooldown skill <color=#00F6FF>1</color>.",
  str_skill_desc_3402023 = "Di awal pertempuran, kurangi cooldown skill sebesar <color=#00F6FF>3</color>. Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>650%</color> kerusakan, ditambah kerusakan tambahan itu <color=#00F6FF>4%</color> dari target <color=#00F6FF>maks</color> HP (dipengaruhi oleh penghitung elemen). Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setelah membunuh target, menghasilkan 1 Blade tambahan Dawn di lokasi sasaran. Setiap Pisau dari Dawn diambil atau diambil mengurangi cooldown skill <color=#00F6FF>1</color>.",
  str_skill_desc_3432023 = "Memilih 1 ubin di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> di mana musuh berdiri dan berurusan <color=#00F6FF>650%</color> kerusakan, ditambah kerusakan tambahan itu <color=#00F6FF>4%</color> dari mereka <color=#00F6FF>maks</color> HP (dipengaruhi oleh penghitung elemen). Kemudian, menghasilkan Blade of Dawn pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak dalam 2 kelompok di sekitar ubin yang dipilih. Setelah membunuh target, menghasilkan 1 Blade tambahan Dawn di lokasi sasaran. Setiap Pisau dari Dawn diambil atau diambil mengurangi cooldown skill <color=#00F6FF>1</color>.",
  str_skill_desc_3302022 = "Memilih apa saja <color=#00F6FF>1</color> Pisau dari Dawn dan mengambilnya.",
  str_skill_desc_3362022 = "Memilih apa saja <color=#00F6FF>1</color> Pisau dari Dawn dan mengambilnya.",
  str_skill_passive_name_410202 = "Dimana Cahaya Bersinar",
  str_skill_passive_name_420202 = "Dimana Cahaya Bersinar",
  str_skill_passive_name_430202 = "Dimana Cahaya Bersinar",
  str_skill_passive_desc_410202 = "Untuk setiap Blade dari Dawn diambil, kumpulkan 1 tumpukan Ode to Ephemeral Night. Normal Attack berikutnya menghabiskan 1 tumpukan Ode hingga Ephemeral Night dan memberikan damage tambahan ke target yang setara dengan <color=#00F6FF>{1}</color> dari mereka <color=#00F6FF>saat ini</color> HP (kerusakan tambahan tidak kurang dari <color=#00F6FF>{2}</color> dan tidak lebih dari <color=#00F6FF>{3}</color> ATK dasar).",
  str_skill_passive_desc_420202 = "Untuk setiap Blade dari Dawn diambil, kumpulkan 1 tumpukan Ode to Ephemeral Night. Normal Attack berikutnya menghabiskan 1 stack Ode hingga Ephemeral Night dan memberikan damage tambahan ke target yang setara dengan <color=#00F6FF>{1}</color> dari mereka <color=#00F6FF>saat ini</color> HP (kerusakan tambahan tidak kurang dari <color=#00F6FF>{2}</color> dan tidak lebih dari <color=#00F6FF>{3}</color> ATK dasar).",
  str_skill_passive_desc_430202 = "Untuk setiap Blade dari Dawn diambil atau diambil, kumpulkan 1 stack Ode to Ephemeral Night. Normal Attack berikutnya menghabiskan 1 tumpukan Ode hingga Ephemeral Night dan memberikan damage tambahan ke target yang setara dengan <color=#00F6FF>{1}</color> dari mereka <color=#00F6FF>saat ini</color> HP (kerusakan tambahan tidak kurang dari <color=#00F6FF>{2}</color> dan tidak lebih dari <color=#00F6FF>{3}</color> ATK dasar).",
  str_skill_passive_desc_440202 = "Untuk setiap Blade dari Dawn diambil, kumpulkan 1 tumpukan Ode to Ephemeral Night. Normal Attack berikutnya menghabiskan 1 stack Ode hingga Ephemeral Night dan memberikan damage tambahan ke target yang setara dengan <color=#00F6FF>4%</color> dari <color=#00F6FF>saat ini</color> HP (kerusakan tambahan tidak kurang dari <color=#00F6FF>150%</color> dan tidak lebih dari <color=#00F6FF>600%</color> ATK dasar).",
  str_skill_upgrade_desc_16020213 = "Peningkatan Keterampilan Aktif: Perubahan <color=#FFFF00>Hari Tanpa Akhir</color> ke <color=#FFFF00>Serangan Preemptive</color>. Tersedia saat memasuki pertempuran.",
  str_skill_upgrade_desc_16020216 = "Peningkatan Skill Aktif: Mengurangi cooldown skill <color=#FFFF00>Kegelapan Hancur</color> oleh <color=#FFFF00>1</color> putaran (berlaku untuk Ascension III).",
  str_skill_upgrade_refine_desc_16020211 = "Peningkatan Keterampilan Peralatan: Meningkatkan batas kerusakan tambahan hingga <color=#00F6FF>600%</color> dari ATK.",
  str_skill_upgrade_refine_desc_16020212 = "Peningkatan Keterampilan Aktif: Meningkatkan kerusakan pada <color=#00F6FF>650%</color>.",
  str_skill_upgrade_refine_desc_16020213 = "Peningkatan Skill Aktif: Setelah membunuh target, menghasilkan 1 Blade tambahan Dawn di lokasi sasaran.",
  str_skill_upgrade_refine_desc_15007811 = "Peningkatan Keterampilan Peralatan: Untuk setiap 1 ubin Hijau di kaki musuh, bonus kerusakan bertambah <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15007812 = "Peningkatan Keterampilan Aktif: Memberikan kerusakan ganda pada petak di tengah jangkauan keterampilan.",
  str_skill_upgrade_refine_desc_15007813 = "Peningkatan Keterampilan Aktif: Jika Keterampilan Aktif sudah siap di babak terakhir, rentang pemilihan menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_passive_desc_4400781 = "Meningkatkan kerusakan Robyn terhadap musuh yang menempati ubin Hijau <color=#00F6FF>10%</color>. Untuk setiap ubin Hijau di kaki musuh, bonus kerusakan bertambah <color=#00F6FF>1%</color>. Juga memberikan rekan setim Forest Aurorian <color=#00F6FF>50%</color> dari bonus ini.",
  str_skill_name_3400782 = "Slithering Breath",
  str_skill_name_3420782 = "Slithering Breath",
  str_skill_name_3400783 = "Slithering Breath",
  str_skill_name_3420783 = "Slithering Breath",
  str_skill_desc_3400782 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih. Kerusakan yang diberikan pada petak tengah yang dipilih digandakan.",
  str_skill_desc_3420782 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih. Kerusakan yang diberikan pada ubin yang dipilih digandakan. Mengubah hingga 1 ubin di bawah musuh menjadi <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link>.",
  str_skill_desc_3400783 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih. Kerusakan yang diberikan pada petak tengah yang dipilih digandakan. Jika Skill Aktif ini sudah siap di ronde terakhir, rentang pilihannya menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_desc_3420783 = "Penawaran <color=#00F6FF>250%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih. Kerusakan yang diberikan pada ubin yang dipilih digandakan. Mengubah hingga 1 petak di bawah musuh menjadi <link=\"20001\"><#FFAE07><u>ubin yang disempurnakan</u></color></link>. Jika Skill Aktif ini sudah siap di ronde terakhir, rentang pilihannya menjadi <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_upgrade_refine_desc_15007511 = "Peningkatan Keterampilan Peralatan: Peluang serangan normal untuk menimbulkan Racun meningkat menjadi <color=#00F6FF>80%</color>.",
  str_skill_upgrade_refine_desc_15007512 = "Peningkatan Skill Aktif: Faktor kerusakan Skill Aktif meningkat menjadi <color=#00F6FF>500%</color>.",
  str_skill_upgrade_refine_desc_15007513 = "Peningkatan Skill Aktif: Cooldown Skill berkurang sebesar <color=#00F6FF>2</color> di awal setiap pertempuran.",
  str_skill_name_340075 = "Internal Struggle",
  str_skill_name_342075 = "Internal Struggle",
  str_skill_name_345075 = "Internal Struggle",
  str_skill_desc_340075 = "Memberikan 500% kerusakan pada musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> dan menimbulkan <link=\"10006\"><#FFAE07><u>Lambat</u></color></link> untuk 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Racun</u></color></link> untuk 2 putaran.",
  str_skill_desc_342075 = "Memberikan 500% kerusakan pada musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> dan menimbulkan <link=\"10006\"><#FFAE07><u>Lambat</u></color></link> untuk 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Racun</u></color></link> untuk 2 putaran.",
  str_skill_desc_345075 = "Memberikan 500% kerusakan pada <color=#00F6FF>semua</color> musuh dan menimbulkan <link=\"10006\"><#FFAE07><u>Lambat</u></color></link> untuk 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Racun</u></color></link> untuk 2 putaran.",
  str_skill_desc_350075 = "Memberikan 500% kerusakan pada musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> dan menimbulkan <link=\"10006\"><#FFAE07><u>Lambat</u></color></link> untuk 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Racun</u></color></link> untuk 2 putaran. Cooldown keterampilan <color=#00F6FF>-2</color> putaran di awal pertempuran.",
  str_skill_desc_352075 = "Memberikan 500% kerusakan pada musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color> dan menimbulkan <link=\"10006\"><#FFAE07><u>Lambat</u></color></link> untuk 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Racun</u></color></link> untuk 2 putaran. Cooldown keterampilan <color=#00F6FF>-2</color> putaran di awal pertempuran.",
  str_skill_desc_355075 = "Memberikan 500% kerusakan pada <color=#00F6FF>semua</color> musuh dan menimbulkan <link=\"10006\"><#FFAE07><u>Lambat</u></color></link> untuk 2 putaran dan 2 tumpukan <link=\"10001\"><#FFAE07><u>Racun</u></color></link> untuk 2 putaran. Cooldown keterampilan <color=#00F6FF>-2</color> putaran di awal pertempuran.",
  str_skill_passive_desc_440075 = "Serangan normal dapat menargetkan musuh <color=#00F6FF>ubin diagonal</color> dan memiliki <color=#00F6FF>80%</color> kemungkinan menimbulkan 1 tumpukan <link=\"10001\"><#FFAE07><u>Racun</u></color></link> untuk 2 putaran.",
