  str_skill_name_290540102 = "Joshua: Penghapusan",
  str_skill_desc_290540102 = "Bergerak ke arah Aurorian dan mengayunkan tombak untuk memberikan damage pada target di depan.",
  str_skill_name_290540103 = "Yosua: Pemusnahan",
  str_skill_desc_290540103 = "Anda dapat menyerap energi dari ubin yang cocok dengan elemen Phantom Crystal, mengatur ulang elemen ubin, dan menyerang semua target di lapangan. Semakin banyak energi yang diserap, semakin kuat kerusakannya.",
  str_skill_name_290540202 = "Joshua: Serangan Menghancurkan",
  str_skill_name_290540203 = "Joshua: Pemusnahan",
  str_skill_name_290540204 = "Joshua: Doa",
  str_skill_desc_290540202 = "Bergerak ke arah Aurorian dan memberikan kerusakan berat pada 2 ubin di depan.",
  str_skill_desc_290540203 = "Bergerak menuju tim, mengayunkan sebuah tombak, dan mengucapkan kutukan pada target di area depan. Ketika nilai kutukan melampaui HP target saat ini, mereka akan menderita kerusakan yang sangat besar.",
  str_skill_desc_290540204 = "Melepaskan serangan yang menghancurkan, menangani kerusakan medan penuh dan meningkatkan nilai kutukan; memanggil 2 Pengawal Lumo ke medan perang.",
  str_skill_desc_290540206 = "Melepaskan serangan yang menghancurkan, menangani kerusakan medan penuh dan meningkatkan nilai kutukan; memanggil 3 Pengawal Lumo ke medan pertempuran.",
  str_skill_name_200060601 = "Pelukan Gelap",
  str_skill_desc_200060601 = "Lurker menempel pada Penjaga Lumo dalam 1 cluster di sekitarnya, membuat mereka tidak pingsan dan meningkatkan kekuatan mereka.",
  str_skill_desc_29002111 = "Jika Kerikil kecil tidak dapat mengalahkan musuhnya, Umbrahulk akan mencoba menggabungkan semua Kerikil di lapangan untuk menghancurkan musuhnya.",
  str_skill_name_29001811 = "Penyembuhan Eclipsite",
  str_skill_name_29001821 = "Terapi Rohani",
  str_skill_name_29001411 = "Iblis Cair",
  str_skill_name_29001421 = "Serangan Api Neraka",
  str_skill_desc_29001811 = "Memanggil Shadowgeist yang memiliki kemampuan penyembuhan.",
  str_skill_desc_29001821 = "Kematian Shelt mengaktifkan kekuatan penyembuhan yang lebih kuat, memanggil 2 Shadowgeists yang memiliki kemampuan penyembuhan.",
  str_skill_desc_29001411 = "Memanggil Gloom Ghoul yang dapat melakukan serangan jarak jauh.",
  str_skill_desc_29001421 = "Kematian satu mengirim yang lain ke dalam kegilaan, yang kemudian menggunakan kekuatan penghancurannya untuk memanggil 2 Gloom Ghouls untuk menyerang musuh apa pun.",
