  str_skill_desc_2202042 = "Menyebabkan <color=#00F6FF>{1}%</color> damage pada 2 target terdekat. Jika hanya ada 1 target, damage akan ditingkatkan sebesar <color=#00F6FF>50%</color>.",
  str_skill_desc_2202043 = "Menyebabkan <color=#00F6FF>{1}%</color> damage pada 2 target terdekat. Jika hanya ada 1 target, damage akan ditingkatkan sebesar <color=#00F6FF>50%</color>.",
  str_skill_desc_2302041 = "Memberikan <color=#00F6FF>{1}%</color> damage kepada 2 target terdekat. Menyebabkan <color=#00F6FF>30%</color> lebih banyak damage pada target dalam 3 klaster di sekitar. Jika hanya ada 1 target, damage akan ditingkatkan sebesar <color=#00F6FF>50%</color>.",
  str_skill_desc_2302042 = "Memberikan <color=#00F6FF>{1}%</color> damage kepada 2 target terdekat. Menyebabkan <color=#00F6FF>30%</color> lebih banyak damage pada target dalam 3 klaster di sekitar. Jika hanya ada 1 target, damage akan ditingkatkan sebesar <color=#00F6FF>50%</color>.",
  str_skill_desc_2302043 = "Memberikan <color=#00F6FF>{1}%</color> damage kepada 2 target terdekat. Menyebabkan <color=#00F6FF>30%</color> lebih banyak damage pada target dalam 3 klaster di sekitar. Jika hanya ada 1 target, damage akan ditingkatkan sebesar <color=#00F6FF>50%</color>.",
  str_skill_desc_2502041 = "Penawaran <color=#00F6FF>140%</color> kerusakan pada 2 target terdekat. Menimbulkan <color=#00F6FF>30%</color> lebih banyak kerusakan pada target dalam 3 cluster di sekitarnya. Jika hanya ada 1 target, damage akan bertambah sebesar <color=#00F6FF>65%</color>.",
  str_skill_desc_2502042 = "Penawaran <color=#00F6FF>155%</color> kerusakan pada 2 target terdekat. Menimbulkan <color=#00F6FF>30%</color> lebih banyak kerusakan pada target dalam 3 cluster di sekitarnya. Jika hanya ada 1 target, damage akan bertambah <color=#00F6FF>65%</color>.",
  str_skill_desc_2502043 = "Penawaran <color=#00F6FF>170%</color> kerusakan pada 2 target terdekat. Menimbulkan <color=#00F6FF>30%</color> lebih banyak kerusakan pada target dalam 3 cluster di sekitarnya. Jika hanya ada 1 target, damage akan bertambah <color=#00F6FF>65%</color>.",
  str_skill_desc_3002041 = "Memilih target, menimbulkan <link=\"30083\"><#FFAE07><u>Kebijaksanaan Suci</u></color></link> dan Kebijaksanaan sebesar <color=#00F6FF>200% dari ATK Joshua</color>. Juga memberikan <color=#00F6FF>200%</color> kerusakan yang mengabaikan DEF pada target yang tidak memiliki HP Maks. Memilih target yang sama lagi akan meningkatkan Kebijaksanaan mereka. Ketika Kebijaksanaan target melebihi HP saat ini, mereka akan menerima kerusakan slash yang mengabaikan perisai (ketidakterkalahkan tetap berlaku).",
  str_skill_desc_3032041 = "Memilih target, menimbulkan <link=\"30083\"><#FFAE07><u>Kebijaksanaan Suci</u></color></link> dan Kebijaksanaan sebesar <color=#00F6FF>250% dari ATK Joshua</color>. Juga memberikan <color=#00F6FF>250%</color> kerusakan yang mengabaikan DEF pada target yang tidak memiliki HP Maks. Memilih target yang sama lagi akan meningkatkan Kebijaksanaan mereka. Ketika Kebijaksanaan target melebihi HP saat ini, mereka akan menerima kerusakan slash yang mengabaikan Shield (ketidakterkalahkan tetap berlaku).",
  str_skill_desc_3062041 = "Memilih target, memberikan <link=\"30083\"><#FFAE07><u>Kebijaksanaan Suci</u></color></link> dan Kebijaksanaan sebesar <color=#00F6FF>250% dari ATK Joshua + 3% dari HP Maks target</color> (tidak kurang dari <color=#00F6FF>120%</color> dari ATK Joshua). Juga memberikan damage mengabaikan DEF sebesar <color=#00F6FF>370%</color> pada target yang tidak memiliki HP Maks. Memilih target yang sama lagi akan meningkatkan Kebijaksanaan mereka. Ketika Kebijaksanaan target melebihi HP saat ini, mereka akan menerima damage slash mengabaikan Shield (ketidakterkalahkan tetap berlaku).",
  str_skill_passive_desc_4102041 = "Joshua memberikan <color=#00F6FF>{1}</color> damage kepada musuh dalam keadaan <link=\"30083\"><#FFAE07><u>Kebijaksanaan Suci</u></color></link>, mengabaikan semua perisai, dan mengubah semua damage yang diberikan menjadi poin Kebijaksanaan.",
  str_skill_upgrade_refine_desc_16020411 = "Peningkatan Keahlian Perlengkapan: Meningkatkan semua kerusakan yang diberikan kepada target dalam keadaan Kebijaksanaan Suci <color=#00F6FF>124%</color>.",
  str_skill_upgrade_refine_desc_16020412 = "Peningkatan Kombo Rantai: Saat hanya ada 1 target, tingkatkan kerusakan sebesar <color=#00F6FF>65%</color>.",
  str_skill_upgrade_refine_desc_16020413 = "Peningkatan Keahlian Aktif: Segarkan kembali cooldown keahlian secara langsung setelah kematian target dalam status Kebijaksanaan Suci.",
  str_skill_desc_3502041 = "Memilih target, memberikan <link=\"30083\"><#FFAE07><u>Kebijaksanaan Suci</u></color></link> dan Kebijaksanaan sebesar <color=#00F6FF>200% dari ATK Joshua</color>. Juga memberikan <color=#00F6FF>200%</color> damage yang mengabaikan DEF pada target yang tidak memiliki HP Maks. Memilih target yang sama lagi akan meningkatkan Kebijaksanaan mereka. Ketika Kebijaksanaan target melebihi HP saat ini, mereka akan menerima damage slash yang mengabaikan perisai (ketahanan masih berlaku). Segera menyegarkan cooldown Active Skill saat kematian target dalam keadaan Kebijaksanaan Suci.",
  str_skill_desc_3532041 = "Memilih target, memberikan <link=\"30083\"><#FFAE07><u>Kebijaksanaan Suci</u></color></link> dan Kebijaksanaan sebesar <color=#00F6FF>250% dari ATK Joshua</color>. Juga memberikan damage mengabaikan DEF sebesar <color=#00F6FF>250%</color> pada target yang tidak memiliki HP Maks. Memilih target yang sama lagi akan meningkatkan Kebijaksanaan mereka. Ketika Kebijaksanaan target melebihi HP saat ini, mereka akan menerima damage slash yang mengabaikan Shield (ketidakterkalahkan tetap berlaku). Segera menyegarkan cooldown Active Skill saat kematian target dalam keadaan Kebijaksanaan Suci.",
  str_skill_desc_3562041 = "Memilih target, memberikan <link=\"30083\"><#FFAE07><u>Kebijaksanaan Suci</u></color></link> dan Kebijaksanaan sebesar <color=#00F6FF>250% dari ATK Joshua + 3% dari HP Maks target</color> (tidak kurang dari <color=#00F6FF>120%</color> dari ATK Joshua). Juga memberikan damage mengabaikan DEF sebesar <color=#00F6FF>370%</color> pada target yang tidak memiliki HP Maks. Memilih target yang sama lagi akan meningkatkan Kebijaksanaan mereka. Ketika Kebijaksanaan target melebihi HP saat ini, mereka akan menerima damage slash yang mengabaikan Shield (ketidakterkalahkan tetap berlaku). Segera menyegarkan cooldown Skill Aktif saat kematian target dalam keadaan Kebijaksanaan Suci.",
  str_skill_passive_desc_4502041 = "Joshua memberikan <color=#00F6FF>124%</color> damage kepada musuh dalam keadaan <link=\"30083\"><#FFAE07><u>Kebijaksanaan Suci</u></color></link>, mengabaikan semua perisai, dan mengubah semua damage yang diberikan menjadi poin Kebijaksanaan.",
