  str_skill_desc_3052051 = "Pilih 1 tile tidak rusak dan ubah menjadi tile rusak yang bertahan selama 9 ronde, lalu ubah <color=#00F6FF>4 tile dalam bentuk silang</color> menjadi tile Biru.",
  str_skill_passive_name_410205 = "Salam Menyenangkan",
  str_skill_passive_name_430205 = "Salam Menyenangkan",
  str_skill_passive_desc_410205 = "Blanc: Pura Cordis tidak melakukan serangan normal saat berada di Tile Biru. Setiap kali dia melewati 1 Tile Biru, dia mendapatkan 1 tumpukan Hospitality jika ada musuh dalam jarak <color=#00F6FF>4 tile dalam bentuk silang</color>. Setiap tumpukan Hospitality meningkatkan tingkat damage Chain Combo sebesar <color=#00F6FF>{1}</color> dan mengurangi kondisi pemicu Chain Combo sebesar <color=#00F6FF>1</color>. Semua tumpukan dihapus setelah dia menggunakan Chain Combo.",
  str_skill_passive_desc_430205 = "Blanc: Pura Cordis tidak melakukan serangan normal saat berada di Tile Biru. Setiap kali dia melewati 1 Tile Biru, dia mendapatkan 1 tumpukan Hospitality jika ada musuh atau tile rusak dalam jarak <color=#00F6FF>4 tile dalam bentuk salib</color>. Setiap tumpukan Hospitality meningkatkan tingkat damage Chain Combo sebesar <color=#00F6FF>{1}</color> dan mengurangi kondisi pemicu Chain Combo sebesar <color=#00F6FF>1</color>. Semua tumpukan dihapus setelah dia menggunakan Chain Combo.",
  str_skill_upgrade_desc_15020512 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_15020515 = "Peningkatan Combo Rantai: Durasi ubin yang rusak dalam jangkauan Combo Rantai berkurang <color=#FFFF00>2/3/4</color> putaran (berlaku untuk Ascension II).",
  str_skill_passive_desc_440097 = "Serangan normal menjadi serangan 2-kombo yang menangani <color=#00F6FF>60%</color> dari kerusakan dasar setiap serangan. Setiap serangan memiliki a <color=#00F6FF>20%</color> kesempatan untuk berurusan <color=#00F6FF>50%</color> kerusakan ekstra. Setiap kombo meningkatkan peluang pemicu <color=#00F6FF>1%</color>, hingga 50%.",
  str_skill_name_3400971 = "Varian Frigid Debone I",
  str_skill_name_3400972 = "Varian Debone Dingin II",
  str_skill_name_3420971 = "Varian Frigid Debone I",
  str_skill_name_3420972 = "Varian Debone Dingin II",
  str_skill_desc_3400971 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Teleportasi ke lokasi mana pun dan memberikan kerusakan pada musuh dalam bentuk persegi panjang antara titik awal dan tujuan. Semakin kecil areanya, semakin tinggi damage yang diberikan, hingga <color=#00F6FF>600%</color> kerusakan.",
  str_skill_desc_3400972 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Teleportasi ke lokasi mana pun di dalamnya <color=#FFFF00>3 cluster sekitarnya</color> dan memberikan kerusakan pada musuh dalam bentuk persegi panjang antara titik awal dan tujuan. Semakin kecil areanya, semakin tinggi damage yang diberikan, hingga <color=#00F6FF>360%</color> kerusakan.",
  str_skill_desc_3420971 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Teleportasi ke lokasi mana pun dan memberikan kerusakan pada musuh dalam bentuk persegi panjang antara titik awal dan tujuan. Semakin kecil areanya, semakin tinggi damage yang diberikan, hingga <color=#00F6FF>720%</color> kerusakan.",
  str_skill_desc_3420972 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Teleportasi ke lokasi mana pun di dalamnya <color=#FFFF00>3 cluster sekitarnya</color> dan memberikan kerusakan pada musuh dalam bentuk persegi panjang antara titik awal dan tujuan. Semakin kecil areanya, semakin tinggi damage yang diberikan, hingga <color=#00F6FF>480%</color> kerusakan.",
  str_skill_upgrade_refine_desc_15009711 = "<color=#00F6FF>Varian Skill Aktif Baru I</color>: <color=#FFFF00>Cooldown skill +1 setelah casting</color>. Teleportasi ke lokasi mana pun dan memberikan kerusakan pada musuh dalam bentuk persegi panjang antara titik awal dan tujuan. Semakin kecil areanya, semakin tinggi damage yang diberikan. Kerusakan Skill Aktif meningkat sebesar <color=#FFFF00>120%</color>.",
  str_skill_upgrade_refine_desc_15009712 = "Peningkatan Keterampilan Peralatan: Setiap kombo meningkatkan peluang untuk memicu kerusakan tambahan <color=#00F6FF>1%</color>, hingga 50%.",
  str_skill_upgrade_refine_desc_15009713 = "<color=#00F6FF>Varian Skill Aktif Baru II</color>: <color=#FFFF00>Cooldown skill -1 setelah casting</color>. Teleportasi ke lokasi mana pun di dalamnya <color=#FFFF00>3 cluster sekitarnya</color> dan memberikan kerusakan pada musuh dalam bentuk persegi panjang antara titik awal dan tujuan. Semakin kecil areanya, semakin tinggi damage yang diberikan. Damage Skill Aktif berkurang sebesar <color=#FFFF00>120%</color>.",
  str_skill_upgrade_refine_desc_16002711 = "Peningkatan Skill Aktif: Faktor kerusakan Skill Aktif meningkat menjadi <color=#00F6FF>360%</color>.",
  str_skill_upgrade_refine_desc_16002712 = "Peningkatan Keterampilan Peralatan: Keuntungan <color=#00F6FF>2</color> tumpukan Tanda Guntur Diam saat menggunakan Skill Aktif.",
  str_skill_upgrade_refine_desc_16002713 = "Peningkatan Keterampilan Peralatan: Serangan Normal menghabiskan 1 tumpukan Tanda Guntur Senyap untuk memberikan kerusakan ekstra yang setara <color=#00F6FF>2,5%</color> dari HP saat ini ke musuh. Kerusakan ini tidak akan lebih rendah dari <color=#00F6FF>50%</color> dari ATK Michael.",
  str_skill_desc_3400271 = "Berlari ke lokasi yang dipilih, bertransaksi <color=#00F6FF>360%</color> kerusakan, dan kerusakan ekstra sama dengan <color=#00F6FF>5%</color> dari HP mereka saat ini ke musuh di sepanjang jalan dan di petak yang berdekatan.",
  str_skill_desc_3430271 = "Dash ke lokasi yang dipilih, bertransaksi <color=#00F6FF>360%</color> kerusakan, dan kerusakan ekstra sama dengan <color=#00F6FF>5%</color> dari HP mereka saat ini ke musuh di sepanjang jalan dan pada petak yang berdekatan, dan kemudian secara instan melemparkan Combo Rantai satu kali di lokasi yang dipilih sesuai dengan jarak yang ditempuh.",
  str_skill_desc_3400272 = "Berlari ke lokasi yang dipilih, bertransaksi <color=#00F6FF>360%</color> kerusakan, dan kerusakan ekstra sama dengan <color=#00F6FF>5%</color> dari HP mereka saat ini ke musuh di sepanjang jalan dan di petak yang berdekatan.",
  str_skill_desc_3430272 = "Dash ke lokasi yang dipilih, bertransaksi <color=#00F6FF>360%</color> kerusakan, dan kerusakan ekstra sama dengan <color=#00F6FF>5%</color> dari HP mereka saat ini ke musuh di sepanjang jalan dan pada petak yang berdekatan, dan kemudian secara instan melemparkan Combo Rantai satu kali di lokasi yang dipilih sesuai dengan jarak yang ditempuh.",
  str_skill_desc_4400271 = "Memberikan 1 tumpukan Tanda Guntur Senyap di awal tiap ronde dan saat menggunakan Kombo Rantai, dan 2 tumpukan Tanda Guntur Senyap saat menggunakan Skill Aktif. Serangan Normal menghabiskan 1 tumpukan Tanda Guntur Senyap untuk memberikan kerusakan ekstra yang setara dengan <color=#00F6FF>2,5%</color> dari HP saat ini ke musuh.",
  str_skill_desc_440027 = "Memberikan 1 tumpukan Tanda Guntur Senyap di awal tiap ronde dan saat menggunakan Kombo Rantai, dan 2 tumpukan Tanda Guntur Senyap saat menggunakan Skill Aktif. Serangan Normal menghabiskan 1 tumpukan Tanda Guntur Senyap untuk memberikan kerusakan ekstra yang setara dengan <color=#00F6FF>2,5%</color> dari HP saat ini ke musuh. Kerusakan ini tidak akan lebih rendah dari <color=#00F6FF>50%</color> dari ATK Michael.",
  str_skill_name_490250101 = "Ditinggalkan: Restorasi Phantom",
  str_skill_desc_490250101 = "Terlupakan: Minos menyerap ubin yang ditingkatkan dan ubin yang dilemahkan dalam 2 klaster di sekitar, kemudian memberikan damage pada target dalam 1 klaster di sekitar. Damage serangan ini ditingkatkan berdasarkan jumlah ubin yang diserap.",
  str_skill_name_490250102 = "Ditinggalkan: Final Immolation",
  str_skill_desc_490250102 = "Terlupakan: Minos menyerap semua tile yang ditingkatkan dan dilemahkan di papan, kemudian memberikan damage kepada Aurorian. Minos memberikan damage 1 kali ekstra untuk setiap tile yang diserap.",
  str_skill_name_490250103 = "Ditinggalkan: Restorasi Phantom+",
  str_skill_desc_490250103 = "Terlupakan: Minos menyerap ubin yang ditingkatkan dan ubin yang dilemahkan dalam 2 klaster di sekitar, kemudian memberikan damage pada target dalam 1 klaster di sekitar. Damage serangan ini ditingkatkan berdasarkan jumlah ubin yang diserap.",
  str_skill_name_490250104 = "Ditinggalkan: Immolation Finale+",
  str_skill_desc_490250104 = "Terlupakan: Minos menyerap semua tile yang ditingkatkan dan dilemahkan di papan, kemudian memberikan damage kepada Aurorian. Minos memberikan damage 1 kali ekstra untuk setiap tile yang diserap.",
  str_skill_upgrade_refine_desc_16002811 = "Peningkatan Keterampilan Peralatan: Meningkatkan faktor pemulihan menjadi <color=#00F6FF>1,8%</color>.",
  str_skill_upgrade_refine_desc_16002812 = "Peningkatan Keterampilan Aktif: Meningkatkan faktor pemulihan menjadi <color=#00F6FF>250%</color>.",
  str_skill_upgrade_refine_desc_16002813 = "Peningkatan Keterampilan Aktif: Semakin rendah HP tim, semakin tinggi efektivitas penyembuhan, hingga tambahan <color=#00F6FF>bonus 100%.</color>.",
  str_skill_passive_desc_450028 = "Setiap ubin Biru yang dibuat di peta memulihkan HP tim sebesar <color=#00F6FF>1,8%</color> dari HP Raphael. Semakin rendah HP tim, semakin tinggi efektivitas penyembuhan, hingga tambahan <color=#00F6FF>bonus 100%.</color>.",
  str_skill_desc_350028 = "Memulihkan HP tim dengan <color=#00F6FF>250%</color> dari ATK Raphael. Mereset <color=#00F6FF>semua non-Biru</color> ubin.",
  str_skill_desc_356028 = "Memulihkan HP tim dengan <color=#00F6FF>250%</color> dari ATK Raphael. Mereset <color=#00F6FF>semua non-Biru</color> ubin, dan memiliki <color=#00F6FF>kesempatan kecil</color> untuk menghasilkan ubin Biru.",
  str_skill_desc_360028 = "Memulihkan HP tim dengan <color=#00F6FF>250%</color> dari ATK Raphael. Mereset <color=#00F6FF>semua non-Biru</color> ubin. Semakin rendah HP tim, semakin tinggi efektivitas penyembuhan, hingga tambahan <color=#00F6FF>bonus 100%.</color>.",
  str_skill_desc_366028 = "Memulihkan HP tim dengan <color=#00F6FF>250%</color> dari ATK Raphael. Mereset <color=#00F6FF>semua non-Biru</color> ubin, dengan a <color=#00F6FF>kesempatan kecil</color> untuk menghasilkan ubin Biru. Semakin rendah HP tim, semakin tinggi efektivitas penyembuhan, hingga tambahan <color=#00F6FF>bonus 100%.</color>.",
  str_skill_upgrade_refine_desc_15007011 = "Peningkatan Keterampilan Aktif: Meningkatkan faktor kerusakan ke <color=#00F6FF>100%</color>.",
  str_skill_upgrade_refine_desc_15007012 = "Peningkatan Keterampilan Peralatan: Meningkatkan faktor kerusakan <color=#00F6FF>60%</color>.",
  str_skill_upgrade_refine_desc_15007013 = "Peningkatan Keterampilan Aktif: Saat memberikan kerusakan, ada a <color=#00F6FF>25%</color> kesempatan untuk menimbulkan 1 tumpukan <link=\"10002\"><#FFAE07><u>Membakar</u></color></link>.",
  str_skill_desc_350070 = "Penawaran <color=#00F6FF>100%</color> kerusakan <color=#00F6FF>5</color> kali untuk acak musuh di lapangan. Meluncurkan 1 serangan tambahan untuk setiap ubin Merah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> unit.",
  str_skill_desc_355070 = "Penawaran <color=#00F6FF>100%</color> kerusakan <color=#00F6FF>6</color> kali untuk acak musuh di lapangan. Meluncurkan 1 serangan tambahan untuk setiap ubin Merah di dalamnya <color=#00F6FF>12 ubin yang berdekatan</color>.",
  str_skill_desc_360070 = "Penawaran <color=#00F6FF>100%</color> kerusakan <color=#00F6FF>5</color> kali untuk acak musuh di lapangan. Meluncurkan 1 serangan tambahan untuk setiap ubin Merah di dalamnya <color=#00F6FF>1 cluster sekitarnya</color> unit. Saat menangani kerusakan, ada a <color=#00F6FF>25%</color> kesempatan untuk menimbulkan 1 tumpukan <link=\"10002\"><#FFAE07><u>Membakar</u></color></link>.",
  str_skill_desc_365070 = "Penawaran <color=#00F6FF>100%</color> kerusakan <color=#00F6FF>6</color> kali untuk musuh acak di lapangan. Meluncurkan 1 serangan tambahan untuk setiap ubin Merah di dalamnya <color=#00F6FF>12 ubin yang berdekatan</color>. Saat menangani kerusakan, ada a <color=#00F6FF>25%</color> kesempatan untuk menimbulkan 1 tumpukan <link=\"10002\"><#FFAE07><u>Membakar</u></color></link>.",
  str_skill_passive_desc_450070 = "Serangan Normal memiliki a <color=#00F6FF>75%</color> kesempatan untuk memicu 1 Red Dragon Attack yang memberikan damage setara dengan <color=#00F6FF>60%</color> kerusakan Serangan Normal Leona, dan menimbulkan 1 tumpukan <link=\"10002\"><#FFAE07><u>Membakar</u></color></link> untuk 2 putaran.",
  str_skill_desc_400140110 = "Saat Aurorian mulai bergerak, Tentaclaw meringkuk untuk menghindari serangan dan memulihkan HP untuk Mirren Gautier.",
  str_skill_upgrade_desc_16020713 = "Peningkatan Kemampuan Peralatan: Mengurangi jumlah tumpukan Ripple yang diperlukan untuk memicu efek menjadi 5. Mengurangi jumlah tumpukan Ripple yang dikonsumsi menjadi kelipatan 5 tumpukan. (Berlaku untuk Kenaikan Tingkat I)",
  str_skill_upgrade_desc_16020716 = "Peningkatan Keterampilan Aktif: Mengubah tile yang dipilih menjadi biru.",
  str_skill_name_2002071 = "Manis Pahit",
  str_skill_name_2002072 = "Manis Pahit",
  str_skill_name_2002073 = "Manis Pahit",
  str_skill_desc_2002071 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_2002072 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2002073 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color>.",
  str_skill_name_3002071 = "Tarian Mimpi yang Terbangun",
  str_skill_name_3062071 = "Tarian Mimpi yang Terbangun",
  str_skill_name_3202071 = "Tarian Mimpi yang Terbangun",
  str_skill_name_3262071 = "Tarian Mimpi yang Terbangun",
  str_skill_name_3302071 = "Tarian Mimpi yang Terbangun",
  str_skill_name_3362071 = "Tarian Mimpi yang Terbangun",
  str_skill_desc_3002071 = "Memilih 1 tile dan membuat semua tile biru dalam kolom yang sama <link=\"30084\"><#FFAE07><u>berkumpul</u></color></link> menuju tile yang dipilih.",
  str_skill_desc_3062071 = "Memilih 1 ubin dan mengubah ubin ini menjadi biru, lalu membuat semua ubin biru dalam kolom yang sama <link=\"30084\"><#FFAE07><u>berkumpul</u></color></link> menuju ubin yang dipilih.",
  str_skill_desc_3202071 = "Memilih 1 ubin dan membuat semua ubin biru dalam kolom yang sama <link=\"30084\"><#FFAE07><u>berkumpul</u></color></link> menuju ubin yang dipilih. Mengetuknya lagi akan membuat efek bergantian antara <color=#00F6FF>baris/kolom</color>.",
  str_skill_desc_3262071 = "Memilih 1 ubin dan mengubah ubin ini menjadi biru, lalu membuat semua ubin biru dalam kolom yang sama <link=\"30084\"><#FFAE07><u>berkumpul</u></color></link> menuju ubin yang dipilih. Mengetuknya lagi akan membuat efek bergantian antara <color=#00F6FF>baris/kolom</color>.",
  str_skill_desc_3302071 = "Memilih 1 ubin dan membuat semua ubin biru dalam kolom yang sama <link=\"30084\"><#FFAE07><u>berkumpul</u></color></link> menuju ubin yang dipilih. Mengetuknya lagi akan membuat efek bergantian antara <color=#00F6FF>baris/kolom</color>. Mendapatkan 1 tumpukan Ripple untuk setiap 1 ubin biru dalam jangkauan Active Skill.",
  str_skill_desc_3362071 = "Memilih 1 tile dan mengubah tile ini menjadi biru, lalu membuat semua tile biru dalam kolom yang sama <link=\"30084\"><#FFAE07><u>berkumpul</u></color></link> menuju tile yang dipilih. Mengetuknya lagi akan membuat efek bergantian antara <color=#00F6FF>baris/kolom</color>. Mendapatkan 1 tumpukan Ripple untuk setiap 1 tile biru dalam jangkauan Active Skill.",
  str_skill_passive_name_410207 = "Dari Dawn Hingga Senja",
  str_skill_passive_desc_410207 = "Cena mendapatkan 1 stack <link=\"30085\"><#FFAE07><u>Ripple</u></color></link> saat Aurorian dalam tim mengeluarkan Skill Aktif untuk pertama kalinya dalam ronde tersebut. Jika Cena sudah memiliki 7 tumpukan Ripple atau lebih saat mendapatkan tumpukan, tumpukan tersebut akan dikonsumsi untuk memulihkan HP setara dengan <color=#00F6FF>{1}</color> HP Maks Cena.",
  str_skill_passive_name_416207 = "Dari Dawn Hingga Senja",
  str_skill_passive_desc_416207 = "Cena mendapatkan 1 tumpukan <link=\"30086\"><#FFAE07><u>Ripple</u></color></link> saat Aurorian dalam tim menggunakan Active Skill untuk pertama kalinya dalam putaran. Jika Cena sudah memiliki 5 atau lebih tumpukan Ripple saat mendapatkan tumpukan, sebagian akan dikonsumsi untuk memulihkan HP sebesar <color=#00F6FF>{1}</color> dari HP Maks Cena.",
  str_skill_desc_350025 = "Menyebabkan <color=#00F6FF>300%</color> kerusakan pada <color=#00F6FF>3 kolom terpilih</color> atau <color=#00F6FF>3 baris terpilih</color> dan mendorong musuh ke belakang. Kerusakan yang diberikan pada baris atau kolom tengah akan 1,7 kali kerusakan yang diberikan pada kedua sisi. Mengatur ulang semua ubin <color=#00F6FF>non-Merah</color> dalam area serangan.",
  str_skill_desc_356025 = "Memberikan <color=#00F6FF>300%</color> kerusakan pada <color=#00F6FF>3 kolom terpilih</color> atau <color=#00F6FF>3 baris terpilih</color> dan mendorong musuh ke belakang. Kerusakan yang diberikan pada baris atau kolom tengah akan 1,7 kali kerusakan yang diberikan pada kedua sisi. Mengatur ulang semua ubin <color=#00F6FF>non-Merah</color> dalam area serangan, dan memiliki <color=#00F6FF>kesempatan kecil</color> untuk menghasilkan ubin Merah.",
  str_skill_desc_360025 = "Menyebabkan <color=#00F6FF>340%</color> kerusakan pada <color=#00F6FF>3 kolom terpilih</color> atau <color=#00F6FF>3 baris terpilih</color> dan mendorong musuh ke belakang. Kerusakan yang diberikan pada baris atau kolom tengah akan 1,7 kali kerusakan yang diberikan pada kedua sisi. Mengatur ulang semua ubin <color=#00F6FF>non-Merah</color> dalam area serangan.",
  str_skill_desc_366025 = "Memberikan <color=#00F6FF>340%</color> kerusakan pada <color=#00F6FF>3 kolom terpilih</color> atau <color=#00F6FF>3 baris terpilih</color> dan mendorong musuh ke belakang. Kerusakan yang diberikan pada baris atau kolom tengah akan 1,7 kali kerusakan yang diberikan pada kedua sisi. Mengatur ulang semua ubin <color=#00F6FF>non-Merah</color> dalam area serangan, dan memiliki <color=#00F6FF>kesempatan kecil</color> untuk menghasilkan ubin Merah.",
  str_skill_passive_desc_440025 = "Serangan normal <color=#00F6FF>kini dapat menyerang secara diagonal</color>. Serangan normal memberikan tambahan kerusakan yang mengabaikan DEF sebesar <color=#00F6FF>12%</color> dari ATK.",
  str_skill_upgrade_refine_desc_16002511 = "Peningkatan Kemampuan Peralatan: Meningkatkan faktor kerusakan menjadi <color=#00F6FF>12%</color>.",
  str_skill_upgrade_refine_desc_16002512 = "Peningkatan Kemampuan Aktif: Memberikan <color=#00F6FF>1,7 kali</color> kerusakan pada baris atau kolom tengah.",
  str_skill_upgrade_refine_desc_16002513 = "Peningkatan Keterampilan Aktif: Meningkatkan faktor kerusakan menjadi <color=#00F6FF>340%</color>.",
