  str_skill_desc_2002062 = "Memberikan <color=#00F6FF>{1}%</color> damage ke <color=#00F6FF>1 klaster di sekitar</color> dan ubin Merah <color=#00F6FF>yang meluas ke luar dalam bentuk silang</color>.",
  str_skill_desc_2002063 = "Memberikan <color=#00F6FF>{1}%</color> damage ke <color=#00F6FF>1 klaster di sekitar</color> dan ubin Merah <color=#00F6FF>yang meluas ke 8 arah</color>.",
