  str_skill_desc_32020622 = "Dapatkan Kemampuan Aktif Baru: Preemptive Strike. Memilih 1 ubin dalam bentuk <color=#00F6FF>salib</color> dan mengubahnya menjadi merah, memberikan <color=#00F6FF>{1}%</color> kerusakan dan menghancurkan ubin pada saat yang sama. Semakin rendah HP saat ini dari target, semakin besar kerusakan yang diberikan, meningkat hingga <color=#00F6FF>250%</color>.",
  str_skill_desc_32020623 = "Dapatkan Kemampuan Aktif Baru: Preemptive Strike. Memilih 1 ubin dalam bentuk <color=#00F6FF>salib</color> dan mengubahnya menjadi merah, memberikan <color=#00F6FF>{1}%</color> kerusakan dan menghancurkan ubin pada saat yang sama. Semakin rendah HP saat ini dari target, semakin besar kerusakan yang diberikan, meningkat hingga <color=#00F6FF>250%</color>.",
  str_skill_desc_32020624 = "Dapatkan Kemampuan Aktif Baru: Preemptive Strike. Memilih 1 ubin dalam bentuk <color=#00F6FF>salib</color> dan mengubahnya menjadi merah, memberikan <color=#00F6FF>{1}%</color> kerusakan dan menghancurkan ubin pada saat yang sama. Semakin rendah HP saat ini dari target, semakin besar kerusakan yang diberikan, meningkat hingga <color=#00F6FF>250%</color>.",
  str_skill_desc_3302062 = "Dapatkan Active Skill Baru: Preemptive Strike. Memilih 1 tile di <color=#00F6FF>1 klaster di sekitar</color> dan mengubahnya menjadi merah, memberikan <color=#00F6FF>{1}%</color> kerusakan dan menghancurkan tile pada saat yang sama. Semakin rendah HP target saat ini, semakin besar kerusakan yang diberikan, meningkat hingga <color=#00F6FF>250%</color>.",
  str_skill_desc_33020622 = "Dapatkan Active Skill Baru: Preemptive Strike. Memilih 1 tile di <color=#00F6FF>1 klaster di sekitar</color> dan mengubahnya menjadi merah, memberikan <color=#00F6FF>{1}%</color> kerusakan dan menghancurkan tile pada saat yang sama. Semakin rendah HP target saat ini, semakin besar kerusakan yang diberikan, meningkat hingga <color=#00F6FF>250%</color>.",
  str_skill_desc_33020623 = "Dapatkan Active Skill Baru: Preemptive Strike. Memilih 1 tile di <color=#00F6FF>1 klaster di sekitar</color> dan mengubahnya menjadi merah, memberikan <color=#00F6FF>{1}%</color> kerusakan dan menghancurkan tile pada saat yang sama. Semakin rendah HP target saat ini, semakin besar kerusakan yang diberikan, meningkat hingga <color=#00F6FF>250%</color>.",
  str_skill_desc_33020624 = "Dapatkan Active Skill Baru: Preemptive Strike. Memilih 1 tile di <color=#00F6FF>1 klaster di sekitar</color> dan mengubahnya menjadi merah, memberikan <color=#00F6FF>{1}%</color> kerusakan dan menghancurkan tile pada saat yang sama. Semakin rendah HP target saat ini, semakin besar kerusakan yang diberikan, meningkat hingga <color=#00F6FF>250%</color>.",
