  str_skill_upgrade_refine_desc_15002413 = "Peningkatan Kombo Rantai: Pada ronde di mana Active Skill diaktifkan, mengurangi jumlah tile pemicu combo sebanyak <color=#00F6FF>1</color>.",
  str_skill_passive_desc_440024 = "Serangan normal memberikan tambahan <color=#00F6FF>65%</color> damage pada musuh yang berada di kotak Merah.",
  str_skill_desc_340024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>1,5</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, melemparkan Chain Combo sekali lagi di lokasi yang ditandai (meningkatkan damage final dari kedua Chain Combo sebesar <color=#00F6FF>35%</color>).",
  str_skill_desc_342024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>1,5</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, melemparkan Chain Combo sekali lagi di lokasi yang ditandai (meningkatkan damage final dari kedua Chain Combo sebesar <color=#00F6FF>35%</color>).",
  str_skill_desc_345024 = "Menandai 1 tile. Ketika jumlah tile yang terhubung mencapai <color=#00F6FF>1,5</color> kali jumlah tile yang diperlukan untuk memicu Chain Combo, melemparkan Chain Combo sekali lagi di lokasi yang ditandai (meningkatkan damage final dari kedua Chain Combo sebesar <color=#00F6FF>35%</color>).",
  str_skill_desc_240241 = "Memberikan <color=#00F6FF>140%</color> kerusakan pada <color=#00F6FF>1 klaster di sekitar</color>. Pada ronde di mana Active Skill diaktifkan, mengurangi jumlah ubin pemicu combo sebanyak <color=#00F6FF>1</color>.",
  str_skill_desc_240242 = "Memberikan <color=#00F6FF>145%</color> kerusakan ke <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Pada ronde di mana Active Skill diaktifkan, mengurangi jumlah ubin pemicu combo sebanyak <color=#00F6FF>1</color>.",
  str_skill_desc_240243 = "Memberikan <color=#00F6FF>155%</color> kerusakan ke <color=#00F6FF>16 ubin dalam bentuk lingkaran</color>. Pada ronde di mana Active Skill diaktifkan, mengurangi jumlah ubin pemicu combo sebanyak <color=#00F6FF>1</color>.",
  str_skill_name_290560101 = "Dewi Denuo - Duri Anggur",
  str_skill_desc_290560101 = "Bergerak menuju Aurorian dan memberikan kerusakan pada target dalam baris atau kolom di depan.",
  str_skill_name_290560102 = "Dewi Denuo - Penyerbukan",
  str_skill_desc_290560102 = "Bergerak menuju Aurorian dan memberikan kerusakan pada semua target dalam 12 ubin sekitar dalam bentuk berlian sambil menimbulkan racun dan mengkatalis pertumbuhan tanaman di sekitar.",
  str_skill_name_290560103 = "Dewi Denuo - Meledak",
  str_skill_desc_290560103 = "Menargetkan Aurorian dan memberikan kerusakan pada semua target dalam 12 ubin dalam bentuk berlian di sekitar Aurorian sambil menimbulkan racun dan mengkatalis pertumbuhan tanaman dalam jangkauan (tidak bisa meleset).",
  str_skill_name_200260101 = "Sadesian Enchantweed - Dormant",
  str_skill_desc_200260101 = "Dalam bentuk juvenilnya, Sadesian Enchantweed kebal terhadap serangan dari Aurorian.",
  str_skill_name_200260201 = "Sadesian Enchantweed - Pertumbuhan",
  str_skill_desc_200260201 = "Dalam tahap metamorfosisnya, Sadesian Enchantweed dapat diserang oleh Aurorian, tetapi tidak memiliki kemampuan untuk melakukan serangan balik.",
  str_skill_name_200260301 = "Sadesian Enchantweed - Sengat",
  str_skill_desc_200260301 = "Menarget Aurorian dan memberikan kerusakan sambil menimbulkan racun.",
  str_skill_name_53310002 = "Dewi Denuo - Penyerbukan",
  str_skill_desc_53310002 = "Mengkatalis pertumbuhan tanaman di 12 ubin sekitarnya dalam bentuk berlian.",
  str_skill_desc_3300051 = "<color=#FFFF00>Penundaan skill +1 setelah digunakan</color>. Menyebabkan <color=#00F6FF>{1}%</color> damage kepada <color=#00F6FF>semua</color> musuh. Semakin rendah persentase HP musuh, semakin tinggi damage (damage ditingkatkan hingga 100%). Meningkatkan damage dampak yang diberikan oleh setiap tumpukan Jiwa menjadi 130%.",
  str_skill_desc_3300052 = "<color=#FFFF00>Cooldown skill -1 setelah melakukan casting</color>. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar. Semakin rendah persentase HP musuh, semakin tinggi damage (damage ditingkatkan hingga 100%). Tidak mendapatkan Soul untuk musuh yang dikalahkan oleh Aurorian di lapangan dengan Skill Aktif mereka.",
  str_skill_desc_3360051 = "<color=#FFFF00>Penundaan skill +1 setelah digunakan</color>. Menyebabkan <color=#00F6FF>{1}%</color> damage kepada <color=#00F6FF>semua</color> musuh. Semakin rendah persentase HP musuh, semakin tinggi damage (damage ditingkatkan hingga 100%). Meningkatkan damage dampak yang diberikan oleh setiap tumpukan Jiwa menjadi 130%.",
  str_skill_desc_3360052 = "<color=#FFFF00>Cooldown skill -1 setelah melakukan casting</color>. Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh di layar. Semakin rendah persentase HP musuh, semakin tinggi damage (damage ditingkatkan hingga 100%). Tidak mendapatkan Soul untuk musuh yang dikalahkan oleh Aurorian di lapangan dengan Skill Aktif mereka.",
  str_skill_passive_desc_443005 = "Mia mendapatkan 1 tumpukan Jiwa untuk setiap musuh yang dikalahkan <color=#00F6FF>Aurora</color> di lapangan dengan Keterampilan Aktif mereka, hingga <color=#00F6FF>8</color> tumpukan. Setiap tumpukan melepaskan ledakan yang menghasilkan <color=#00F6FF>100%</color> Kerusakan ATK ke satu target, selain itu meningkatkan Serangan Normal Mia <color=#00F6FF>3%</color>, dan Chain Combo Damage oleh <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_16000511 = "<color=#00F6FF>Varian Skill Aktif Baru I</color>: <color=#FFFF00>Penundaan skill +1 setelah digunakan</color>. Meningkatkan kerusakan dampak yang diberikan oleh setiap tumpukan Jiwa menjadi 130%.",
  str_skill_upgrade_refine_desc_16000512 = "<color=#00F6FF>Varian Skill Aktif Baru II</color>: <color=#FFFF00>Kurangi waktu pendinginan Skill -1 setelah digunakan</color>. Tidak mendapatkan Soul untuk musuh yang dikalahkan oleh Aurorian di lapangan dengan Skill Aktif mereka.",
  str_skill_upgrade_refine_desc_16000513 = "Peningkatan Kemampuan Peralatan: Meningkatkan batas atas tumpukan Jiwa menjadi <color=#00F6FF>8</color>.",
  str_skill_desc_8001201 = "Memanggil Shadowgeist ke ubin terdekat secara instan.",
