  str_skill_desc_300208 = "Memanggil <link=\"30087\"><#FFAE07><u>Iron Lizard</u></color></link> di tile yang bisa dilewati yang dipilih. <color=#00F6FF>Sebelum putaran musuh</color>, Iron Lizard akan menarik musuh dalam <color=#00F6FF>2 klaster di sekitar</color> ke arah dirinya sejauh 1 tile.",
  str_skill_desc_305208 = "Memanggil <link=\"30087\"><#FFAE07><u>Iron Lizard</u></color></link> pada tile yang bisa dilewati yang dipilih. Ketika Iron Lizard <color=#00F6FF>baru muncul</color> dan <color=#00F6FF>sebelum giliran musuh</color>, Iron Lizard akan menarik musuh dalam <color=#00F6FF>2 klaster di sekitar</color> ke arah dirinya sejauh 1 tile.",
  str_skill_desc_310208 = "Memanggil <link=\"30087\"><#FFAE07><u>Iron Lizard</u></color></link> di tile yang bisa dilewati yang dipilih. <color=#00F6FF>Sebelum putaran musuh</color>, Iron Lizard akan menarik musuh dalam <color=#00F6FF>2 klaster di sekitar</color> ke arah dirinya sejauh 1 tile.",
  str_skill_desc_315208 = "Memanggil <link=\"30087\"><#FFAE07><u>Iron Lizard</u></color></link> pada tile yang bisa dilewati yang dipilih. Ketika Iron Lizard <color=#00F6FF>baru muncul</color> dan <color=#00F6FF>sebelum giliran musuh</color>, Iron Lizard akan menarik musuh dalam <color=#00F6FF>2 klaster di sekitar</color> ke arah dirinya sejauh 1 tile.",
  str_skill_desc_320208 = "Memanggil <link=\"30088\"><#FFAE07><u>Iron Lizard</u></color></link> pada tile yang bisa dilewati yang dipilih. <color=#00F6FF>Sebelum putaran musuh</color>, Iron Lizard akan menarik musuh dalam <color=#00F6FF>2 klaster di sekitar</color> ke arah dirinya sejauh 1 tile. Iron Lizard mendapatkan kemampuan <link=\"30089\"><#FFAE07><u>Magnetix</u></color></link>.",
  str_skill_desc_325208 = "Memanggil <link=\"30088\"><#FFAE07><u>Iron Lizard</u></color></link> pada petak yang dapat dilalui yang dipilih. Ketika Iron Lizard <color=#00F6FF>baru muncul</color> dan <color=#00F6FF>sebelum putaran musuh</color>, Iron Lizard akan menarik musuh dalam <color=#00F6FF>2 cluster di sekitarnya</color> ke arah dirinya sejauh 1 petak. Iron Lizard mendapatkan kemampuan <link=\"30089\"><#FFAE07><u>Magnetix</u></color></link>.",
  str_skill_desc_330208 = "Memanggil <link=\"30088\"><#FFAE07><u>Iron Lizard</u></color></link> di tile yang bisa dilewati yang dipilih. <color=#00F6FF>Sebelum giliran musuh</color>, Iron Lizard akan menarik musuh dalam jarak <color=#00F6FF>2 klaster di sekitar</color> ke arah dirinya sejauh 1 tile. Iron Lizard mendapatkan kemampuan <link=\"30089\"><#FFAE07><u>Magnetix</u></color></link> dan <link=\"30090\"><#FFAE07><u>Whirlpool</u></color></link>.",
  str_skill_desc_335208 = "Panggil <link=\"30088\"><#FFAE07><u>Iron Lizard</u></color></link> di tile yang bisa dilewati yang dipilih. Ketika Iron Lizard <color=#00F6FF>baru muncul</color> dan <color=#00F6FF>sebelum putaran musuh</color>, Iron Lizard akan menarik musuh dalam <color=#00F6FF>2 klaster di sekitar</color> ke arah dirinya sejauh 1 tile. Iron Lizard mendapatkan kemampuan <link=\"30089\"><#FFAE07><u>Magnetix</u></color></link> dan <link=\"30090\"><#FFAE07><u>Whirlpool</u></color></link>.",
  str_skill_passive_name_410208 = "Ledakan Kadal",
  str_skill_passive_desc_410208 = "Saat Kadal Besi menghilang, ia berurusan <color=#00F6FF>{1}</color> kerusakan pada 2 cluster di sekitarnya.",
