  str_skill_upgrade_desc_15020815 = "Peningkatan Kemampuan Aktif: Ketika Iron Lizard <color=#FFFF00>muncul</color>, ia akan menarik musuh dalam <color=#00F6FF>2 klaster di sekitar</color> ke arah dirinya sejauh 1 ubin.",
  str_skill_name_1522081 = "Magnetix",
