  str_skill_name_291600103 = "Berduka Eve teleport ke posisi terdekat dengan target dan kemudian menyerangnya.",
  str_skill_name_291600104 = "Berduka Eve menimbulkan kerusakan pada area pusat besar medan perang.",
  str_skill_name_291600105 = "Berduka Eve mendapatkan sejumlah tumpukan Darkflow, mendapatkan Pengurangan DMG berdasarkan jumlah tumpukan. Setiap kali dia diserang, tumpukan Darkflow berkurang.",
  str_skill_name_291600106 = "Berduka Eve mengunci target dan menimbulkan kerusakan, lalu memulihkan sejumlah besar HP berdasarkan tumpukan Darkflow yang tersisa.",
  str_skill_name_20060011 = "Dawn Bunga",
  str_skill_desc_20060011 = "Memberikan bonus pemulihan HP untuk Berduka Eve",
  str_skill_name_200310102 = "Teladan Pemimpin",
  str_skill_desc_200310102 = "Melepaskan serangan cleave yang merusak terlebih dahulu dan segera mengikutinya dengan tendangan, memberikan kerusakan tambahan yang ringan pada musuh dan memukul mereka mundur.",
  str_skill_name_200310103 = "Peningkatan Morale",
  str_skill_desc_200310103 = "Memberikan Prajurit Illumina dalam 2 klaster di sekitar ACT tambahan, dan mengubah sebagian Bruise yang terakumulasi menjadi HP untuk semua prajurit dalam jangkauan dan diri mereka sendiri.",
  str_skill_name_200290103 = "L5 Penekanan Senapan Mesin",
  str_skill_desc_200290103 = "Menimbulkan kerusakan pada musuh di dalam 20 ubin sekitarnya dengan senapan mesin.",
  str_skill_name_200290104 = "L5 Serangan Charge",
  str_skill_desc_200290104 = "Ketika musuh tidak berada dalam 20 ubin di sekitarnya, dengan cepat menghantam ke arah ubin dalam area berbentuk silang yang terdekat dengan musuh. Setibanya di sana, memberikan kerusakan pada musuh di depan tempat tujuan dan mendorong mereka mundur sejauh 2 ubin.",
  str_skill_name_200300101 = "Semprotan Api Bentuk Kipas",
  str_skill_desc_200300101 = "Menimbulkan damage pada semua target dalam area berbentuk kipas di depan dan memberikan 1 tumpukan Burn pada mereka sambil menghasilkan api pada ubin yang dapat dilalui dalam jangkauan.",
  str_skill_name_200340103 = "Sapu Mencemari",
  str_skill_desc_200340103 = "Mengayunkan senjata untuk memberikan kerusakan pada musuh di depan.",
  str_skill_name_200340104 = "Tusukan Mencemari",
  str_skill_desc_200340104 = "Menusukkan senjata untuk memberikan kerusakan pada musuh di depan.",
  str_skill_name_200270101 = "Pertolongan Pertama di Medan Perang Illumina",
  str_skill_desc_200270101 = "Memulihkan HP Prajurit Illumina dengan HP terendah dalam jarak 4 petak dalam bentuk salib dan mengubah sebagian Bruise yang terakumulasi menjadi HP.",
  str_skill_name_200280101 = "Panggil Bala Bantuan",
  str_skill_desc_200280101 = "Memanggil 1 Prajurit Illumina ke medan perang.",
  str_skill_upgrade_desc_16020913 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16020916 = "Active Skill Enhancement: Mengurangi cooldown skill sebanyak <color=#FFFF00>1</color> putaran.",
  str_skill_name_2002091 = "Array Dampak",
  str_skill_name_2002092 = "Array Dampak",
  str_skill_name_2002093 = "Array Dampak",
  str_skill_name_2002094 = "Array Dampak",
  str_skill_desc_2002091 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>150%</color> kerusakan pada <color=#00F6FF>9 ubin dalam bentuk persegi</color>.",
  str_skill_desc_2002092 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>160%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>.",
  str_skill_desc_2002093 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu transaksi <color=#00F6FF>170%</color> kerusakan pada <color=#00F6FF>17 ubin dalam bentuk radial</color>.",
  str_skill_desc_2002094 = "Melompat ke arah musuh terdekat dengan HP tertinggi di dalamnya <color=#00F6FF>12 ubin dalam bentuk berlian</color>, lalu memberikan <color=#00F6FF>200%</color> kerusakan pada <color=#00F6FF>25 ubin dalam bentuk persegi</color>. Selama setiap koneksi ubin, setiap instance kerusakan yang diberikan mengurangi kondisi pemicu sebesar 1.",
  str_skill_name_3002091 = "Patroli Petir",
  str_skill_name_3002092 = "Patroli Thunder Varian II",
  str_skill_name_3002093 = "Patroli Thunder Varian I",
  str_skill_name_3062091 = "Patroli Petir",
  str_skill_name_3062092 = "Patroli Thunder Varian II",
  str_skill_name_3062093 = "Patroli Thunder Varian I",
  str_skill_desc_3002091 = "Pilih 1 Tile untuk menimbulkan <color=#00F6FF>200%</color> damage pada 25 Tile dalam bentuk persegi. Jika caster berada dalam jangkauan skill, damage akhir akan meningkat sebesar <color=#00F6FF>30%</color>.",
  str_skill_desc_3002092 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Pilih 1 petak untuk memberikan <color=#00F6FF>100%</color> kerusakan pada 9 petak dalam bentuk persegi. Jika caster berada dalam jangkauan skill, kerusakan akhir ditingkatkan sebesar <color=#00F6FF>30%</color>.",
  str_skill_desc_3002093 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Menimbulkan 300% kerusakan pada semua ubin, dan kerusakan akhir meningkat sebesar <color=#00F6FF>30%</color>.",
  str_skill_desc_3062091 = "Pilih 1 Tile untuk menimbulkan <color=#00F6FF>200%</color> damage pada 25 Tile dalam bentuk persegi. Jika caster berada dalam jangkauan skill, damage akhir akan meningkat sebesar <color=#00F6FF>30%</color>.",
  str_skill_desc_3062092 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Pilih 1 petak untuk memberikan <color=#00F6FF>100%</color> kerusakan pada 9 petak dalam bentuk persegi. Jika caster berada dalam jangkauan skill, kerusakan akhir ditingkatkan sebesar <color=#00F6FF>30%</color>.",
  str_skill_desc_3062093 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Menimbulkan <color=#00F6FF>300%</color> kerusakan pada semua ubin dan kerusakan akhir meningkat sebesar <color=#00F6FF>30%</color>.",
  str_skill_passive_name_410209 = "Kemarahan Petir",
  str_skill_passive_name_420209 = "Kemarahan Petir",
  str_skill_passive_name_430209 = "Kemarahan Petir",
  str_skill_passive_desc_410209 = "Musuh yang diserang oleh Skill Aktif akan memasuki status Thunderous Echo selama <color=#00F6FF>2 ronde</color>. Menimbulkan <color=#00F6FF>{1}</color> kerusakan pada target dalam status Thunderous Echo dalam jarak <color=#00F6FF>12 ubin dalam bentuk berlian</color> untuk setiap ubin yang dilalui tim.",
  str_skill_passive_desc_420209 = "Musuh yang diserang oleh Skill Aktif akan memasuki status Thunderous Echo selama <color=#00F6FF>2 ronde</color>. Menimbulkan <color=#00F6FF>{1}</color> kerusakan pada target dalam status Thunderous Echo dalam jarak <color=#00F6FF>12 ubin dalam bentuk berlian</color> untuk setiap ubin yang dilalui tim.",
  str_skill_passive_desc_430209 = "Serangan normal dapat menarget musuh dalam <color=#00F6FF>8 ubin dalam bentuk salib</color>. Musuh yang diserang oleh Skill Aktif akan memasuki status Thunderous Echo selama <color=#00F6FF>2 ronde</color>. Menimbulkan <color=#00F6FF>{1}</color> kerusakan pada target dalam status Thunderous Echo dalam <color=#00F6FF>12 ubin dalam bentuk berlian</color> untuk setiap ubin yang dilalui tim.",
  str_skill_passive_desc_440209 = "Serangan normal dapat menarget musuh dalam <color=#00F6FF>8 ubin dalam bentuk salib</color>. Musuh yang diserang oleh Skill Aktif akan memasuki status Thunderous Echo selama <color=#00F6FF>2 ronde</color>. Menimbulkan <color=#00F6FF>50%</color> kerusakan pada target dalam status Thunderous Echo dalam <color=#00F6FF>12 ubin dalam bentuk berlian</color> untuk setiap ubin yang dilalui tim.",
  str_skill_upgrade_refine_desc_16020911 = "Peningkatan Keterampilan Peralatan: Meningkatkan faktor kerusakan menjadi <color=#00F6FF>50%</color>.",
  str_skill_upgrade_refine_desc_16020912 = "<color=#00F6FF>Varian Skill Aktif Baru I</color>: <color=#FFFF00>Cooldown skill +1 setelah casting</color>. Menimbulkan <color=#00F6FF>300%</color> kerusakan pada semua petak dan kerusakan akhir meningkat sebesar <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16020913 = "<color=#00F6FF>Varian Skill Aktif Baru II</color>: <color=#FFFF00>Cooldown skill -1 setelah casting</color>. Pilih 1 petak untuk memberikan <color=#00F6FF>100%</color> kerusakan pada 9 petak dalam bentuk persegi. Jika pengguna skill berada dalam jangkauan skill, kerusakan akhir meningkat sebesar 30%.",
  str_skill_desc_320116 = "Fleur menimbulkan damage <color=#00F6FF>{1}%</color> pada 1 musuh yang dipilih dan menandai target serta mampu menimbulkan damage pada target yang diberi Mark 1 kali lagi saat menggunakan Chain Combo di putaran ini. Jika Active Skill siap di putaran sebelumnya, damage final putaran ini meningkat sebesar <color=#00F6FF>35%</color>.",
  str_skill_desc_323116 = "Fleur menimbulkan damage <color=#00F6FF>{1}%</color> pada 1 musuh yang dipilih dan menandai target, dan mampu menimbulkan damage pada target yang diberi Mark 1 kali lagi saat menggunakan Chain Combo di putaran ini. Jika Active Skill siap di putaran sebelumnya, damage final putaran ini meningkat sebesar <color=#00F6FF>35%</color>.",
  str_skill_upgrade_desc_16011113 = "Peningkatan Keahlian Peralatan: Kisaran pembentukan kristal meningkat menjadi 1/2/3 <color=#00F6FF>klaster di sekitar</color>.",
  str_skill_upgrade_desc_16011116 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_desc_300111 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh. Makin sedikit musuh, makin besar damage yang ditimbulkan, hingga 2 kali lipat dari aslinya.",
  str_skill_desc_303111 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh. Makin sedikit musuh, makin besar damage yang ditimbulkan, hingga 2 kali lipat dari aslinya.",
  str_skill_desc_320111 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh. Makin sedikit musuh, makin besar damage yang ditimbulkan, hingga 2 kali lipat dari aslinya. Menandai posisi saat ini <color=#00F6FF>setelah menggunakan Active Skills</color> dan saat <color=#00F6FF>memasuki Aurora Time</color>. Jika Equipment Skill menghasilkan kristal di putaran ini, maka akan dipicu sekali di posisi yang ditandai.",
  str_skill_desc_323111 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>semua</color> musuh. Makin sedikit musuh, makin besar damage yang ditimbulkan, hingga 2 kali lipat dari aslinya. Menandai posisi saat ini <color=#00F6FF>setelah menggunakan Active Skills</color> dan saat <color=#00F6FF>memasuki Aurora Time</color>. Jika Equipment Skill menghasilkan kristal di putaran ini, maka akan dipicu sekali di posisi yang ditandai.",
  str_skill_passive_name_416111 = "Crystal Touch",
  str_skill_passive_name_436111 = "Crystal Touch",
  str_skill_passive_desc_410111 = "Sebelum musuh mengambil tindakan, jika Beryl telah meluncurkan Chain Combo pada putaran ini, kristal akan dihasilkan dalam <color=#00F6FF>jangkauan Chain Combo-nya</color> dan akan tetap ada selama 1 putaran. Ketika musuh <link=\"30091\"><#FFAE07><u>menyentuh</u></color></link> kristalnya, mereka akan menerima damage <color=#00F6FF>{1}</color> yang mengabaikan DEF (dipengaruhi oleh penghitung elemen).",
  str_skill_passive_desc_430111 = "Sebelum musuh mengambil tindakan, jika Beryl telah meluncurkan Chain Combo pada putaran ini, kristal akan dihasilkan dalam <color=#00F6FF>jangkauan Chain Combo-nya</color> dan akan tetap ada selama 1 putaran. Ketika musuh <link=\"30091\"><#FFAE07><u>menyentuh</u></color></link> kristalnya, mereka akan menerima damage <color=#00F6FF>{1}</color> yang mengabaikan DEF (dipengaruhi oleh penghitung elemen). Damage ini meningkat sebesar <color=#00F6FF>10%</color> untuk setiap tile yang terhubung, hingga maksimal 20 tile.",
  str_skill_passive_desc_416111 = "Sebelum musuh mengambil tindakan, jika Beryl telah meluncurkan Chain Combo pada putaran ini, kristal akan dihasilkan dalam <color=#00F6FF>1/2/3 klaster di sekitarnya</color> dan akan tetap ada selama 1 putaran. Ketika musuh <link=\"30091\"><#FFAE07><u>menyentuh</u></color></link> kristalnya, mereka akan menerima damage <color=#00F6FF>{1}</color> yang mengabaikan DEF (dipengaruhi oleh penghitung elemen).",
  str_skill_passive_desc_436111 = "Sebelum musuh mengambil tindakan, jika Beryl telah meluncurkan Chain Combo pada putaran ini, kristal akan dihasilkan dalam <color=#00F6FF>1/2/3 klaster di sekitarnya</color> dan akan tetap ada selama 1 putaran. Ketika musuh <link=\"30091\"><#FFAE07><u>menyentuh</u></color></link> kristalnya, mereka akan menerima damage <color=#00F6FF>{1}</color> yang mengabaikan DEF (dipengaruhi oleh penghitung elemen). Damage ini meningkat sebesar <color=#00F6FF>10%</color> untuk setiap tile yang terhubung, hingga maksimal 20 tile.",
  str_skill_desc_2001161 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>Splash</u></color></link> pada <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitarnya.",
  str_skill_desc_2001162 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>Splash</u></color></link> pada <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitarnya.",
  str_skill_desc_2001163 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>Splash</u></color></link> pada <color=#00F6FF>4 tile dalam bentuk silang</color> di sekitarnya.",
  str_skill_desc_2061161 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>splash</u></color></link> pada <color=#00F6FF>4 tile dalam area berbentuk silang</color> di sekitarnya. Serangan ini mengabaikan semua DEF jika target ditandai.",
  str_skill_desc_2061162 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>splash</u></color></link> pada <color=#00F6FF>4 tile dalam area berbentuk silang</color> di sekitarnya. Serangan ini mengabaikan semua DEF jika target ditandai.",
  str_skill_desc_2061163 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>splash</u></color></link> pada <color=#00F6FF>4 tile dalam area berbentuk silang</color> di sekitarnya. Serangan ini mengabaikan semua DEF jika target ditandai.",
  str_skill_desc_2201161 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>splash</u></color></link> pada <color=#00F6FF>4 tile dalam area berbentuk silang</color> di sekitarnya. Serangan ini mengabaikan 40% DEF jika target ditandai.",
  str_skill_desc_2201162 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>splash</u></color></link> pada <color=#00F6FF>4 tile dalam area berbentuk silang</color> di sekitarnya. Serangan ini mengabaikan 40% DEF jika target ditandai.",
  str_skill_desc_2201163 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat dan <color=#00F6FF>30%</color> damage <link=\"30015\"><#FFAE07><u>splash</u></color></link> pada <color=#00F6FF>4 tile dalam area berbentuk silang</color> di sekitarnya. Serangan ini mengabaikan 40% DEF jika target ditandai.",
  str_skill_name_2201161 = "Iron Fist",
  str_skill_name_2201162 = "Iron Fist",
  str_skill_name_2201163 = "Iron Fist",
  str_skill_desc_300116 = "Memilih 1 musuh dan menimbulkan <color=#00F6FF>{1}%</color> damage sambil meninggalkan tanda. Chain Combo Fleur menimbulkan damage pada target yang diberi tanda 1 kali lagi pada putaran ini.",
  str_skill_desc_303116 = "Memilih 1 musuh dan menimbulkan <color=#00F6FF>{1}%</color> damage sambil meninggalkan tanda. Chain Combo Fleur menimbulkan damage pada target yang diberi tanda 1 kali lagi pada putaran ini. Fleur dapat menggunakan Active Skill lagi setelah <color=#00F6FF>memasuki Aurora Time</color> atau ketika <color=#00F6FF>target yang diberi tanda dikalahkan</color>.",
  str_skill_passive_name_400116 = "Handyman",
  str_skill_passive_name_410116 = "Handyman",
  str_skill_passive_name_430116 = "Handyman",
  str_skill_passive_desc_410116 = "Semua damage yang ditimbulkan Fleur pada musuh dengan HP Maks kurang dari 50% akan ditingkatkan sebesar <color=#00F6FF>{1}</color> (jika target tidak memiliki nilai HP Maks, peningkatan damage ini berlaku segera).",
  str_skill_passive_desc_430116 = "Semua damage yang diberikan Fleur pada musuh dengan HP Maks kurang dari 50% akan ditingkatkan sebesar <color=#00F6FF>{1}</color> (jika target tidak memiliki nilai HP Maks, peningkatan damage ini berlaku segera). Memberikan bonus tambahan <color=#00F6FF>{2}</color> saat menyerang target yang ditandai.",
  str_skill_upgrade_desc_16011613 = "Chain Combo Enhancement: Saat menyerang target yang ditandai, serangan Chain Combo mengabaikan DEF sepenuhnya. (Berlaku untuk Ascension II.)",
  str_skill_upgrade_desc_16011616 = "Peningkatan Keterampilan Aktif: Dapat digunakan lagi setelah memasuki Aurora Time atau saat target yang ditandai dikalahkan.",
  str_skill_name_20021011 = "Kehancuran Pentagram",
