  str_skill_name_3352101 = "Blitz Suci",
  str_skill_passive_name_410210 = "Penyesalan Orang yang Akan Mati",
  str_skill_passive_name_415210 = "Penyesalan Orang yang Akan Mati",
  str_skill_desc_20021011 = "Menimbulkan <color=#00F6FF>130%</color> damage 2 kali, ditetapkan secara acak pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> unit ini. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_2002102 = "Menimbulkan <color=#00F6FF>135%</color> damage 3 kali, ditetapkan secara acak pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> unit ini. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_2002103 = "Penawaran <color=#00F6FF>140%</color> kerusakan 4 kali, ditugaskan secara acak ke musuh dalam <color=#00F6FF>3 cluster sekitarnya</color>. Ketika target menerima damage lebih dari sekali, damage dari kedua kalinya akan berkurang setengahnya.",
  str_skill_desc_3002101 = "Memilih 1 dari <color=#00F6FF>4</color> arah dan mengisi, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 tile di depan</color>.",
  str_skill_desc_3102101 = "Memilih 1 dari <color=#00F6FF>4</color> arah dan mengisi, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 tile di depan</color>.",
  str_skill_desc_3202101 = "Memilih 1 dari <color=#00F6FF>4</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Untuk setiap 4 tumpukan Kemauan yang Tertahan pada target, tambahan menimbulkan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>12 petak dalam bentuk berlian</color> yang berpusat pada posisi tim.",
  str_skill_desc_3302101 = "Memilih 1 dari <color=#00F6FF>4</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Damage ini, bersama dengan yang dihasilkan oleh Kemampuan Peralatan, dapat menembus 1 petak, memberikan <color=#00F6FF>setengah damage</color> pada petak yang ditembus. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan memberikan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>12 petak dalam bentuk berlian</color> yang berpusat pada posisi tim.",
  str_skill_desc_3022101 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 tile di depan</color>.",
  str_skill_desc_3122101 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 tile di depan</color>.",
  str_skill_desc_3222101 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan menimbulkan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>12 petak dalam bentuk berlian</color> dari posisi tim.",
  str_skill_desc_3322101 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Damage ini, bersama dengan yang dihasilkan oleh Kemampuan Peralatan, dapat menembus 1 petak, memberikan <color=#00F6FF>setengah damage</color> pada petak yang ditembus. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan memberikan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>12 petak dalam bentuk berlian</color> yang berpusat pada posisi tim.",
  str_skill_desc_3152101 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 tile di depan</color>.",
  str_skill_desc_3252101 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan menimbulkan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>12 petak dalam bentuk berlian</color> dari posisi tim.",
  str_skill_desc_3352101 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>{1}%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Damage ini, bersama dengan yang dihasilkan oleh Kemampuan Peralatan, dapat menembus 1 petak, memberikan <color=#00F6FF>setengah damage</color> pada petak yang ditembus. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan memberikan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>12 petak dalam bentuk berlian</color> yang berpusat pada posisi tim.",
  str_skill_passive_desc_410210 = "Setiap Serangan Normal dan Chain Combo dari Joselyne menimbulkan 1 tumpukan Lingering Will pada musuh yang terkena, hingga <color=#00F6FF>6</color> tumpukan. Active Skill-nya juga memberikan <color=#00F6FF>{1}</color> ATK sebagai kerusakan pada musuh <color=#00F6FF>1 petak di depan</color> beberapa kali sesuai dengan jumlah tumpukan Lingering Will pada target. Tumpukan akan diatur ulang setelahnya.",
  str_skill_passive_desc_415210 = "Setiap Serangan Normal dan Chain Combo dari Joselyne menimbulkan 1 tumpukan Lingering Will pada musuh yang terkena, hingga <color=#00F6FF>8</color> tumpukan. Active Skill-nya juga memberikan <color=#00F6FF>{1}</color> ATK sebagai kerusakan pada musuh <color=#00F6FF>1 petak di depan</color> beberapa kali sesuai dengan jumlah tumpukan Lingering Will pada target. Tumpukan akan diatur ulang setelahnya.",
  str_skill_upgrade_desc_15021012 = "Active Skill Enhancement: Pilih salah satu dari <color=#FFFF00>8</color> arah dan melaju ke arah tersebut.",
  str_skill_upgrade_desc_15021015 = "Peningkatan Keterampilan Peralatan: Meningkatkan batas atas tumpukan Lingering Will menjadi <color=#FFFF00>8</color>.",
  str_skill_name_200330110 = "Manipulasi Psionik",
  str_skill_desc_200330110 = "Dreadweaver menjauhkan diri dari lokasi tim pemain. Setelah pergerakan tim berakhir, Dreadweaver akan segera mengubah lokasi tim, mempengaruhi posisi Chain Combo yang dikeluarkan oleh timnya.",
  str_skill_name_200330121 = "Korban Darah",
  str_skill_desc_200330121 = "Dreadweaver membakar sisa HP-nya hingga menjadi 1 poin, memberikan kerusakan sejati yang mengabaikan pertahanan kepada pemain. Jumlah HP yang terbakar secara langsung menentukan DMG akhir. Skill ini hanya dapat digunakan sekali.",
  str_skill_upgrade_refine_desc_15021011 = "Peningkatan Keterampilan Peralatan: Meningkatkan faktor kerusakan menjadi <color=#00F6FF>36%</color>.",
  str_skill_upgrade_refine_desc_15021012 = "Peningkatan Keterampilan Aktif: Untuk setiap 4 tumpukan Kemauan yang Tersisa pada target, memberikan 120% kerusakan sekali kepada semua musuh di dalam <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_upgrade_refine_desc_15021013 = "Peningkatan Keterampilan Aktif: Active Skill dan Equipment Skill memberikan kerusakan penuh pada ubin yang mereka tembus.",
  str_skill_passive_desc_440210 = "Setiap Serangan Normal dan Chain Combo dari Joselyne menimbulkan 1 tumpukan Lingering Will pada musuh yang terkena, hingga <color=#00F6FF>8</color> tumpukan. Active Skill-nya juga memberikan <color=#00F6FF>36%</color> ATK sebagai kerusakan pada musuh <color=#00F6FF>1 petak di depan</color> beberapa kali sesuai dengan jumlah tumpukan Lingering Will pada target. Tumpukan akan diatur ulang setelahnya.",
  str_skill_passive_desc_445210 = "Setiap Serangan Normal dan Chain Combo dari Joselyne menimbulkan 1 tumpukan Lingering Will pada musuh yang terkena, hingga <color=#00F6FF>8</color> tumpukan. Active Skill-nya juga memberikan <color=#00F6FF>36%</color> ATK sebagai kerusakan pada musuh <color=#00F6FF>1 petak di depan</color> beberapa kali sesuai dengan jumlah tumpukan Lingering Will pada target. Tumpukan akan diatur ulang setelahnya.",
  str_skill_desc_34021011 = "Memilih 1 dari <color=#00F6FF>4</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>80%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Damage ini, bersama dengan yang dihasilkan oleh Kemampuan Peralatan, dapat menembus 1 petak, memberikan <color=#00F6FF>setengah damage</color> pada petak yang ditembus. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan memberikan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>2 kelompok sekitar</color>.",
  str_skill_desc_34221011 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>80%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Damage ini, bersama dengan yang dihasilkan oleh Kemampuan Peralatan, dapat menembus 1 petak, memberikan <color=#00F6FF>setengah damage</color> pada petak yang ditembus. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan memberikan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>2 kelompok sekitar</color>.",
  str_skill_desc_34521011 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>80%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Damage ini, bersama dengan yang dihasilkan oleh Kemampuan Peralatan, dapat menembus 1 petak, memberikan <color=#00F6FF>setengah damage</color> pada petak yang ditembus. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan memberikan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>2 kelompok sekitar</color>.",
  str_skill_desc_34021012 = "Memilih 1 dari <color=#00F6FF>4</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>80%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Damage ini, bersama dengan yang dihasilkan oleh Kemampuan Peralatan, dapat menembus 1 petak, memberikan <color=#00F6FF>damage penuh</color> pada petak yang ditembus. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan memberikan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>2 kelompok sekitar</color>.",
  str_skill_desc_34221012 = "Memilih 1 dari <color=#00F6FF>8</color> arah dan mengisi daya, berhenti ketika menemui rintangan. Menimbulkan <color=#00F6FF>80%</color> damage sekali pada musuh <color=#00F6FF>1 petak di depan</color>. Damage ini, bersama dengan yang dihasilkan oleh Kemampuan Peralatan, dapat menembus 1 petak, memberikan <color=#00F6FF>damage penuh</color> pada petak yang ditembus. Untuk setiap 4 tumpukan Lingering Will pada target, tambahan menimbulkan <color=#00F6FF>120%</color> damage sekali pada semua musuh dalam <color=#00F6FF>2 kelompok sekitar</color>.",
