  str_skill_name_70010981 = "Forsaken: Colossus Sharpness",
  str_skill_name_70010982 = "Forsaken: Kekuatan Petir",
  str_skill_name_70010983 = "Forsaken: Colossus Shriek",
  str_skill_desc_70010981 = "Forsaken: Schummer si Aviduz menimbulkan damage pada target dalam bentuk silang yang berpusat pada dirinya sendiri.",
  str_skill_desc_70010982 = "Terlupakan: Schummer si Aviduz memanggil Lightning Power untuk menimbulkan damage di beberapa area di medan tempur dan menyebabkan Paralysis.",
  str_skill_desc_70010983 = "Forsaken: Schummer mengontrol Aviduz Colossus untuk melepaskan Sonic Blast, menimbulkan damage pada semua target dan menarik Aurorian mendekatinya.",
  str_skill_name_290610101 = "Mengamuk Maju",
  str_skill_desc_290610101 = "Mendorong maju perlahan dan memberikan pukulan berat pada musuh di depan.",
  str_skill_name_290610102 = "Percepatan Bertenaga",
  str_skill_desc_290610102 = "Maju cepat jika tidak ada musuh di depan.",
  str_skill_name_290610103 = "Pengeboman Serba Guna",
  str_skill_desc_290610103 = "Menimbulkan kerusakan pada Aurorian di sekitar mech dan menjatuhkan mereka ke belakang. Kemampuan ini juga memberikan kerusakan pada dinding.",
  str_skill_name_290610104 = "Semprotan Api",
  str_skill_desc_290610104 = "Melancarkan serangan dahsyat, menimbulkan kerusakan besar pada Aurorian di depan dan dinding.",
  str_skill_name_290610105 = "Mekanik yang Rusak",
  str_skill_desc_290610105 = "Memperbaiki komponennya saat lumpuh, dan setelah perbaikan selesai, akan dikerahkan kembali untuk pengepungan.",
  str_skill_name_280240101 = "Tusukan Penghilang",
  str_skill_desc_280240101 = "Memberikan pukulan berat pada musuh di depan Gerbang Benteng dan melumpuhkan mereka.",
  str_skill_name_290570101 = "Mudbundle: Guyuran",
  str_skill_name_290570102 = "Mudbundle: Mengalir deras",
  str_skill_name_290570103 = "Mudbundle: Menyedot",
  str_skill_desc_290570101 = "Mudbundle tenggelam ke dalam lumpur dan muncul di lokasi terdekat dengan Aurorian, memberikan damage pada unit dalam 2 klaster sekitarnya dan menghasilkan rawa-rawa di lapangan.",
  str_skill_desc_290570102 = "Mudbundle tenggelam ke dalam lumpur dan muncul di lokasi terdekat dengan Aurorian, memberikan kerusakan pada unit dalam 2 kolom di depan dan menghasilkan rawa-rawa di lapangan.",
  str_skill_desc_290570103 = "Menyerap semua ubin di lapangan dan mengatur ulang mereka, memberikan kerusakan pada Aurorian dan memindahkan mereka ke rawa acak.",
  str_skill_desc_290570104 = "Mara Sol memanggil 2 Dreadweaver ke medan tempur.",
  str_skill_upgrade_desc_16021213 = [[
Peningkatan Skill Aktif: Mengubah Skill Aktif menjadi <color=#FFFF00>Serangan Preemptive</color>. Tersedia saat memasuki pertempuran.
Mengubah 2 ubin non-hijau acak dalam area persegi panjang yang ditentukan dari Skill Aktif menjadi ubin hijau.]],
  str_skill_upgrade_desc_16021216 = "Peningkatan Keterampilan Aktif: Rentang pemilihan tile kedua meluas hingga <color=#00F6FF>4 cluster sekitarnya</color>.",
  str_skill_desc_3002121 = "Memilih tile mana saja, lalu memilih tile lain dalam <color=#00F6FF>3 klaster sekitarnya</color> untuk menentukan area persegi panjang. 2 tile yang dipilih diubah menjadi Tile Hijau, dan jika tim berada dalam area yang ditentukan, mengembalikan HP sebesar <color=#00F6FF>250%</color> dari ATK Antony.",
  str_skill_desc_3032121 = "Memilih ubin mana saja, lalu memilih ubin lain di dalam <color=#00F6FF>3 cluster sekitarnya</color> untuk menentukan area persegi panjang. 2 ubin yang dipilih diubah menjadi ubin hijau, lalu mengubah 2 ubin non-hijau acak di dalam area yang ditentukan menjadi ubin hijau. Jika tim berada di dalam area yang ditentukan, mengembalikan HP sebanding dengan <color=#00F6FF>250%</color> dari ATK Antony.",
  str_skill_desc_3062121 = "Memilih tile mana saja, lalu memilih tile lain dalam <color=#00F6FF>4 klaster sekitarnya</color> untuk menentukan area persegi panjang. 2 tile yang dipilih diubah menjadi tile hijau, lalu mengubah 2 tile non-hijau acak di dalam area yang ditentukan menjadi tile hijau. Jika tim berada di dalam area yang ditentukan, mengembalikan HP sebesar <color=#00F6FF>250%</color> dari ATK Antony.",
  str_skill_desc_3202121 = "Memilih 1 tile apa saja, lalu memilih 1 tile lain dalam <color=#00F6FF>3 klaster sekitarnya</color> untuk menentukan area persegi panjang. 2 tile yang dipilih diubah menjadi Hijau <link=\"20001\"><#FFAE07><u>tile yang ditingkatkan</u></color></link>, dan jika tim berada dalam area yang ditentukan, mengembalikan HP sebesar <color=#00F6FF>250%</color> dari ATK Antony.",
  str_skill_desc_3232121 = "Memilih tile mana saja, lalu memilih tile lain dalam <color=#00F6FF>3 klaster sekitarnya</color> untuk menentukan area persegi panjang. 2 tile yang dipilih diubah menjadi <link=\"20001\"><#FFAE07><u>tile hijau yang ditingkatkan</u></color></link>, lalu mengubah 2 tile non-hijau acak di dalam area yang ditentukan menjadi tile hijau. Jika tim berada di dalam area yang ditentukan, mengembalikan HP sebesar <color=#00F6FF>250%</color> dari ATK Antony.",
  str_skill_desc_3262121 = "Memilih tile mana saja, lalu memilih tile lain dalam <color=#00F6FF>4 klaster sekitarnya</color> untuk menentukan area persegi panjang. 2 tile yang dipilih diubah menjadi <link=\"20001\"><#FFAE07><u>tile hijau yang ditingkatkan</u></color></link>, lalu mengubah 2 tile non-hijau acak dalam area yang ditentukan menjadi tile hijau. Jika tim berada dalam area yang ditentukan, mengembalikan HP sebesar <color=#00F6FF>250%</color> dari ATK Antony.",
  str_skill_desc_2002121 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 kolom</color>.",
  str_skill_desc_2002122 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom</color>.",
  str_skill_desc_2002123 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>3 kolom</color>.",
  str_skill_passive_desc_410212 = "Ketika anggota tim melintasi 1 ubin melalui ubin Hijau yang terhubung atau <link=\"30092\"><#FFAE07><u>bergerak</u></color></link> 1 ubin dengan cara apa pun, mereka mengembalikan HP sebesar <color=#00F6FF>{1}</color> dari ATK Antony.",
  str_skill_passive_desc_430212 = "Ketika anggota tim melintasi 1 tile melalui tile Hijau yang terhubung atau <link=\"30092\"><#FFAE07><u>bergerak</u></color></link> 1 tile dengan cara apa pun, mereka memulihkan HP sebesar <color=#00F6FF>{1}</color> dari ATK Antony. Semakin rendah kesehatan tim, semakin besar efek pemulihan, hingga <color=#00F6FF>100%</color>.",
