  str_skill_name_8002005 = "Dreamflare: Lompatan Gelombang",
  str_skill_desc_8002001 = "Memilih 1 tile, lalu memilih tile lain untuk membentuk bidang 2×2 atau 1×4 dan mengonversi tile di dalamnya menjadi ubin berwarna, sekaligus menghasilkan <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>.",
  str_skill_desc_8002002 = "Memilih 1 ubin dan secara acak mengubah 5 dari 9 ubin dalam bentuk persegi menjadi <color=#00F6FF>ubin berwarna</color>, serta menghasilkan 5 <color=#00F6FF>ubin yang disempurnakan</color> secara acak.",
  str_skill_desc_8002003 = "Memilih 1 ubin dan mengubah 6 ubin non-warna terdekat menjadi 6 ubin berwarna, serta menghasilkan ubin yang ditingkatkan.",
  str_skill_desc_8002004 = "Memilih 1 ubin dan mengubah 4 ubin di sekitarnya menjadi ubin berwarna, serta menghasilkan <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link>.",
  str_skill_desc_8002005 = "Mengonversi 5 ubin yang dipilih menjadi <color=#00F6FF>ubin berwarna</color> dan menghasilkan <link=\"20001\"><#FFAE07><u>ubin ditingkatkan</u></color></link>.",
  str_skill_name_8002006 = "Silence",
  str_skill_desc_8002006 = "Lama terdiam, tidak lagi merespon apa pun. Menanggung kerusakan yang diterima oleh semua Eclipsite dan Prajurit Lumopolis.",
  str_skill_name_80020042 = "Menace",
  str_skill_desc_80020042 = "Ketika Aurorian berada dalam jangkauan berbentuk radial, bergerak berdampingan dengan mereka, memberikan kerusakan, dan menjatuhkan mereka kembali. Serangan ini dapat diblokir oleh rintangan.",
