  str_skill_desc_30021105 = "Mengonversi <color=#00F6FF>4</color> tile Kuning terdekat menjadi Biru. Setelah menggunakan Wintry Hailstorm, waktu pendinginan Evergreen Whiteout bertambah 1.",
  str_skill_desc_30021106 = "Mengonversi <color=#00F6FF>4</color> tile Hijau terdekat menjadi Biru. Setelah menggunakan Evergreen Whiteout, waktu pendinginan Wintry Hailstorm bertambah 1.",
  str_skill_desc_30321101 = "Mengonversi <color=#00F6FF>2</color> tile Kuning terdekat menjadi Biru. Setelah menggunakan, Active Skill berikutnya akan dapat mengonversi <color=#00F6FF>3</color> tile, dan waktu pendinginan Evergreen Whiteout bertambah 1.",
  str_skill_desc_30321102 = "Mengonversi <color=#00F6FF>2</color> tile Hijau terdekat menjadi Biru. Setelah menggunakan, Active Skill berikutnya akan dapat mengonversi <color=#00F6FF>3</color> tile, dan cooldown Wintry Hailstorm bertambah 1.",
  str_skill_desc_30621103 = "Mengonversi <color=#00F6FF>3</color> tile kuning terdekat menjadi biru. Setelah menggunakan skill, cooldown Evergreen Whiteout bertambah +1. Jika 2 Active Skill ini tidak siap ketika putaran dimulai, mengonversi <color=#00F6FF>1</color> tile non-biru terdekat ke tim menjadi <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> biru.",
  str_skill_desc_30621104 = "Mengonversi <color=#00F6FF>3</color> tile hijau terdekat menjadi biru. Setelah menggunakan skill, cooldown Wintry Hailstorm bertambah +1. Jika 2 Active Skill ini tidak siap saat putaran dimulai, mengonversi <color=#00F6FF>1</color> tile non-biru terdekat ke tim menjadi <color=#00F6FF>Biru</color> <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>.",
  str_skill_passive_name_410211 = "Remediasi Bersalju",
  str_skill_passive_name_420211 = "Remediasi Bersalju",
  str_skill_passive_name_430211 = "Remediasi Bersalju",
  str_skill_passive_desc_410211 = "Serangan normal menjadi serangan 2-kombo yang menghasilkan <color=#00F6FF>50%</color> kerusakan dasar per pukulan. Setelah setiap <color=#00F6FF>7</color> serangan normal, Zarya mengembalikan HP sebesar <color=#00F6FF>{1}</color> dari ATK-nya untuk tim.",
  str_skill_passive_desc_420211 = "Serangan normal menjadi serangan 2-kombo yang menghasilkan <color=#00F6FF>50%</color> kerusakan dasar per pukulan. Setelah setiap <color=#00F6FF>7</color> serangan normal, Zarya memulihkan HP sebesar <color=#00F6FF>{1}</color> dari ATK-nya untuk tim. Saat memasuki Aurora Time, ia langsung memulihkan HP sebesar <color=#00F6FF>100%</color> dari ATK-nya untuk tim.",
  str_skill_passive_desc_430211 = "Serangan normal dapat dilancarkan secara diagonal. Serangan normal terhadap musuh dalam bentuk salib menjadi serangan 2-kombo yang menghasilkan <color=#00F6FF>50%</color> kerusakan dasar per pukulan. Setelah setiap <color=#00F6FF>7</color> serangan normal, Zarya mengembalikan HP sebesar <color=#00F6FF>{1}</color> dari ATK-nya untuk tim. Ketika memasuki Aurora Time, ia langsung mengembalikan HP sebesar <color=#00F6FF>100%</color> dari ATK-nya untuk tim.",
  str_skill_upgrade_desc_16021113 = "Active Skill Enhancement: Meningkatkan hitungan tile-converting menjadi <color=#FFFF00>3</color>.",
  str_skill_upgrade_desc_16021116 = "Active Skill Enhancement: Jika 2 Active Skill ini <color=#00F6FF>tidak siap</color> ketika putaran dimulai, mengubah 1 tile non-biru terdekat dengan tim menjadi Dark Tile biru.",
  str_skill_name_200350101 = "Gempa bumi",
  str_skill_name_200350102 = "Serangan Menyakitkan",
  str_skill_name_200350103 = "Penghancur Tengkorak",
  str_skill_name_200350104 = "Pencium Darah",
  str_skill_desc_200350101 = "Rimebeast mengejutkan ke tanah, memberikan beberapa kali kerusakan pada musuh dalam bentuk silang hingga jangkauan maksimum dan mendorong mereka kembali ke jarak terjauh.",
  str_skill_desc_200350102 = "Ketika musuh berada dalam 1 cluster di sekitarnya, Rimebeast menimbulkan kerusakan pada mereka dan menjatuhkan mereka kembali satu ubin.",
  str_skill_desc_200350103 = "Jika musuh berada dalam jangkauan tertentu di sekitar Rimebeast dan tidak ada rintangan di area berbentuk silang, Rimebeast dengan cepat mendekati mereka dan memberikan pukulan kuat, menimbulkan damage. Musuh di area pusat akan menerima lebih banyak damage dan akan terkena stun.",
  str_skill_desc_200350104 = "Rimebeast akan memulihkan HP-nya saat tidak ada musuh di sekitarnya.",
  str_skill_name_200360102 = "Crimson Specter - Pen pursuit",
  str_skill_desc_200360102 = "Berteleportasi ke tim, memberikan beberapa pukulan yang merusak pada unit dalam jarak 1 ubin di depan dan mendorong mereka mundur. Semakin jauh ia berteleportasi, semakin sedikit serangan yang dilancarkan.",
  str_skill_name_290213101 = "Reruntuhan Abadi",
  str_skill_name_290213102 = "Penghakiman Wali",
  str_skill_name_290213103 = "Ancaman Terdeteksi",
  str_skill_desc_290213101 = "Berteleportasi 1 kali sambil menimbulkan damage. Setelah itu, mengubah 3 tile acak dalam 1 klaster di sekitar tim menjadi tile Hijau.",
  str_skill_desc_290213102 = "Berteleportasi 1 kali sambil menimbulkan damage. Setelah itu, mengubah 3 tile acak dalam 1 klaster di sekitar tim menjadi Tile Kuning.",
  str_skill_desc_290213103 = "Menyerap energi dari ubin Biru dalam 2 klaster sekitarnya sebelum menyerang (makin banyak ubin yang diserap, makin tinggi damage-nya).",
  str_skill_desc_200270201 = "Memulihkan HP untuk Illumina Signalman dan mengubah sebagian Bruise yang terkumpul menjadi HP.",
  str_skill_desc_200280201 = "Memanggil 2 Prajurit Illumina ke medan perang.",
  str_skill_desc_200280202 = "Memanggil 1 Prajurit Illumina dan 1 Sersan Illumina ke medan perang.",
  str_skill_desc_200280301 = "Memanggil 2 Illumina Flamethrower ke medan tempur.",
  str_skill_desc_200280302 = "Memanggil 1 Illumina Flamethrower dan 1 Sersan Illumina ke medan perang.",
  str_skill_name_290280111 = "Sanki - Potongan Silang",
  str_skill_desc_290280111 = "Sanki bergerak menuju target, melancarkan serangan sapuan dengan Pedang Sakae untuk menimbulkan kerusakan.",
  str_skill_name_290280121 = "Sanki - Dahsyatnya Pedang",
  str_skill_desc_290280121 = "Mengeluarkan pusaran angin yang ganas dari serangan pedang di tempat, menimbulkan damage pada target dalam jangkauan.",
  str_skill_name_290280131 = "Sanki - Tusukan Taring",
  str_skill_desc_290280131 = "Mengikuti petunjuk dari Pedang Sakae, menusuk ke sisi target, memberikan dua kali kerusakan.",
  str_skill_name_290280141 = "Sanki - Lemparan Pedang Empat Lipat",
  str_skill_desc_290280141 = "Sebelum bertindak, Sanki melepaskan Pedang Sakae ke empat arah, yang menimbulkan kerusakan pada target di sepanjang jalur mereka.",
  str_skill_name_290280151 = "Sanki - Pengingat Pedang",
  str_skill_desc_290280151 = "Sebelum bertindak, Sanki mengambil kembali semua Pedang Sakae yang ada di lapangan, yang menimbulkan kerusakan pada target di sepanjang jalur mereka.",
  str_skill_name_290280112 = "Potongan silang",
  str_skill_desc_290280112 = "Bergerak mendekati Eclipsite terdekat dan mengayunkan Pedang Sakae secara horizontal, menimbulkan kerusakan besar.",
  str_skill_name_290280122 = "Frenzy",
  str_skill_desc_290280122 = "Maju menuju gerombolan Eclipsite dan meluncurkan pusaran pedang yang gila, menimbulkan kerusakan pada semua Eclipsite dalam jangkauan tertentu.",
  str_skill_name_700110233 = "Forsaken: Hati Singa Serangan",
  str_skill_name_700110234 = "Forsaken: Pukulan Supercharged",
  str_skill_name_700110235 = "Forsaken: Penyerapan Turbin",
  str_skill_desc_700110233 = "Bergerak dan kemudian menyerang target di sekitar.",
  str_skill_desc_700110234 = "Lempar pukulan untuk menimbulkan damage pada 12 tile dalam bentuk wajik.",
  str_skill_desc_700110235 = "Menarik musuh mendekat dan melancarkan serangan menghancurkan.",
  str_skill_name_700110413 = "Ditinggalkan: Dewa Petir",
  str_skill_name_700110414 = "Yang Ditinggalkan: Kekuatan Benar",
  str_skill_name_700110415 = "Yang Ditinggalkan: Guntur Kekaisaran",
  str_skill_desc_700110413 = "Bergerak dan kemudian menyerang target di sekitar.",
  str_skill_desc_700110414 = "Bergerak dan kemudian memanggil petir untuk menyerang 16 tile dalam bentuk lingkaran, memberikan damage pada musuh yang tertangkap dalam jangkauan.",
  str_skill_desc_700110415 = "Menimbulkan damage sekali pada semua musuh di medan perang, dan damage tambahan sebesar 10% dari HP saat ini.",
  str_skill_desc_700110416 = "Bergerak dan kemudian memanggil petir untuk menyerang 16 tile dalam bentuk lingkaran, memberikan damage pada musuh yang tertangkap dalam jangkauan.",
  str_skill_desc_700110417 = "Menimbulkan damage sekali kepada semua musuh di medan perang, dan damage tambahan setara dengan 15% dari HP saat ini.",
  str_skill_name_111807112 = "Bisikan Gulungan",
  str_skill_desc_111807112 = "Meningkatkan ATK dan DEF saat diambil.",
  str_skill_name_111807113 = "Pengumpul Gulungan",
  str_skill_desc_111807113 = "Mengambil Gulungan Perkamen yang ditemukan di medan perang.",
  str_skill_name_111807111 = "Pemanggil Gulungan",
  str_skill_desc_111807111 = "Memanggil 3 Gulungan Perkamen ke posisi acak di medan tempur.",
  str_skill_name_111807212 = "Pemanggil Gulungan",
  str_skill_desc_111807212 = "Memanggil 5 Gulungan Perkamen ke posisi acak di medan tempur.",
  str_skill_name_2002131 = "Ancaman Terdeteksi",
  str_skill_name_2102131 = "Ancaman Terdeteksi",
  str_skill_desc_2002131 = "Menimbulkan <color=#00F6FF>{1}%</color> damage ke musuh terdekat, yang mendapatkan bonus damage tambahan berdasarkan jumlah Chain Combo.",
  str_skill_desc_2102131 = "Menimbulkan 3 kali damage pada musuh terdekat, masing-masing setara dengan 30% dari damage asli. Damage mendapatkan bonus berdasarkan jumlah serangan normal yang dilakukan oleh penyihir pada putaran ini.",
  str_skill_name_300213 = "Kontrol Area",
  str_skill_desc_300213 = "Memilih 1 tile, menonaktifkan sementara elemennya, dan menghasilkan <color=#00F6FF>sebuah domain persegi yang mencakup 25 tile</color> yang berpusat pada tile yang dipilih. Selama <color=#00F6FF>15 detik</color> berikutnya, Anda dapat terus mengetuk untuk menukar elemen tile yang berdekatan. Tile yang dipilih akan diubah menjadi <color=#00F6FF>Kuning</color> saat hitungan mundur berakhir. Hanya dapat digunakan 1 kali selama pertempuran.",
  str_skill_name_302213 = "Kontrol Area",
  str_skill_desc_302213 = "Memilih 1 tile, menonaktifkan sementara elemennya, dan menghasilkan <color=#00F6FF>domain berbentuk kotak yang mencakup 25 tile</color> yang berpusat pada tile yang dipilih. Selama <color=#00F6FF>15 detik</color> berikutnya, Anda dapat terus mengetuk untuk menukar elemen tile yang berdekatan. Tile yang dipilih akan diubah menjadi <color=#00F6FF>Kuning</color> saat hitungan mundur berakhir. Memberikan satu kali penggunaan saat memasuki pertempuran/gelombang ke-2.",
  str_skill_name_305213 = "Kontrol Area",
  str_skill_desc_305213 = "Memilih 1 tile, menonaktifkan sementara elemennya, dan menghasilkan <color=#00F6FF>domain berbentuk kotak yang mencakup 25 tile</color> yang berpusat pada tile yang dipilih. Selama <color=#00F6FF>15 detik</color> berikutnya, Anda dapat terus mengetuk untuk menukar elemen tile yang berdekatan. Tile yang dipilih akan diubah menjadi <color=#00F6FF>Kuning</color> saat hitungan mundur berakhir. Memberikan satu kali penggunaan saat memasuki pertempuran/gelombang ke-2/putaran ke-7.",
  str_skill_passive_name_410213 = "Jam Meletus",
  str_skill_passive_desc_410213 = "Ketika jumlah combo mencapai <color=#00F6FF>{1}</color>, Chain Combo saat ini meluncurkan 3 kali instance damage, masing-masing setara dengan 30% dari damage asli. Damage mendapatkan bonus berdasarkan jumlah serangan normal yang diberikan oleh caster pada putaran ini.",
  str_skill_passive_name_420213 = "Jam Meletus",
  str_skill_passive_desc_420213 = "Ketika jumlah combo mencapai <color=#00F6FF>{1}</color>, Chain Combo saat ini meluncurkan 3 kali damage, masing-masing setara dengan 30% dari damage asli. Damage mendapatkan bonus berdasarkan jumlah serangan normal yang diberikan oleh caster pada putaran ini, dan dapat dikeluarkan <color=#00F6FF>tanpa memperhatikan elemen tile yang terhubung</color>.",
  str_skill_passive_name_430213 = "Jam Meletus",
  str_skill_passive_desc_430213 = "Ketika jumlah combo mencapai <color=#00F6FF>{1}</color>, Chain Combo saat ini meluncurkan 3 kali damage, masing-masing setara dengan 30% dari damage asli. Damage mendapatkan bonus berdasarkan jumlah serangan normal yang diberikan oleh caster pada putaran ini, dan dapat dikeluarkan <color=#00F6FF>tanpa memperhatikan elemen tile yang terhubung</color>. Ketika tile baru ditambahkan ke rantai, tile ke-N dari rantai ini akan diubah menjadi Kuning, dengan N mewakili sisa putaran.",
  str_skill_upgrade_desc_15021312 = "Peningkatan Keterampilan Aktif: Memberikan satu kali penggunaan saat memasuki gelombang ke-2.",
  str_skill_upgrade_desc_15021315 = "Peningkatan Skill Aktif: Memberikan satu kali penggunaan saat memasuki putaran ke-7.",
  str_skill_name_53520212 = "Summon",
  str_skill_desc_53520212 = "Menyerang Aurorian terlebih dahulu jika mereka berada di sekitarnya; jika tidak, memanggil lebih banyak Lumopolis Pikers untuk membantu dalam pertempuran.",
  str_skill_name_53520213 = "Encourage",
  str_skill_desc_53520213 = "Menyerang Aurorian terlebih dahulu jika mereka ada di sekitarnya; jika tidak, menginspirasi Prajurit Lumopolis terdekat, meningkatkan ATK mereka.",
  str_skill_name_53520411 = "Ancaman Terdeteksi",
  str_skill_desc_53520411 = "Menyerap energi dari ubin Biru dalam 2 klaster sekitarnya sebelum memberikan damage pada musuh. Semakin banyak ubin yang diserap, semakin tinggi damage-nya.",
  str_skill_name_53520412 = "Ancaman Terdeteksi",
  str_skill_desc_53520412 = "Menyerap energi dari tile Merah dalam 2 klaster sekitarnya sebelum memberikan damage pada musuh. Semakin banyak tile yang diserap, semakin tinggi damage-nya.",
  str_skill_name_53520413 = "Ancaman Terdeteksi",
  str_skill_desc_53520413 = "Menyerap energi dari tile Hijau dalam 2 klaster sekitarnya sebelum memberikan damage pada musuh. Semakin banyak tile yang diserap, semakin tinggi damage-nya.",
  str_skill_name_5352031 = "Ledakan Fatal",
  str_skill_desc_5352031 = "Meledak setiap kali waktu tertentu telah berlalu, menimbulkan damage pada semua unit di medan perang.",
  str_skill_name_29089011 = "Palu Hakim Ketua",
  str_skill_name_29089012 = "Putusan Ketua Hakim",
  str_skill_name_29089014 = "Palu Hakim Ketua",
  str_skill_desc_29089011 = "Meluncurkan cahaya suci ke arah lokasi target pada putaran sebelumnya, memberikan kerusakan pada target di sepanjang jalan dan pada ubin yang berdekatan. Kerusakan meningkat sesuai dengan tumpukan Prejudice pada target.",
  str_skill_desc_29089012 = "Mengunci posisi target dan menimbulkan kerusakan parah. Kerusakan meningkat sesuai dengan tumpukan Prejudice pada target.",
  str_skill_desc_29089014 = "Melancarkan cahaya suci ke arah lokasi target di putaran sebelumnya, menimbulkan kerusakan pada target di sepanjang jalan dan pada ubin yang berdekatan. Kerusakan meningkat sesuai dengan tumpukan Prejudice target. Memanggil Patung Juror ke lokasi yang tetap.",
  str_skill_name_29089021 = "Palu Hakim Ketua",
  str_skill_desc_29089021 = "Meluncurkan cahaya suci ke arah lokasi target pada putaran sebelumnya, memberikan kerusakan pada target di sepanjang jalan dan pada ubin yang berdekatan. Kerusakan meningkat sesuai dengan tumpukan Prejudice pada target.",
  str_skill_name_290580101 = "Dampak Kekacauan",
  str_skill_name_290580102 = "Sentuhan Misterius",
  str_skill_name_290580103 = "Menuju Kehancuran",
  str_skill_name_290580104 = "Akhir Takdir",
  str_skill_desc_290580101 = "Memberikan kerusakan pada semua target dalam bentuk kipas dan mendorong mereka mundur ke jarak terjauh.",
  str_skill_desc_290580102 = "Teleportasi sekali dan memberikan kerusakan pada pemain, lalu mendorong pemain mundur 2 ubin.",
  str_skill_desc_290580103 = "Menandai 2 klaster di sekitar target, dan pada awal ronde monster, melepaskan damage parah di area yang ditandai dan menjatuhkan target kembali sebanyak 3 ubin.",
