  str_skill_desc_2001872 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh terdekat.",
  str_skill_desc_2001873 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 4 musuh terdekat.",
  str_skill_desc_3001871 = "Secara acak memberikan <color=#00F6FF>90%</color> kerusakan <color=#00F6FF>6</color> kali pada musuh dalam <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih.",
  str_skill_desc_3051871 = "Secara acak memberikan <color=#00F6FF>90%</color> kerusakan sebanyak <color=#00F6FF>8</color> kali pada musuh dalam <color=#00F6FF>13 ubin dalam bentuk berlian</color> yang berpusat pada 1 ubin yang dipilih.",
  str_skill_passive_desc_410187 = "Jika tidak ada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>, setiap kali Chain Combo memiliki peluang <color=#00F6FF>25%</color> untuk memberikan damage sebesar <color=#00F6FF>{1}×</color>.",
  str_skill_passive_desc_420187 = "Jika tidak ada musuh dalam <color=#00F6FF>1 klaster sekitar</color>, setiap kali Active Skill dan Chain Combo memiliki kesempatan <color=#00F6FF>25%</color> untuk menimbulkan <color=#00F6FF>{1}×</color> damage.",
  str_skill_passive_desc_430187 = "Jika tidak ada musuh dalam <color=#00F6FF>1 klaster di sekitar</color>, setiap kali Active Skill dan Chain Combo memiliki kesempatan <color=#00F6FF>25%</color> untuk menimbulkan <color=#00F6FF>{1}×</color> damage. Jika tidak ada musuh dalam <color=#00F6FF>2 klaster di sekitar</color>, kesempatan tersebut meningkat menjadi <color=#00F6FF>50%</color>.",
  str_skill_upgrade_desc_15018712 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_15018715 = "Peningkatan Skill Aktif: Skill Aktif kini menimbulkan damage 8 kali.",
