  str_skill_passive_name_420188 = "Di Saat Membutuhkan",
  str_skill_passive_name_430188 = "Di Saat Membutuhkan",
  str_skill_desc_2001881 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_2001882 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2001883 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_300188 = "Memilih <color=#00F6FF>2</color> tile untuk diubah menjadi tile Merah, menimbulkan <color=#00F6FF>{1}%</color> damage pada tile di sepanjang jalur dan tile yang berdekatan.",
  str_skill_desc_306188 = "Memilih <color=#00F6FF>2</color> tile mana pun untuk diubah menjadi Tile Merah, menimbulkan <color=#00F6FF>{1}%</color> damage pada tile di sepanjang jalur dan tile yang berdekatan. Membunuh musuh non-bos dalam jangkauan dengan HP kurang dari <color=#00F6FF>15%</color>.",
  str_skill_passive_desc_410188 = "Selama ronde ini, serangan normal pertama yang dilancarkan ke setiap arah akan menghasilkan serangan kritis, menimbulkan <color=#00F6FF>{1}</color> kerusakan.",
  str_skill_passive_desc_420188 = "Selama ronde ini, serangan normal pertama yang diluncurkan di setiap arah akan menghasilkan serangan kritis, menimbulkan <color=#00F6FF>{1}</color> damage. Saat memasuki Aurora Time, jumlah serangan kritis untuk semua arah serangan normal direset.",
  str_skill_passive_desc_430188 = "Normal attack <color=#00F6FF>dapat dilancarkan secara diagonal</color>. Selama ronde ini, serangan normal pertama yang dilancarkan di setiap arah akan menghasilkan serangan kritis, menimbulkan <color=#00F6FF>{1}</color> damage. Saat memasuki Aurora Time, hitungan serangan kritis untuk semua arah serangan normal direset.",
