  str_skill_passive_name_435215 = "Sejenak Kegembiraan",
  str_skill_passive_desc_410215 = "Ketika Isa melepaskan Serangan Normal pada <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>, mereka akan menimbulkan <color=#00F6FF>{1}</color> damage sebanyak 3 kali.",
  str_skill_passive_desc_420215 = "Ketika Isa melepaskan Serangan Normal pada <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>, mereka akan menimbulkan <color=#00F6FF>{1}</color> damage sebanyak 3 kali. Setelah Isa menimbulkan damage pada musuh yang sama <color=#00F6FF>7 kali</color> dengan Serangan Normal-nya, dia akan menimbulkan damage tambahan sebesar <color=#00F6FF>100%</color> dari ATK-nya.",
  str_skill_passive_desc_430215 = "Ketika Isa melakukan Normal Attack pada <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>, mereka akan menimbulkan <color=#00F6FF>{1}</color> damage sebanyak 3 kali. Setelah Isa memberikan damage pada musuh yang sama sebanyak <color=#00F6FF>7 kali</color> dengan Normal Attack dan/atau Chain Combo, dia akan menimbulkan damage tambahan sebesar <color=#00F6FF>100%</color> dari ATK-nya. Mengenai target dengan Active Skill-nya juga akan memicu damage tambahan 1 kali.",
  str_skill_passive_desc_425215 = "Ketika Isa melepaskan Serangan Normal pada <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>, mereka akan menimbulkan <color=#00F6FF>{1}</color> damage sebanyak 3 kali. Setelah Isa menimbulkan damage pada musuh yang sama <color=#00F6FF>7 kali</color> dengan Serangan Normalnya, dia akan menimbulkan damage tambahan sebesar <color=#00F6FF>150%</color> dari ATK-nya.",
  str_skill_passive_desc_435215 = "Ketika Isa melakukan Normal Attack pada <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>, mereka menimbulkan <color=#00F6FF>{1}</color> damage 3 kali. Setelah Isa menimbulkan damage pada musuh yang sama <color=#00F6FF>7 kali</color> dengan Normal Attack dan/atau Chain Combo, ia menimbulkan damage tambahan sebesar <color=#00F6FF>150%</color> dari ATK-nya. Mengenai target dengan Active Skill-nya juga akan memicu damage tambahan 1 kali.",
  str_skill_name_2002151 = "Teguran Guntur",
  str_skill_name_2002152 = "Teguran Guntur",
  str_skill_name_2002153 = "Teguran Guntur",
  str_skill_desc_2002151 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_2002152 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2002153 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>24 tile dalam bentuk lingkaran</color>.",
  str_skill_name_300215 = "Mengenai Penagihan Hutang",
  str_skill_desc_300215 = "Memilih sebuah tile tempat musuh berdiri, lalu memilih 1 dari 4 arah di sekitar tile tersebut. Jika musuh bukan boss, memaksa mereka untuk bergerak 1 tile ke arah yang dipilih, menimbulkan <color=#00F6FF>{1}%</color> damage pada mereka, dan menghasilkan sebuah <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link> pada tile yang dipilih.",
  str_skill_upgrade_refine_desc_15021511 = "Peningkatan Keterampilan Peralatan: Serangan normal menghasilkan damage 3 kali lipat pada musuh yang berada di <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link> dan faktor kerusakan meningkat menjadi <color=#00F6FF>65%</color>.",
  str_skill_upgrade_refine_desc_15021512 = "Efek Baru Keterampilan Peralatan: Ketika Isa dan Rebecca (Ascension I atau lebih tinggi) berada dalam tim yang sama, kerusakan tambahan yang diberikan oleh Keterampilan Peralatan Isa <color=#00F6FF>menimbulkan 1 tumpukan Immersion</color> pada target.",
  str_skill_upgrade_refine_desc_15021513 = "Peningkatan Keterampilan Peralatan: Mengurangi kondisi pemicu kerusakan tambahan menjadi <color=#00F6FF>6 kali</color>.",
  str_skill_passive_desc_440215 = "Ketika Isa melakukan Normal Attack pada <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>, mereka akan menimbulkan <color=#00F6FF>65%</color> damage sebanyak 3 kali. Setelah Isa memberikan damage pada musuh yang sama sebanyak <color=#00F6FF>7 kali</color> dengan Normal Attack dan/atau Chain Combo, ia akan menimbulkan damage tambahan sebesar <color=#00F6FF>100%</color> dari ATK-nya. Mengenai target dengan Active Skill-nya juga akan memicu damage tambahan 1 kali.",
  str_skill_passive_desc_445215 = "Ketika Isa melakukan Normal Attack pada <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>, mereka menimbulkan <color=#00F6FF>65%</color> damage 3 kali. Setelah Isa memberikan damage pada musuh yang sama <color=#00F6FF>7 kali</color> dengan Normal Attack dan/atau Chain Combo, dia menimbulkan damage tambahan sebesar <color=#00F6FF>150%</color> dari ATK-nya. Mengenai target dengan Active Skill-nya juga akan memicu damage tambahan 1 kali.",
  str_skill_passive_desc_450215 = "Ketika Isa melakukan Serangan Normal pada <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>, mereka menghasilkan <color=#00F6FF>65%</color> kerusakan 3 kali. Setelah Isa memberikan kerusakan ke musuh yang sama <color=#00F6FF>7 kali</color> dengan Serangan Normal dan/atau Chain Combo, dia memberikan kerusakan tambahan sebesar <color=#00F6FF>100%</color> dari ATK-nya. Mengenai target dengan Active Skill-nya juga akan memicu kerusakan tambahan 1 kali. Jika Isa dan Rebecca (Ascension I atau lebih tinggi) berada dalam tim yang sama, kerusakan tambahan ini juga <color=#00F6FF>menimbulkan 1 tumpukan Immersion</color>.",
  str_skill_passive_desc_455215 = "Ketika Isa melakukan Serangan Normal pada <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>, mereka memberikan <color=#00F6FF>65%</color> kerusakan 3 kali. Setelah Isa memberikan kerusakan ke musuh yang sama <color=#00F6FF>7 kali</color> dengan Serangan Normal dan/atau Chain Combo, dia memberikan kerusakan tambahan sebesar <color=#00F6FF>150%</color> dari ATK-nya. Mengenai target dengan Active Skill-nya juga akan memicu kerusakan tambahan 1 kali. Jika Isa dan Rebecca (Ascension I atau lebih tinggi) berada dalam tim yang sama, kerusakan tambahan ini juga <color=#00F6FF>menimbulkan 1 tumpukan Immersion</color>.",
  str_skill_passive_desc_460215 = "Ketika Isa melakukan Serangan Normal pada <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>, mereka menghasilkan <color=#00F6FF>65%</color> kerusakan 3 kali. Setelah Isa memberikan kerusakan ke musuh yang sama <color=#00F6FF>6 kali</color> dengan Serangan Normal dan/atau Chain Combo, dia memberikan kerusakan tambahan sebesar <color=#00F6FF>100%</color> dari ATK-nya. Mengenai target dengan Active Skill-nya juga akan memicu kerusakan tambahan 1 kali. Jika Isa dan Rebecca (Ascension I atau lebih tinggi) berada dalam tim yang sama, kerusakan tambahan ini juga <color=#00F6FF>menimbulkan 1 tumpukan Immersion</color>.",
  str_skill_passive_desc_465215 = "Ketika Isa melakukan Serangan Normal pada <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>, mereka menghasilkan <color=#00F6FF>65%</color> kerusakan 3 kali. Setelah Isa memberikan kerusakan ke musuh yang sama <color=#00F6FF>6 kali</color> dengan Serangan Normal dan/atau Chain Combo, dia memberikan kerusakan tambahan sebesar <color=#00F6FF>150%</color> dari ATK-nya. Mengenai target dengan Active Skill-nya juga akan memicu kerusakan tambahan 1 kali. Jika Isa dan Rebecca (Ascension I atau lebih tinggi) berada dalam tim yang sama, kerusakan tambahan ini juga <color=#00F6FF>menimbulkan 1 tumpukan Immersion</color>.",
