  str_skill_desc_2302143 = "Menimbulkan <color=#00F6FF>{1}%</color> damage dalam <color=#00F6FF>bentuk lingkaran hingga jangkauan maksimum</color>. Memberikan <color=#00F6FF>1</color> tumpukan Immersion pada semua target dalam jangkauan.",
  str_skill_desc_2402141 = "Menimbulkan <color=#00F6FF>145%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>. Memberikan <color=#00F6FF>2</color> tumpukan Immersion pada semua target dalam jangkauan.",
  str_skill_desc_2402142 = "Menimbulkan <color=#00F6FF>160%</color> damage pada <color=#00F6FF>16 Tile dalam bentuk lingkaran</color>. Memberikan <color=#00F6FF>2</color> tumpukan Immersion pada semua target dalam jangkauan.",
  str_skill_desc_2402143 = "Menimbulkan <color=#00F6FF>165%</color> damage dalam <color=#00F6FF>bentuk lingkaran hingga jangkauan maksimum</color>. Menginfeksi <color=#00F6FF>2</color> tumpukan Immersion pada semua target dalam jangkauan.",
  str_skill_desc_3002141 = "Mengonversi 1 tile yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> Biru dan mengonversi <color=#00F6FF>3</color> tile Biru terdekat dari tile ini menjadi Dark Tile Biru.",
  str_skill_desc_3062141 = "Mengonversi 1 tile yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> Biru dan mengonversi <color=#00F6FF>5</color> tile Biru terdekat dari tile ini menjadi Dark Tile Biru.",
  str_skill_passive_name_410214 = "Metastasis Beracun",
  str_skill_passive_desc_410214 = "Setiap kali melewati Dark Tile, memberikan <link=\"30094\"><#FFAE07><u>Immersion</u></color></link> pada <color=#00F6FF>12 tile dalam bentuk wajik</color>. Di awal putaran musuh, setiap tumpukan Immersion menimbulkan damage sebesar <color=#00F6FF>{1}</color> dari ATK ke target.",
  str_skill_passive_name_430214 = "Metastasis Beracun",
  str_skill_passive_desc_430214 = "Setiap kali melewati Dark Tile, memberikan <link=\"30094\"><#FFAE07><u>Immersion</u></color></link> pada <color=#00F6FF>12 tile dalam bentuk wajik</color>. Di awal putaran musuh, setiap tumpukan Immersion menimbulkan damage sebesar <color=#00F6FF>{1}</color> dari ATK ke target. Immersion menimbulkan damage yang mengabaikan DEF pada musuh yang terkena Chain Combo di putaran ini.",
  str_skill_upgrade_desc_16021413 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16021416 = "Active Skill Enhancement: Mengonversi <color=#FFFF00>5</color> tile Biru terdekat dari tile yang dipilih menjadi Blue Dark Tiles.",
  str_skill_upgrade_refine_desc_16021411 = "Peningkatan Keterampilan Peralatan: Setiap tumpukan Immersion memberikan damage sebesar <color=#00F6FF>40%</color> dari ATK Rebecca ke target.",
  str_skill_upgrade_refine_desc_16021412 = "Chain Combo Enhancement: Chain Combo memberikan <color=#00F6FF>2</color> tumpukan Immersion pada semua target dalam jangkauan.",
  str_skill_upgrade_refine_desc_16021413 = "Peningkatan Keterampilan Aktif: Mengecor Keterampilan Aktif memicu kerusakan 1 kali pada semua target dengan Immersion, memberikan kerusakan dua kali lipat.",
  str_skill_passive_desc_440214 = "Setiap kali melewati Dark Tile, berikan <link=\"30094\"><#FFAE07><u>Immersion</u></color></link> pada <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Di awal putaran musuh, setiap tumpukan Immersion menimbulkan damage sebesar <color=#00F6FF>40%</color> dari ATK ke target. Immersion memberikan damage yang mengabaikan DEF kepada musuh yang terkena Chain Combo di putaran ini.",
  str_skill_desc_3402141 = "Mengonversi 1 tile yang dipilih menjadi tile Biru <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> dan mengonversi <color=#00F6FF>3</color> tile Biru terdekat ke tile ini menjadi Blue Dark Tiles, kemudian memicu kerusakan 1 kali pada semua target di lapangan dengan Immersion, memberikan kerusakan ganda.",
  str_skill_desc_3462141 = "Mengonversi 1 tile yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> Biru dan mengonversi <color=#00F6FF>5</color> tile Biru terdekat ke tile ini menjadi Dark Tile Biru, kemudian memicu kerusakan 1 kali pada semua target di lapangan dengan Immersion, memberikan kerusakan ganda.",
