  str_skill_name_29092001 = "Pencengkraman Mengoyak",
  str_skill_desc_29092001 = "Stinger menimbulkan damage pada target dalam 1 klaster di sekitar dirinya sebanyak 2 kali dan memberikan efek Bleeding pada mereka.",
  str_skill_desc_290920011 = "Stinger menimbulkan damage pada target dalam 1 klaster di sekitar dirinya sebanyak 2 kali dan memberikan efek Bleeding serta No Healing pada mereka.",
  str_skill_name_29092002 = "Pertempuran Pegunungan",
  str_skill_desc_29092002 = "Stinger memilih 1 arah di mana pemain berada dalam area berbentuk silang, mengisi ke tepi lapangan atau rintangan terdekat, lalu menjatuhkan semua target di sepanjang jalannya, memberikan damage tambahan pada target dalam 1 tile di kedua sisi jalannya dan mengakibatkan mereka mengalami Pendarahan.",
  str_skill_name_29092003 = "Pembakaran",
