  str_skill_passive_name_430216 = "Perimeter Capung",
  str_skill_desc_2002161 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat.",
  str_skill_desc_2002162 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 3 musuh terdekat.",
  str_skill_desc_2002163 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 4 musuh terdekat.",
  str_skill_desc_2202161 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat, kemudian memberikan damage sekali lagi pada 1 musuh acak di dalam Array Petir Persegi.",
  str_skill_desc_2202162 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada 3 musuh terdekat, lalu menimbulkan kerusakan sekali lagi pada 1 musuh acak di dalam Array Petir Persegi.",
  str_skill_desc_2202163 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 4 musuh terdekat, kemudian memberikan damage sekali lagi pada 1 musuh acak di dalam Array Petir Persegi.",
  str_skill_desc_300216 = "Menggunakan 3 <link=\"30095\"><#FFAE07><u>Suku Cadang</u></color></link> untuk memilih 1 tile dan menghasilkan Square Thunder Array dalam <color=#00F6FF>9 tile dalam bentuk persegi</color> yang bertahan selama <color=#00F6FF>2</color> putaran. Serangan normal Xuan Ji <color=#00F6FF>dapat diluncurkan secara diagonal</color> di dalam Square Thunder Array.",
  str_skill_desc_303216 = "Menggunakan 3 <link=\"30095\"><#FFAE07><u>Suku Cadang</u></color></link> untuk memilih 1 tile dan menghasilkan Square Thunder Array dalam <color=#00F6FF>25 tile dalam bentuk persegi</color> yang bertahan selama <color=#00F6FF>3</color> putaran. Serangan normal Xuan Ji <color=#00F6FF>dapat diluncurkan secara diagonal</color> di dalam Square Thunder Array.",
  str_skill_passive_desc_410216 = "Meningkatkan damage Xuan Ji dalam Square Thunder Array sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_416216 = "Meningkatkan damage Xuan Ji dalam Square Thunder Array sebesar <color=#00F6FF>{1}</color>. Damage-nya akan meningkat lagi sebesar <color=#00F6FF>5%</color> untuk setiap Square Thunder Array tambahan di lapangan. Jika Xuan Ji berada di dalam Square Thunder Array saat putaran berakhir, ia akan mendapatkan 1 Spare Part.",
  str_skill_passive_desc_430216 = "Meningkatkan damage Xuan Ji dalam Square Thunder Array sebesar <color=#00F6FF>{1}</color>. Setiap kali Xuan Ji berada di dalam Square Thunder Array setelah menggunakan Chain Combo, Basic ATK-nya meningkat sebesar <color=#00F6FF>4%</color>, dapat ditumpuk hingga 5 kali. Jika ia tidak berada di dalam Square Thunder Array saat putaran berakhir, tumpukan efek ini akan berkurang menjadi setengahnya.",
  str_skill_passive_desc_436216 = "Meningkatkan damage Xuan Ji dalam Square Thunder Array sebesar <color=#00F6FF>{1}</color>. Damage-nya akan meningkat lagi sebesar <color=#00F6FF>5%</color> untuk setiap Square Thunder Array tambahan di lapangan. Jika Xuan Ji berada di dalam Square Thunder Array saat putaran berakhir, ia mendapatkan 1 Spare Part. Setiap kali Xuan Ji berada di dalam Square Thunder Array setelah menggunakan Chain Combo, ATK dasarnya meningkat sebesar <color=#00F6FF>4%</color>, menumpuk hingga 5 kali. Jika ia tidak berada di dalam Square Thunder Array saat putaran berakhir, tumpukan efek ini akan berkurang menjadi setengahnya.",
  str_skill_upgrade_desc_16021613 = "Peningkatan Keterampilan Aktif: Memperluas area dari Square Thunder Array menjadi <color=#00F6FF>25 ubin dalam bentuk persegi</color>. Berlangsung selama <color=#00F6FF>3</color> ronde.",
  str_skill_upgrade_desc_16021616 = "Peningkatan Keterampilan Peralatan: Kerusakan Xuan Ji lebih lanjut ditingkatkan sebesar <color=#00F6FF>5%</color> untuk setiap Tambahan Square Thunder Array di lapangan. Jika Xuan Ji berada di dalam Square Thunder Array ketika putaran berakhir, dia mendapatkan 1 Suku Cadang.",
  str_skill_name_53820323 = "Meledak saat Aurorian mendekat. Jika dibiarkan, ia akan meledak setelah sejumlah putaran berlalu dan menghasilkan beberapa nyala api di sekitarnya.",
  str_skill_name_200400103 = "Belly Fire",
  str_skill_name_200400104 = "Belly Fire",
  str_skill_desc_200400103 = "Bergerak secara lateral dan memuntahkan api, memberikan kerusakan pada musuh di depannya. Ia berhenti bergerak ketika menemui rintangan.",
  str_skill_desc_200400104 = "Bergerak secara lateral dan memuntahkan api, memberikan kerusakan pada musuh di depannya. Ia berhenti bergerak ketika menemui rintangan.",
  str_skill_name_290570123 = "Mudbundle: Menghabiskan",
  str_skill_desc_290570123 = "Mudbundle muncul dari pusat rawa besar, melahap segalanya dan menimbulkan kerusakan pada Aurorian.",
  str_skill_name_290620102 = "Space Cutter: Garis Lintang",
  str_skill_desc_290620102 = "Vilanor bergegas dan melancarkan serangan, menimbulkan kerusakan dan melemparkan Dinding Terlarang sepanjang 3 ubin secara horizontal di samping Aurorian dan berpindah ke lokasi baru.",
  str_skill_name_290620104 = "Space Cutter: Bujur",
  str_skill_desc_290620104 = "Vilanor bergegas dan melancarkan serangan, menimbulkan kerusakan dan melemparkan Dinding Terlarang sepanjang 3 ubin secara vertikal di samping Aurorian dan berpindah ke lokasi baru.",
  str_skill_name_290620106 = "Menjauhlah",
  str_skill_desc_290620106 = "Vilanor memberikan kerusakan pada musuh dalam 1 klaster di sekitar dan mendorong mereka kembali ke lokasi terjauh yang mungkin, kemudian melemparkan Dinding Terlarang di tepi luar tile dalam 1 klaster di sekitar.",
  str_skill_name_800400011 = "Perangkap Pengusiran Setan",
  str_skill_desc_800400011 = "Menginjak Perangkap Exorcism akan menghilangkan semua Dinding Terlarang di lapangan.",
  str_skill_desc_2900273 = "Memberikan kerusakan pada Aurorian di mana saja di medan perang dan memanggil Goldor.",
  str_skill_desc_2000303 = "Membayar Emas untuk memulihkan HP Cursed Goldor saat berada dalam 1 klaster di sekitarnya.",
  str_skill_desc_2000304 = "Saat berada dalam 1 klaster di sekitar Istvan, bayar Emas untuk memulihkan HP-nya.",
  str_skill_desc_200381101 = "Meningkatkan jangkauan gerakan, kemudian bergerak mendekati target dan memberikan kerusakan 2 kali. Gerakan ini tidak terhalang oleh rintangan.",
  str_skill_desc_200411101 = "Menyerang target 2 kali setelah bergerak, mendorong target dan meninggalkan bom, kemudian mundur hingga 3 ubin. Jika tidak ada target dalam jangkauan, meningkatkan ACT di ronde berikutnya.",
  str_skill_desc_200371101 = "Memberikan kerusakan kepada musuh dalam jangkauan 3 ubin sepanjang bentuk salib, menjatuhkan mereka, dan meninggalkan bom di tempat mereka sebelum dipukul mundur.",
