  str_skill_name_3022201 = "Eksposur Penuh",
  str_skill_desc_20022011 = "Menimbulkan <color=#00F6FF>125%</color> damage 2 kali, ditetapkan secara acak pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> unit ini. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_2002202 = "Penawaran <color=#00F6FF>130%</color> kerusakan 3 kali, ditugaskan secara acak ke musuh di dalam <color=#00F6FF>3 cluster sekitarnya</color> dari unit ini. Ketika target menerima damage lebih dari satu kali, damage dari kedua kalinya akan berkurang setengahnya.",
  str_skill_desc_2002203 = "Menimbulkan <color=#00F6FF>135%</color> damage 4 kali, ditetapkan secara acak pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color>. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_3002201 = "Mengonversi <color=#00F6FF>2</color> tile Kuning terdekat menjadi Tile Biru Gelap.",
  str_skill_desc_3002202 = "Mengonversi <color=#00F6FF>2</color> tile Kuning terdekat menjadi Tile Biru Gelap. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan tile-converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3052201 = "Mengonversi <color=#00F6FF>3</color> tile Kuning terdekat menjadi Tile Biru Gelap. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan tile-converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_desc_3052202 = "Mengonversi <color=#00F6FF>3</color> tile Kuning terdekat menjadi Tile Biru Gelap. Jika Active Skill siap di putaran sebelumnya, meningkatkan hitungan tile-converting sebanyak <color=#00F6FF>+1</color> di putaran ini.",
  str_skill_passive_name_410220 = "Refraksi Kaleidoskopik",
  str_skill_passive_name_420220 = "Refraksi Kaleidoskopik",
  str_skill_passive_name_430220 = "Refraksi Kaleidoskopik",
  str_skill_passive_desc_410220 = "Di awal setiap putaran, memberikan <color=#00F6FF>Appraisal</color> pada 1 target terjauh di lapangan selama 1 putaran. Setiap kali target dengan Appraisal terkena 1 skill Chain Combo target tunggal, 1 serangan tambahan diluncurkan pada target, menimbulkan kerusakan sebesar <color=#00F6FF>{1}</color> dari ATK Vergil.",
  str_skill_passive_desc_420220 = "Di awal setiap putaran, memberikan <color=#00F6FF>Appraisal</color> pada 1 target terjauh di lapangan selama 1 putaran. Saat memasuki Aurora Time, efek ini berlaku 1 kali tambahan. Setiap kali target dengan Appraisal terkena skill Chain Combo target tunggal, 1 serangan tambahan diluncurkan ke target, menimbulkan damage sebesar <color=#00F6FF>{1}</color> dari ATK Vergil.",
  str_skill_passive_desc_430220 = "Di awal setiap putaran, memberikan <color=#00F6FF>Appraisal</color> pada 1 target terjauh di lapangan selama 1 putaran. Saat memasuki Aurora Time, efek ini berlaku 1 kali tambahan. Setiap kali target dengan Appraisal terkena skill Chain Combo target tunggal, 1 serangan tambahan diluncurkan ke target, menimbulkan damage setara dengan <color=#00F6FF>{1}</color> dari ATK Vergil. Ketika target terkena Chain Combo Vergil, damage tambahan ini digandakan.",
  str_skill_upgrade_desc_15022012 = "Active Skill Enhancement: Jika Active Skill siap di putaran sebelumnya, konversi 1 tile Kuning tambahan menjadi Blue Dark Tile di putaran ini.",
  str_skill_upgrade_desc_15022015 = "Active Skill Enhancement: Meningkatkan jumlah tile yang dikonversi menjadi Tile Biru Gelap sebanyak 1.",
  str_skill_desc_290910114 = "Setelah bergerak, menimbulkan kerusakan dalam jangkauan tetap dan memberikan 3 tumpukan Fusion.",
  str_skill_desc_290910124 = "Setelah bergerak, menimbulkan damage dalam jangkauan tetap, memberikan 3 tumpukan Fusion, dan memanggil banyak Poison Marks.",
