  str_skill_desc_2002182 = "Menimbulkan <color=#00F6FF>155%</color> damage pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> 4 kali dalam urutan yang tetap. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_2002183 = "Menimbulkan <color=#00F6FF>165%</color> damage pada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> 5 kali dalam urutan yang tetap. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya.",
  str_skill_desc_2002184 = "Menimbulkan <color=#00F6FF>150%</color> damage kepada musuh dalam <color=#00F6FF>2 klaster di sekitar</color> 3 kali dalam urutan yang tetap. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya. Menimbulkan damage 1 kali tambahan pada target yang paling jauh.",
  str_skill_desc_2002185 = "Menimbulkan <color=#00F6FF>155%</color> damage kepada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> 4 kali dalam urutan yang tetap. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya. Menimbulkan damage 1 kali tambahan pada target yang paling jauh.",
  str_skill_desc_2002186 = "Menimbulkan <color=#00F6FF>165%</color> damage ke musuh dalam <color=#00F6FF>3 klaster di sekitar</color> 5 kali dalam urutan yang tetap. Jika target menerima damage lebih dari sekali, damage kedua dan seterusnya akan dikurangi setengahnya. Menimbulkan kerusakan 1 kali tambahan pada target terjauh.",
  str_skill_desc_2202181 = "Menimbulkan <color=#00F6FF>150%</color> kerusakan pada musuh di dalam <color=#00F6FF>2 cluster sekitarnya</color> 3 kali dalam urutan tetap. Ketika target menerima kerusakan lebih dari satu kali, kerusakan dari kedua kalinya akan berkurang setengahnya. Untuk setiap Ubin Gelap yang dilewati saat menghubungkan ubin kali ini, jangkauan Chain Combo akan melebar sebanyak 1 cluster sekitarnya.",
  str_skill_desc_2202182 = "Menimbulkan <color=#00F6FF>155%</color> damage ke musuh di dalam <color=#00F6FF>3 cluster sekitarnya</color> 4 kali dalam urutan tetap. Ketika target menerima damage lebih dari satu kali, damage dari kedua kalinya akan berkurang setengahnya. Untuk setiap Tile Gelap yang dilewati saat menghubungkan tile kali ini, jangkauan Chain Combo akan melebar sebanyak 1 cluster sekitarnya.",
  str_skill_desc_2202183 = "Menimbulkan <color=#00F6FF>165%</color> kerusakan ke musuh di dalam <color=#00F6FF>3 cluster sekitarnya</color> 5 kali dalam urutan tetap. Ketika target menerima kerusakan lebih dari satu kali, kerusakan dari kedua kalinya akan berkurang setengahnya. Untuk setiap Tile Gelap yang dilewati saat menghubungkan tile kali ini, jangkauan Chain Combo akan meluas sebanyak 1 cluster sekitarnya.",
  str_skill_desc_2202184 = "Menimbulkan <color=#00F6FF>150%</color> kerusakan ke musuh di dalam <color=#00F6FF>2 cluster sekitarnya</color> 3 kali dalam urutan tetap. Ketika target menerima kerusakan lebih dari satu kali, kerusakan dari kedua kalinya akan berkurang setengahnya. Menimbulkan kerusakan 1 kali tambahan ke target terjauh. Kerusakan tambahan ini tidak akan berkurang setengahnya ketika memberikan kerusakan ke target yang sama. Untuk setiap Tile Gelap yang dilewati saat menghubungkan tile kali ini, jangkauan Chain Combo diperluas oleh 1 cluster sekitarnya.",
  str_skill_desc_2202185 = "Menimbulkan <color=#00F6FF>155%</color> damage kepada musuh dalam <color=#00F6FF>3 klaster di sekitar</color> 4 kali dalam urutan tetap. Ketika target menerima damage lebih dari sekali, damage dari kedua kalinya dan seterusnya akan berkurang setengahnya. Menimbulkan damage 1 kali tambahan ke target terjauh. Damage tambahan ini tidak akan berkurang setengahnya ketika memberikan damage ke target yang sama. Untuk setiap Tile Gelap yang dilewati saat menghubungkan tile kali ini, jangkauan Chain Combo diperluas oleh 1 klaster di sekitar.",
  str_skill_desc_2202186 = "Menimbulkan <color=#00F6FF>165%</color> kerusakan ke musuh di dalam <color=#00F6FF>3 cluster sekitarnya</color> 5 kali dalam urutan tetap. Ketika target menerima kerusakan lebih dari satu kali, kerusakan dari kedua kalinya akan berkurang setengahnya. Menimbulkan kerusakan 1 kali tambahan ke target terjauh. Kerusakan tambahan ini tidak akan berkurang setengahnya saat memberikan kerusakan ke target yang sama. Untuk setiap Tile Gelap yang dilewati saat menghubungkan tile kali ini, jangkauan Chain Combo diperluas oleh 1 cluster sekitarnya.",
  str_skill_desc_3002181 = "Mengonversi 1 tile yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> Biru dan menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color>.",
  str_skill_desc_30021811 = "Mengubah 1 ubin yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link> Biru dan menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>.",
  str_skill_desc_3402181 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Menimbulkan <color=#00F6FF>{1}%</color> kerusakan ke <color=#00F6FF>5 petak dalam bentuk silang</color> yang berpusat pada 1 petak yang dipilih.",
  str_skill_desc_3412181 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Penawaran <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada 1 ubin yang dipilih.",
  str_skill_desc_3402182 = "Mengubah 1 tile yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link> Biru dan menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>5 tile dalam bentuk silang</color>. Untuk setiap 5 poin Modal, dapatkan 1 Modal tambahan sebagai dividen.",
  str_skill_desc_3412182 = "Mengubah 1 ubin yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> Biru dan menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>. Untuk setiap 5 poin Modal, dapatkan 1 Modal tambahan sebagai dividen.",
  str_skill_desc_30021812 = "Mengonversi 1 tile yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Tile Biru Gelap</u></color></link> dan menimbulkan <color=#00F6FF>150%</color> damage pada <color=#00F6FF>5 tile dalam bentuk silang</color>.",
  str_skill_desc_300218112 = "Mengubah 1 ubin yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link> Biru dan menimbulkan <color=#00F6FF>150%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>.",
  str_skill_desc_34021812 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Menimbulkan <color=#00F6FF>150%</color> kerusakan ke <color=#00F6FF>5 petak dalam bentuk silang</color> yang berpusat pada 1 petak yang dipilih.",
  str_skill_desc_34121812 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Menimbulkan <color=#00F6FF>150%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> yang berpusat pada 1 ubin yang dipilih.",
  str_skill_desc_34021822 = "Mengubah 1 ubin yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Dark Tile Biru</u></color></link> dan menimbulkan <color=#00F6FF>150%</color> kerusakan pada <color=#00F6FF>5 ubin dalam bentuk silang</color>. Untuk setiap 5 poin Modal, dapatkan 1 Modal tambahan sebagai dividen.",
  str_skill_desc_34121822 = "Mengubah 1 ubin yang dipilih menjadi <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link> Biru dan menimbulkan <color=#00F6FF>150%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>. Untuk setiap 5 poin Modal, dapatkan 1 Modal tambahan sebagai dividen.",
  str_skill_passive_desc_410218 = "Sheol memulai pertempuran dengan <link=\"510218\"><#FFAE07><u>Strategi Investasi</u></color></link> dan dapat mengumpulkan Modal untuk memilih strategi investasi dan mendapatkan kemampuan bertarung yang sesuai. (Capai Level Peralatan Lv. 3/6/10 untuk membuka strategi investasi \"Digerakkan oleh Kabut,\" \"Kekayaan Menghancurkan,\" dan \"Serangan Modal.\")",
  str_skill_passive_desc_413218 = "Sheol memulai pertempuran dengan <link=\"513218\"><#FFAE07><u>Strategi Investasi</u></color></link> dan dapat mengumpulkan Modal untuk memilih strategi investasi dan mendapatkan kemampuan bertarung yang sesuai. Setiap poin Modal yang diperoleh setelah menyelesaikan putaran investasi kedua meningkatkan ATK Sheol sebesar 1%, hingga 40 poin. (Capai Level Peralatan Lv. 3/6/10 untuk membuka strategi investasi \"Digerakkan oleh Kabut,\" \"Kekayaan Menghancurkan,\" dan \"Serangan Modal.\")",
  str_skill_passive_desc_416218 = "Sheol memulai pertempuran dengan <link=\"516218\"><#FFAE07><u>Strategi Investasi</u></color></link> dan dapat mengumpulkan Modal untuk memilih strategi investasi dan mendapatkan kemampuan bertarung yang sesuai. Sheol memulai pertempuran dengan 5 Modal. Setiap poin Modal yang diperoleh setelah menyelesaikan putaran investasi kedua meningkatkan ATK Sheol sebesar 1%, hingga 40 poin. (Capai Level Peralatan Lv. 3/6/10 untuk membuka strategi investasi \"Digerakkan oleh Kabut,\" \"Kekayaan Menghancurkan,\" dan \"Serangan Modal.\")",
  str_skill_passive_desc_430218 = "Sheol memulai pertempuran dengan <link=\"530218\"><#FFAE07><u>Strategi Investasi</u></color></link> dan dapat mengumpulkan Modal untuk memilih strategi investasi dan mendapatkan kemampuan bertarung yang sesuai. Setelah menyelesaikan putaran investasi pertama, dia dapat melakukan putaran investasi kedua untuk mendapatkan kemampuan bertarung yang tidak dia miliki di putaran investasi pertama. (Capai Level Peralatan Lv. 3/6/10 untuk membuka strategi investasi \"Digerakkan oleh Kabut,\" \"Kekayaan Menghancurkan,\" dan \"Serangan Modal.\")",
  str_skill_passive_desc_433218 = "Sheol memulai pertempuran dengan <link=\"533218\"><#FFAE07><u>Strategi Investasi</u></color></link> dan dapat mengumpulkan Modal untuk memilih strategi investasi dan mendapatkan kemampuan bertarung yang sesuai. Setelah menyelesaikan putaran investasi pertama, dia dapat melakukan putaran investasi kedua untuk mendapatkan kemampuan bertarung yang tidak dia miliki di putaran investasi pertama. Setiap poin Modal yang diperoleh setelah menyelesaikan putaran investasi kedua meningkatkan ATK Sheol sebesar 1%, hingga 40 poin. (Capai Level Peralatan Lv. 3/6/10 untuk membuka strategi investasi \"Digerakkan oleh Kabut,\" \"Kekayaan Menghancurkan,\" dan \"Serangan Modal.\")",
  str_skill_passive_desc_436218 = "Sheol memulai pertempuran dengan <link=\"536218\"><#FFAE07><u>Strategi Investasi</u></color></link> dan dapat mengumpulkan Modal untuk memilih strategi investasi dan mendapatkan kemampuan bertarung yang sesuai. Setelah menyelesaikan putaran investasi pertama, dia dapat melakukan putaran investasi kedua untuk mendapatkan kemampuan bertarung yang tidak dia miliki di putaran investasi pertama. Sheol memulai pertempuran dengan 5 Modal. Setiap poin Modal yang diperoleh setelah menyelesaikan putaran investasi kedua meningkatkan ATK Sheol sebesar 1%, hingga 40 poin. (Capai Level Peralatan Lv. 3/6/10 untuk membuka strategi investasi \"Digerakkan oleh Kabut,\" \"Kekayaan Menghancurkan,\" dan \"Serangan Modal.\")",
  str_skill_upgrade_desc_16021813 = "Peningkatan Keterampilan Peralatan: Setiap poin Modal yang diperoleh setelah menyelesaikan putaran investasi kedua meningkatkan ATK Sheol sebesar 1%, hingga 40 poin. (membuka kunci di Ascension III)",
  str_skill_upgrade_desc_16021816 = "Sheol memulai pertempuran dengan 5 Capital. Untuk setiap 5 poin Capital yang dia miliki saat menggunakan Skill Aktifnya, dia mendapatkan 1 Capital tambahan sebagai dividen.",
  str_skill_name_53920111 = "Normal Attack",
  str_skill_desc_53920111 = "Menyerang musuh dengan Normal Attack setelah bergerak, menimbulkan banyak kerusakan pada mereka.",
  str_skill_desc_53920112 = "Menimbulkan damage pada musuh dalam 2 klaster di sekitar setelah bergerak.",
  str_skill_desc_53920214 = "Setelah tim melewati Tile Gelap, Sheol memberikan kerusakan pada musuh dalam 2 klaster di sekitarnya 2 kali.",
  str_skill_upgrade_refine_desc_16021811 = "<color=#00F6FF>Varian Skill Aktif Baru</color>: <color=#FFFF00>Cooldown skill -1 setelah casting</color>. Skill Aktif hanya menimbulkan kerusakan dan tidak menghasilkan Petak Gelap Biru apa pun.",
  str_skill_upgrade_refine_desc_16021812 = "Active Skill Enhancement: Meningkatkan damage Active Skill sebesar <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16021813 = "Peningkatan Keterampilan Peralatan: Mengurangi biaya poin Modal untuk putaran investasi kedua sebanyak 1 poin.",
  str_skill_name_70011191 = "Terbuang: Devour - Wholesome",
  str_skill_desc_70011191 = "Saat target berada dalam jangkauan, Aurorian dan Hantu dalam dua kluster di arah depan akan dimangsa. Aurorian kemudian menerima damage dan akan dimuntahkan ke tepi papan.",
  str_skill_name_70011192 = "Terbuang: Devour - Hancurkan",
  str_skill_desc_70011192 = "Memberikan damage dalam jumlah besar kepada target yang berada dalam jangkauan, dan hantu di sekitar target akan tersingkir dalam sekejap.",
  str_skill_name_70011193 = "Terbuang: Devour - Hantu Army",
  str_skill_desc_70011193 = "Memanggil hantu dalam jumlah banyak saat target berada dalam jangkauan dan memperkuat semua hantu di medan tempur.",
  str_skill_name_70011195 = "Terbuang: Devour - Wholesome",
  str_skill_desc_70011195 = "Saat target berada dalam jangkauan, Aurorian dan Hantu dalam dua kluster di arah depan akan dimangsa, menimbulkan damage sebenarnya pada Aurorian. Semakin banyak Hantu yang dimangsa, semakin tinggi pula damage yang ditimbulkan. Kemudian, Aurorian akan dimuntahkan ke tepi papan.",
  str_skill_name_200440103 = "Pukulan Penghancur",
  str_skill_name_200450103 = "Blast Barrage",
  str_skill_name_200460103 = "Serangan Bersenjata",
  str_skill_name_200460104 = "Total Annihilation",
  str_skill_desc_200440103 = "Mengayunkan senjata untuk memberikan damage pada Aurorian.",
  str_skill_desc_200450103 = "Memberikan kerusakan pada Aurorian dalam bentuk salib hingga jangkauan maksimum.",
  str_skill_desc_200460103 = "Memberikan kerusakan pada Aurorian setelah bergerak.",
  str_skill_desc_200460104 = "Meluncurkan serangan menembus ke arah Aurorian setelah bergerak, memberikan kerusakan pada musuh dan sekutu, lalu kehilangan sejumlah HP.",
  str_skill_name_8004003 = "Meledak saat Aurorian mendekatinya. Jika dibiarkan, ia akan meledak setelah sejumlah putaran berlalu dan menghasilkan Dinding Terlarang sepanjang 1 ubin di sekelilingnya.",
  str_skill_desc_8004039 = "Peningkatan kerusakan di ronde ini: Dreadblades menggunakan pedang untuk menyerang target dalam jangkauan 2 kali, menimbulkan kerusakan yang sangat tinggi.",
  str_skill_name_8004039 = "Double Slash+",
  str_skill_desc_8004055 = "Vilanor bergegas dan melancarkan serangan, menimbulkan kerusakan dan melempar Dinding Terlarang sepanjang 5 ubin secara horizontal di samping Aurorian. kemudian teleportasi ke lokasi baru.",
  str_skill_desc_8004057 = "Vilanor bergegas dan melancarkan serangan, menimbulkan kerusakan dan melempar Dinding Terlarang sepanjang 5 ubin secara vertikal di samping Aurorian, kemudian teleportasi ke lokasi baru.",
  str_skill_desc_8004051 = "Vilanor bergegas dan melancarkan serangan, menimbulkan kerusakan dan melemparkan Dinding Terlarang sepanjang 3 ubin secara horizontal di samping Aurorian, kemudian teleportasi kembali ke lokasi asalnya.",
  str_skill_desc_8004053 = "Vilanor bergegas dan melancarkan serangan, menimbulkan kerusakan dan melemparkan Dinding Terlarang sepanjang 3 ubin secara vertikal di samping Aurorian, kemudian teleportasi kembali ke lokasi asalnya.",
  str_skill_name_8004012 = "Panggil Darkwasp Vinesmark+",
  str_skill_desc_8004012 = "Memanggil 1 Darkwasp dan 1 Vinesmark ke dalam pertempuran setiap ronde.",
  str_skill_desc_8004022 = "Setelah menginjak Exorcism Trap, mulai dari ronde berikutnya, Forbidden Walls di sekitar Aurorian akan meluas kembali ke 3 kluster sekitarnya.",
  str_skill_desc_8004040 = "Menginjak Perangkap Pengusiran akan memanggil Dinding Terlarang di sekitar musuh.",
  str_skill_desc_8004050 = "Menginjak Perangkap Pengusiran akan menghilangkan semua Dinding Terlarang dalam 2 klaster di sekitarnya.",
  str_skill_name_290640101 = "Injak-injak",
  str_skill_name_290640102 = "Output Efisien",
  str_skill_name_290640103 = "Penggantian Komponen",
  str_skill_desc_290640101 = "Menghabiskan persentase tertentu dari HP sendiri dan semua tumpukan Armor Mekanik setelah bergerak untuk menyerang target dalam jarak 2 tile di depannya. Jika target berada di sebelah Blaugm, ia akan mendorong target mundur sejauh 1 tile. Setelah menyerang, ia memulihkan HP sendiri berdasarkan jumlah tumpukan Armor Mekanik yang dihabiskan.",
  str_skill_desc_290640102 = "Memberikan kerusakan kepada semua target dalam bentuk kipas. Semakin dekat target, semakin besar kerusakan yang ditimbulkan.",
  str_skill_desc_290640103 = "Blaugm meningkatkan kekuatan, secara permanen meningkatkan ATK, DEF, dan Max HP, dan mendapatkan sejumlah tumpukan Armor Mekanis.",
  str_skill_name_29063011 = "Kecepatan Angin yang Menekan",
  str_skill_name_29063012 = "Menarget lokasi Aurorian dan bergerak cepat ke tepi papan, memberikan kerusakan pada semua musuh dalam jangkauan di sepanjang jalan.",
  str_skill_name_29063013 = "Modifikasi Tubuh",
  str_skill_desc_29063011 = "Bergerak menuju Aurorian dan memberikan kerusakan pada musuh dalam jarak 2 ubin di depannya.",
  str_skill_desc_29063012 = "Data Strike",
  str_skill_desc_29063013 = "Ulysses menggunakan Guardian Prototype untuk memberikan kerusakan pada Aurorian di mana saja di medan perang.",
  str_skill_name_2002211 = "Letusan Biner",
  str_skill_name_2002212 = "Letusan Biner",
  str_skill_name_2002213 = "Letusan Biner",
  str_skill_desc_2002211 = "Bool menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2002212 = "Bool menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 Tile dalam bentuk wajik</color>.",
  str_skill_desc_2002213 = "Bool menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>24 tile dalam bentuk wajik</color>.",
  str_skill_name_300221 = "Tarif Kematian",
  str_skill_name_306221 = "Tarif Kematian",
  str_skill_name_320221 = "Tarif Kematian",
  str_skill_name_326221 = "Tarif Kematian",
  str_skill_name_340221 = "Tarif Kematian",
  str_skill_name_346221 = "Tarif Kematian",
  str_skill_desc_300221 = "Pilih 1 Tile apa saja, lalu pilih 3 Tile dalam <color=#00F6FF>1 klaster di sekitar</color> untuk mengubahnya menjadi <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>. Bool menimbulkan <color=#00F6FF>{1}%</color> damage pada area ini.",
  str_skill_desc_306221 = "Memilih 1 ubin mana saja, kemudian memilih 4 ubin dalam <color=#00F6FF>12 ubin dalam bentuk berlian</color> di sekitarnya untuk mengubahnya menjadi <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>. Bool menimbulkan <color=#00F6FF>{1}%</color> kerusakan pada area ini.",
  str_skill_desc_320221 = "Memilih 1 Tile apa saja, kemudian memilih 3 Tile dalam <color=#00F6FF>1 klaster di sekitar</color> untuk mengubahnya menjadi <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>. Bool menimbulkan <color=#00F6FF>{1}%</color> damage pada area ini. Mendapatkan 1 poin komputasi setiap kali damage diberikan.",
  str_skill_desc_326221 = "Memilih 1 ubin mana saja, kemudian memilih 4 ubin dalam <color=#00F6FF>12 ubin dalam bentuk berlian</color> di sekitarnya untuk mengubahnya menjadi <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>. Bool memberikan <color=#00F6FF>{1}%</color> kerusakan ke area ini. Mendapatkan 1 poin komputasi setiap kali kerusakan diberikan.",
  str_skill_desc_340221 = "Memilih 1 ubin apa saja, kemudian memilih 3 ubin dalam <color=#00F6FF>1 klaster sekitar</color> di sekitarnya untuk mengubahnya menjadi <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>. Bool menimbulkan <color=#00F6FF>250%</color> kerusakan pada area ini. Mendapatkan 1 poin komputasi setiap kali kerusakan ditimbulkan.",
  str_skill_desc_346221 = "Memilih 1 ubin mana saja, kemudian memilih 4 ubin dalam <color=#00F6FF>12 ubin dalam bentuk berlian</color> di sekitarnya untuk mengubahnya menjadi <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>. Bool memberikan <color=#00F6FF>250%</color> kerusakan ke area ini. Mendapatkan 1 poin perhitungan setiap kali kerusakan diberikan.",
  str_skill_passive_name_410221 = "Angka Sihir Nanometrik",
  str_skill_passive_name_430221 = "Angka Sihir Nanometrik",
  str_skill_passive_name_440221 = "Angka Sihir Nanometrik",
  str_skill_passive_name_443221 = "Angka Sihir Nanometrik",
  str_skill_passive_desc_410221 = "Mendapatkan 1 poin komputasi setiap kali melewati <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. Setiap poin komputasi meningkatkan kerusakan Bool sebesar <color=#00F6FF>{1}</color>, dan setengah dari poin komputasi akan dipertahankan di akhir putaran.",
  str_skill_passive_desc_430221 = "Mendapatkan 1 poin komputasi setiap kali melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>. Setiap poin komputasi meningkatkan kerusakan Bool sebesar <color=#00F6FF>{1}</color>, dan setengah dari poin komputasi akan dipertahankan di akhir ronde. Jika tidak kurang dari <color=#00F6FF>3</color> poin komputasi setelah aksi Bool berakhir, Bool memberikan kerusakan tambahan <color=#00F6FF>100%</color> kepada musuh yang paling sering menerima kerusakan darinya.",
  str_skill_passive_desc_440221 = "Mendapatkan 1 poin komputasi setiap kali melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>. Setiap poin komputasi meningkatkan kerusakan Bool sebesar <color=#00F6FF>6%</color>, dan setengah dari poin komputasi akan dipertahankan di akhir ronde. Jika tidak kurang dari <color=#00F6FF>3</color> poin komputasi setelah aksi Bool berakhir, Bool memberikan kerusakan tambahan sebesar <color=#00F6FF>100%</color> kepada musuh yang paling sering menerima kerusakan darinya.",
  str_skill_passive_desc_443221 = "Mendapatkan 1 poin komputasi setiap kali melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>. Setiap poin komputasi meningkatkan kerusakan Bool sebesar <color=#00F6FF>6%</color>, dan setengah dari poin komputasi akan dipertahankan di akhir ronde. Jika tidak kurang dari <color=#00F6FF>3</color> poin komputasi setelah aksi Bool berakhir, Bool memberikan kerusakan tambahan sebesar <color=#00F6FF>120%</color> kepada musuh yang telah menerima kerusakan terbanyak darinya.",
  str_skill_upgrade_refine_desc_16022111 = "Peningkatan Keterampilan Peralatan: Setiap titik perhitungan meningkatkan kerusakan Bool sebesar <color=#00F6FF>6%</color>.",
  str_skill_upgrade_refine_desc_16022112 = "Active Skill Enhancement: Meningkatkan faktor kerusakan sebesar <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16022113 = "Peningkatan Keterampilan Peralatan: Meningkatkan kerusakan tambahan yang diberikan oleh Bool menjadi <color=#00F6FF>120%</color>.",
  str_skill_upgrade_desc_16022113 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16022116 = "Active Skill Enhancement: Jangkauan meluas hingga 13 tile dalam bentuk berlian, dan jumlah tile yang dapat dipilih meningkat menjadi 4.",
  str_skill_name_802401 = "Keahlian: Skybreaker",
  str_skill_name_802402 = "Keahlian: Hapus",
  str_skill_name_802403 = "Keahlian: Vitalisasi",
  str_skill_name_802404 = "Knack: Gempa",
  str_skill_name_802405 = "Keahlian: Disorientasi",
  str_skill_desc_802401 = "Potongan logam ini dapat melipat kain ruang dan mengangkut Aurorian ke ubin mana pun yang dapat dilalui.",
  str_skill_desc_802402 = "Sisa-sisa tanah longsor yang menghancurkan sebuah kota. Ini dapat menghilangkan Batu atau Dinding Terlarang dari 1 tile mana pun.",
  str_skill_desc_802403 = "Sebuah embun yang ditinggalkan oleh bintang-bintang yang bergerak. Menggunakan ini akan meningkatkan poin kekuatan Aurorian sebanyak 7.",
  str_skill_desc_802404 = "Senjata bubuk mesiu dari timur yang misterius. Menjatuhkan semua musuh dalam 1 klaster di sekitar ke jarak terjauh dan memberikan kerusakan pada mereka.",
  str_skill_desc_802405 = "Ramuan dapat digunakan untuk menyelamatkan orang, atau untuk meracuni mereka. Membuat target terkena Stun selama 1 putaran.",
  str_skill_desc_80240131 = "Memanggil 3 Shadowgeist Rune sekaligus, masing-masing akan berubah menjadi Shadowgeist dengan kemampuan penyembuhan setelah 3 putaran.",
  str_skill_desc_8024441 = "Murkmite menyerang target dalam jangkauan dan mengurangi poin kekuatan target sebanyak 2.",
  str_skill_name_802431111 = "Kehendak Jahat: Panggilan",
  str_skill_desc_802431111 = "Memanggil beberapa musuh ke area terdekat untuk memberikan dukungan.",
  str_skill_desc_8024150 = "Collector menimbulkan damage sebesar 30% HP Maks pada musuh terdekat. Membutuhkan 5 poin kekuatan.",
  str_skill_desc_8024151 = "Collector melakukan perbaikan mandiri untuk memulihkan 25% HP Maks. Membutuhkan 3 poin kekuatan.",
  str_skill_desc_8024152 = "Collector mengeluarkan partikel energi, membentuk 3 lapis Shield yang dapat menahan damage. Membutuhkan 1 poin kekuatan.",
  str_skill_name_80242801 = "Jebakan Sangkar",
  str_skill_desc_80242801 = "Sebuah kandang yang kokoh, tampaknya tak bisa dihancurkan. Musuh di dalamnya dapat mentransfer sebagian dari kerusakan yang diterimanya ke musuh inti. Menghabiskan 3 poin kekuatan untuk membebaskan musuh dari kandang.",
  str_skill_upgrade_desc_16022313 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16022316 = "Peningkatan Skill Aktif: Mengurangi cooldown skill sebanyak <color=#FFFF00>1</color> putaran. Meningkatkan jumlah Dark Tiles yang dihasilkan menjadi 5.",
  str_skill_name_2002231 = "Tarian Naga yang Diberkati",
