  str_skill_passive_name_420223 = "Lonceng Timbangan Naga",
  str_skill_passive_name_430223 = "Lonceng Sisik Naga",
  str_skill_desc_2002231 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_2002232 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2002233 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>24 tile dalam bentuk wajik</color>.",
  str_skill_desc_3002231 = "Memilih 1 dari 8 arah dan mengonversi <color=#00F6FF>semua ubin</color> di garis itu menjadi Kuning, dengan prioritas menciptakan <color=#00F6FF>3</color> <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link> di arah yang dipilih.",
  str_skill_desc_3062231 = "Memilih 1 dari 8 arah dan mengonversi <color=#00F6FF>semua ubin</color> di garis itu menjadi Kuning, dengan prioritas menciptakan <color=#00F6FF>5</color> <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> di arah yang dipilih.",
  str_skill_passive_desc_410223 = "Serangan normal Chen'ni menargetkan musuh dengan perbedaan persentase HP terbesar dari tim, menimbulkan damage setara dengan <color=#00F6FF>{1}</color> dari rata-rata ATK tim.",
  str_skill_passive_desc_420223 = "Serangan normal Chen'ni menargetkan musuh dengan perbedaan persentase HP terbesar dari tim, menimbulkan kerusakan setara dengan <color=#00F6FF>{1}</color> dari rata-rata ATK tim. Memicu <color=#00F6FF>1.5×</color> kerusakan setiap kali melewati <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>.",
  str_skill_passive_desc_430223 = "Serangan normal Chen'ni menargetkan musuh dengan perbedaan persentase HP terbesar dari tim, menimbulkan kerusakan setara dengan <color=#00F6FF>{1}</color> dari rata-rata ATK tim. Memicu <color=#00F6FF>1.5×</color> kerusakan setiap kali melewati <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. Semakin besar perbedaan persentase HP antara target dan tim, semakin tinggi kerusakannya, dengan peningkatan maksimum sebesar <color=#00F6FF>50%</color>.",
  str_skill_name_70011211 = "Ditinggalkan: Kekuatan Dominan",
  str_skill_name_70011212 = "Ditinggalkan: Gelombang Mengamuk",
  str_skill_upgrade_desc_15022412 = "Mengubah Skill Aktif menjadi <color=#FFFF00>Serangan Preemptive</color>, tersedia saat memasuki pertempuran. Dapatkan 10 Api Penjaga Fiendling di awal pertempuran.",
  str_skill_upgrade_desc_15022415 = "Peningkatan Keterampilan Peralatan: Mendapatkan Api Penjaga Fiendling setiap kali melewati ubin dari elemen apa pun.",
  str_skill_name_2002241 = "Api Beladiri",
  str_skill_name_2002242 = "Api Beladiri",
  str_skill_name_2002243 = "Martial Flame",
  str_skill_name_300224 = "Granat Kejutan",
  str_skill_name_3002241 = "Variasi Granat Kejutan I",
  str_skill_name_3002242 = "Varian Granat Kejutan II",
  str_skill_passive_name_410224 = "Upaya Bersama",
  str_skill_passive_name_412224 = "Upaya Bersama",
  str_skill_passive_name_415224 = "Upaya Bersama",
  str_skill_desc_2002241 = "Melempar Ah Ding, menimbulkan <color=#00F6FF>{1}%</color> damage ke tile terdekat dari musuh terdekat.",
  str_skill_desc_2002242 = "Melempar Ah Ding, menimbulkan <color=#00F6FF>{1}%</color> damage pada tile terdekat dari musuh terdekat dan 30% damage splash pada <color=#00F6FF>4 tile di sekitar dalam bentuk silang</color>.",
  str_skill_desc_2002243 = "Melempar Ah Ding, menimbulkan <color=#00F6FF>{1}%</color> damage pada tile terdekat dari musuh terdekat dan 30% damage splash pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_300224 = "Memilih sebuah tile sebagai pusat Chain Combo dan mengurangi persyaratan pemicu Chain Combo sebanyak 3, hanya berlaku untuk putaran ini saja.",
  str_skill_desc_3002241 = "<color=#FFFF00>Setelah casting, mengurangi cooldown skill sebanyak 1</color>, dan jika tidak ada Chain Combo yang dilepaskan putaran ini, serangan normal dapat diluncurkan secara diagonal. Mendapatkan 2 Api Penjaga Fiendling dengan setiap serangan normal.",
  str_skill_desc_3002242 = "<color=#FFFF00>Setelah casting, meningkatkan cooldown skill sebanyak 1</color>. Memilih sebuah tile untuk menjadi pusat Chain Combo di putaran ini, kemudian menimbulkan <color=#00F6FF>100%</color> kerusakan. Setiap Fiendling Guardian Flame meningkatkan kerusakan sebesar 10%. Mengurangi persyaratan pemicu Chain Combo sebanyak 3 untuk putaran ini dan mendapatkan efek knockback tambahan.",
  str_skill_passive_desc_410224 = "Mendapatkan 1 Fiendling Guardian Flame untuk setiap Tile Merah yang dilalui. Setiap Flame meningkatkan damage dari Chain Combo berikutnya sebesar <color=#00F6FF>{1}</color>, yang akan direset setelah Chain Combo dilepaskan.",
  str_skill_passive_desc_412224 = "Mendapatkan 1 Fiendling Guardian Flame untuk setiap tile Merah yang dilalui. Setiap Flame meningkatkan damage Chain Combo berikutnya sebesar <color=#00F6FF>{1}</color>, yang akan direset setelah Chain Combo dilepaskan. Dapatkan 10 Fiendling Guardian Flames di awal pertempuran.",
  str_skill_passive_desc_415224 = "Mendapatkan 1 Api Penjaga Fiendling untuk setiap ubin yang dilalui. Setiap Api meningkatkan damage dari Chain Combo berikutnya sebesar <color=#00F6FF>{1}</color>, yang akan direset setelah Chain Combo dilepaskan. Dapatkan 10 Api Penjaga Fiendling di awal pertempuran.",
  str_skill_desc_9997040 = "Mengubah 2 ubin yang dipilih menjadi ubin berwarna, mendapatkan 1 energi untuk setiap ubin yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 60 energi; hingga 2 kesempatan dapat disimpan.",
  str_skill_desc_9997041 = "Memilih area 3x3 dan menghapus semua ubin Biru di dalamnya, mendapatkan 1 energi untuk setiap ubin yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 50 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_desc_9997042 = "Memilih area 3x3 dan menghapus semua ubin Merah di dalamnya, mendapatkan 1 energi untuk setiap ubin yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 50 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_desc_9997043 = "Memilih area 3x3 dan menghapus semua ubin Hijau di dalamnya, mendapatkan 1 energi untuk setiap ubin yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 50 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_desc_9997044 = "Memilih area 3x3 dan menghapus semua ubin Kuning di dalamnya, mendapatkan 1 energi untuk setiap ubin yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 50 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_desc_9997045 = "Mereset semua tile di lapangan, mendapatkan 1 energi untuk setiap tile yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 80 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_desc_9997046 = "Memilih 1 warna dan mengatur ulang semua ubin dengan warna ini di lapangan, mendapatkan 1 energi untuk setiap ubin yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 80 energi; hingga 2 kesempatan dapat disimpan.",
  str_skill_desc_9997047 = "Memilih 1 tile dan menghapus 4 tile terdekat dengan warna yang sama. Mendapatkan 1 energi untuk setiap tile yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 60 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_name_5066101 = "Kaleidogem",
  str_skill_desc_5066101 = "Mengubah semua ubin di lapangan menjadi ubin berwarna.",
  str_skill_name_5060801 = "Wallbreaker",
  str_skill_desc_5060801 = "Menghabiskan 2 putaran untuk segera menggunakan skill dukungan faksi Lv.2. Hanya bisa digunakan satu kali setiap putaran.",
  str_skill_name_20047011 = "Shuttle Strike",
  str_skill_desc_20047011 = "Setelah bergerak, menyerang target pada 4 tile sekitarnya dalam bentuk silang, kemudian melewati target ke tile di sekitarnya, dengan mengutamakan tile langsung di belakang target.",
  str_skill_name_5412015 = "Panggil: Gloom Ghoul",
  str_skill_desc_5412015 = "Memanggil Gloom Ghoul ke dalam pertempuran di setiap putaran.",
  str_skill_name_9997040 = "Sword of Radiance",
  str_skill_name_9997046 = "Shield of Radiance",
  str_skill_name_9997047 = "Lance of Radiance",
  str_skill_desc_5064701 = "Memilih area 5x5 dan menghapus semua ubin Biru di dalamnya, mendapatkan 1 energi untuk setiap ubin yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 40 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_desc_5064702 = "Memilih area 5x5 dan menghapus semua ubin Merah di dalamnya, mendapatkan 1 energi untuk setiap ubin yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 40 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_desc_5064703 = "Memilih area 5x5 dan menghapus semua tile Hijau di dalamnya, mendapatkan 1 energi untuk setiap tile yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 40 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_desc_5064704 = "Memilih area 5x5 dan menghapus semua tile Kuning di dalamnya, mendapatkan 1 energi untuk setiap tile yang dihapus. Mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 40 energi; hingga 3 kesempatan dapat disimpan.",
  str_skill_name_5411002 = "Tarian Naga yang Diberkati",
  str_skill_desc_5411002 = "Menimbulkan damage ke 24 ubin dalam bentuk wajik.",
  str_skill_name_5411003 = "Panggilan: Fiendling",
  str_skill_desc_5411003 = "Memanggil 2 Fiendling: Tikus ke medan tempur.",
  str_skill_desc_5411012 = "Nozard mengumpulkan kekuatan untuk Rising Tide yang segera datang, memanggil beberapa Gloom Ghouls di depannya.",
  str_skill_desc_5411020 = "Gertzurde memanggil 4 Gertzurde's Servant yang tidak bergerak ke medan tempur secara acak.",
  str_skill_desc_5411021 = "Gertzurde menyerang target dalam area efek dan menerapkan 1 Penetrability Mark. Semakin banyak tanda, semakin rendah DEF target. Juga memanggil 2 Servant Gertzurde.",
  str_skill_desc_5411022 = "Gertzurde mengaum dan menerapkan 2 Penetrability Mark ke target dalam area efek. Semakin banyak tanda, DEF target semakin rendah. Juga memanggil 2 Servant Gertzurde.",
  str_skill_desc_5411023 = "Gertzurde meledakkan Penetrability Mark pada target untuk menimbulkan kerusakan besar. Semakin banyak Mark yang dimiliki target, semakin besar kerusakan yang mereka terima. Juga memanggil 2 Servant Gertzurde.",
  str_skill_desc_5411025 = "Gertzurde memanggil 4 Gertzurde's Servant yang tidak bergerak ke medan tempur secara acak.",
  str_skill_desc_5411026 = "Gertzurde dengan panik menyerang target dalam area efek 2 kali dan menerapkan 2 Tanda Penetrabilitas. Semakin banyak tanda, DEF target semakin rendah. Juga memanggil 2 Servant Gertzurde.",
  str_skill_desc_5411027 = "Gertzurde mengeluarkan raungan terakhirnya dan menerapkan 3 Tanda Penetrabilitas ke target dalam area efek. Semakin banyak tanda, DEF target semakin rendah. Juga memanggil 2 Servant Gertzurde.",
  str_skill_desc_5411004 = "Memanggil Perangkap Sangkar.",
  str_skill_name_5411031 = "Mengikat",
  str_skill_desc_5411031 = "Garis antara kenyataan dan fantasi menjadi kabur di alam ilusi ini...",
  str_skill_name_5064701 = "Floating Icer",
  str_skill_name_5064702 = "Floating Scorcher",
  str_skill_name_5064703 = "Floating Forestwrath",
  str_skill_name_5064704 = "Floating Thunder",
  str_skill_name_5065501 = "Jebakan Peningkatan Kerusakan",
  str_skill_name_5065601 = "Toples Permen Energi",
  str_skill_name_5065801 = "Mobile Energizer",
  str_skill_desc_5065501 = "Setelah dihapus, damage Chain Combo meningkat sebesar 35% pada ronde ini.",
  str_skill_desc_5065601 = "Setelah dilepas, memberikan 1 kesempatan penggunaan untuk Gear Caelestite Spesial acak.",
  str_skill_desc_5065801 = "Setelah penghapusan, memberikan 3 putaran tambahan.",
  str_skill_name_29093013 = "Langkah Tahun Baru",
  str_skill_desc_29093013 = "Nian melompat maju 3 ubin, memberikan kerusakan pada 1 klaster di sekitar ubin pendaratan dan mendorong musuh dalam jangkauan ke kedua sisi. Jika Nian sampai di gerbang, gerbang tersebut akan hancur, memungkinkan Nian untuk masuk.",
  str_skill_name_7001125103 = "Forsaken: Lolongan Marah",
  str_skill_desc_7001125103 = "Forsaken: Cerritus memberikan kerusakan kepada semua Aurorian di lapangan, meningkatkan ACT-nya sendiri, dan memanggil kerikil.",
  str_skill_name_7001125104 = "Terlantar: Hancuran Menghancurkan",
  str_skill_desc_7001125104 = "Terlupakan: Cerritus menghasilkan ubin yang melemah dan menyerang Aurorian, menjatuhkan mereka dan menghancurkan kerikil di jalurnya.",
  str_skill_name_7001125105 = "Forsaken: Gempa yang Menghancurkan",
  str_skill_desc_7001125105 = "Terlupakan: Cerritus memukul 2 ubin di depannya setelah bergerak, memberikan kerusakan besar dan menghasilkan ubin yang melemah.",
  str_skill_name_7001126103 = "Forsaken: Lepaskan Negativitas",
  str_skill_desc_7001126103 = "Forsaken: Chandra bergerak menjauh dari Aurorian dan kemudian memberikan kerusakan pada Aurorian dalam 2 klaster di sekitarnya.",
  str_skill_name_7001126104 = "Forsaken: Proyek Emosi Negatif",
  str_skill_desc_7001126104 = "Forsaken: Chandra menimbulkan kerusakan pada semua Aurorian yang ada di medan.",
  str_skill_name_80150311 = "Rock",
  str_skill_desc_80150311 = "Batu ini telah menghalangi jalan di sini cukup lama. Gunakan 2 Force Points untuk menghapusnya.",
  str_skill_name_290940103 = "Tombak Shadowfire",
  str_skill_desc_290940103 = "Ira memberikan kerusakan pada Aurorian dan menghasilkan Shadowfire pada ubin terluar lapangan hingga jangkauan maksimum di area berbentuk salib yang berpusat di sekitar Aurorian.",
  str_skill_name_290940104 = "Ledakan Api",
  str_skill_desc_290940104 = "Ira memberikan kerusakan pada Aurorian dalam 2 klaster di sekitarnya.",
  str_skill_name_290940105 = "Meteor Murka",
  str_skill_desc_290940105 = "Ira memanggil meteorit untuk menyerang posisi di mana Aurorian berada di putaran sebelumnya, menimbulkan kerusakan mematikan dan menghancurkan ubin, meninggalkan 4 ubin rusak dalam bentuk silang.",
  str_skill_name_200480103 = "Inferno Shadowfire",
  str_skill_desc_200480103 = "Shadowfire memberikan kerusakan pada Aurorian dalam jangkauan dan berpindah ke sisi berlawanan dari lapangan. Jika tidak dapat menyerang pemain, ia berpindah searah jarum jam di sepanjang kluster terluar lapangan, bergerak 2 petak.",
  str_skill_name_300226 = "Ini adalah Dunia Kodok",
  str_skill_name_200226 = "Semua Hormat kepada Kodok",
  str_skill_passive_name_400226 = "Simfoni Ribbit",
  str_skill_desc_300226 = "Dalam mimpi, Pangeran Teratai memiliki kekuatan untuk meredam letusan gunung berapi dan memperbaiki retakan hitam di langit. Di dunia nyata, dia bercita-cita untuk menyembuhkan teman-temannya dengan kelembutannya... Apa sebenarnya yang dia lakukan, kamu tanya? Membanjiri kamu dengan kegemasannya!",
  str_skill_desc_200226 = "Kroak tegas Pangeran Teratai bergema di seluruh Astra! Apa sebenarnya yang dilakukannya, kamu bertanya? Membanjiri kamu dengan kegemasannya!",
  str_skill_passive_desc_400226 = "Suara gaok seekor katak adalah detak jantung alam, nafas Astra, seberkas cahaya dalam kegelapan yang tak berujung. Bisakah kamu mendengarnya? Dia mengundang setiap orang untuk bergabung dalam perayaan besar ini dengan menyanyikan sebuah himne bersama-sama! Apa sebenarnya yang dilakukannya, kamu bertanya? Membuat semua orang gaok, tentu saja!",
  str_skill_name_54350081 = "Guardian Senjata Salvo",
  str_skill_desc_54350081 = "Ini adalah tugas meriam salvo untuk melindungi raja! Mereka akan meninggalkan medan perang setelah Chain Combo Aurorian.",
  str_skill_upgrade_desc_16022513 = "Peningkatan Skill Aktif: Mengubah Skill Aktif menjadi <color=#FFFF00>Serangan Preemptive</color>. Tersedia saat memasuki pertempuran. Menimbulkan 1 titik lemah tambahan pada musuh dalam jangkauan.",
  str_skill_upgrade_desc_16022516 = "Peningkatan Keterampilan Peralatan: Saat melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>, ada peluang 50% untuk menimbulkan 1 titik lemah tambahan.",
