  str_skill_passive_name_4462253 = "Thunder & Sky, Sebagai Satu",
  str_skill_desc_2002251 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada kolom sepanjang jalur menuju musuh terdekat.",
  str_skill_desc_2002252 = "Menimbulkan <color=#00F6FF>{1}%</color> damage dalam satu kolom dan ke tile yang berdekatan sepanjang jalan menuju musuh terdekat.",
  str_skill_desc_2002253 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy.",
  str_skill_desc_2102251 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan dalam kolom sepanjang jalan menuju musuh terdekat. Juga merusak 1 titik lemah dalam arah itu.",
  str_skill_desc_2102252 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan dalam sebuah kolom dan ke ubin yang berdekatan sepanjang jalan menuju musuh terdekat. Juga merusak 1 titik lemah dalam arah itu.",
  str_skill_desc_2102253 = "Menimbulkan <color=#00F6FF>{1}%</color> kerusakan dalam satu kolom dan ke ubin yang berdekatan sepanjang jalan menuju musuh terdekat. Juga merusak hingga 2 titik lemah dalam arah itu.",
  str_skill_desc_2302251 = "Deals <color=#00F6FF>{1}%</color> damage in a column along the path towards the nearest enemy. Also breaks 1 weak spot in that direction.",
  str_skill_desc_2302252 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy. Also breaks 1 weak spot in that direction.",
  str_skill_desc_2302253 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy. Also breaks up to 2 weak spots in that direction.",
  str_skill_desc_300225 = "Menarget 1 tile dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam bentuk kerucut ke arah tersebut.",
  str_skill_desc_303225 = "Targets 1 tile and deals <color=#00F6FF>{1}%</color> damage in a cone shape in that direction.",
  str_skill_desc_320225 = "Menarget 1 tile dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam bentuk kerucut ke arah itu. Juga menimbulkan 1 titik lemah pada semua musuh dalam jangkauan serangan.",
  str_skill_desc_323225 = "Menarget 1 tile dan menimbulkan <color=#00F6FF>{1}%</color> damage dalam bentuk kerucut ke arah itu. Juga menimbulkan 2 titik lemah pada semua musuh dalam jangkauan serangan.",
  str_skill_desc_340225 = "Menarget 1 ubin dan memberikan <color=#00F6FF>250%</color> kerusakan dalam bentuk kerucut ke arah itu. Juga memberikan 1 titik lemah pada semua musuh dalam jangkauan serangan.",
  str_skill_desc_343225 = "Menarget 1 ubin dan memberikan <color=#00F6FF>250%</color> kerusakan dalam bentuk kerucut ke arah itu. Juga menimbulkan 2 titik lemah pada semua musuh dalam jangkauan serangan.",
  str_skill_passive_desc_410225 = "Saat melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>, Tiare akan menimbulkan 1 titik lemah pada musuh dengan HP tertinggi di lapangan dalam arah terdekat dengannya. Setiap kali Serangan Normal atau Combo Rantai Tiare menyerang dalam arah itu, titik lemah akan rusak, menghasilkan <color=#00F6FF>{1}</color> kerusakan. Ketika musuh mati, titik lemahnya berpindah ke musuh terdekat. Ketika musuh dikelilingi oleh titik-titik lemah, setengah tambahan dari kerusakan pecah akan ditimbulkan.",
  str_skill_passive_desc_416225 = "Saat melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>, Tiare akan menimbulkan 1 titik lemah (dengan peluang 50% untuk 1 titik lemah tambahan) pada musuh dengan HP tertinggi di lapangan dalam arah terdekat dengannya. Setiap kali Serangan Normal atau Combo Rantai Tiare menyerang dalam arah itu, titik-titik lemah akan rusak, menghasilkan <color=#00F6FF>{1}</color> kerusakan. Ketika musuh mati, titik lemahnya berpindah ke musuh terdekat. Ketika musuh dikelilingi oleh titik lemah, tambahan setengah dari damage break akan diberikan.",
  str_skill_passive_desc_430225 = "Saat melewati <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>, Tiare akan menimbulkan 1 titik lemah pada musuh dengan HP tertinggi di lapangan dalam arah terdekat dengannya. Setiap kali Serangan Normal atau Combo Rantai Tiare mengenai arah tersebut, titik lemah akan pecah, menghasilkan <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>Kerusakan Splash</u></color></link> dan <color=#00F6FF>{2}</color> kerusakan pada jangkauan splash. Ketika musuh mati, titik lemahnya berpindah ke musuh terdekat. Ketika musuh dikelilingi oleh titik lemah, tambahan setengah dari kerusakan yang dihasilkan akan diberikan.",
  str_skill_passive_desc_436225 = "Saat melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link>, Tiare akan menimbulkan 1 titik lemah (dengan peluang 50% untuk 1 titik lemah tambahan) pada musuh dengan HP tertinggi di lapangan dalam arah terdekat dengannya. Setiap kali Serangan Normal atau Combo Rantai Tiare menyerang dalam arah itu, titik lemah akan pecah, menghasilkan <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>Kerusakan Splash</u></color></link> dan <color=#00F6FF>{2}</color> kerusakan pada jangkauan splash. Ketika musuh mati, titik lemahnya berpindah ke musuh terdekat. Ketika musuh dikelilingi oleh titik lemah, tambahan setengah dari damage break akan diberikan.",
  str_skill_passive_desc_440225 = "Saat melewati <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>, Tiare akan menimbulkan 1 titik lemah pada musuh dengan HP tertinggi di lapangan dalam arah terdekat dengannya. Setiap kali Serangan Normal atau Combo Rantai Tiare menyerang dalam arah itu, titik lemah akan pecah, menghasilkan <color=#00F6FF>230%</color> <link=\"30015\"><#FFAE07><u>Kerusakan Splash</u></color></link> dan <color=#00F6FF>100%</color> kerusakan pada jangkauan splash. Ketika musuh mati, titik lemahnya berpindah ke musuh terdekat. Ketika musuh dikelilingi oleh titik lemah, tambahan setengah dari damage break akan diberikan.",
  str_skill_passive_desc_446225 = "Saat melewati <link=\"30093\"><#FFAE07><u>Ubin Gelap</u></color></link>, Tiare akan menimbulkan 1 titik lemah (dengan peluang 50% untuk 1 titik lemah tambahan) pada musuh dengan HP tertinggi di lapangan dalam arah terdekat dengannya. Setiap kali Serangan Normal atau Combo Rantai Tiare mengenai arah tersebut, titik lemah akan pecah, menghasilkan <color=#00F6FF>230%</color> <link=\"30015\"><#FFAE07><u>Kerusakan Splash</u></color></link> dan <color=#00F6FF>100%</color> kerusakan pada jangkauan splash. Ketika musuh mati, titik lemahnya berpindah ke musuh terdekat. Ketika musuh dikelilingi oleh titik lemah, tambahan setengah dari damage break akan diberikan.",
  str_skill_passive_desc_4402253 = "Saat melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link> atau memasuki Aurora Time, Tiare akan menimbulkan 1 titik lemah pada musuh dengan HP tertinggi di lapangan dalam arah terdekat dengannya. Setiap kali Serangan Normal atau Combo Rantai Tiare mengenai arah tersebut, titik lemah akan pecah, menghasilkan <color=#00F6FF>230%</color> <link=\"30015\"><#FFAE07><u>Damage Splash</u></color></link> dan <color=#00F6FF>100%</color> damage ke jangkauan splash. Ketika musuh mati, titik lemahnya berpindah ke musuh terdekat. Ketika musuh dikelilingi oleh titik lemah, tambahan setengah dari damage break akan diberikan.",
  str_skill_passive_desc_4462253 = "Saat melewati <link=\"30093\"><#FFAE07><u>Tile Gelap</u></color></link> atau memasuki Aurora Time, Tiare akan menimbulkan 1 titik lemah (dengan peluang 50% untuk 1 titik lemah tambahan) pada musuh dengan HP tertinggi di lapangan dalam arah terdekat dengannya. Setiap kali Serangan Normal atau Combo Rantai Tiare mengenai arah tersebut, titik-titik lemah akan pecah, menghasilkan <color=#00F6FF>230%</color> <link=\"30015\"><#FFAE07><u>Damage Splash</u></color></link> dan <color=#00F6FF>100%</color> damage ke jangkauan splash. Ketika musuh mati, titik lemahnya berpindah ke musuh terdekat. Ketika musuh dikelilingi oleh titik-titik lemah, tambahan setengah dari kerusakan yang dihasilkan akan diberikan.",
  str_skill_upgrade_refine_desc_16022511 = "Peningkatan Keterampilan Peralatan: Meningkatkan kerusakan yang disebabkan oleh pemecahan titik lemah sebesar <color=#00F6FF>230%</color>.",
  str_skill_upgrade_refine_desc_16022512 = "Active Skill Enhancement: Meningkatkan faktor kerusakan skill sebesar <color=#00F6FF>50%</color>.",
  str_skill_upgrade_refine_desc_16022513 = "Peningkatan Keterampilan Peralatan: Saat memasuki Aurora Time, memberikan 1 titik lemah pada musuh dengan HP tertinggi dalam arah terdekat.",
  str_skill_desc_70011272 = "Energi Caracalune meluap, memberikan kerusakan pada 4 kolom dan baris.",
  str_skill_desc_70011273 = "Caracalune menjadi Plenalune, menimbulkan damage pada target dalam area serangan dan bergerak ke sisi lain lapangan. Setelah bergerak, mengunci tile dalam 1 klaster di sekitar. Tile terkunci tidak dapat dikonversi.",
  str_skill_name_290501142 = "Ditinggalkan: Mangsa",
  str_skill_name_290501143 = "Forsaken: Hunt",
  str_skill_name_290501144 = "Yang Ditinggalkan: Rally",
  str_skill_desc_290501142 = "Ratu Laba-laba Queen menukik ke arah mangsanya, memasang jaring untuk mengunci ubin, dan merusak Aurorian. Ubin yang terkunci kembali ke keadaan semula setelah 1 putaran.",
  str_skill_desc_290501143 = "Spider Queen memutar jaring untuk mengunci ubin di sekitar Aurorian, lalu memanggil tukiknya untuk menerkam mereka dan memberikan kerusakan. Ubin yang terkunci kembali ke keadaan semula setelah 1 putaran.",
  str_skill_desc_290501144 = "Ratu Laba-laba memanggil tukiknya untuk menyerang. Mereka akan memutar jaring laba-laba, mengunci sejumlah besar ubin. Ubin yang terkunci kembali ke keadaan semula setelah 1 putaran.",
  str_skill_desc_9011062 = "-1 putaran skill untuk Aurorian dengan cooldown tertinggi saat ini.",
  str_skill_name_290420209 = "Scythe",
  str_skill_desc_290420209 = "Dreamwalker Phantasm bergerak dan menimbulkan kerusakan pada target di depan.",
  str_skill_desc_510233 = "Semua Putaran Skill Aurorian yang dikerahkan -2.",
  str_skill_desc_520233 = "Mengakhiri cooldown skill untuk Aurorian acak.",
  str_skill_desc_530233 = "Mengakhiri cooldown skill untuk semua Aurorian yang diterjunkan.",
  str_skill_desc_292600105 = "Eve yang berduka mendapatkan sejumlah besar tumpukan Darkflow, mendapatkan efek Assault berdasarkan jumlah tumpukan. Setiap kali dia diserang, tumpukan Darkflow berkurang.",
  str_skill_desc_292600106 = "Grieving Eve mengunci target dan memberikan kerusakan.",
  str_skill_desc_20060012 = "Memberikan bonus DEF untuk Grieving Eve.",
  str_skill_name_200490101 = "Kabut asap",
  str_skill_desc_200490101 = "Haze bergerak menuju Aurorian.",
  str_skill_name_290950105 = "Blight Hail",
  str_skill_name_290950106 = "Badai Blight",
  str_skill_name_290950107 = "Blight Hail",
  str_skill_name_290950108 = "Badai Blight",
  str_skill_name_290950109 = "Blight Crush",
  str_skill_desc_290950105 = "Carrot: Blight memberikan beberapa instance kerusakan kepada Aurorian. Semakin rendah HP Aurorian, semakin besar kerusakan yang akan diberikan.",
  str_skill_desc_290950106 = "Carrot: Blight berputar dengan kecepatan tinggi, memberikan beberapa kali kerusakan pada target di sekitarnya. Setiap kali memberikan kerusakan, ada kemungkinan untuk mendorong Aurorian 1 ubin ke arah berlawanan arah jarum jam atau ke luar. Setiap pukulan yang berhasil mengurangi kerusakan dari pukulan berikutnya.",
  str_skill_desc_290950107 = "Carrot: Blight memberikan beberapa instance kerusakan kepada Aurorian. Semakin rendah HP Aurorian, semakin besar kerusakan yang akan diberikan.",
  str_skill_desc_290950108 = "Jika Aurorian tidak berada dalam jangkauan Blight Crush, Carrot: Blight berputar dengan kecepatan tinggi, menimbulkan beberapa kali kerusakan pada target di sekitarnya. Setiap kali memberikan kerusakan, ada peluang untuk menjatuhkan Aurorian sebanyak 1 ubin ke arah berlawanan jarum jam atau ke luar. Setiap pukulan yang berhasil mengurangi kerusakan dari pukulan berikutnya.",
  str_skill_desc_290950109 = "Jika Aurorian berada dalam jangkauan Blight Crush, Carrot: Blight menghantam mereka dengan wortel raksasa, menimbulkan kerusakan pada mereka dan menjatuhkan mereka sebanyak 2 petak.",
  str_skill_name_80060401 = "Duri-duri Kontradiksi",
  str_skill_desc_80060401 = "Menimbulkan kerusakan yang cukup besar di akhir setiap putaran kepada monster apa pun yang terjebak dalam duri dan memberikan 1 tumpukan Bleeding. Duri ini terlihat familiar, tetapi mereka tidak akan melukai kamu kali ini.",
  str_skill_name_80060501 = "Panggil Slasher",
  str_skill_name_80060502 = "Summon Prober",
  str_skill_name_80060503 = "Summon: Siphorb",
  str_skill_desc_80060501 = "Memanggil Slasher ke medan perang!",
  str_skill_desc_80060502 = "Memanggil Prober ke medan perang!",
  str_skill_desc_80060503 = "Memanggil Siphorb ke medan perang!",
  str_skill_desc_800637101 = "Mengeluarkan tembakan yang tepat, diam-diam, dan terampil yang menimbulkan kerusakan dalam bentuk silang hingga jangkauan maksimum.",
  str_skill_desc_800638101 = "Menimbulkan kerusakan pada targetnya dua kali setelah menggunakan kegesitannya yang luar biasa untuk menjauh dari musuh.",
  str_skill_desc_80062201 = "Pemulihan Poin Kekuatan Tim per putaran +1.",
