  str_skill_name_3062271 = "Death Recon",
  str_skill_desc_2002271 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat.",
  str_skill_desc_2002272 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat.",
  str_skill_desc_2002273 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat.",
  str_skill_desc_20022712 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat. Ini dapat dikeluarkan saat Kelelahan, tetapi akan memberikan 1 tumpukan Cakar Elang alih-alih memberikan kerusakan.",
  str_skill_desc_20022722 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat. Ini dapat dikeluarkan saat Kelelahan, tetapi akan memberikan 2 tumpukan Cakar Elang alih-alih memberikan kerusakan.",
  str_skill_desc_20022732 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat. Ini dapat dikeluarkan saat Kelelahan, tetapi akan menimbulkan 3 tumpukan Cakar Elang alih-alih memberikan kerusakan.",
  str_skill_desc_2202271 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat. Ini dapat dikeluarkan saat Kelelahan, tetapi akan memberikan 1 tumpukan Cakar Elang alih-alih memberikan kerusakan.",
  str_skill_desc_2202272 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat. Ini dapat dikeluarkan saat Kelelahan, tetapi akan memberikan 2 tumpukan Cakar Elang alih-alih memberikan kerusakan.",
  str_skill_desc_2202273 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada 2 musuh terdekat. Ini dapat dikeluarkan saat Kelelahan, tetapi akan menimbulkan 3 tumpukan Cakar Elang alih-alih memberikan kerusakan.",
  str_skill_desc_3002271 = [[
