  str_skill_name_3322321 = "Bloody Salvation",
  str_skill_name_3322322 = "Darah untuk Varian Keselamatan",
  str_skill_passive_name_4002321 = "Maaf Mabuk",
  str_skill_passive_name_4052321 = "Maaf Mabuk",
  str_skill_desc_2002321 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color> dan memberikan 1 tumpukan <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> selama 2 putaran.",
  str_skill_desc_2002322 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>16 tile dalam bentuk lingkaran</color> dan memberikan 1 tumpukan <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> selama 2 putaran.",
  str_skill_desc_2002323 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color> dan memberikan 1 tumpukan <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> selama 2 putaran.",
  str_skill_desc_3002321 = "Mengkonsumsi <color=#00F6FF>10%</color> dari Max HP tim untuk mengubah <color=#00F6FF>1</color> tile yang dipilih menjadi tile gelap. Tidak dapat dilemparkan jika HP tidak mencukupi.",
  str_skill_desc_3202322 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Mengkonsumsi <color=#00F6FF>25%</color> dari Max HP tim untuk mengubah <color=#00F6FF>2</color> ubin yang dipilih menjadi ubin gelap. Tidak dapat dicast jika HP tidak cukup.",
  str_skill_desc_3022321 = "Mengkonsumsi <color=#00F6FF>10%</color> dari Max HP tim untuk mengubah <color=#00F6FF>1</color> tile yang dipilih menjadi tile gelap. Tidak dapat dilemparkan jika HP tidak mencukupi.",
  str_skill_desc_3222322 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Mengkonsumsi <color=#00F6FF>25%</color> dari Max HP tim untuk mengubah <color=#00F6FF>2</color> ubin yang dipilih menjadi ubin gelap. Tidak dapat dicast jika HP tidak cukup.",
  str_skill_desc_3302321 = "Mengkonsumsi <color=#00F6FF>10%</color> dari Max HP tim untuk mengubah <color=#00F6FF>1</color> ubin yang dipilih menjadi ubin gelap. Tidak dapat dilemparkan jika HP tidak mencukupi. Jika HP tim di bawah <color=#00F6FF>30%</color> setelah dilemparkan, mengubah ubin yang dipilih pertama menjadi ubin gelap merah.",
  str_skill_desc_3302322 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Mengkonsumsi <color=#00F6FF>25%</color> dari Max HP tim untuk mengubah <color=#00F6FF>2</color> ubin yang dipilih menjadi ubin gelap. Tidak bisa dicasting jika HP tidak mencukupi. Jika HP tim di bawah <color=#00F6FF>30%</color> setelah casting, mengubah ubin yang dipilih pertama menjadi ubin gelap merah.",
  str_skill_desc_3322321 = "Mengkonsumsi <color=#00F6FF>10%</color> dari Max HP tim untuk mengubah <color=#00F6FF>1</color> ubin yang dipilih menjadi ubin gelap. Tidak dapat dilemparkan jika HP tidak mencukupi. Jika HP tim di bawah <color=#00F6FF>30%</color> setelah dilemparkan, mengubah ubin yang dipilih pertama menjadi ubin gelap merah.",
  str_skill_desc_3322322 = "<color=#FFFF00>Cooldown skill +1 setelah casting</color>. Mengkonsumsi <color=#00F6FF>25%</color> dari Max HP tim untuk mengubah <color=#00F6FF>2</color> ubin yang dipilih menjadi ubin gelap. Tidak bisa dicasting jika HP tidak mencukupi. Jika HP tim di bawah <color=#00F6FF>30%</color> setelah casting, mengubah ubin yang dipilih pertama menjadi ubin gelap merah.",
  str_skill_passive_desc_4002321 = "Ketika persentase HP saat ini turun di bawah <color=#00F6FF>50%</color>, menghasilkan Crimson Blessing pada tile merah yang dapat dilalui terdekat. Saat melewatinya, mengembalikan HP sebanding dengan <color=#00F6FF>{1}</color> dari ATK Nails: Sacred Rite.",
  str_skill_passive_desc_4052321 = "Ketika persentase HP saat ini turun di bawah <color=#00F6FF>50%</color>, menghasilkan Crimson Blessing pada tile merah yang dapat dilalui terdekat. Saat melewatinya, mengembalikan HP sebanding dengan <color=#00F6FF>{1}</color> dari ATK Nails: Sacred Rite. Menganggap Crimson Blessing sebagai tile gelap saat melaluinya.",
  str_skill_passive_desc_4402321 = "Ketika persentase HP saat ini turun di bawah <color=#00F6FF>50%</color>, menghasilkan Crimson Blessing pada tile merah yang dapat dilalui terdekat. Saat melewatinya, mengembalikan HP sebesar <color=#00F6FF>110%</color> dari ATK Nails: Sacred Rite.",
  str_skill_passive_desc_4452321 = "Ketika persentase HP saat ini turun di bawah <color=#00F6FF>50%</color>, menghasilkan Crimson Blessing pada tile merah yang dapat dilalui terdekat. Saat melewatinya, mengembalikan HP sebanding dengan <color=#00F6FF>110%</color> dari ATK Nails: Sacred Rite. Menganggap Crimson Blessing sebagai tile gelap saat melaluinya.",
  str_skill_passive_desc_4502321 = "Ketika persentase HP saat ini turun di bawah <color=#00F6FF>50%</color>, menghasilkan Crimson Blessing pada tile merah yang dapat dilalui terdekat. Saat melewatinya, memulihkan HP sebesar <color=#00F6FF>110%</color> dari ATK Nails: Sacred Rite dan <color=#00F6FF>5%</color> dari HP yang hilang.",
  str_skill_passive_desc_4552321 = "Ketika persentase HP saat ini turun di bawah <color=#00F6FF>50%</color>, menghasilkan Crimson Blessing pada tile merah yang dapat dilalui terdekat. Saat melewatinya, memulihkan HP sebanding dengan <color=#00F6FF>110%</color> dari ATK Nails: Sacred Rite dan <color=#00F6FF>5%</color> dari HP yang hilang. Menganggap Crimson Blessing sebagai tile gelap saat melaluinya.",
  str_skill_passive_desc_4602321 = "Ketika persentase HP saat ini turun di bawah <color=#00F6FF>50%</color> dan <color=#00F6FF>30%</color>, menghasilkan Crimson Blessing pada tile merah yang dapat dilalui terdekat. Saat melewatinya, memulihkan HP sebesar <color=#00F6FF>110%</color> dari ATK Nails: Sacred Rite dan <color=#00F6FF>5%</color> dari HP yang hilang.",
  str_skill_passive_desc_4652321 = "Ketika persentase HP saat ini turun di bawah <color=#00F6FF>50%</color> dan <color=#00F6FF>30%</color>, menghasilkan Crimson Blessing pada tile merah yang dapat dilalui terdekat. Saat melewatinya, memulihkan HP sebanding dengan <color=#00F6FF>110%</color> dari ATK Nails: Sacred Rite dan <color=#00F6FF>5%</color> dari HP yang hilang. Menganggap Crimson Blessing sebagai tile gelap saat melaluinya.",
  str_skill_upgrade_desc_15023212 = "Active Skill Enhancement: Mengurangi cooldown skill sebanyak <color=#FFFF00>1</color> putaran.",
  str_skill_upgrade_desc_15023215 = "Peningkatan Keterampilan Peralatan: Menganggap Crimson Blessing sebagai Dark Tile saat melewatinya.",
  str_skill_upgrade_refine_desc_15023211 = "Peningkatan Skill Peralatan: Memulihkan HP sebesar <color=#00F6FF>110%</color> dari ATK Nails: Sacred Rite saat melewati Crimson Blessing.",
  str_skill_upgrade_refine_desc_15023212 = "Peningkatan Keterampilan Peralatan: Selain itu, mengembalikan HP sebesar <color=#00F6FF>5%</color> dari HP yang hilang.",
  str_skill_upgrade_refine_desc_15023213 = "Peningkatan Keterampilan Peralatan: Ketika persentase HP saat ini turun di bawah <color=#00F6FF>30%</color>, menciptakan Berkat Merah lainnya pada ubin merah terdekat.",
