  str_skill_passive_desc_4402331 = "Karakter Kolaborasi dari Atelier Ryza 2 bertarung dengan <link=\"30122\"><#FFAE07><u>Tactics System</u></color></link>. Ryza mendapatkan <color=#00F6FF>20</color> Tactical Point setiap kali dia menggunakan Active Skill dan <color=#00F6FF>3</color> Tactical Point setiap kali dia bergerak melalui Dark Tile.",
  str_skill_passive_desc_4502331 = "Karakter Kolaborasi dari Atelier Ryza 2 bertarung dengan <link=\"30122\"><#FFAE07><u>Tactics System</u></color></link>. Ryza mendapatkan <color=#00F6FF>20</color> Tactical Point setiap kali dia menggunakan Active Skill dan <color=#00F6FF>5</color> Tactical Point setiap kali dia bergerak melalui Dark Tile.",
