  str_skill_passive_desc_440234 = "Karakter kolaborasi dari Atelier Ryza 2 bertarung dengan <link=\"30122\"><#FFAE07><u>Sistem Taktik</u></color></link>. Klaudia mendapatkan <color=#00F6FF>20</color> Poin Taktis setiap kali dia menggunakan Active Skill.",
  str_skill_upgrade_refine_desc_16023411 = "Peningkatan Keterampilan Peralatan: Klaudia mendapatkan <color=#00F6FF>20</color> Poin Taktis setiap kali dia menggunakan Skill Aktif.",
