  str_skill_upgrade_refine_desc_16023413 = "Peningkatan Kombo Rantai: Faktor kerusakan Kombo Rantai meningkat sebesar <color=#00F6FF>5%</color> untuk setiap Tile Gelap yang dilalui dalam putaran saat ini.",
  str_skill_desc_240461 = "Menimbulkan <color=#00F6FF>120%</color> kerusakan pada <color=#00F6FF>3</color> musuh dalam <color=#00F6FF>4 klaster di sekitar</color> dan memberikan 1 tumpukan Tawa, hingga 8 tumpukan. Setiap tumpukan meningkatkan kerusakan Chain Combo sebesar <color=#00F6FF>7%</color>.",
  str_skill_desc_240462 = "Menimbulkan <color=#00F6FF>140%</color> kerusakan pada <color=#00F6FF>3</color> musuh dalam <color=#00F6FF>4 klaster di sekitar</color> dan memberikan 2 tumpukan Tawa, hingga 8 tumpukan. Setiap tumpukan meningkatkan kerusakan Chain Combo sebesar <color=#00F6FF>7%</color>.",
  str_skill_desc_240463 = "Menimbulkan <color=#00F6FF>155%</color> damage pada <color=#00F6FF>3</color> musuh dalam <color=#00F6FF>4 klaster di sekitar</color> dan memberikan 3 tumpukan Laughter, hingga 8 tumpukan. Setiap tumpukan meningkatkan damage Chain Combo sebesar <color=#00F6FF>7%</color>.",
  str_skill_upgrade_refine_desc_13004612 = "Peningkatan Chain Combo: Setiap tumpukan Laughter meningkatkan damage Chain Combo sebesar <color=#00F6FF>7%</color>.",
  str_skill_desc_300046 = "Menempatkan Clucky di tile yang dipilih, kemudian menarik <color=#00F6FF>semua</color> musuh dan memberikan efek <link=\"10006\"><#FFAE07><u>Slow</u></color></link> pada musuh dengan 5 tumpukan Laughter selama 2 putaran.",
  str_skill_desc_302046 = "Menempatkan Clucky di tile yang dipilih, kemudian menarik <color=#00F6FF>semua</color> musuh. Menimbulkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> pada musuh dengan 4 tumpukan Tawa selama 2 putaran dan <link=\"10004\"><#FFAE07><u>Paralyzed</u></color></link> pada musuh dengan 6 tumpukan Tawa selama 1 putaran.",
  str_skill_desc_305046 = "Menempatkan Clucky di tile yang dipilih, kemudian menarik <color=#00F6FF>semua</color> musuh. Menimbulkan <link=\"10006\"><#FFAE07><u>Slow</u></color></link> pada musuh dengan 4 tumpukan Tawa selama 2 putaran dan <link=\"10004\"><#FFAE07><u>Paralyzed</u></color></link> pada musuh dengan 6 tumpukan Tawa selama <color=#00F6FF>1</color> putaran.",
