  str_skill_desc_2002372 = "Menimbulkan <color=#00F6FF>170%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada musuh terdekat dalam <color=#00F6FF>12 ubin dalam bentuk berlian</color>.",
  str_skill_desc_2002373 = "Menimbulkan <color=#00F6FF>180%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada musuh terdekat dalam <color=#00F6FF>2 cluster sekitarnya</color>.",
  str_skill_desc_2302371 = "Menimbulkan <color=#00F6FF>160%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2302372 = "Menimbulkan <color=#00F6FF>170%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada musuh terdekat dalam <color=#00F6FF>12 ubin dalam bentuk berlian</color>. Memanggil Bubble Radiant di lokasi target.",
  str_skill_desc_2302373 = "Menimbulkan <color=#00F6FF>180%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color> berpusat pada musuh terdekat dalam <color=#00F6FF>2 cluster sekitarnya</color>. Memanggil Bubble Radiant di lokasi target.",
  str_skill_desc_3002371 = "Pilih ubin yang dapat dilalui dari <color=#00F6FF>12 ubin dalam bentuk berlian</color> sebagai titik awal, lalu sambungkan sejumlah <color=#00F6FF>Ubin Biru</color> sambil mengabaikan semua rintangan. Berteleportasi secara instan ke akhir koneksi. Jika ada musuh di ubin terakhir, berikan <color=#00F6FF>200%</color> kerusakan pada target sebelum pindah ke ubin yang berdekatan.",
  str_skill_desc_3032371 = "Pilih ubin yang dapat dilalui dari <color=#00F6FF>12 ubin dalam bentuk berlian</color> sebagai titik awal, lalu sambungkan sejumlah <color=#00F6FF>Ubin Biru</color> sambil mengabaikan semua rintangan. Teleportasi seketika ke akhir sambungan. Jika ada musuh di ubin terakhir, berikan <color=#00F6FF>300%</color> kerusakan pada target sebelum berpindah ke ubin yang berdekatan.",
  str_skill_desc_3202371 = "Pilih ubin yang dapat dilalui dari <color=#00F6FF>12 ubin dalam bentuk berlian</color> sebagai titik awal, lalu sambungkan sejumlah <color=#00F6FF>Ubin Biru, Ubin Gelap, atau Ubin Gelembung Radiant</color> sambil mengabaikan semua rintangan. Teleportasi ke akhir koneksi. Jika ada musuh di ubin terakhir, berikan <color=#00F6FF>200%</color> kerusakan pada target sebelum pindah ke ubin yang berdekatan.",
  str_skill_desc_3232371 = "Pilih ubin yang dapat dilalui dari <color=#00F6FF>12 ubin dalam bentuk berlian</color> sebagai titik awal, lalu sambungkan sejumlah <color=#00F6FF>Ubin Biru, Ubin Gelap, atau Ubin Gelembung Radiant</color> sambil mengabaikan semua rintangan. Teleportasi ke akhir sambungan. Jika ada musuh di ubin terakhir, berikan <color=#00F6FF>300%</color> kerusakan pada target sebelum pindah ke ubin yang berdekatan.",
  str_skill_passive_name_4102371 = "Unreal",
  str_skill_passive_desc_4102371 = "Di awal setiap putaran, menghasilkan Radiant Bubbles pada <color=#00F6FF>2</color> tile yang dapat dilalui secara acak yang bertahan selama 3 putaran. Saat melewati Radiant Bubble melalui tile yang terhubung atau Active Skills, itu menimbulkan <color=#00F6FF>{1}</color> damage pada 3 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_passive_name_4402371 = "Unreal",
  str_skill_passive_desc_4402371 = "Di awal setiap putaran, menghasilkan Radiant Bubbles pada <color=#00F6FF>2</color> tile yang dapat dilalui secara acak yang bertahan selama 3 putaran. Ketika melewati Radiant Bubble melalui tile yang terhubung atau Active Skills, itu menimbulkan <color=#00F6FF>140%</color> damage pada 3 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_passive_name_4502371 = "Unreal",
  str_skill_passive_desc_4502371 = "Di awal setiap putaran, menghasilkan Radiant Bubbles pada <color=#00F6FF>2</color> tile yang dapat dilalui secara acak yang bertahan selama 3 putaran. Saat melewati Radiant Bubble melalui tile yang terhubung atau Active Skills, itu menimbulkan <color=#00F6FF>140%</color> damage kepada 4 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_passive_name_4602371 = "Unreal",
  str_skill_passive_desc_4602371 = "Di awal setiap putaran, menghasilkan Radiant Bubbles pada <color=#00F6FF>2</color> tile yang dapat dilalui secara acak yang bertahan selama 3 putaran. Saat melewati Radiant Bubble melalui tile yang terhubung atau Active Skills, menimbulkan <color=#00F6FF>140%</color> damage pada 4 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>. Dapatkan 1 Illusion Source saat melewati Dark Tiles atau Radiant Bubbles. Setiap poin dari Illusion Source meningkatkan damage Chain Combo sebesar <color=#00F6FF>1%</color>.",
  str_skill_passive_name_4162371 = "Unreal",
  str_skill_passive_desc_4162371 = "Di awal setiap putaran, menghasilkan Radiant Bubbles pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak yang bertahan selama 5 putaran. Saat melewati Radiant Bubble melalui ubin yang terhubung atau Skill Aktif, itu menimbulkan <color=#00F6FF>{1}</color> kerusakan pada 3 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_passive_name_4462371 = "Unreal",
  str_skill_passive_desc_4462371 = "Di awal setiap putaran, menghasilkan Radiant Bubbles pada <color=#00F6FF>3</color> tile yang dapat dilalui secara acak yang bertahan selama 5 putaran. Ketika melewati Radiant Bubble melalui tile yang terhubung atau Active Skills, itu menimbulkan <color=#00F6FF>140%</color> damage pada 3 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_passive_name_4562371 = "Unreal",
  str_skill_passive_desc_4562371 = "Di awal setiap ronde, menghasilkan Radiant Bubbles pada <color=#00F6FF>3</color> tile yang dapat dilalui secara acak yang bertahan selama 5 ronde. Saat melewati Radiant Bubble melalui tile yang terhubung atau Active Skills, itu menimbulkan <color=#00F6FF>140%</color> damage kepada 4 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>.",
  str_skill_passive_name_4662371 = "Unreal",
  str_skill_passive_desc_4662371 = "Di awal setiap putaran, menghasilkan Radiant Bubbles pada <color=#00F6FF>3</color> ubin yang dapat dilalui secara acak yang bertahan selama 3 putaran. Saat melewati Radiant Bubble melalui ubin yang terhubung atau Active Skills, menimbulkan <color=#00F6FF>140%</color> damage pada 4 musuh dalam <color=#00F6FF>3 klaster di sekitar</color>. Dapatkan 1 Illusion Source saat melewati Dark Tiles atau Radiant Bubbles. Setiap poin dari Illusion Source meningkatkan damage Chain Combo sebesar <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_16023711 = "Peningkatan Keterampilan Peralatan: Meningkatkan kerusakan Radiant Bubble menjadi <color=#00F6FF>140%</color>.",
  str_skill_upgrade_refine_desc_16023712 = "Peningkatan Keterampilan Peralatan: Radiant Bubbles menimbulkan kerusakan pada <color=#00F6FF>4</color> musuh dalam jangkauan.",
  str_skill_upgrade_refine_desc_16023713 = "Peningkatan Keterampilan Peralatan: Mendapatkan 1 Sumber Ilusi saat melewati Ubin Gelap atau Gelembung Radiant. Setiap poin Sumber Ilusi meningkatkan kerusakan Kombo Rantai sebesar <color=#00F6FF>1%</color>.",
  str_skill_upgrade_desc_16023713 = "Peningkatan Skill Aktif: Mengurangi cooldown skill sebanyak <color=#FFFF00>1</color> putaran. Jika ada musuh di tile terakhir, memberikan kerusakan sebesar <color=#FFFF00>300%</color>.",
  str_skill_upgrade_desc_16023716 = "Peningkatan Keterampilan Peralatan: Radiant Bubbles bertahan selama 5 putaran dan menghasilkan 1 Radiant Bubble tambahan di awal setiap putaran.",
  str_skill_name_291020103 = "Kejaran Terdampar",
  str_skill_name_291020104 = "Cinta Putus Asa",
  str_skill_name_291020105 = "Ratap Siren",
  str_skill_desc_291020103 = "Menimbulkan kerusakan pada Aurorian dan memanggil Salvo Guns di sekitar mereka. Ketika HP turun di bawah 70%/40%, jumlah Salvo Guns yang dipanggil meningkat sebanyak 1 masing-masing.",
  str_skill_desc_291020104 = "Memanggil Request di ubin terjauh dari Aurorian dalam 1 cluster sekitar. Ketika HP turun di bawah 50%, jumlah Request yang dipanggil meningkat sebanyak 1.",
  str_skill_desc_291020105 = "Memberikan peningkatan kerusakan pada Aurorian 3 kali dan mendorong mereka kembali ke tepi lapangan.",
  str_skill_desc_291020113 = "Memberikan kerusakan pada Aurorian dan memanggil Salvo Guns di sekitar mereka.",
  str_skill_passive_desc_443173 = "Segera memberikan <color=#00F6FF>85%</color> kerusakan pada <color=#00F6FF>1</color> target acak di lapangan setiap kali tim mendapatkan <link=\"20001\"><#FFAE07><u>ubin yang ditingkatkan</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>penyerapan</u></color></link>). Memulai pertempuran dengan <color=#00F6FF>33</color> tumpukan Mortal Mark dan mengurangi <color=#00F6FF>1</color> tumpukan untuk setiap ubin yang ditingkatkan yang diperoleh. Minos memasuki Minotaur State ketika semua Mark telah dihapus, meningkatkan ATK dasarnya sebesar <color=#00F6FF>25%</color>, memungkinkan serangan normalnya untuk mengenai tile diagonal, meningkatkan damage Skill Equipment menjadi <color=#00F6FF>2.5</color> kali, dan memungkinkan Chain Combo-nya untuk menimbulkan damage normal ketika mengenai target yang sama lagi.",
  str_skill_passive_desc_453173 = "Langsung menimbulkan damage sebesar <color=#00F6FF>85%</color> kepada <color=#00F6FF>1</color> target acak di lapangan setiap kali tim mendapatkan <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>penyerapan</u></color></link>). Memulai pertempuran dengan <color=#00F6FF>33</color> tumpukan Mortal Mark dan mengurangi <color=#00F6FF>1</color> tumpukan untuk setiap Enhanced Tile yang diperoleh. Minos memasuki Minotaur State ketika semua Mark telah dihapus, meningkatkan ATK dasarnya sebesar <color=#00F6FF>25%</color>, memungkinkan serangan normalnya untuk mengenai tile diagonal, dan meningkatkan damage Skill Peralatan menjadi <color=#00F6FF>2.5</color> kali. Mengurangi persyaratan pemicu Chain Combo sebanyak <color=#00F6FF>1/2/3</color> dan damage-nya tidak lagi berkurang saat mengenai target yang sama.",
  str_skill_passive_desc_463173 = "Langsung menimbulkan <color=#00F6FF>85%</color> damage ke <color=#00F6FF>1</color> target acak di lapangan setiap kali tim mendapatkan <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>penyerapan</u></color></link>). Memulai pertempuran dengan <color=#00F6FF>33</color> tumpukan Mark Mortal dan mengurangi <color=#00F6FF>1</color> tumpukan untuk setiap Enhanced Tile yang diperoleh. Minos memasuki Minotaur State ketika semua Mark telah dihapus, meningkatkan ATK dasarnya sebesar <color=#00F6FF>25%</color>, memungkinkan serangan normalnya mengenai tile diagonal, dan meningkatkan damage Skill Peralatan menjadi <color=#00F6FF>2.5</color> kali. Mengurangi persyaratan pemicu Chain Combo sebesar <color=#00F6FF>1/2/3</color> dan damage-nya tidak lagi berkurang saat mengenai target yang sama. Meningkatkan faktor damage Active Skill menjadi <color=#00F6FF>200%</color>.",
  str_skill_passive_desc_440173 = "Langsung menimbulkan <color=#00F6FF>85%</color> damage ke <color=#00F6FF>1</color> target acak di lapangan setiap kali tim mendapatkan <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>penyerapan</u></color></link>). Memulai pertempuran dengan <color=#00F6FF>33</color> tumpukan Mark Mortal dan mengurangi <color=#00F6FF>1</color> tumpukan untuk setiap Enhanced Tile yang diperoleh. Minos memasuki Minotaur State ketika semua Mark telah dihapus, meningkatkan ATK dasarnya sebesar <color=#00F6FF>20%</color>, memungkinkan serangan normalnya untuk mengenai tile diagonal, meningkatkan damage Skill Peralatan menjadi <color=#00F6FF>2.5</color> kali, dan damage Chain Combo tidak lagi berkurang saat mengenai target yang sama.",
  str_skill_passive_desc_450173 = "Langsung menimbulkan damage sebesar <color=#00F6FF>85%</color> kepada <color=#00F6FF>1</color> target acak di lapangan setiap kali tim mendapatkan <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>penyerapan</u></color></link>). Memulai pertempuran dengan <color=#00F6FF>33</color> tumpukan Mortal Mark dan mengurangi <color=#00F6FF>1</color> tumpukan untuk setiap Enhanced Tile yang diperoleh. Minos memasuki Minotaur State ketika semua Mark telah dihapus, meningkatkan ATK dasarnya sebesar <color=#00F6FF>20%</color>, memungkinkan serangan normalnya mengenai tile diagonal, dan meningkatkan damage Skill Peralatan menjadi <color=#00F6FF>2.5</color> kali. Mengurangi persyaratan pemicu Chain Combo sebanyak <color=#00F6FF>1/2/3</color> dan damage-nya tidak lagi berkurang saat mengenai target yang sama.",
  str_skill_passive_desc_460173 = "Secara langsung memberikan <color=#00F6FF>85%</color> damage ke <color=#00F6FF>1</color> target acak di lapangan setiap kali tim mendapatkan <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link> (termasuk <link=\"30065\"><#FFAE07><u>penyerapan</u></color></link>). Memulai pertempuran dengan <color=#00F6FF>33</color> tumpukan Mortal Mark dan mengurangi <color=#00F6FF>1</color> tumpukan untuk setiap Enhanced Tile yang diperoleh. Minos memasuki Minotaur State ketika semua Mark telah dihapus, meningkatkan ATK dasarnya sebesar <color=#00F6FF>20%</color>, memungkinkan serangan normalnya untuk mengenai tile diagonal, dan meningkatkan damage Skill Peralatan menjadi <color=#00F6FF>2.5</color> kali. Mengurangi persyaratan pemicu Chain Combo sebesar <color=#00F6FF>1/2/3</color> dan damage-nya tidak lagi berkurang saat mengenai target yang sama. Meningkatkan faktor damage Active Skill menjadi <color=#00F6FF>200%</color>.",
  str_skill_upgrade_refine_desc_16017311 = "Peningkatan Keterampilan Peralatan: Meningkatkan faktor kerusakan menjadi 85%.",
  str_skill_upgrade_refine_desc_16017312 = "Peningkatan Skill Peralatan: Mengurangi persyaratan pemicu Chain Combo sebanyak 1/2/3 dalam Kondisi Minotaur.",
  str_skill_upgrade_refine_desc_16017313 = "Peningkatan Skill Perlengkapan: Meningkatkan faktor kerusakan Skill Aktif menjadi 200% dalam Kondisi Minotaur.",
  str_skill_upgrade_refine_desc_14016911 = "Peningkatan Keterampilan Peralatan: Meningkatkan ATK dasar Sadie sebesar <color=#00F6FF>33%</color>. Setiap Poin Kecelakaan meningkatkan faktor kerusakan Skill Aktif sebesar <color=#00F6FF>22%</color>.",
  str_skill_upgrade_refine_desc_14016912 = "Peningkatan Keterampilan Peralatan: Dapatkan 1 <color=#00F6FF>Titik Kecelakaan</color> saat melewati Ubin Gelap.",
  str_skill_upgrade_refine_desc_14016913 = "Peningkatan Keterampilan Aktif: Memperluas jangkauan ubin yang dapat dipilih menjadi <color=#00F6FF>1 cluster sekitarnya</color>.",
  str_skill_passive_desc_440169 = "Meningkatkan ATK dasar Sadie sebesar <color=#00F6FF>33%</color>. Sadie menawarkan hingga <color=#00F6FF>3</color> Serangan Normal saat menghubungkan ubin, dan Serangan Normal ketiga memberikan kerusakan ganda. Setelah 3 serangan, dapatkan 1 <color=#00F6FF>Titik Kecelakaan</color> dengan Serangan Normal berikutnya. Setiap Titik Kecelakaan meningkatkan faktor kerusakan Skill Aktif sebesar <color=#00F6FF>22%</color>. Semua Titik Kecelakaan dihapus setelah menggunakan Skill Aktif.",
  str_skill_passive_desc_450169 = "Meningkatkan ATK dasar Sadie sebesar <color=#00F6FF>33%</color>. Sadie menawarkan hingga <color=#00F6FF>3</color> Serangan Normal saat menghubungkan ubin, dan Serangan Normal ketiga memberikan kerusakan ganda. Setelah 3 serangan, dapatkan 1 <color=#00F6FF>Titik Kecelakaan</color> dengan Serangan Normal berikutnya. Setiap Titik Kecelakaan meningkatkan faktor kerusakan Skill Aktif sebesar <color=#00F6FF>22%</color>. Semua Titik Kecelakaan dihapus setelah menggunakan Skill Aktif. Dapatkan 1 <color=#00F6FF>Titik Kecelakaan</color> tambahan untuk setiap Ubin Gelap yang dilalui.",
  str_skill_name_360169 = "Bola Terbang",
  str_skill_name_365169 = "Bola Terbang",
  str_skill_desc_360169 = "Penawaran <color=#00F6FF>300%</color> kerusakan pada 1 musuh dalam <color=#00F6FF>1 kelompok sekitar</color> dan menjatuhkan mereka kembali 2 ubin. Musuh yang diblokir oleh <color=#00F6FF>rintangan</color> saat dipukul mundur mengambil tambahan <color=#00F6FF>200%</color> kerusakan dan <color=#00F6FF>tercengang</color> untuk 1 putaran. Jika diblokir oleh musuh lain, keduanya akan terkena damage dan stun.",
  str_skill_desc_365169 = "Menawarkan <color=#00F6FF>300%</color> kerusakan pada 1 musuh dalam <color=#00F6FF>1 kelompok sekitar</color> dan menjatuhkan mereka kembali 3 ubin. Musuh yang diblokir oleh <color=#00F6FF>rintangan</color> saat dipukul mundur mengambil tambahan <color=#00F6FF>200%</color> kerusakan dan <color=#00F6FF>tercengang</color> selama 1 putaran. Jika diblokir oleh musuh lain, keduanya menerima kerusakan dan stun.",
  str_skill_name_20053011 = "Bisikan Laut Dalam",
  str_skill_desc_20053011 = "Menimbulkan damage pada unit musuh dalam 1 klaster di sekitar.",
  str_skill_name_20054011 = "Sentuh",
  str_skill_desc_20054011 = "Ketika ada Aurorian dalam 2 klaster dari dirinya sendiri, ia memanggil Eclipsite di dekat target untuk membantu dirinya sendiri.",
  str_skill_upgrade_desc_17023613 = "Peningkatan Active Skill: Dapatkan 5 Vis pada awal setiap putaran.",
  str_skill_upgrade_desc_17023616 = "Skill Aktif Baru: Dapat digunakan untuk kembali ke tim saat dalam keadaan off-team, menimbulkan <color=#00F6FF>550%</color> kerusakan pada ubin sepanjang jalan.",
  str_skill_passive_name_4102361 = "Agitato",
  str_skill_name_2002361 = "Keajaiban Czerny",
  str_skill_name_2002362 = "Keajaiban Czerny",
  str_skill_name_2002363 = "Keajaiban Czerny",
  str_skill_name_2002364 = "Keajaiban Czerny",
  str_skill_name_3302361 = "Con Brio",
  str_skill_name_3302362 = "Returning Stars",
  str_skill_desc_3302361 = "Mendapatkan <link=\"30125\"><#FFAE07><u>Vis</u></color></link> selama pertempuran. Saat mengaktifkan skill, Claymore memasuki mode pertempuran unik, memungkinkan <link=\"30127\"><#FFAE07><u>koneksi tile</u></color></link> yang independen. Setelah koneksi, Claymore memasuki <link=\"30128\"><#FFAE07><u>status off-team</u></color></link>, meninggalkan <link=\"30129\"><#FFAE07><u>bayangan</u></color></link> pada tile terakhir yang terhubung, yang akan menjadi titik awal untuk Skill Aktif berikutnya.",
  str_skill_desc_3332361 = "Mendapatkan <link=\"30126\"><#FFAE07><u>Vis</u></color></link> selama pertempuran. Saat mengaktifkan skill, Claymore memasuki mode pertempuran unik, memungkinkan <link=\"30127\"><#FFAE07><u>koneksi tile</u></color></link> yang independen. Setelah koneksi, Claymore memasuki <link=\"30128\"><#FFAE07><u>status off-team</u></color></link>, meninggalkan <link=\"30129\"><#FFAE07><u>bayangan</u></color></link> pada tile terakhir yang terhubung, yang akan menjadi titik awal untuk Skill Aktif berikutnya.",
  str_skill_desc_3302362 = "Dapat dilemparkan untuk kembali ke tim saat dalam keadaan off-team, menimbulkan <color=#00F6FF>550%</color> kerusakan pada ubin di sepanjang jalan.",
  str_skill_desc_2002361 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>4 Tile di sekitar</color>.",
  str_skill_desc_2002362 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>. Mendapatkan 3 Vis jika tidak dalam keadaan off-team.",
  str_skill_desc_2002363 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 Tile dalam bentuk wajik</color>. Mendapatkan 4 Vis jika tidak dalam keadaan tim off.",
  str_skill_desc_2002364 = "Menimbulkan <color=#00F6FF>175%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color>. Mendapatkan 5 Vis jika tidak dalam kondisi tim cadangan.",
  str_skill_passive_desc_4102361 = "Claymore adalah Aurorian <color=#00F6FF>non-elemen</color> dan memiliki Counter Elemen <color=#00F6FF>100%</color> saat menyerang atau diserang. <color=#00F6FF>Claymore beraksi selama pertempuran ketika dia adalah Kapten, tetapi hanya terlibat sebagai anggota tim ketika semua ubin yang terhubung adalah ubin kromatik.</color> Setiap penggunaan Active Skill menghabiskan 1 Vis, memberikan Claymore 1 tumpukan Star Power. Star Power meningkatkan damage sebesar <color=#00F6FF>{1}</color>, hingga 99 tumpukan.",
  str_skill_passive_desc_4402361 = "Claymore adalah Aurorian <color=#00F6FF>non-elemen</color> dan memiliki Counter Elemen <color=#00F6FF>100%</color> saat menyerang atau diserang. <color=#00F6FF>Claymore bertindak selama pertempuran ketika dia adalah Kapten, tetapi hanya terlibat sebagai anggota tim ketika semua ubin yang terhubung adalah ubin kromatik.</color> Setiap penggunaan Active Skill menghabiskan 1 Vis, memberikan Claymore 1 tumpukan Star Power. Star Power meningkatkan damage sebesar <color=#00F6FF>1.1%</color>, hingga 99 tumpukan.",
  str_skill_passive_desc_4602361 = "Claymore adalah Aurorian <color=#00F6FF>non-elemen</color> dan memiliki Counter Elemen <color=#00F6FF>100%</color> saat menyerang atau diserang. <color=#00F6FF>Claymore bertindak selama pertempuran ketika dia adalah Kapten, tetapi hanya terlibat sebagai anggota tim ketika semua ubin yang terhubung adalah ubin kromatik.</color> Setiap penggunaan Active Skill menghabiskan 1 Vis, memberikan Claymore 2 tumpukan Star Power. Star Power meningkatkan damage sebesar <color=#00F6FF>1.1%</color>, hingga 99 tumpukan.",
  str_skill_upgrade_refine_desc_17023611 = "Peningkatan Keterampilan Peralatan: Meningkatkan faktor menjadi <color=#00F6FF>1.1%</color>.",
  str_skill_upgrade_refine_desc_17023612 = "Kombo Rantai Tier Baru <color=#00F6FF>4</color>: Memerlukan 12 tile yang terhubung. Menimbulkan 175% kerusakan pada 2 cluster sekitar. Mendapatkan 5 Vis jika tidak dalam keadaan tim cadangan.",
  str_skill_upgrade_refine_desc_17023613 = "Peningkatan Keterampilan Peralatan: <color=#00F6FF>Menggandakan</color> tumpukan Star Power yang diperoleh.",
  str_skill_upgrade_desc_16023813 = "Active Skill Enhancement: Mengubah Active Skill menjadi <color=#FFFF00>Preemptive Strike</color>. Tersedia saat memulai pertempuran.",
  str_skill_upgrade_desc_16023816 = "Peningkatan Keterampilan Aktif: Meningkatkan jumlah ubin yang dapat Anda pilih sebanyak <color=#00F6FF>1</color>.",
  str_skill_name_2002381 = "Tepi Celestial",
  str_skill_desc_2002381 = "Melemparkan pisau bulu ke <color=#00F6FF>musuh terdekat</color>, menimbulkan 170% kerusakan, yang kemudian memantul ke <color=#00F6FF>musuh terdekat berikutnya</color>. Untuk setiap klaster antara target, kerusakan akhir meningkat sebesar 10%, hingga 50%. Kerusakan ditingkatkan lebih lanjut berdasarkan hitungan Kombo Rantai.",
  str_skill_name_3002381 = "Pesan Revelatory",
  str_skill_name_3062381 = "Pesan Revelatory",
  str_skill_name_3302381 = "Pesan Wahyu Varian I",
  str_skill_name_3362381 = "Revelatory Message Variant I",
  str_skill_desc_3002381 = "Mengonversi <color=#00F6FF>5</color> tile yang dipilih menjadi enhanced tile.",
  str_skill_desc_3062381 = "Mengonversi <color=#00F6FF>6</color> tile yang dipilih menjadi tile enhanced.",
  str_skill_desc_3302381 = "<color=#FFFF00>Cooldown skill -1 setelah casting</color>. Mengonversi <color=#00F6FF>3</color> tile yang dipilih menjadi enhanced tile.",
  str_skill_desc_3362381 = "<color=#FFFF00>Cooldown skill -1 setelah melakukan casting</color>. Mengonversi <color=#00F6FF>4</color> tile yang dipilih menjadi enhanced tile.",
  str_skill_passive_name_4102381 = "Warisan Cahaya Bintang",
  str_skill_passive_name_4162381 = "Warisan Cahaya Bintang",
  str_skill_passive_desc_4102381 = "Dapatkan <color=#00F6FF>1 Starlight Mark</color> untuk <color=#00F6FF>setiap enhanced tile</color> yang diperoleh. Chain Combos mengkonsumsi <color=#00F6FF>seperempat</color> dari Starlight Marks, menambahkan <color=#00F6FF>{1}%</color> dari rata-rata ATK tim sebagai damage tambahan per tumpukan.",
  str_skill_passive_desc_4162381 = "Dapatkan <color=#00F6FF>1 Starlight Mark</color> untuk <color=#00F6FF>setiap tile yang ditingkatkan</color> yang diperoleh. Chain Combos mengkonsumsi <color=#00F6FF>sepertiga</color> dari Starlight Marks, menambahkan <color=#00F6FF>{1}</color> dari rata-rata ATK tim sebagai damage ekstra per tumpukan. Setiap tile yang ditingkatkan yang diperoleh dalam satu putaran mengurangi persyaratan pemicu Chain Combo sebanyak 1.",
  str_skill_upgrade_refine_desc_15017611 = "Peningkatan Keterampilan Peralatan: Setiap <color=#00F6FF>4</color> serangan normal, Beretta menembus targetnya saat ini dengan 1 Tombak Australis.",
  str_skill_upgrade_refine_desc_15017612 = "Peningkatan Skill Aktif: Setiap Tombak Australis memberikan <color=#00F6FF>100%</color> kerusakan pada target.",
  str_skill_upgrade_refine_desc_15017613 = "Peningkatan Skill Aktif: Setiap Tombak Australis memulihkan <color=#00F6FF>15%–22.5%</color> dari kerusakan yang ditangani sebagai HP saat menimbulkan kerusakan pada target.",
  str_skill_passive_desc_4401761 = "Setiap <color=#00F6FF>4</color> serangan normal, Beretta menembus targetnya saat ini dengan <color=#00F6FF>1</color> <color=#00F6FF>Tombak Australis</color>.",
  str_skill_passive_desc_4451761 = "Every <color=#00F6FF>4</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_desc_3501761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>2 cluster sekitarnya</color>. Penawaran <color=#00F6FF>100%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%–15%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_desc_3521761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>100%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%–15%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_desc_3551761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>100%–120%</color> merusak dan memulihkan HP dengan <color=#00F6FF>10%–15% dari</color> kerusakan yang ditangani dengan cara ini untuk setiap <color=#00F6FF>Tombak Australis</color> yang ditarik keluar. Semakin rendah HP target saat ini, semakin tinggi faktor kerusakannya. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_desc_3601761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>2 cluster sekitarnya</color>. Penawaran <color=#00F6FF>100%</color> merusak dan memulihkan HP dengan <color=#00F6FF>15%–22.5%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_desc_3621761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>100%</color> merusak dan memulihkan HP dengan <color=#00F6FF>15%–22.5%</color> dari kerusakan yang ditangani dengan cara ini untuk setiap Australis Spear yang ditarik keluar. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_desc_3651761 = "Menarik keluar <color=#00F6FF>Tombak Australis</color> dari semua musuh di dalamnya <color=#00F6FF>3 cluster sekitarnya</color>. Penawaran <color=#00F6FF>100%–120%</color> merusak dan memulihkan HP dengan <color=#00F6FF>15%–22.5% dari</color> kerusakan yang ditangani dengan cara ini untuk setiap <color=#00F6FF>Tombak Australis</color> yang ditarik keluar. Semakin rendah HP target saat ini, semakin tinggi faktor kerusakannya. Semakin rendah HP tim, semakin tinggi faktor pemulihannya.",
  str_skill_name_3501821 = "Penyempitan Ular Varian I",
  str_skill_name_3601821 = "Penyempitan Ular Varian II",
  str_skill_desc_3501821 = "Active Skill can be unleashed when <color=#00F6FF>2</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit, and <color=#FFFF00>2 Serpent Flares will be extinguished upon its cast</color>. Selects 1 tile and deals <color=#00F6FF>400%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>. This does not trigger the Equipment Skill: Moonglow Relict Arts.",
  str_skill_desc_3601821 = "Active Skill can be unleashed when <color=#00F6FF>2</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit, and <color=#FFFF00>2 Serpent Flares will be extinguished upon its cast</color>. Triggers the Equipment Skill: Moonglow Relict Arts, dealing <color=#00F6FF>300%</color> damage to <color=#00F6FF>all</color> enemies.",
  str_skill_upgrade_refine_desc_16018211 = "Peningkatan Skill Aktif: Meningkatkan faktor kerusakan menjadi 400%.",
  str_skill_upgrade_refine_desc_16018212 = "<color=#00F6FF>New Active Skill Variant I</color>: Active Skill can be unleashed when 2 Serpent Flares are lit, and 2 Serpent Flares will be extinguished upon its cast. Selects 1 tile and deals 400% damage to 13 tiles in a diamond shape. This does not trigger the Equipment Skill: Moonglow Relict Arts.",
  str_skill_upgrade_refine_desc_16018213 = "<color=#00F6FF>New Active Skill Variant II</color>: Active Skill can be unleashed when 2 Serpent Flares are lit, and 2 Serpent Flares will be extinguished upon its cast. Triggers the Equipment Skill: Moonglow Relict Arts, dealing 300% damage to all enemies.",
  str_skill_desc_3401821 = "Skill Aktif dapat dilepaskan saat <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Suar Ular</u></color></link> menyala. Memilih 1 ubin dan penawaran <color=#00F6FF>400%</color> kerusakan pada <color=#00F6FF>13 ubin dalam bentuk berlian</color>. Semua Serpent Flare akan padam setelah menggunakan Skill Aktif.",
  str_skill_upgrade_desc_16024113 = "Peningkatan Keterampilan Aktif: Mengurangi cooldown Keterampilan Aktif sebanyak <color=#00F6FF>1</color> putaran dan meningkatkan faktor kerusakan sebesar <color=#00F6FF>50%</color>.",
  str_skill_upgrade_desc_16024116 = "Varian Active Skill Baru: <color=#00F6FF>Menggandakan</color> konsumsi Sanity dan damage yang ditimbulkan. Menghasilkan hingga <color=#00F6FF>3</color> Dark Tile.",
  str_skill_name_2002411 = "Ledakan yang Merajalela",
  str_skill_name_2002412 = "Ledakan yang Merajalela",
  str_skill_name_2002413 = "Ledakan yang Merajalela",
  str_skill_name_2302411 = "Ledakan yang Merajalela",
  str_skill_name_2302412 = "Ledakan yang Merajalela",
  str_skill_name_2302413 = "Ledakan yang Merajalela",
  str_skill_name_3002411 = "Tarian Gila",
  str_skill_name_3032411 = "Tarian Gila",
  str_skill_name_3062411 = "Tarian Gila Varian I",
  str_skill_desc_2002411 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>.",
  str_skill_desc_2002412 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 tile dalam bentuk wajik</color>.",
  str_skill_desc_2002413 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color>.",
  str_skill_desc_2302411 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>1 klaster di sekitar</color>. <link=\"30124\"><#FFAE07><u>Menyerap</u></color></link> ubin gelap di dalam 4 ubin sekitarnya.",
  str_skill_desc_2302412 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>12 Tile dalam bentuk wajik</color>. <link=\"30124\"><#FFAE07><u>Menyerap</u></color></link> tile gelap dalam 1 klaster di sekitar.",
  str_skill_desc_2302413 = "Menimbulkan <color=#00F6FF>{1}%</color> damage pada <color=#00F6FF>2 klaster di sekitar</color>. <link=\"30124\"><#FFAE07><u>Menyerap</u></color></link> ubin gelap dalam 12 ubin di sekitar dalam bentuk wajik.",
  str_skill_desc_3002411 = "Pepita terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Mengkonsumsi <color=#00F6FF>15</color> Sanity Point untuk menimbulkan 150% DMG pada musuh yang dipilih, menghasilkan 1 Tile gelap di bawah target.",
  str_skill_desc_3032411 = "Pepita terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Mengkonsumsi <color=#00F6FF>15</color> Sanity Point untuk menimbulkan 200% DMG pada musuh yang dipilih, menghasilkan 1 Tile gelap di bawah target.",
  str_skill_desc_3062411 = "Pepita terjun ke pertempuran dengan <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Mengkonsumsi <color=#00F6FF>30</color> Sanity Point untuk menimbulkan 400% DMG pada musuh yang dipilih, menghasilkan hingga 3 Tile gelap secara acak di bawah target.",
  str_skill_passive_name_4102411 = "Api Menyala",
  str_skill_passive_name_4202411 = "Api Menyala",
  str_skill_passive_desc_4102411 = "Setiap kali Pepita memperoleh ubin gelap, dia mendapatkan <color=#00F6FF>1</color> tumpukan Heart's Flame, hingga <color=#00F6FF>7</color> tumpukan. Kapten saat ini mengkonsumsi 1 tumpukan Heart's Flame dengan setiap serangan normal, meningkatkan kerusakan akhirnya sebesar <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_4202411 = "Setiap kali Pepita mendapatkan Tile Gelap, dia mendapatkan <color=#00F6FF>1</color> Api Hati, hingga <color=#00F6FF>7</color>. Kapten saat ini mengonsumsi 1 Api Hati dengan setiap serangan normal, meningkatkan damage akhirnya sebesar <color=#00F6FF>{1}</color>. Pada awal setiap putaran, <color=#00F6FF>2</color> Tile Gelap secara acak dihasilkan di bawah musuh di lapangan.",
